def _detect_jurisdiction_in_link_tree(tree) -> tuple[str | None, str]:
    """R-F301: scan a LinkTreeResult for city + country tokens → ISO2.
    Returns (iso2, evidence_quote) of the WINNING jurisdiction on hit,
    else (None, ""). For multi-jurisdiction inference (Modirum has FI HQ
    + BR ops + UAE admin + ...), use `_detect_all_jurisdictions_in_link_tree`."""
    all_juris = _detect_all_jurisdictions_in_link_tree(tree)
    if not all_juris:
        return None, ""
    # Winner is the highest-voted; evidence comes back from the all-list helper
    winner = all_juris[0]
    return winner["iso2"], winner["evidence"]


def _detect_all_jurisdictions_in_link_tree(tree) -> list[dict]:
    """R-F301 multi-jurisdiction follow-up (live observation 2026-05-11
    on modirumgespi.com): the previous winner-only logic picked BR because
    the page emphasises GESPI Brazil, but the Finnish PRH adapter (R-F302)
    couldn't fire because FI was the second-place vote, not first. This
    returns ALL jurisdictions ranked by vote so the caller can try
    every registry adapter in order until one returns data.

    Returns: [{iso2, country, score, evidence}, ...] sorted by score desc.
    Empty list when no detection."""
    if not tree:
        return []

    haystack_parts: list[str] = []
    for ff in (getattr(tree, "fused_facts", None) or [])[:60]:
        if getattr(ff, "value", ""):
            haystack_parts.append(str(ff.value))
        if getattr(ff, "first_context", ""):
            haystack_parts.append(str(ff.first_context))
    for page in (getattr(tree, "pages", None) or [])[:30]:
        if getattr(page, "title", ""):
            haystack_parts.append(str(page.title))
        for fact in (getattr(page, "facts", None) or [])[:25]:
            if getattr(fact, "value", ""):
                haystack_parts.append(str(fact.value))
            if getattr(fact, "context", ""):
                haystack_parts.append(str(fact.context))
    if not haystack_parts:
        return []

    haystack = " | ".join(haystack_parts)[:80000]
    haystack_lower = haystack.lower()

    votes: dict[str, int] = {}
    for token, iso2 in _LINK_TREE_CITY_TO_ISO2.items():
        if token in haystack_lower:
            weight = 2 if token == _ISO2_TO_COUNTRY_HINT.get(iso2, "").lower() else 1
            votes[iso2] = votes.get(iso2, 0) + weight
    if not votes:
        return []

    out: list[dict] = []
    for iso2, score in sorted(votes.items(), key=lambda kv: -kv[1]):
        # Require at least 2 points to make the list — discards single
        # incidental mentions.
        if score < 2:
            continue
        # Evidence quote — first matching token's surrounding text
        evidence = ""
        for token, t_iso2 in _LINK_TREE_CITY_TO_ISO2.items():
            if t_iso2 != iso2:
                continue
            idx = haystack_lower.find(token)
            if idx >= 0:
                start = max(0, idx - 60)
                end = min(len(haystack_lower), idx + len(token) + 60)
                evidence = haystack[start:end].replace("\n", " ").strip()
                break
        out.append({
            "iso2": iso2,
            "country": _ISO2_TO_COUNTRY_HINT.get(iso2, iso2),
            "score": score,
            "evidence": evidence,
        })
    return out


def _brandify_name_for_search(name: str, target: dict) -> str:
    """R-F299: derive a search-friendly brand string from a name that may
    have been set from a hostname by the R-F153 fallback. If the name was
    NOT derived from a domain, return as-is.

    Examples:
      "modirumgespi.com"          → "modirumgespi"
      "duma-engineering.com"      → "duma engineering"
      "f3ir.uk"                   → "f3ir"
      "Modirum GESPI"             → "Modirum GESPI"   (untouched — has space)
    """
    if not name:
        return name
    derivation = target.get("_name_derivation") or ""
    looks_like_host = (
        "." in name
        and " " not in name
        and not name.startswith("(")
    )
    if not (looks_like_host or "hostname" in derivation):
        return name
    # Strip TLD (the last .xx / .xxx)
    stripped = re.sub(r"\.[A-Za-z]{2,6}$", "", name)
    # Hyphens and underscores become spaces
    stripped = re.sub(r"[-_]+", " ", stripped)
    # Collapse repeated whitespace
    stripped = re.sub(r"\s+", " ", stripped).strip()
    return stripped or name


def _env_float(name: str, default: float) -> float:
    try:
        return float(os.getenv(name, "") or default)
    except (TypeError, ValueError):
        return default


def _env_int(name: str, default: int) -> int:
    try:
        return int(os.getenv(name, "") or default)
    except (TypeError, ValueError):
        return default


DEFAULT_COST_CAP_USD = _env_float("ARIA_DD_COST_CAP_USD", 0.50)
DEFAULT_LAYER_TIMEOUT_S = _env_int("ARIA_DD_LAYER_TIMEOUT_S", 90)

# R-F2977 — PER-OP timeouts. Live DD 2026-07-24 (Silverbrook) showed the COMPLIANCE
# layer ERROR 'timeout after 90s' and the DIGITAL layer ERROR 'timeout after 180s':
# each layer runs several heavy external sub-ops SEQUENTIALLY with NO per-op bound,
# so one slow/hung call (or the sum) exceeds the layer budget → the whole layer is
# CANCELLED mid-op → status ERROR (health showed digital 29 err / 1 ok over 7d).
# §1 root fix (NOT a layer-timeout bump): bound each heavy op so a slow one degrades
# to a data_gap and the LAYER COMPLETES (status OK) with partial-but-honest results.
# Bounds are sized so the worst-case SUM stays under the layer budget with margin
# (compliance ~57s < 90s; digital ~145s < 180s). All env-tunable.
_OP_T_USASPENDING   = _env_float("ARIA_DD_OP_T_USASPENDING_S", 12.0)
_OP_T_FINANCIAL     = _env_float("ARIA_DD_OP_T_FINANCIAL_S", 25.0)
_OP_T_WORLDBANK     = _env_float("ARIA_DD_OP_T_WORLDBANK_S", 15.0)
_OP_T_MULTIQUERY    = _env_float("ARIA_DD_OP_T_MULTIQUERY_S", 45.0)
_OP_T_WEBSEARCH     = _env_float("ARIA_DD_OP_T_WEBSEARCH_S", 30.0)
_OP_T_WEBSITE_MINE  = _env_float("ARIA_DD_OP_T_WEBSITE_MINE_S", 30.0)
_OP_T_RAG           = _env_float("ARIA_DD_OP_T_RAG_S", 15.0)
_OP_T_KB            = _env_float("ARIA_DD_OP_T_KB_S", 15.0)
_OP_T_DEEPRESEARCH  = _env_float("ARIA_DD_OP_T_DEEPRESEARCH_S", 40.0)

# ── R-F3093 — DEEP MODE MUST ACTUALLY BE DEEP ───────────────────────────────
#
# THE DEFECT (Mitie, operator report 2026-07-26). The report's own data gap read:
#     "deep research was bounded at 37s and stopped after article read (no budget
#      left to analyse articles) — 0 article(s) analysed, 0 fact(s) retained"
# A DEEP DD read nothing. Adverse media searched 12 of 48 query templates. With no
# substance to report, the renderer filled the page with process narration — which
# is the real reason the report reads as noise. Layout was the symptom; an empty
# evidence set was the cause.
#
# WHY 37s. The budget is a three-level nest and every level was sized for the
# STANDARD run: deep research got `_OP_T_DEEPRESEARCH` 40s (−3s cooperative margin)
# inside a 180s digital layer inside a 660s total. Raising only the op timeout does
# nothing — `_bounded_dd_op` clamps to what the LAYER has left (R-F3059), and the
# digital layer had already spent ~82s on multi-query + search before deep research
# started. So all three levels are scaled together, for `mode == "deep"` ONLY.
#
# STANDARD AND QUICK ARE UNCHANGED. They keep the 660s total that guarantees a
# WhatsApp async-push delivery inside the 15-min poll window (see the R-F1572 note
# at the budget site). A deep DD is an explicit, low-volume operator choice served
# by the fire-and-poll list, and already ran 10-15 min.
_OP_T_DEEPRESEARCH_DEEP = _env_float("ARIA_DD_OP_T_DEEPRESEARCH_DEEP_S", 300.0)

# ── R-F3131 — A CAPABILITY MUST FIT THE BUDGET IT RUNS IN ───────────────────
#
# MEASURED on the live Babcock DD (dd_8c7242c2b45b, 2026-07-26). The report said:
#     "financial health did not complete within 25s (bounded) — partial result"
#     "Financial capacity — UNRESOLVED — financial capacity is unknown"
# R-F3124/R-F3128 added the issuer-annual-report route to exactly that op: it must
# fetch a multi-hundred-page PDF, extract its text layer, and send ~120k characters
# to Claude. That cannot happen in 25 SECONDS. The capability was shipped into a
# budget it could never complete in, so financial capacity stayed UNKNOWN for the one
# class of counterparty the route exists to answer — a listed group.
#
# This is the R-F3093 defect repeated: there, deep research had 37s and read ZERO
# articles. Same lesson, and the same three-level fix, because `_bounded_dd_op`
# clamps every op to the LAYER deadline (R-F3059) — raising the op alone changes
# nothing:
#     total budget  ->  compliance LAYER  ->  financial OP
# Deep mode only. Standard/quick keep 25s and the 90s layer: they do not run the
# issuer-report route to completion either way, and the 660s total that guarantees
# WhatsApp delivery inside the poll window must not move.
_OP_T_FINANCIAL_DEEP = _env_float("ARIA_DD_OP_T_FINANCIAL_DEEP_S", 150.0)
#: Compliance-layer budget in deep mode: usaspending 12 + financial 150 + worldbank
#: 15 = 177, plus the R-F3066 tail reserve and margin.
_DEEP_COMPLIANCE_BUDGET_S = _env_float("ARIA_DD_DEEP_COMPLIANCE_BUDGET_S", 210.0)
#: Digital-layer budget in deep mode. Must cover deep research (300) + the other
#: bounded ops it shares the layer with (multi-query 45 + search 30 + site mine 30
#: + RAG 15 + KB 15 + link-tree 90 ≈ 225) with margin.
_DEEP_DIGITAL_BUDGET_S = _env_float("ARIA_DD_DEEP_DIGITAL_BUDGET_S", 560.0)
#: Total wall budget in deep mode: identity(90) + [network‖digital](560) +
#: compliance(90) + extensions(45) + synthesis reserve, with margin.
_DEEP_TOTAL_BUDGET_S = _env_int("ARIA_DD_DEEP_TOTAL_BUDGET_S", 1140)


def _dd_total_budget_default(mode: str) -> float:
    """R-F3093 — the wall budget for a run of this mode.

    Deep mode buys the research time; every other mode keeps the 660s that the
    WhatsApp push window depends on.

    PRECEDENCE. An explicitly-set `ARIA_DD_TOTAL_BUDGET_S` wins for EVERY mode. It
    is the existing global handle (R-F1572) and the one the runbook tells an operator
    to reach for when a DD overruns; a mode-specific default that silently ignored it
    would make deep runs unbounded by the very knob documented to bound them."""
    if os.getenv("ARIA_DD_TOTAL_BUDGET_S"):
        return float(_env_int("ARIA_DD_TOTAL_BUDGET_S", 660))
    if str(mode or "").strip().lower() == "deep":
        return float(_env_int("ARIA_DD_DEEP_TOTAL_BUDGET_S", _DEEP_TOTAL_BUDGET_S))
    return 660.0


#: R-F3066 — seconds reserved at the end of a layer's budget for its own post-op
#: work, so the LAST bounded op cannot return at the wall and still overrun.
_LAYER_TAIL_S = _env_float("ARIA_DD_LAYER_TAIL_S", 6.0)


#: R-F3059 — the deadline of the LAYER currently running, as a `time.monotonic()`
#: stamp. Published by each bounded layer wrapper, read by `_bounded_dd_op`.
_LAYER_DEADLINE: "contextvars.ContextVar[float | None]" = contextvars.ContextVar(
    "dd_layer_deadline", default=None)


def _layer_budget_left(default: float = 0.0) -> float:
    """R-F3066 — seconds remaining in the current layer's budget.

    Returns `default` when no layer deadline is in scope (direct calls, tests), so a
    caller that asks for a sub-budget still gets its normal allowance outside a
    bounded layer. Used to DERIVE a child operation's own wall budget instead of
    letting it claim a flat constant the layer cannot afford."""
    dl = _LAYER_DEADLINE.get()
    if dl is None:
        return float(default)
    return max(0.0, dl - time.monotonic() - 1.0)


def _subject_is_person(report) -> bool:
    """R-F3063 — True when the DD subject is an INDIVIDUAL.

    Company-register enrichment (Companies House lookups, officer/PSC backfill,
    filed-accounts financials) must never run for a person: those registers are
    keyed by COMPANY, so resolving a human's name against them is a name match whose
    output is then attributed to that human. Deliberately an explicit person test
    rather than a company test, so a subject of genuinely unknown type keeps its
    existing behaviour instead of silently losing registry coverage."""
    try:
        return str(getattr(getattr(report, "identity", None), "entity_type", "") or "").strip().lower() == "person"
    except Exception:
        return False


async def _bounded_dd_op(coro, timeout_s: float, layer, op_name: str, default=None,
                         progress: dict | None = None):
    """R-F2977 — await `coro` under a hard per-op timeout. On timeout: record a
    data_gap on `layer` and return `default` so the layer KEEPS GOING and completes
    (status OK) instead of the whole layer being cancelled → ERROR. Any OTHER
    exception propagates unchanged to the caller's existing try/except.

    R-F3059 — the per-op bound is ADDITIONALLY clamped to the LAYER's remaining
    time. R-F2977 sized these bounds against the 180s digital budget (sum ≈145s),
    but the digital layer only gets 180s when a website was supplied — otherwise it
    is `DEFAULT_LAYER_TIMEOUT_S` (90s), while the op bounds still sum to ~175s:
    multi-query 45 + web-search 30 + site-mine 30 + rag 15 + kb 15 + deep-research
    40. So on the common no-website path the layer could NOT fit its own ops and was
    guaranteed to be cancelled → `status=ERROR, "timeout after 90s"` — which is what
    every live report showed, and it meant R-F2977's whole mechanism could never
    take effect. Clamping makes that intent true for any budget: a slow op degrades
    to a data_gap and the LAYER COMPLETES."""
    _dl = _LAYER_DEADLINE.get()
    if _dl is not None:
        # R-F3066 — the tail must cover the layer's OWN post-op work (press
        # processing, tier breakdown, wiring), not just one second of slack. With a
        # 1s tail a single op could return at T-1 and the layer still overran.
        _remaining = _dl - time.monotonic() - _LAYER_TAIL_S
        if _remaining <= 0:
            try:
                layer.data_gaps.append(
                    f"{op_name} was SKIPPED — the layer's time budget was already "
                    "exhausted. Not attempted, so treat as unchecked, not as clean.")
            except Exception:
                pass
            logger.info("[R-F3059] DD op '%s' skipped — layer budget exhausted", op_name)
            return default
        timeout_s = max(2.0, min(float(timeout_s), _remaining))
    try:
        return await asyncio.wait_for(coro, timeout=timeout_s)
    except asyncio.TimeoutError:
        # R-F3316 — a hard cancel destroys the callee's stack, so it can report
        # NOTHING about where its budget went. Three consecutive attempts at the
        # deep-research timeout (R-F3258, R-F3300, R-F3306) were therefore
        # hypotheses rather than diagnoses: the gap said only "did not complete
        # within 300s", which is true and useless.
        #
        # `progress` is owned by the CALLER, so writes into it survive the
        # cancellation that discards everything else. A module-level global would
        # be clobbered by concurrent DDs; a dict per call is not.
        _where = ""
        try:
            if isinstance(progress, dict) and progress.get("stage"):
                _detail = ", ".join(
                    f"{k}={v}" for k, v in progress.items()
                    if k != "stage" and v not in (None, "")
                )
                _where = f", last stage: {progress['stage']}"
                if _detail:
                    _where += f" ({_detail})"
        except Exception:
            _where = ""
        try:
            layer.data_gaps.append(
                f"{op_name} did not complete within {int(timeout_s)}s (bounded)"
                f"{_where}. Partial result, NOT a clean check")
        except Exception:
            pass
        logger.warning("[R-F2977] DD op '%s' exceeded %ss (bounded, layer continues)%s",
                       op_name, timeout_s, _where)
        return default
DEEP_RESEARCH_ENABLED = (os.getenv("ARIA_DD_DEEP_RESEARCH", "1") or "1").strip() not in ("0", "false", "no", "off")
ORCHESTRATOR_ENABLED = (os.getenv("ARIA_DD_ORCHESTRATOR_ENABLED", "1") or "1").strip() not in ("0", "false", "no", "off")

REPORT_REDIS_KEY = "crucix:dd:report:{run_id}"
REPORT_INDEX_KEY = "crucix:dd:report_index"

# R-F2777 — CROSS-TENANT LEAK FIX. The R-F608 "same-company" share treats any two
# users with the SAME email domain as colleagues who may see each other's DDs. That
# is correct for a corporate domain (acme.com) but a CROSS-TENANT DISCLOSURE for a
# PUBLIC WEBMAIL domain: two unrelated strangers on gmail.com are NOT one company, so
# sharing "share_to_company" DDs across gmail.com leaks one user's due-diligence to
# another. A public-webmail user must therefore get OWNER-EXACT access only — never a
# domain-share. This set is the exclusion list; extend it as new consumer providers
# appear. All entries are lower-cased bare domains (no '@').
_PUBLIC_WEBMAIL_DOMAINS: frozenset[str] = frozenset({
    "gmail.com", "googlemail.com",
    "outlook.com", "outlook.co.uk", "hotmail.com", "hotmail.co.uk", "hotmail.fr",
    "live.com", "live.co.uk", "msn.com",
    "yahoo.com", "yahoo.co.uk", "yahoo.fr", "yahoo.de", "ymail.com", "rocketmail.com",
    "icloud.com", "me.com", "mac.com",
    "proton.me", "protonmail.com", "pm.me",
    "gmx.com", "gmx.net", "gmx.de",
    "aol.com", "zoho.com", "mail.com", "yandex.com", "yandex.ru",
    "fastmail.com", "tutanota.com", "tuta.com", "hey.com",
})


def _is_public_webmail_domain(domain: str | None) -> bool:
    """R-F2777 — True if ``domain`` is a public/free webmail provider whose users are
    NOT a single company. Same-company DD sharing (R-F608) must be DISABLED for these
    domains so a free-webmail user only ever sees their OWN reports. Case/space-safe;
    None/empty → False (no domain → no domain-share anyway)."""
    d = (domain or "").strip().lower()
    return bool(d and d in _PUBLIC_WEBMAIL_DOMAINS)
# R-F2469 — run_ids whose ownership this process has already backfilled into the
# wipe-surviving vault (dd_report_owners). Bounds the on-read backfill to one
# vault upsert per run_id per process (not per dashboard poll). Vault-DB writes,
# separate from the state_store — no impact on the R-F2277 write ceiling.
_R2469_OWNER_BACKFILLED: set[str] = set()
# R-F877 (2026-05-25) — DD report bodies + index NO LONGER EXPIRE.
# Was `7 * 24 * 3600` (7-day TTL). A DD verdict is a compliance artifact
# (HARD_STOP / SAR-trigger) and knowledge — CLAUDE.md §7 is binding: "No TTL
# on knowledge. No eviction. Overflow → cold storage, never delete." The
# 7-day TTL also broke the R-F573 version-diff: a re-DD 8+ days after the
# previous run found the prior body aged out (the R-F575 cold tier only
# archived the INDEX entry, not the body) so it silently produced diff=None.
# The store is file/SQLite-backed (Upstash cancelled 2026-05-12), so there is
# no RAM-pressure reason to expire — same infinite-memory model as the
# knowledge store. `ex=None` → set_json writes with no expiry. Name kept
# (12 call sites) but semantically "persist forever".
REPORT_TTL_SECONDS = None

# R-F2343 — ONE process-wide lock for every report-index read-modify-write. The index is a
# single shared key (crucix:dd:report_index); mark_dd_running / mark_dd_failed / the
# completion persist / reconcile each did a non-atomic get -> modify -> set, so a concurrent
# DD start/completion could CLOBBER another DD's freshly-written row (lost update), and the
# completion path reused an index snapshot read minutes earlier. Routing all mutations
# through _mutate_report_index (lock + read the CURRENT index INSIDE the lock) makes them
# serialisable + last-write-consistent. aria-intel is single-process, so one asyncio.Lock
# fully serialises them.
_REPORT_INDEX_LOCK = asyncio.Lock()


async def _mutate_report_index(mutator, *, persist: bool = True):
    """R-F2343 — atomically read-modify-write the report index under _REPORT_INDEX_LOCK,
    always reading the CURRENT index inside the lock (never a stale snapshot). `mutator`
    is a pure, quick transform ``(index: list) -> new_index: list``. Returns the new index
    (or None on error). Best-effort — index maintenance must never break a DD run."""
    from . import redis_store as rs
    try:
        async with _REPORT_INDEX_LOCK:
            index = await rs.get_json(REPORT_INDEX_KEY) or []
            new_index = mutator(list(index))
            if new_index is None:
                new_index = index
            if persist:
                await rs.set_json(REPORT_INDEX_KEY, new_index[:500], ex=REPORT_TTL_SECONDS)
            return new_index
    except Exception:
        logger.exception("[R-F2343] report-index mutate failed")
        return None


# =============================================================================
# LAYER RUNNERS — each layer is a coroutine that fills a section of the report
# =============================================================================

async def _run_identity_person(
    target: dict,
    report: ARKDDReport,
) -> bool:
    """Layer 1 (person mode) — Identity for a natural person.

    Runs:
      1. Name resolution → variant set (transliteration, short forms,
         particle handling, initials)
      2. Multi-variant sanctions screen — each variant is screened and
         matches are aggregated. Severity = worst across variants.
      3. PEP / ICC / Interpol topic classification from the match data.
      4. Role extraction from any supplied free-text context (title,
         organisation, nationality) so the synthesis layer has context.

    No Companies House, no CUI, no ghost score — those are company-only.
    Returns True on hard-stop (active sanctions hit).
    """
    t0 = time.time()
    report.identity.meta.started_at = datetime.now(timezone.utc).isoformat()

    name = (target.get("name") or target.get("entity") or target.get("query", "")).strip()
    nationality = target.get("nationality") or target.get("nationality_iso2")
    role = target.get("role") or target.get("title")
    organisation = target.get("organisation") or target.get("employer")
    dob = target.get("dob") or target.get("date_of_birth")

    report.identity.entity_name = _coerce_entity_text(name)   # R-F3268
    report.identity.entity_type = "person"
    report.identity.jurisdiction = target.get("jurisdiction") or nationality
    report.identity.jurisdiction_iso2 = target.get("jurisdiction_iso2")
    if role:
        report.identity.declared_activity = f"{role}" + (f" at {organisation}" if organisation else "")

    hard_stop = False

    # ── 1a. Name resolution ──
    try:
        from . import person_resolver
        resolution = person_resolver.resolve(
            name,
            nationality_iso2=target.get("jurisdiction_iso2"),
            max_variants=12,
        )
        report.identity.findings.append(Finding(
            severity="info",
            title=f"Name resolved: {len(resolution.variants)} variants ({resolution.script})",
            detail=(
                f"Canonical: {resolution.canonical}. "
                f"Components: given={resolution.components.given or '-'}, "
                f"particles={resolution.components.particles or '-'}, "
                f"surname={resolution.components.surname or '-'}. "
                f"First 5 variants: {', '.join(resolution.variants[:5])}."
            ),
            source="person_resolver.resolve",
            confidence="CONFIRMED",
        ))
    except Exception as e:
        logger.warning("Identity (person): name resolution failed: %s", e)
        resolution = None
        report.identity.data_gaps.append(f"name resolution failed: {str(e)[:120]}")

    # ── 1b. Multi-variant sanctions screen ──
    #
    # Each variant is screened separately against OpenSanctions. Matches
    # are aggregated and the worst severity wins. Token-overlap filtering
    # in classify_matches rejects short-string collisions (e.g. "Ali"
    # matching hundreds of unrelated sanctioned individuals named Ali).
    all_matches: list = []
    screened_variants: list[str] = []
    try:
        from . import sanctions as _sanc
        from ._sanctions_classify import classify_matches as _cm
        # R-F3689 — the name reaching here is the DD SUBJECT: operator-supplied
        # or registry-resolved, not free text. Declaring that (R-F3228) skips
        # the search-query shape heuristic, which otherwise rejects exactly the
        # sanctions-dense population this screen exists for — verified live:
        # `_looks_like_entity_name` returns False for "Ahmed bin Mohammed
        # Al-Saud", "Muhammad bin Salman" and "Marks & Spencer Group plc", and
        # a rejected name came back `{"error": "not_entity_shaped"}`, which the
        # old guard below then counted as a SUCCESSFUL screen.
        #
        # The kwarg is bound to the function actually resolved: the legacy
        # fallback `fuzzy_screen(name, *, threshold=0.78)` has NO `source`
        # parameter (sanctions.py:1100), so passing it unconditionally would
        # raise TypeError straight into the `except` below — a screen that
        # never runs, reported as a variant that failed. §3b.
        _screen_fn = getattr(_sanc, "screen_with_aliases", None)
        _screen_kwargs: dict = {"source": "dd_subject"}
        if _screen_fn is None:
            _screen_fn = getattr(_sanc, "fuzzy_screen", None)
            _screen_kwargs = {}

        variants_to_screen: list[str] = []
        if resolution and resolution.variants:
            variants_to_screen = resolution.variants[:6]  # cost cap
        else:
            variants_to_screen = [name]

        _unavailable_variants: list[str] = []
        for variant in variants_to_screen:
            if not variant or len(variant) < 4:
                continue
            try:
                _scr = await _screen_fn(variant, **_screen_kwargs) if _screen_fn else {"matches": []}
                report.identity.meta.subcalls += 1
                # R-F2416 / R-F3689: fuzzy_screen / screen_with_aliases SOFT-return
                # on an unavailable source WITHOUT raising. Counting such a variant
                # as "screened" makes _screen_ok True and stamps every list CLEAN on
                # a screen that never ran — a never-false-clean breach.
                #
                # R-F3689 — R-F2416's guard ENUMERATED the failure states
                # (`screened is False or source_unavailable`) and so was defeated by
                # any state it had not enumerated. Reproduced: an unshaped name
                # returns `{"error": "not_entity_shaped", "matches": [], ...}` with
                # NO `screened` key at all, so `.get("screened") is False` was False
                # (it is None), `source_unavailable` was absent, the guard did not
                # fire, and the variant was recorded as successfully screened.
                # `derive_verified_sources(screen_succeeded=True)` then stamped all
                # 10 canonical lists CLEAN and the renderer emitted "a POSITIVE
                # CLEAN result — treat as clearance under standard commercial PDD"
                # at confidence=CONFIRMED. No SANCTIONS_SOURCE_UNVERIFIED marker was
                # written, so the R-F2167 synthesis gate never fired either.
                #
                # The company path solved this correctly at ~:5830 (R-F3217) with a
                # POSITIVE predicate: a screen counts only if it PROVED it ran.
                # That is the shape used here now — an unknown future failure state
                # fails CLOSED instead of silently passing.
                if not (
                    isinstance(_scr, dict)
                    and _scr.get("screened") is True
                    and not _scr.get("error")
                    and not _scr.get("source_unavailable")
                ):
                    _unavailable_variants.append(variant)
                    continue
                screened_variants.append(variant)
                _matches = _scr.get("matches") or []
                # Tag each match with which variant surfaced it for audit
                for _m in _matches:
                    if isinstance(_m, dict):
                        _m.setdefault("_variant", variant)
                all_matches.extend(_matches)
            except Exception as _e:
                logger.warning("Person screen failed for variant '%s': %s", variant, _e)
                _unavailable_variants.append(variant)

        # Store the aggregate screen result on the report for renderers.
        # R-F287 (2026-05-11): include explicit per-source verified-status
        # so the LLM renderer can NEVER fabricate "NOT CHECKED" claims for
        # sources OpenSanctions actually queried. screen_succeeded reflects
        # whether AT LEAST ONE variant was screened — if all variants
        # crashed OR the source was unavailable, the screen genuinely failed
        # and per-source UNAVAILABLE is the honest answer.
        from ._sanctions_classify import derive_verified_sources as _dvs
        _screen_ok = len(screened_variants) > 0
        # R-F2416: attempted ≥1 real variant but NONE actually screened → the
        # sanctions/PEP source was unavailable; the screen did NOT run.
        _sanctions_unverified = (not _screen_ok) and bool(_unavailable_variants)
        # R-F3689 §21a — surface the soft failure. Before this, an unavailable
        # source on the person path reached NEITHER the operator (no data_gap)
        # NOR the brain (no gap recorded): the only trace was a logger.warning
        # per variant, and on the not_entity_shaped path not even that.
        if _sanctions_unverified:
            _note_dd_screen_unavailable(
                report, name,
                f"{len(_unavailable_variants)} of {len(_unavailable_variants)} "
                f"name variant(s) could not be screened",
            )
        _screen_blob = {
            "matches": all_matches,
            "variants_screened": screened_variants,
            "source_unavailable": _sanctions_unverified,
            "verified_sources": _dvs(all_matches, screen_succeeded=_screen_ok),
            # R-F3031 — completes R-F3019. That change stamped `screened_at` inside
            # sanctions.fuzzy_screen(), but the DD does NOT use that dict: it builds
            # its own screen blob here from the raw matches. Proven live on
            # dd_ba494e53f850 (Roke Manor) — 11 lists screened CLEAN and
            # `screened_at: None`, so the report rendered "screening date not
            # recorded" while it had just screened them. Sanctions lists change
            # daily; an undated clean is an undatable claim.
            "screened_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        }
        _record_sanctions_screen(report, _screen_blob)   # R-F3535

        classified = _cm(all_matches, query_name=name)
        worst = classified["worst_severity"]

        if worst == "hard_stop":
            report.identity.findings.append(Finding(
                severity="hard_stop",
                title=f"{name} on active sanctions list",
                detail=classified["summary"],
                source="sanctions.person_screen",
                confidence="CONFIRMED",
            ))
            hard_stop = True
        elif worst == "red":
            report.identity.findings.append(Finding(
                severity="red",
                title=f"{name} linked to crime/debarment/ICC list",
                detail=classified["summary"],
                source="sanctions.person_screen",
                confidence="PROBABLE",
            ))
        elif worst == "amber":
            report.identity.findings.append(Finding(
                severity="amber",
                title=f"{name} on PEP / adverse-media list",
                detail=classified["summary"] + " — enhanced DD required on individual before contracting.",
                source="sanctions.person_screen",
                confidence="ASSESSED",
            ))
        elif worst == "info":
            report.identity.findings.append(Finding(
                severity="info",
                title=f"{name} on transparency / officeholder register",
                detail=classified["summary"] + " — informational only, not a refusal ground.",
                source="sanctions.person_screen",
                confidence="ASSESSED",
            ))
        elif _sanctions_unverified:
            # R-F2416: the sanctions/PEP source was unavailable for EVERY name
            # variant, so the screen did NOT run. An empty match list here is
            # NOT a clearance. Write the SANCTIONS_SOURCE_UNVERIFIED marker (the
            # synthesis freshness-gate 6b1 keys off it to force GREEN→AMBER for
            # persons too) and emit an amber UNVERIFIED finding instead of CLEAN.
            report.identity.data_gaps.append(
                "person sanctions screen: SANCTIONS_SOURCE_UNVERIFIED — index "
                "unavailable for all name variants, NOT screened (re-screen "
                "required, not a clearance)"
            )
            report.identity.findings.append(Finding(
                severity="amber",
                title=f"Sanctions + PEP screen UNVERIFIED for {name} — source unavailable",
                detail=(
                    f"The sanctions/PEP index was unavailable for all name variant(s) "
                    f"attempted ({', '.join(_unavailable_variants[:8])}), so {name} could "
                    f"NOT be screened against OFAC SDN, UK OFSI, EU Consolidated, UN 1267, "
                    f"ICC, Interpol Red Notices or OpenSanctions PEP data. Treat as UNKNOWN, "
                    f"NOT a clearance — re-screen when the source is reachable."
                ),
                source="sanctions.person_screen",
                confidence="UNCERTAIN",
            ))
        else:
            report.identity.findings.append(Finding(
                severity="info",
                title=f"Sanctions + PEP screen CLEAN across {len(screened_variants)} name variant(s)",
                detail=(
                    f"No matches for {name} across OFAC SDN, UK OFSI, EU Consolidated, "
                    f"UN 1267, ICC, Interpol Red Notices, or OpenSanctions PEP data. "
                    f"Variants tested: {', '.join(screened_variants[:8])}. "
                    f"This is a POSITIVE CLEAN result — treat as clearance under "
                    f"standard commercial PDD."
                ),
                source="sanctions.person_screen",
                confidence="CONFIRMED",
            ))
        # ── Family/associate edge detection ─────────────────────────────
        # 2026-04-12: if any sanctions match has family/associate relationships,
        # the subject inherits elevated risk (e.g., spouse of sanctioned person).
        for pm in classified.get("per_match") or []:
            match_obj = next((m for m in all_matches if isinstance(m, dict) and m.get("name") == pm.get("name")), None)
            if not match_obj:
                continue
            rels = match_obj.get("relationships") or []
            for rel in rels[:3]:
                kind = rel.get("kind", "relatedTo")
                target = rel.get("target", "unknown")
                # Family of a sanctioned entity inherits red risk
                inherited_sev = "red" if pm["severity"] in ("hard_stop", "red") else "amber"
                report.identity.findings.append(Finding(
                    severity=inherited_sev,
                    title=f"{name} — {kind} link to {target}",
                    detail=(
                        f"OpenSanctions reports {pm['name']} has a '{kind}' "
                        f"relationship with '{target}'. If the related party is "
                        f"sanctioned, {name} inherits elevated risk via association."
                    ),
                    source="sanctions.family_edges",
                    confidence="ASSESSED",
                ))

    except Exception as e:
        logger.warning("Identity (person): sanctions screen failed: %s", e)
        report.identity.findings.append(Finding(
            severity="amber", title="Sanctions screen failed", detail=str(e)[:200],
            source="sanctions", confidence="UNCERTAIN",
        ))
        report.identity.data_gaps.append("sanctions screen did not complete")

    # ── 1c. Role / context hints ──
    if role or organisation:
        report.identity.findings.append(Finding(
            severity="info",
            title=f"Context: {role or 'unknown role'}{' at ' + organisation if organisation else ''}",
            detail=(
                f"Role and employer were supplied with the query. "
                f"These narrow match disambiguation but do NOT substitute "
                f"for verification — the subject's identity must still be "
                f"cross-referenced against the named organisation's own records."
            ),
            source="person_resolver.context",
            confidence="ASSESSED",
        ))

    if dob:
        report.identity.findings.append(Finding(
            severity="info",
            title=f"DOB supplied: {dob}",
            detail="DOB is the highest-value disambiguator for common names.",
            source="person_resolver.context",
            confidence="CONFIRMED",
        ))

    # ── 1d. Data gaps ──
    if not nationality:
        report.identity.data_gaps.append("nationality not supplied — material disambiguator missing")
    if not dob:
        report.identity.data_gaps.append("DOB not supplied — recommended before contracting")
    if not role and not organisation:
        report.identity.data_gaps.append("role/employer not supplied — weakens variant disambiguation")

    # R-F1836 — domain-ownership (RDAP) as a Layer 1 signal, also for persons
    # who claim a personal/company website. Guarded no-op when no domain given.
    await _check_domain_ownership(target, report)

    report.identity.meta.duration_ms = int((time.time() - t0) * 1000)
    report.identity.meta.status = LayerStatus.OK.value
    return hard_stop


# ── R-F602 — Formalised shell-co indicator-row Findings ──────────────
#
# The 12-indicator ghost scorer in due_diligence_playbooks produces a
# rich breakdown but the orchestrator was only surfacing the TOTAL
# (e.g. "Ghost score 12/20 — RED"). The triggered indicator details
# ("Mail-drop address", "No LinkedIn presence", "Nominee director",
# etc.) were locked inside the identity.ghost_score dict and invisible
# to a client reading the report.
#
# This pure helper turns each triggered indicator into its own Finding
# so the report becomes AUDITABLE — a client can challenge "why is
# this scored 2/2 on mail-drop?" by reading the dedicated row.
#
# Cap at 12 (one per indicator). Severity:
#   ratio >= 0.5  → amber  (substantial weight relative to indicator max)
#   ratio <  0.5  → info   (partial trigger)
# GREEN classification → returns [] (don't clutter clean reports).
def _emit_ghost_indicator_findings(ghost: Any) -> list[Finding]:
    """Pure helper: GhostScoreResult → list of auditable indicator Findings.

    Only fires when overall classification is not GREEN. Each TRIGGERED
    indicator (points > 0) becomes its own Finding with severity tied
    to the indicator's weight ratio. Confidence is PROBABLE because the
    scoring model is heuristic, not Tier-1a authoritative.
    """
    if not ghost or not hasattr(ghost, "classification"):
        return []
    if ghost.classification == "GREEN":
        return []
    out: list[Finding] = []
    triggered = ghost.triggered() if hasattr(ghost, "triggered") else []
    for ind in triggered[:12]:
        ratio = (ind.points / max(ind.max_points, 1)) if ind.max_points else 0.0
        severity = "amber" if ratio >= 0.5 else "info"
        detail = (
            ind.reason
            if ind.reason
            else f"Indicator triggered at {ind.points}/{ind.max_points} weight."
        )
        out.append(Finding(
            severity=severity,
            title=f"Ghost indicator #{ind.id}: {ind.label} ({ind.points}/{ind.max_points})",
            detail=detail,
            source="due_diligence_playbooks.score_ghost_indicators",
            confidence="PROBABLE",
        ))
    return out


# ── R-F600 — Formalised litigation / court-record Findings ────────────
#
# court_records (R-F584) + dd_layer_extensions (R-F584/F585/F586/F587)
# already query CourtListener (US) + BAILII (UK) and stash the result
# inside `report.extensions["by_module"]["court_records"]` — but the
# individual case hits never surface as Findings rows in any report
# section. A client reading the DD report sees "litigation_history"
# under "extensions" (if at all) but no auditable "Smith v. ABC Corp
# · 2024-03-15 · S.D.N.Y." rows.
#
# This pure helper turns each hit into a Finding so the litigation
# history appears as first-class evidence in compliance, alongside
# FATF (R-F601) and shell-co indicators (R-F602).
#
# Severity:
#   ELEVATED (any US federal court hit) → amber headline + amber per-case
#   LOW (non-federal / BAILII only)     → info headline + info per-case
#   NONE                                → returns [] (no clutter)
#
# Confidence: PROBABLE. Court records are Tier-1a authoritative, but
# fuzzy-name matches need human disambiguation (the headline ALWAYS
# notes "verify name match against the entity"). Using PROBABLE
# bypasses the R-5005 gate's CONFIRMED→ASSESSED demotion path.
def _emit_court_record_findings(court_records_block: Any) -> list[Finding]:
    """Pure helper: court_records extension result → list of Findings.

    Inputs: the dict produced by
        dd_layer_extensions.run_court_records_check(...) or its slot in
        run_all_extensions()["by_module"]["court_records"]. Tolerates
        None / empty / missing fields.

    Returns at most 1 + 5 Findings:
      - 1 headline summarising us_count + uk_count
      - up to 5 individual case rows with citation URL inline
    """
    if not court_records_block or not isinstance(court_records_block, dict):
        return []
    hits = court_records_block.get("hits") or []
    # Defensive: upstream contract says list[dict] but tolerate garbage
    if not isinstance(hits, list):
        return []
    # ── R-F3102 — A COURT SEARCH THAT DID NOT RUN IS NOT A CLEAN LITIGATION FILE ──
    #
    # This function returned [] whenever `hits` was empty — and court_records
    # erased a FAILED fetch to an empty list, calling it "an honest zero-result".
    # So CourtListener and BAILII both being down produced zero findings AND zero
    # data gaps: no litigation section, and no disclosure that litigation was never
    # checked. Now the adapter reports coverage, this reads it and says so.
    _failed = court_records_block.get("sources_failed") or []
    if _failed and not hits:
        _names = ", ".join(str(f.get("source") or "?") for f in _failed if isinstance(f, dict))
        return [Finding(
            severity="info",
            title="Litigation search did NOT complete — coverage unknown",
            detail=(
                f"The court-record search could not reach: {_names}. No litigation "
                "hits are shown because the sources did not answer, NOT because none "
                "exist. Treat litigation exposure as UNCHECKED, not clear, and re-run "
                "or search the relevant court registers directly."
            ),
            source="sources.court_records:R-F3102",
            confidence="UNVERIFIED",
        )]
    severity_label = (court_records_block.get("severity") or "NONE").upper()
    if severity_label == "NONE" or not hits:
        return []
    us_count = int(court_records_block.get("us_count") or 0)
    uk_count = int(court_records_block.get("uk_count") or 0)
    headline_severity = "amber" if severity_label == "ELEVATED" else "info"
    out: list[Finding] = []

    # Headline row
    summary = court_records_block.get("summary") or (
        f"Litigation history: {us_count} US case(s), {uk_count} UK/BAILII case(s)."
    )
    out.append(Finding(
        severity=headline_severity,
        title=f"Litigation history: {us_count} US · {uk_count} UK case(s)",
        detail=(
            summary
            + " VERIFY each case is the same entity (court records are "
            "Tier-1a authoritative but fuzzy-name matches require human "
            "disambiguation against the registered legal name)."
        ),
        source=(
            "dd_layer_extensions.run_court_records_check "
            "[from https://www.courtlistener.com + https://www.bailii.org]"
        ),
        confidence="PROBABLE",
    ))

    # Per-case rows — cap at 5 (the extension dict already enforces this
    # but defending the helper too).
    for hit in hits[:5]:
        if not isinstance(hit, dict):
            continue
        title = (hit.get("title") or "").strip() or "Untitled case"
        court = (hit.get("court") or "").strip() or "?"
        date = (hit.get("date") or "").strip() or "?"
        citation_url = (hit.get("citation_url") or "").strip()
        snippet = (hit.get("snippet") or "").strip()
        jurisdiction = (hit.get("jurisdiction") or "?").strip()
        source_name = (hit.get("source") or "court_records").strip()
        # Federal-court detection — narrowed from run_court_records_check
        # to avoid false-firing on "New York Supreme Court" (which is a
        # state trial court). Federal cases always carry one of the
        # specific federal-jurisdiction markers below.
        federal_kw = ("U.S.", "S.D.", "E.D.", "N.D.", "W.D.", "D.C.",
                      "Cir.", "Federal", "U.S. Supreme")
        is_federal = any(k in court for k in federal_kw)
        # Severity escalates for federal court hits
        case_severity = "amber" if (severity_label == "ELEVATED" and is_federal) else "info"

        detail_bits = [f"Court: {court}", f"Date: {date}"]
        if snippet:
            detail_bits.append(f"Snippet: {snippet[:240]}")
        if citation_url:
            detail_bits.append(f"URL: {citation_url}")
        out.append(Finding(
            severity=case_severity,
            title=f"Litigation [{jurisdiction}] {title[:120]}",
            detail=" · ".join(detail_bits),
            # R-F2691 — the `[from {url}]` suffix STAYS. It looks like string-stuffing
            # that the new `url` field supersedes, and this R-number originally removed
            # it — but MEASURED, it is LOAD-BEARING (R-F600 codified it for a reason):
            #   origin_key("bailii [from https://www.bailii.org/…]") -> "pub:bailii.org"
            #   origin_key("bailii")                                 -> "external_unclassified"
            #   _is_tier_1a_source(...)                              -> True vs FALSE
            # The Tier-1a allowlist matches DOMAINS, so the embedded url is what lets a
            # court-record source resolve to a real publisher and clear the R-5005 gate.
            # Stripping it would silently demote these findings to ASSESSED and collapse
            # every bare source name into ONE 'external_unclassified' origin — corrupting
            # the C-3 independent-origin count. Teaching origin_key/_is_tier_1a_source to
            # read `url` first is the real fix; that touches the tier gate + ~127 sites
            # and is NOT this R-number.
            source=(
                f"{source_name} [from {citation_url}]"
                if citation_url else source_name
            ),
            # Additive: the same provenance, now machine-readable instead of only
            # recoverable by parsing a display string.
            url=citation_url or None,
            # Court records are primary official documents when we have the citation;
            # without one we cannot claim that tier, so stay UNKNOWN rather than
            # asserting authority we cannot show.
            source_tier="OFFICIAL" if citation_url else "UNKNOWN",
            confidence="PROBABLE",
        ))

    return out


# ── R-F610 — Formalised maritime AIS dark-voyage Findings ─────────────
#
# ais_gap_detector (R-F587) already runs inside dd_layer_extensions.
# run_ais_gap_check when the target carries `ais_positions` /
# `vessel_positions` — but the result (vessel_id + total_gaps +
# longest_gap_h + score + signals + severity) sits inside
# report.extensions["by_module"]["ais_gap_detector"] and never
# becomes a Finding row on report.compliance. Same pattern R-F600
# fixed for court records.
#
# This pure helper turns the AIS analysis into auditable Findings
# so dark-voyage indicators surface as first-class evidence in
# compliance alongside FATF (R-F601) + shell-co (R-F602) +
# litigation (R-F600).
#
# Severity:
#   ELEVATED (score ≥50 or any critical gap) → amber headline + amber signals
#   LOW (score 15..49)                       → info everything
#   NONE / no vessel data                    → []
#
# Confidence: PROBABLE. AIS gaps are factual (positions either exist
# or don't), but interpretation requires human assessment of context
# (legitimate maintenance vs sanctions-evasion). Bypasses the R-5005
# CONFIRMED→ASSESSED gate path.
def _emit_ais_findings(ais_block: Any) -> list[Finding]:
    """Pure helper: ais_gap_detector extension result → list of Findings.

    Inputs: dict from dd_layer_extensions.run_ais_gap_check(...) or
        its slot in by_module["ais_gap_detector"]. Tolerates None /
        empty / missing fields.

    Returns at most 1 + 5 Findings:
      - 1 headline: total_gaps + longest_gap_h + score
      - up to 5 individual signal rows
    """
    if not ais_block or not isinstance(ais_block, dict):
        return []
    severity_label = (ais_block.get("severity") or "NONE").upper()
    if severity_label == "NONE":
        return []
    signals_raw = ais_block.get("signals") or []
    if not isinstance(signals_raw, list):
        signals_raw = []
    headline_severity = "amber" if severity_label == "ELEVATED" else "info"
    vessel_id = ais_block.get("vessel_id") or "(unspecified)"
    total_gaps = int(ais_block.get("total_gaps") or 0)
    longest_gap_h = ais_block.get("longest_gap_h") or 0
    score = int(ais_block.get("score") or 0)

    out: list[Finding] = []

    # Headline row
    out.append(Finding(
        severity=headline_severity,
        title=(
            f"Maritime AIS [vessel={vessel_id}]: {total_gaps} gap(s), "
            f"longest {longest_gap_h}h, score {score}/100"
        ),
        detail=(
            f"AIS-gap analysis flagged {total_gaps} transponder gap(s); "
            f"longest gap {longest_gap_h}h; suspicion score {score}/100. "
            "AIS-off periods can indicate legitimate operations (port "
            "stay, antenna failure) OR sanctions-evasion / illicit "
            "trade. VERIFY by cross-referencing port-call records and "
            "AIS-on resumption coordinates against declared voyage."
        ),
        source=(
            "ais_gap_detector.detect_gaps (R-F587) "
            "[from vessel AIS positions in target]"
        ),
        confidence="PROBABLE",
    ))

    # Per-signal rows — cap at 5
    for sig in signals_raw[:5]:
        if not isinstance(sig, str) or not sig.strip():
            continue
        sig_lower = sig.lower()
        # Severity escalates for critical-tagged signals
        is_critical = (
            "critical" in sig_lower
            or "dark" in sig_lower
            or "anomal" in sig_lower
        )
        sig_severity = (
            "amber" if (severity_label == "ELEVATED" and is_critical)
            else "info"
        )
        out.append(Finding(
            severity=sig_severity,
            title=f"AIS signal: {sig[:120]}",
            detail=(
                f"Signal flagged by ais_gap_detector for vessel "
                f"{vessel_id}. Treat as indicator, not verdict — "
                "operator must contextualise."
            ),
            source="ais_gap_detector.detect_gaps (R-F587)",
            confidence="PROBABLE",
        ))

    return out


# ── R-F611 — Formalised cyber/cert-transparency Findings ─────────────
#
# cert_transparency (R-F585) inspects Certificate Transparency logs for
# the counterparty's domain and scores a "shell-broker fingerprint"
# (many apex domains, one issuer, short-lived certs, identical-name
# clusters). Output sits in report.extensions["by_module"][
# "cert_transparency"] but never becomes a Finding row. Same gap
# pattern R-F600 (litigation) / R-F610 (AIS) fixed.
#
# This pure helper turns the CT analysis into auditable Findings.
#
# Severity:
#   ELEVATED (shell_score ≥60) → amber headline + amber per-signal
#   LOW (shell_score 30..59)   → info everything
#   NONE / no domain inferable → []
#
# Confidence: PROBABLE. CT logs are factual (a cert exists or doesn't)
# but the shell-broker FINGERPRINT is a heuristic — needs operator
# corroboration with other indicators.
def _emit_cert_transparency_findings(ct_block: Any) -> list[Finding]:
    """Pure helper: cert_transparency extension result → list of
    Findings. Tolerates None / empty / missing fields.

    Returns at most 1 + 5 Findings:
      - 1 headline: cert_count + apex_count + shell_score
      - up to 5 individual signal rows
    """
    if not ct_block or not isinstance(ct_block, dict):
        return []
    severity_label = (ct_block.get("severity") or "NONE").upper()
    if severity_label == "NONE":
        return []
    # ── R-F3127 — DO NOT COERCE AN UNKNOWN SCORE BACK INTO A CLEAN ZERO ─────
    #
    # R-F3106 made `run_cert_transparency_check` refuse to score an unreachable
    # crt.sh: severity "UNKNOWN", shell_score None. This RENDERER then undid it —
    # `int(ct_block.get("shell_score") or 0)` turns None into 0, and "UNKNOWN" is not
    # "NONE" so the early return never fired. Live on the QinetiQ DD (2026-07-26) the
    # report therefore carried BOTH:
    #     "Cyber footprint [qinetiq.com]: 0 cert(s) … shell-score 0/100"   (PROBABLE)
    #     "CT signal: source_unavailable"
    # — a measured clean and an admission that nothing was measured, side by side.
    # Same two-writer shape as R-F3116: the producer was fixed, the renderer was not.
    if severity_label == "UNKNOWN" or ct_block.get("shell_score") is None:
        return [Finding(
            severity="info",
            title="Certificate-transparency check did NOT complete — no shell score",
            detail=(
                f"The CT lookup for '{ct_block.get('query') or '(unknown)'}' did not "
                f"return usable data ({ct_block.get('outcome') or 'source unavailable'}). "
                "NO shell-broker score was computed — this is UNCHECKED, not a clean "
                "0/100. Absence of a certificate footprint here is an absence of "
                "COVERAGE, not evidence of good standing."
            ),
            source="cert_transparency.detect_shell_pattern:R-F3127",
            confidence="UNVERIFIED",
        )]
    signals_raw = ct_block.get("signals") or []
    if not isinstance(signals_raw, list):
        signals_raw = []
    headline_severity = "amber" if severity_label == "ELEVATED" else "info"
    query = ct_block.get("query") or "(unknown)"
    cert_count = int(ct_block.get("cert_count") or 0)
    apex_count = int(ct_block.get("apex_count") or 0)
    issuer_count = int(ct_block.get("issuer_count") or 0)
    shell_score = int(ct_block.get("shell_score") or 0)

    out: list[Finding] = []

    # Headline row
    out.append(Finding(
        severity=headline_severity,
        title=(
            f"Cyber footprint [{query}]: {cert_count} cert(s), "
            f"{apex_count} apex domain(s), {issuer_count} issuer(s), "
            f"shell-score {shell_score}/100"
        ),
        detail=(
            f"Certificate Transparency log analysis for '{query}': "
            f"{cert_count} certificates across {apex_count} apex "
            f"domains, issued by {issuer_count} distinct CA(s). "
            f"Shell-broker fingerprint score: {shell_score}/100. "
            "High scores indicate domain-spinning patterns common in "
            "shell-broker / typo-squat networks. VERIFY by inspecting "
            "the actual cert SAN list before flagging the counterparty."
        ),
        source=(
            "cert_transparency.detect_shell_pattern (R-F585) "
            "[from https://crt.sh log feed]"
        ),
        confidence="PROBABLE",
    ))

    # Per-signal rows — cap at 5
    for sig in signals_raw[:5]:
        if not isinstance(sig, str) or not sig.strip():
            continue
        sig_lower = sig.lower()
        # Critical signals: many apex domains with one issuer / short-lived
        # / identical-name clusters
        is_critical = any(k in sig_lower for k in (
            "shell", "typo", "squat", "cluster", "many_apex", "one_issuer",
            "short_lived", "anomal", "suspicious",
        ))
        sig_severity = (
            "amber" if (severity_label == "ELEVATED" and is_critical)
            else "info"
        )
        out.append(Finding(
            severity=sig_severity,
            title=f"CT signal: {sig[:120]}",
            detail=(
                f"Signal flagged by cert_transparency.detect_shell_pattern "
                f"for query '{query}'. Treat as indicator, not verdict — "
                "operator must corroborate with other DD evidence."
            ),
            source="cert_transparency.detect_shell_pattern (R-F585)",
            confidence="PROBABLE",
        ))

    return out


# ── R-F612 — Formalised ECCN keyword-indicator Findings ──────────────
#
# eccn_lookup (R-F581) is a deterministic keyword→ECCN lookup against
# the BIS Commerce Control List + Wassenaar Munitions List. When the
# extension wrapper (R-F586) returns hits, they sit in
# report.extensions["by_module"]["eccn_lookup"] but never become
# Finding rows on report.compliance. Same gap pattern fixed by
# R-F600/F610/F611 — last of the R-F584-F587 bundle to surface.
#
# Severity:
#   ELEVATED (max_count ≥ 2) → amber headline + amber per-hit
#   LOW (max_count 1)        → info everything
#   NONE                     → []
#
# Confidence: PROBABLE. Per Clause 3 + Clause 14: ECCN match is an
# INDICATOR, not a legal determination. Operator must consult
# licensed export counsel before sharing externally — this is
# baked into the detail text on EVERY hit.
def _emit_eccn_findings(eccn_block: Any) -> list[Finding]:
    """Pure helper: eccn_lookup extension result → list of Findings.

    Tolerates None / empty / missing fields. Each hit becomes a
    Finding citing the BIS / Wassenaar reference URL inline per
    Clause 15.
    """
    if not eccn_block or not isinstance(eccn_block, dict):
        return []
    severity_label = (eccn_block.get("severity") or "NONE").upper()
    if severity_label == "NONE":
        return []
    hits = eccn_block.get("hits") or []
    if not isinstance(hits, list) or not hits:
        return []
    headline_severity = "amber" if severity_label == "ELEVATED" else "info"
    out: list[Finding] = []

    # Headline summarising the hits
    summary = eccn_block.get("summary") or (
        f"{len(hits)} potential ECCN match(es) detected"
    )
    out.append(Finding(
        severity=headline_severity,
        title=f"Export-control indicator: {len(hits)} ECCN match(es)",
        detail=(
            f"{summary} "
            "INDICATOR ONLY — not a legal classification. Operator MUST "
            "consult licensed export counsel before applying for an "
            "export licence or sharing this assessment externally. "
            "Reference URLs link to the public BIS / Wassenaar source."
        ),
        source=(
            "eccn_lookup.lookup_by_keyword (R-F581) "
            "[from BIS Commerce Control List + Wassenaar Munitions List]"
        ),
        confidence="PROBABLE",
    ))

    # Per-hit rows — cap at 5
    for hit in hits[:5]:
        if not isinstance(hit, dict):
            continue
        eccn = (hit.get("eccn") or "").strip() or "?"
        title = (hit.get("title") or "").strip() or "(unnamed)"
        regime = (hit.get("regime") or "").strip()
        ref_url = (hit.get("reference_url") or "").strip()
        match_count = int(hit.get("match_count") or 0)
        match_kw = hit.get("match_keywords") or []
        if not isinstance(match_kw, list):
            match_kw = []
        kw_str = ", ".join(str(k) for k in match_kw[:5])
        # Severity escalates for high match-count
        hit_severity = (
            "amber" if (severity_label == "ELEVATED" and match_count >= 2)
            else "info"
        )

        detail_parts = []
        if regime:
            detail_parts.append(f"Regime: {regime}")
        if kw_str:
            detail_parts.append(f"Matched keywords: {kw_str}")
        detail_parts.append(f"Match count: {match_count}")
        detail_parts.append(
            "INDICATOR — operator consults licensed export counsel "
            "before any licensing decision."
        )
        if ref_url:
            detail_parts.append(f"Reference: {ref_url}")

        out.append(Finding(
            severity=hit_severity,
            title=f"ECCN indicator: {eccn} — {title[:100]}",
            detail=" · ".join(detail_parts),
            source=(
                f"eccn_lookup.lookup_by_keyword (R-F581) "
                f"[from {ref_url}]" if ref_url
                else "eccn_lookup.lookup_by_keyword (R-F581)"
            ),
            confidence="PROBABLE",
        ))

    return out


async def _check_domain_ownership(target: dict, report: ARKDDReport) -> None:
    """R-F1836 — Domain-ownership (RDAP) verification, run as a Layer 1
    (identity) signal.

    Moved here from the digital layer (was section 5e-bis in _run_digital):
      * Domain ownership is an IDENTITY question — who really owns the website an
        entity claims to operate is a who-are-they signal, best surfaced up front.
      * The digital layer is SKIPPED ENTIRELY in quick mode and whenever the
        identity layer hard-stops, so the check (whose own note said it was
        "worth having in quick mode too") never actually ran in those paths.
        Layer 1 always runs and runs BEFORE the hard-stop short-circuit, so the
        RDAP signal now fires in every mode.

    Cheap (one HTTPS call) and guarded — a no-op when the target carries no
    URL/domain. Reads the claimed jurisdiction from report.identity (already set
    earlier in the identity layer), so there is no cross-layer dependency/race
    (the old placement read report.identity.jurisdiction from a different layer).
    """
    name = (
        report.identity.entity_name
        or target.get("name") or target.get("entity")
        or target.get("query") or ""
    )
    _dom_candidate = (
        target.get("website")
        or target.get("domain")
        or target.get("url")
        or ""
    )
    # If the DD target itself looks like a URL (operator typed "run dd on
    # https://f3ir.com/"), pick it up here.
    if not _dom_candidate:
        for fld in ("name", "entity", "query"):
            v = target.get(fld) or ""
            if isinstance(v, str) and ("://" in v or (v.count(".") >= 1 and " " not in v and len(v) < 120)):
                if "://" in v or v.endswith((".com", ".net", ".org", ".io", ".co",
                                             ".ai", ".uk", ".de", ".fr", ".eu",
                                             ".ae", ".sa", ".qa", ".ru", ".cn",
                                             ".tr", ".br", ".ng", ".ma", ".za",
                                             ".ir")):
                    _dom_candidate = v
                    break
    if not _dom_candidate:
        return
    try:
        from . import domain_ownership_verifier as dov
        dom_result = await dov.verify_domain(
            _dom_candidate,
            claimed_entity_name=name,
            claimed_jurisdiction=(
                report.identity.jurisdiction_iso2
                or report.identity.jurisdiction
                or target.get("jurisdiction_iso2")
                or target.get("jurisdiction")
            ),
        )
        if dom_result.get("verified"):
            flags = dom_result.get("flags") or []
            sev = dov.severity_for(dom_result)
            # Preserve the original escalation intent: an entity mismatch, an
            # unregistered domain, or a brand-new registration are hard-stop-
            # worthy identity signals → red (severity_for maps the last to amber).
            if any(f in flags for f in (
                "REGISTRANT_ENTITY_MISMATCH",
                "DOMAIN_NOT_REGISTERED",
                "VERY_RECENTLY_REGISTERED",
            )):
                sev = "red"
            body = dov.render_finding(dom_result)
            report.identity.findings.append(Finding(
                severity=sev,
                title=f"Domain ownership (RDAP): {dom_result['domain']} — flags: {', '.join(flags) or 'none'}",
                detail=body + ("\n" + "\n".join(dom_result.get("signals") or []) if dom_result.get("signals") else ""),
                source="dd_orchestrator.domain_ownership_verifier",
                confidence="CONFIRMED",
            ))
        elif dom_result.get("reason"):
            report.identity.data_gaps.append(
                f"Domain RDAP check inconclusive for {dom_result.get('domain') or _dom_candidate}: {dom_result['reason']}"
            )
    except Exception as e:
        logger.debug("domain_ownership_verifier failed (non-fatal): %s", e)


# ── R-F3134: SEC form categories — not every EDGAR filing carries financials ──
#
# THE DEFECT, live on the Babcock DD (dd_8c7242c2b45b), two CONFIRMED findings in one
# report:
#     Identity   "SEC filings found: 5 recent (Babcock International Group PLC/ADR)
#                 Most recent: F-6EF filed 2025-03-19.
#                 FULL FILINGS AVAILABLE FOR FINANCIAL DD REVIEW."
#     Compliance "Financial health — no US-listed (SEC EDGAR) filings
#                 No SEC/EDGAR financials available — UNKNOWN, not a clean bill."
#
# A reader cannot reconcile those, and reasonably concludes one section is broken. The
# COMPLIANCE layer was right. An F-6EF is a registration statement filed by a DEPOSITARY
# BANK to register American Depositary Receipts — the "/ADR" on the entity name is the
# tell. It contains NO financial statements whatever. Babcock is UK-listed and is not a
# US reporting issuer; its accounts live at Companies House.
#
# So the identity prose promised financial-DD material that the form category CANNOT
# contain — the same shape as R-F3129's sanctions clearance offered on coverage nothing
# evidenced. The filings ARE real (do not go silent; that is R-F1696 in reverse), but
# what they are must be stated, and the financial-review promise withheld unless a form
# that actually carries statements is present.
_SEC_FINANCIAL_STATEMENT_FORMS = frozenset({
    "10-K", "10-K/A", "10-KSB", "10-Q", "10-Q/A",      # US domestic reporting issuers
    "20-F", "20-F/A", "40-F", "40-F/A",                # foreign private issuers
})

# What the common NON-financial forms actually are, so the report says something a
# reader can act on instead of a bare form code.
_SEC_FORM_MEANING = {
    "F-6": "ADR depositary registration (no financial statements)",
    "F-6EF": "ADR depositary registration, immediately effective (no financial statements)",
    "F-6 POS": "post-effective amendment to an ADR registration (no financial statements)",
    "SC 13D": "beneficial-ownership disclosure filed by a third party",
    "SC 13G": "passive beneficial-ownership disclosure filed by a third party",
    "13F-HR": "institutional holdings report filed by an investment manager",
    "4": "insider transaction report",
    "3": "initial insider holdings report",
    "5": "annual insider transaction report",
    "S-8": "employee benefit-plan share registration",
    "6-K": "foreign private issuer interim report (may or may not contain financials)",
    "8-K": "material-event report",
}


def _sec_form_summary(hits: list) -> tuple:
    """Return (forms_present, has_financial_statements, description).

    `hits` are sec_edgar filing dicts. Returns the DISTINCT forms in filing order, a
    flag for whether any of them is a form that carries financial statements, and a
    human description of the non-financial ones.
    """
    forms = []
    for h in hits:
        f = str((h or {}).get("form") or "").strip()
        if f and f not in forms:
            forms.append(f)
    has_fin = any(f in _SEC_FINANCIAL_STATEMENT_FORMS for f in forms)
    described = [
        f"{f} — {_SEC_FORM_MEANING[f]}" for f in forms if f in _SEC_FORM_MEANING
    ]
    return forms, has_fin, "; ".join(described)


async def _identity_primary_source_screen(
    name: str, jurisdiction: "str | None", report: ARKDDReport,
) -> bool:
    """R-F1844 — extracted from _run_identity (was the inline 1a1 block).

    Runs the six primary-source sanctions/debarment/event screens (SEC, OFAC,
    UK OFSI, UN SC, World Bank, ACLED) in parallel, applies the R-F569
    name-overlap gate, and appends findings to report.identity. Pure
    extraction: behaviour is identical to the prior inline block. Returns
    True iff a hard-stop was triggered (the caller OR-combines it).
    """
    hard_stop = False
    # ── 1a1. Primary-source parallel screen (SEC, OFAC, OFSI, UN, WB, ACLED) ──
    # Added 2026-04-18 after the DD-depth audit. The OpenSanctions call
    # above is convenient but aggregation-lagged; these six direct primary
    # sources run in parallel and surface findings with canonical
    # citations. Each source is wrapped in an individual try so one
    # failure cannot block the others. ~2-4s added to identity layer
    # worst-case (all six fetched in parallel, cached heavily).
    #
    # R-F569 (2026-05-16) — name-overlap gate on the per-source HARD_STOP
    # emissions below. Pre-R-F569 each adapter's `_hits[0]` was emitted
    # verbatim as a HARD_STOP finding with no similarity check beyond the
    # adapter's own internal fuzzy_filter threshold (0.70 for ofac_sdn —
    # too liberal). Live MVP fire-test 2026-05-16 logged
    #   Embraer S.A. → OFAC SDN "MARANER HOLDINGS LIMITED"  (false)
    #   Aselsan A.S. → OFAC SDN "Guillermo NIEBLAS NAVA"     (false)
    #   Aselsan A.S. → UN SC    "ALI SADDAM HUSSEIN AL-TIKRITI" (false)
    #   Acme Widgets → OFAC SDN "TAMIN KALAYE SABZ ARAS COMPANY" (false on fake input)
    # The gate below reuses _sanctions_classify._tokenize_entity_name /
    # _name_overlap (R-F277 / R-F351) so the per-source path applies the
    # same token-overlap discipline the topic-classifier already uses.
    # A hit is allowed to remain HARD_STOP only when it shares ≥1
    # meaningful 5+ char token with the query OR scores ≥0.95.
    from ._sanctions_classify import (
        _tokenize_entity_name as _r569_tokenize,
        _name_overlap as _r569_overlap,
    )

    def _r569_is_real_sanctions_hit(_hit: dict, _query: str) -> tuple[bool, str]:
        """Return (is_real_match, reason). False if the hit is fuzzy noise."""
        if not isinstance(_hit, dict) or not _query:
            return True, ""  # defensive — don't accidentally suppress
        _cand = (
            _hit.get("name") or _hit.get("primary_name")
            or _hit.get("full_name") or _hit.get("caption") or ""
        )
        if not _cand:
            return True, ""
        # Exact-or-near-exact scores bypass the gate (1.0 = identical
        # normalised form, ≥0.95 = trivial spelling/punctuation drift).
        _score = float(_hit.get("_match_score") or _hit.get("score") or 0.0)
        if _score >= 0.95:
            return True, f"score≥0.95 ({_score:.2f}) bypasses overlap gate"
        # Token-overlap discipline: at least one shared token ≥5 chars.
        _q_tokens = _r569_tokenize(_query)
        _c_tokens = _r569_tokenize(_cand)
        _shared = _q_tokens & _c_tokens
        if not _shared:
            return False, f"zero token overlap (query={list(_q_tokens)[:3]}, candidate={list(_c_tokens)[:3]})"
        # Single-overlap on short token = high false-positive risk (R-F351 pattern).
        if len(_shared) == 1:
            _only = next(iter(_shared))
            if len(_only) < 5:
                return False, f"single short-token overlap ('{_only}', <5 chars)"
        return True, f"shared tokens: {sorted(_shared)[:3]}"

    try:
        from .sources import (
            sec_edgar as _src_sec,
            ofac_sdn as _src_ofac,
            fcdo_sanctions as _src_ofsi,
            un_sc_sanctions as _src_un,
            worldbank_debarred as _src_wb,
            acled as _src_acled,
        )
        _src_results = await asyncio.gather(
            _src_sec.lookup(name),
            _src_ofac.lookup(name),
            _src_ofsi.lookup(name),
            _src_un.lookup(name),
            _src_wb.lookup(name),
            _src_acled.lookup(name, country=(jurisdiction or "")),
            return_exceptions=True,
        )
        _src_labels = ["sec_edgar", "ofac_sdn", "uk_ofsi", "un_sc", "wb_debarred", "acled"]

        # R-F3512 — capture the RAW adapter responses when recording is enabled, so a
        # replayable gold corpus can exist. Off by default; a normal customer DD writes
        # nothing. Enveloped as personal data (R-F3488) so it is erasable and visible to
        # retention review rather than becoming an unmanaged store.
        try:
            from .dd_evidence_recorder import record_source_results as _rec3512
            _rec3512(
                run_id=str(getattr(report, "run_id", "") or "unknown"),
                subject_name=str(name or ""),
                subject_key=str(getattr(report.identity, "canonical_entity_id", "")
                                or getattr(report, "canonical_entity_id", "") or ""),
                jurisdiction=str(jurisdiction or ""),
                labels=_src_labels,
                results=list(_src_results),
            )
        except Exception as _rec_e:  # noqa: BLE001 — capture never costs a report
            logger.debug("[R-F3512] evidence recording skipped: %s", _rec_e)

        # R-F2843 — record whether ARIA's OWN snapshot of each primary list was live.
        # This is provenance, never a status change: the aggregate screen and our own
        # adapters are DIFFERENT checks and can disagree about availability (live run
        # dd_06bdbcaaa866 cleared OFAC via the aggregate while our OFAC snapshot failed
        # to load). Only observed results are recorded — an unstamped source asserts
        # nothing, because defaulting to "ok" would claim a check we never made.
        _primary_snapshots: dict = {}
        for _lbl, _r in zip(_src_labels, _src_results):
            if isinstance(_r, Exception):
                logger.debug("Identity: primary source %s raised: %s", _lbl, _r)
                report.identity.data_gaps.append(f"primary source {_lbl} did not complete")
                _primary_snapshots[_lbl] = "unavailable"
                continue
            if not isinstance(_r, dict):
                continue
            report.identity.meta.subcalls += 1
            _primary_snapshots[_lbl] = "ok" if _r.get("ok") else "unavailable"

            if not _r.get("ok"):
                if _r.get("error"):
                    # R-F3092 — was `[:120]`, which cut the wb_debarred gap at
                    # "…apigwext.worldbank.org returns 403). De" — mid-word, and it
                    # amputated the two clauses that matter most: that the signal is
                    # covered via the OpenSanctions dataset and that NO OPERATOR
                    # ACTION IS REQUIRED. A gap truncated before its resolution reads
                    # as an unresolved gap. Truncate on a boundary, and only when the
                    # text is genuinely long.
                    report.identity.data_gaps.append(
                        f"{_lbl}: {_truncate_on_boundary(str(_r.get('error')))}"
                    )
                continue

            # R-F2167: a source that served a STALE / un-refreshed snapshot did
            # NOT screen against current data. Surface it as an UNVERIFIED gap +
            # an amber finding so an empty hit-list is never read as a clearance
            # — the silent false-negative this direct-adapter loop shares with
            # the OpenSanctions-aggregate path already guarded by R-F1696. The
            # synthesis freshness-gate keys off the SANCTIONS_SOURCE_UNVERIFIED
            # marker to force the headline non-GREEN.
            if _r.get("stale") or _r.get("source_unavailable"):
                report.identity.data_gaps.append(
                    f"{_lbl}: SANCTIONS_SOURCE_UNVERIFIED — served stale/unavailable "
                    f"data, NOT freshly screened (re-screen required, not a clearance)"
                )
                report.identity.findings.append(Finding(
                    severity="amber",
                    title=f"Primary sanctions source {_lbl} NOT freshly screened — UNVERIFIED",
                    detail=(
                        f"The {_lbl} feed was unavailable; the screen ran against a "
                        f"stale cached snapshot, so a newly-designated entity may be "
                        f"absent. This is NOT a clearance — re-screen when reachable."
                    ),
                    source=f"sources.{_lbl}",
                    confidence="UNCERTAIN",
                ))
                # An empty result on stale data must NOT read as clean. If the
                # stale snapshot DID match, fall through to surface the hit too.
                if not (_r.get("hits") or []):
                    continue

            _hits = _r.get("hits") or []
            if not _hits:
                continue

            # ── Severity mapping per source (semantics differ) ──
            if _lbl == "ofac_sdn":
                _best = _hits[0]
                _real, _reason = _r569_is_real_sanctions_hit(_best, name)
                if _real:
                    report.identity.findings.append(Finding(
                        severity="hard_stop",
                        title=f"OFAC SDN match: {_best.get('name','?')}",
                        detail=(
                            f"Match score {_best.get('_match_score', 0):.2f}. "
                            f"Programme(s): {', '.join(_best.get('programs', []))}. "
                            f"Designated {_best.get('designation_date','?')}. "
                            f"50-percent-rule applies to subsidiaries. "
                            f"R-F569 gate: {_reason}."
                        ),
                        source="sources.ofac_sdn",
                        confidence="CONFIRMED" if _best.get("_match_score", 0) >= 0.9 else "PROBABLE",
                    ))
                    hard_stop = True
                else:
                    # R-F569: fuzzy noise — surface for operator review at INFO level
                    # so it doesn't block but stays auditable.
                    report.identity.findings.append(Finding(
                        severity="info",
                        title=f"OFAC SDN fuzzy hit (filtered): {_best.get('name','?')}",
                        detail=(
                            f"Match score {_best.get('_match_score', 0):.2f}, "
                            f"but R-F569 name-overlap gate rejected: {_reason}. "
                            f"Not a refusal ground; surfaced for operator audit."
                        ),
                        source="sources.ofac_sdn",
                        confidence="ASSESSED",
                    ))

            elif _lbl == "un_sc":
                _best = _hits[0]
                _real, _reason = _r569_is_real_sanctions_hit(_best, name)
                if _real:
                    report.identity.findings.append(Finding(
                        severity="hard_stop",
                        title=f"UN Security Council match: {_best.get('name','?')}",
                        detail=(
                            f"Match score {_best.get('_match_score', 0):.2f}. "
                            f"Regime: {_best.get('regime','?')}. "
                            f"Listed {_best.get('designation_date','?')}. "
                            f"R-F569 gate: {_reason}."
                        ),
                        source="sources.un_sc_sanctions",
                        confidence="CONFIRMED" if _best.get("_match_score", 0) >= 0.9 else "PROBABLE",
                    ))
                    hard_stop = True
                else:
                    report.identity.findings.append(Finding(
                        severity="info",
                        title=f"UN SC fuzzy hit (filtered): {_best.get('name','?')}",
                        detail=(
                            f"Match score {_best.get('_match_score', 0):.2f}, "
                            f"but R-F569 name-overlap gate rejected: {_reason}. "
                            f"Not a refusal ground; surfaced for operator audit."
                        ),
                        source="sources.un_sc_sanctions",
                        confidence="ASSESSED",
                    ))

            elif _lbl == "uk_ofsi":
                _best = _hits[0]
                _real, _reason = _r569_is_real_sanctions_hit(_best, name)
                if _real:
                    report.identity.findings.append(Finding(
                        severity="hard_stop",
                        title=f"UK OFSI match: {_best.get('name','?')}",
                        detail=(
                            f"Match score {_best.get('_match_score', 0):.2f}. "
                            f"Regime: {_best.get('regime','?')}. "
                            f"Group ID {_best.get('group_id','?')}. "
                            f"Designated {_best.get('designation_date','?')}. "
                            f"R-F569 gate: {_reason}."
                        ),
                        source="sources.fcdo_sanctions",
                        confidence="CONFIRMED" if _best.get("_match_score", 0) >= 0.9 else "PROBABLE",
                    ))
                    hard_stop = True
                else:
                    report.identity.findings.append(Finding(
                        severity="info",
                        title=f"UK OFSI fuzzy hit (filtered): {_best.get('name','?')}",
                        detail=(
                            f"Match score {_best.get('_match_score', 0):.2f}, "
                            f"but R-F569 name-overlap gate rejected: {_reason}. "
                            f"Not a refusal ground; surfaced for operator audit."
                        ),
                        source="sources.fcdo_sanctions",
                        confidence="ASSESSED",
                    ))

            elif _lbl == "wb_debarred":
                _active = [h for h in _hits if h.get("status") == "active"]
                if _active:
                    _best = _active[0]
                    report.identity.findings.append(Finding(
                        severity="red",
                        title=f"World Bank debarment (active): {_best.get('name','?')}",
                        detail=(
                            f"Grounds: {_best.get('grounds','?')}. "
                            f"Ineligible {_best.get('ineligibility_from','?')} → "
                            f"{_best.get('ineligibility_to','?')}. "
                            f"Cross-recognised by AfDB/AsDB/EBRD/IDB under MCEA 2010."
                        ),
                        source="sources.worldbank_debarred",
                        confidence="PROBABLE",
                    ))
                else:
                    report.identity.findings.append(Finding(
                        severity="info",
                        title=f"World Bank debarment (expired): {_hits[0].get('name','?')}",
                        detail=(
                            f"Historical debarment, ineligibility ended "
                            f"{_hits[0].get('ineligibility_to','?')}. "
                            f"Relevant context, not a current refusal ground."
                        ),
                        source="sources.worldbank_debarred",
                        confidence="ASSESSED",
                    ))

            elif _lbl == "sec_edgar":
                # R-F613 (2026-05-17): surface ALL material hits, not just
                # first per severity bucket. Past gap: company with 5
                # recent RED 8-K events (cyber incident + exec departure
                # + investigation + restatement + going-concern) only
                # showed ONE in the DD report — credibility loss for
                # financial-health DD. Cap at 5 per bucket.
                _red_hits = [h for h in _hits if (h.get("severity_hint") or "").startswith("RED")]
                _amber_hits = [h for h in _hits if (h.get("severity_hint") or "").startswith("AMBER")]
                _info_hits = [h for h in _hits if
                              not (h.get("severity_hint") or "").startswith(("RED", "AMBER"))]

                for _b in _red_hits[:5]:
                    report.identity.findings.append(Finding(
                        severity="red",
                        title=f"SEC 8-K material event: {_b.get('company_name','?')}",
                        detail=(
                            f"{_b.get('severity_hint','?')}. "
                            f"Filed {_b.get('filing_date','?')}. "
                            f"Items: {_b.get('items','?')}."
                        ),
                        source="sources.sec_edgar",
                        confidence="CONFIRMED",
                    ))
                for _b in _amber_hits[:5]:
                    report.identity.findings.append(Finding(
                        severity="amber",
                        title=f"SEC filing flagged: {_b.get('company_name','?')}",
                        detail=(
                            f"{_b.get('severity_hint','?')}. "
                            f"Filed {_b.get('filing_date','?')}. "
                            f"Items: {_b.get('items','?')}."
                        ),
                        source="sources.sec_edgar",
                        confidence="PROBABLE",
                    ))
                # INFO summary fires only when no red/amber present —
                # don't clutter when there's already a substantive finding.
                if _info_hits and not (_red_hits or _amber_hits):
                    # R-F3134: say what the filings ARE. Promising "financial DD review"
                    # off an ADR registration contradicted the financial layer in the
                    # same report and overstated what EDGAR actually held.
                    _forms, _has_fin, _desc = _sec_form_summary(_info_hits)
                    _forms_txt = ", ".join(_forms[:6]) or "?"
                    if _has_fin:
                        _title = (
                            f"SEC filings found: {len(_info_hits)} recent "
                            f"({_info_hits[0].get('company_name','?')})"
                        )
                        _detail = (
                            f"Most recent: {_info_hits[0].get('form','?')} filed "
                            f"{_info_hits[0].get('filing_date','?')}. "
                            f"Forms present: {_forms_txt}. "
                            f"Includes filings that carry financial statements — "
                            f"available for financial DD review."
                        )
                    else:
                        _title = (
                            f"SEC filings found: {len(_info_hits)} recent, none carrying "
                            f"financial statements ({_info_hits[0].get('company_name','?')})"
                        )
                        _detail = (
                            f"Most recent: {_info_hits[0].get('form','?')} filed "
                            f"{_info_hits[0].get('filing_date','?')}. "
                            f"Forms present: {_forms_txt}. "
                            + (f"These are: {_desc}. " if _desc else "")
                            + "None of these form types contain financial statements, so "
                            "EDGAR does not evidence this entity's financials — the "
                            "subject is not shown to be a US reporting issuer. Financials "
                            "must come from the home-jurisdiction registry."
                        )
                    report.identity.findings.append(Finding(
                        severity="info",
                        title=_title,
                        detail=_detail,
                        source="sources.sec_edgar",
                        confidence="CONFIRMED",
                    ))

            elif _lbl == "acled":
                _sev = _r.get("severity_hint") or ""
                if _sev.startswith("RED"):
                    # R-F2751 — count/cite ONLY events where the subject is genuinely a
                    # PARTY (source-confirmed), not the country-tempo context events that
                    # may be mixed into _hits. Prevents the RED detail from citing a
                    # different actor's event as "the entity named in violence".
                    _party = [h for h in _hits if h.get("subject_is_party")]
                    _ex = _party[0] if _party else _hits[0]
                    report.identity.findings.append(Finding(
                        severity="red",
                        title=f"ACLED: entity named in political-violence events",
                        detail=(
                            f"{len(_party)} event(s) in last 180d name the entity as a party. "
                            f"Most recent: {_ex.get('event_date','?')} "
                            f"{_ex.get('event_type','?')} in {_ex.get('country','?')}."
                        ),
                        source="sources.acled",
                        confidence="PROBABLE",
                    ))
                elif _sev.startswith("INFO"):
                    report.identity.findings.append(Finding(
                        severity="info",
                        title="ACLED: operational-environment signal",
                        detail=_sev,
                        source="sources.acled",
                        confidence="ASSESSED",
                    ))
    except Exception as _e:
        # R-F118 (2026-05-09): surface the cause in the data_gap so the
        # operator sees WHY in the DD report (and on the chat output)
        # instead of only in fly logs. Previous message was just
        # "did not complete" — operator had to dig fly logs to learn
        # whether it was an import error, a network issue, or an arg
        # mismatch.
        logger.warning(
            "Identity: primary-source parallel screen failed: %s: %s",
            type(_e).__name__, _e, exc_info=True,
        )
        report.identity.data_gaps.append(
            f"primary-source parallel screen did not complete: "
            f"{type(_e).__name__}: {str(_e)[:160]}"
        )

    # R-F2843 — stamp the observed primary-snapshot state onto verified_sources so a
    # reader can tell HOW a list was cleared. Status is never changed here: R-F287
    # established that an aggregate CLEAN is a real screen, and flipping it because a
    # separate adapter failed would re-introduce the "NOT CHECKED" fabrication.
    # No-ops safely when the screen has not been built yet (annotate_primary_snapshots
    # guards its inputs) — an unstamped source asserts nothing.
    try:
        from ._sanctions_classify import annotate_primary_snapshots
        _scr = getattr(report.identity, "sanctions_screen", None)
        if isinstance(_scr, dict) and locals().get("_primary_snapshots"):
            annotate_primary_snapshots(_scr.get("verified_sources"), _primary_snapshots)
            # R-F3452 — carry the OBSERVED per-list availability forward. _run_identity
            # writes its "screen NOT performed" finding BEFORE this function runs, so at
            # that moment it cannot know that OFAC/OFSI/UN answered. Without this the
            # report states "NO screen was performed" on a run whose own OFAC result is
            # printed three sections later.
            _scr["primary_snapshots"] = dict(_primary_snapshots)
    except Exception as _ann_err:  # noqa: BLE001 — provenance must never fail a report
        logger.debug("[R-F2843] primary-snapshot annotation skipped: %s", _ann_err)

    return hard_stop


def _sanctions_brief_line(screen) -> str:
    """R-F3230 — how the sanctions screen is described TO THE VERDICT MODEL.

    THE DEFECT. The RED-verdict second-opinion prompt (`evidence_brief`) built
    this line as:

        f"Sanctions screen: {report.identity.sanctions_screen or 'CLEAN'}"

    so an ABSENT screen — the dict is empty whenever the screen block raised
    before assignment — told the model, in the evidence it was asked to reason
    over, that the entity is sanctions-clean. R-F3217 closed this same failure on
    the three surfaces a CUSTOMER reads; this one sits upstream of them, feeding
    the model whose job is to independently challenge a RED verdict. A fabricated
    clean is at its most dangerous precisely there: it argues against the
    escalation, on a path that only runs when ARIA already believes the
    counterparty is high-risk.

    `or 'CLEAN'` is also the wrong Python for the intent even when a screen
    exists — an empty-but-present dict is falsy, so "we screened and recorded
    nothing" and "we never screened" both rendered as CLEAN.

    Returns a short, honest phrase rather than the raw dict: the previous form
    interpolated the entire screen (every match, every per-alias result) into the
    prompt, which is both noisy and a way for filtered name-overlap noise to
    reach the model as if it were evidence.
    """
    if not isinstance(screen, dict) or not screen:
        return ("NOT PERFORMED — no screen is recorded on this report. Treat as "
                "UNKNOWN, never as clear.")
    if screen.get("error") or screen.get("screened") is False:
        return (f"NOT PERFORMED ({screen.get('error') or 'screen did not run'}) — "
                f"no list was queried. Treat as UNKNOWN, never as clear.")
    _cls = screen.get("match_classification")
    _actionable = int((_cls or {}).get("actionable") or 0) if isinstance(_cls, dict) else None
    _vs = screen.get("verified_sources")
    _lists = (
        len([k for k, v in _vs.items()
             if isinstance(v, dict) and str(v.get("status") or "").upper() in ("CLEAN", "HIT")])
        if isinstance(_vs, dict) else 0
    )
    _cover = f"{_lists} list(s) answered" if _lists else "list coverage not recorded"
    if _actionable is None:
        return f"screen ran; {len(screen.get('matches') or [])} raw match(es), unclassified; {_cover}"
    if _actionable:
        return f"{_actionable} actionable match(es); {_cover}"
    return f"no matches; {_cover}"


async def _rescreen_under_registered_name(
    report: "ARKDDReport", registered_name: str, supplied_name: str,
) -> bool:
    """R-F3219 — screen the REGISTERED name once the registry has resolved the subject.

    The identity sanctions screen runs before the Companies House lookup, so it can
    only ever use the string the customer typed. When the register then resolves a
    DIFFERENT legal name, the screen on record does not cover the entity this report
    is about. Asserting that it does would be the §22 failure — claiming coverage we
    cannot show — so we screen the registered name too.

    Additive and fail-safe: a corroborated hit escalates (returns True), a clean
    result only records that this name was screened as well, and any failure is
    written as a data gap rather than swallowed. Never replaces a screen that ran
    with one that did not.
    """
    from . import sanctions
    from ._sanctions_classify import classify_matches, derive_verified_sources

    prev = (report.identity.sanctions_screen
            if isinstance(report.identity.sanctions_screen, dict) else {})
    already = {str(n).casefold() for n in (prev.get("aliases_checked") or [])}
    if registered_name.casefold() in already:
        return False                      # R-F3218 split may already have covered it

    screen = await sanctions.screen_with_aliases(
        registered_name, known_aliases=[supplied_name] if supplied_name else None,
        source="registry")      # R-F3228 — straight from Companies House
    report.identity.meta.subcalls += 1
    if (not isinstance(screen, dict) or screen.get("error")
            or screen.get("screened") is not True):
        report.identity.data_gaps.append(
            f"registered-name sanctions re-screen did not run for {registered_name!r} "
            f"({(screen or {}).get('error') or 'screen not performed'}) — the screen on "
            f"record covers {supplied_name!r} only"
        )
        return False

    matches = list(screen.get("matches") or [])
    screen["verified_sources"] = derive_verified_sources(matches, screen_succeeded=True)
    if not screen.get("screened_at"):
        screen["screened_at"] = datetime.now(timezone.utc).isoformat(timespec="seconds")
    # Preserve what the first pass covered, so the record shows every name screened
    # rather than only the last one.
    screen["aliases_checked"] = list(dict.fromkeys(
        [*(prev.get("aliases_checked") or []), *(screen.get("aliases_checked") or [])]
    ))
    classified = classify_matches(matches, query_name=registered_name)
    _noise = int(classified.get("noise_filtered") or 0)
    _total = int(classified.get("total_matches") or len(matches))
    screen["match_classification"] = {
        "total": _total,
        "noise_filtered": _noise,
        "actionable": max(0, _total - _noise),
        "worst_severity": classified.get("worst_severity"),
    }
    _record_sanctions_screen(report, screen)   # R-F3535

    _worst = classified.get("worst_severity")
    if _worst in ("hard_stop", "red", "amber"):
        report.identity.findings.append(Finding(
            severity=("hard_stop" if _worst == "hard_stop" else _worst),
            title=(f"Sanctions/PEP match under the REGISTERED name "
                   f"{registered_name!r} ({_worst})"),
            detail=(
                f"{classified.get('summary', '')} — surfaced only after the subject "
                f"was resolved to its registered name; the screen on the supplied "
                f"name {supplied_name!r} did not carry it."
            ),
            source="sanctions.screen_with_aliases:R-F3219",
            confidence="PROBABLE" if _worst != "hard_stop" else "CONFIRMED",
        ))
        return _worst == "hard_stop"

    report.identity.findings.append(Finding(
        severity="info",
        title="Sanctions re-screened under the registered legal name — no matches",
        detail=(
            f"{registered_name} was screened in its own right (the first screen ran on "
            f"{supplied_name!r}). No matches. Lists that answered are listed under the "
            "sanctions screen record; check the data gaps for any that did not."
        ),
        source="sanctions.screen_with_aliases:R-F3219",
        confidence="CONFIRMED",
    ))

    # ── The clean re-screen has just replaced verified_sources. Say so if it now
    # contradicts a HARD_STOP still standing from the FIRST screen.
    #
    # MEASURED, run dd_29368fbb8b3d: the supplied name raised a HARD_STOP on OFAC
    # SDN; the registered name came back clean; `screen["verified_sources"]` above
    # was overwritten with the clean result and the delivered PDF printed
    # "OFAC SDN match ... HARD_STOP" and "OFAC · SDN List — CLEAN" on facing
    # pages. The table described this screen, the finding described the previous
    # one, and the report asserted both.
    #
    # DETECT, never adjudicate. The earlier screen may be the correct one, and a
    # sanctions HARD_STOP that quietly disappears because a later screen was clean
    # is a far worse failure than one that is loudly questioned. This raises the
    # disagreement to the operator and leaves the HARD_STOP standing.
    try:
        from ._sanctions_classify import detect_screen_contradictions
        _all = []
        for _sec_name in ("identity", "compliance", "forensic", "synthesis"):
            _sec = getattr(report, _sec_name, None)
            _all.extend(getattr(_sec, "findings", None) or [])
        _contra = detect_screen_contradictions(_all, screen.get("verified_sources"))
        if _contra:
            _lists = ", ".join(sorted({c["list"] for c in _contra}))
            report.identity.findings.append(Finding(
                severity="amber",
                title="Screens disagree — a HARD_STOP stands against a list now reported CLEAN",
                detail=(
                    f"The re-screen under {registered_name!r} returned CLEAN for: {_lists}. "
                    f"A HARD_STOP raised by the earlier screen on {supplied_name!r} is still "
                    f"on this report against the same list(s). Both cannot be relied on. "
                    f"Neither has been withdrawn automatically: the earlier screen may be "
                    f"correct, and a name that differs only in legal form is a common source "
                    f"of false matches. Adjudicate before relying on either — check whether "
                    f"the match was a genuine alias or a name collision."
                ),
                source="sanctions.screen_contradiction",
                confidence="CONFIRMED",
            ))
            report.identity.data_gaps.append(
                f"sanctions screens disagree on {_lists} between {supplied_name!r} and "
                f"{registered_name!r} — unadjudicated"
            )
    except Exception as _contra_err:      # never let a self-check break a DD
        logger.warning("[dd_orchestrator] screen-contradiction check failed: %s", _contra_err)

    return False


# R-F3233 — legal-form suffixes, stripped before matching so a page naming
# "Acme Holdings" still evidences "Acme Holdings Ltd". Kept deliberately short:
# an over-long list starts stripping real name words.
#
# LEGAL FORMS ONLY. "Holdings", "Group" and "Company" are name words, not legal
# forms — stripping them turned "Acme Holdings Ltd" into the single token
# "acme", which then failed to match a page that plainly said "Acme Holdings".
# The test that caught it is the reason this list stays narrow: anything that
# can carry meaning in a name does not belong here.
_LEGAL_SUFFIXES = {
    "ltd", "limited", "llc", "llp", "lp", "inc", "incorporated", "plc", "corp",
    "corporation", "sa", "sas", "sarl", "ag", "gmbh", "bv", "nv", "as", "asa",
    "ab", "oy", "oyj", "aps", "srl", "spa", "pty", "pte", "kft", "zrt", "nyrt",
    "sp", "zoo", "doo", "ooo", "jsc",
}


def _vault_text_names_subject(name: str, text: str) -> bool:
    """R-F3233 — does this text actually NAME the subject?

    The vault consult matched with `needle in text.lower()`. A bare substring
    cites any page that merely CONTAINS the name as a fragment: "Acme Ltd"
    matched "Acmetech Solutions", and a one-word name matched half the web.
    This is the same name-coincidence class that put a fraud headline about an
    unrelated person into a clean report's cited sources.

    Two rules:

    1. **Word boundaries, suffix-tolerant.** The subject's legal-form suffix is
       stripped before matching, so a page saying "Acme Holdings announced"
       evidences "Acme Holdings Ltd" — but "Acmetech" never evidences "Acme".

    2. **A single word is not an identification.** "Apple", "Shell" and "Orange"
       are ordinary nouns; citing a page because it contains one is a fabricated
       link. Where stripping the suffix leaves ONE token, the FULL name is
       required instead ("Equinor ASA" still matches), and a name that is one
       token even with its suffix is refused outright. Abstaining loses a little
       real signal; the alternative manufactures evidence, and on this product
       that trade is not close.
    """
    subject = (name or "").strip().lower()
    body = (text or "").lower()
    if not subject or not body:
        return False

    tokens = [t for t in re.split(r"[^a-z0-9&]+", subject) if t]
    if not tokens:
        return False
    core = [t for t in tokens if t not in _LEGAL_SUFFIXES]
    # Fall back to the full name when stripping leaves nothing distinctive.
    if len(core) < 2:
        core = tokens
    if len(core) < 2:
        return False          # one token even with its suffix — not an identification

    pattern = r"\b" + r"[\s\-,\.]+".join(re.escape(t) for t in core) + r"\b"
    return re.search(pattern, body) is not None


async def _explain_empty_psc_register(report: "ARKDDReport") -> None:
    """An EMPTY PSC register must be EXPLAINED, not left to be read as opacity.

    R-F2830 built `companies_house.get_psc_exemptions` for exactly this and NOTHING EVER
    CALLED IT. Its own docstring states the stakes: a company disclosing no beneficial
    owners looks opaque, potentially evasive, whereas one exempt because it trades on a UK
    regulated market is behaving entirely normally. Reporting the first when the truth is
    the second is a false ACCUSATION — the mirror of a false clean.

    That is the Babcock case: a listed PLC whose Network section showed "UBO chain nodes
    traversed 11" and nothing else, leaving a reader to infer opacity from an absence that
    had a lawful, checkable explanation.

    R-F3515 — WHY THIS IS A FUNCTION AND NOT AN INLINE BLOCK. R-F3504 put it inline on the
    ``else`` of ``if jurisdiction_iso2 == "GB"`` — the MULTI-JURISDICTION adapter branch —
    and then guarded it on ``jurisdiction in (GB, UK, "")``. A UK-only check on the non-UK
    path: it could not fire for the case it was built for, and a real run on Chemring Group
    PLC (a UK listed PLC, reg 00086662) proved it, returning ``psc_exemptions: {}`` with no
    finding and no gap. Its tests passed throughout because they called the branch directly.
    One named function called once, AFTER both branches converge, is what makes "did this
    run?" answerable — the placement, not the logic, was the whole defect.

    Asked ONLY when the register is empty: an exemption explains nothing when controllers
    are disclosed, and the call would be wasted spend.
    """
    if report.identity.shareholders:
        return
    _rg = str(report.identity.registration_number or "").strip()
    if not _rg:
        return
    if str(report.identity.jurisdiction_iso2 or "").upper() not in ("GB", "UK", ""):
        return
    try:
        from . import companies_house as _ch_psc
        _ex = await _ch_psc.get_psc_exemptions(_rg)
        _ex = _ex if isinstance(_ex, dict) else {}
        report.identity.psc_exemptions = _ex
        _act = _ex.get("active") or []
        if not _ex.get("checked"):
            # Claim NEITHER exemption nor opacity: an unperformed check must not
            # resolve to either.
            report.identity.data_gaps.append(
                "PSC register is empty and the exemption register could NOT be "
                "checked, so it is unknown whether the absence is lawful. Not a "
                "finding of opacity and not a clearance — re-check before relying "
                "on the ownership position.")
        elif _ex.get("has_active_exemption") and _act:
            report.identity.findings.append(Finding(
                severity="info",
                title="No PSC recorded — a LAWFUL exemption is on the register",
                detail=(
                    "The PSC register is empty because an exemption is currently "
                    "active: "
                    + "; ".join(
                        f"{a.get('exemption_type')} (from "
                        f"{a.get('exempt_from') or 'an unstated date'})"
                        for a in _act[:3] if isinstance(a, dict))
                    + ". A company trading on a regulated market discloses ownership "
                      "through market rules rather than the PSC register, so this "
                      "absence is NORMAL and must not be read as opacity."),
                source="companies_house.psc_exemptions:R-F2830",
                confidence="CONFIRMED",
                source_tier="OFFICIAL",
            ))
        else:
            # No exemption AND no PSC is the genuinely opaque case.
            report.identity.data_gaps.append(
                "PSC register is EMPTY and no active exemption is recorded at "
                "Companies House. Beneficial ownership is undisclosed rather than "
                "lawfully exempt — establish it before relying on this file.")
    except Exception as _psc_ex_e:  # noqa: BLE001 — never cost a report
        logger.debug("[R-F3504] PSC exemption lookup skipped: %s", _psc_ex_e)


def _apply_registry_result(
    report: "ARKDDReport",
    reg_result: dict,
    registration_number: str | None = None,
) -> bool:
    """R-F3231/R-F3232 — turn one registry-adapter result into report state.

    THE SINGLE PLACE that decides whether a registry confirmed anything. It was
    previously inline in `_run_identity` and gated on `if reg_result:` —
    truthiness, not authority — which is how a stub that queried NO registry
    produced a `confidence="CONFIRMED"` finding.

    The authority test is `RegistryStatus.is_authority()`, the same closed
    vocabulary `registry_coverage` already keys its liveness ledger on
    (registry_adapters.py:219-228). Two different tests for one question is how
    the two surfaces disagreed: the coverage ledger correctly recorded a stub as
    "empty" while the report called the same result CONFIRMED.

    Returns True when an authoritative registry answered.

    Three rules:

    1. **Never certify what was not established.** A non-authority result still
       produces a finding — silence would be its own kind of dishonesty — but it
       says no registry answered and carries UNCERTAIN confidence.
    2. **A stub may not write identity fields.** `_build_us_stub` copies the
       address it was GIVEN into its profile, so writing it back presents the
       caller's own input as a registry finding. Nothing from a non-authority
       result is written to the identity fields at all.
    3. **Additive, never clobber (R-F2511).** This runs AFTER Companies House on
       GB, and the adapter carries no GB officers, so an unconditional
       assignment overwrote CH's directors with an empty list and real GB
       companies showed 0 directors. Only ever fill what is still empty.
    """
    from .registry_adapters import RegistryStatus

    if not reg_result:
        return False

    profile = reg_result.get("profile") or {}
    adapter = str(reg_result.get("adapter") or "")
    status = RegistryStatus.coerce(reg_result.get("registry_status"))
    if status is None and adapter:
        status = RegistryStatus.for_adapter(adapter)   # older results carry no field
    is_authority = status is not None and status.is_authority()

    # Carry the status onto the report FIRST. This is the field dd_schema's
    # quality metrics read to refuse identity authority; it existing is the
    # whole point of R-F3231, and a later `return` must not be able to skip it.
    #
    # Evidence only ever RATCHETS UP. A second application (primary then
    # fallback) may replace a non-authority status with an authoritative one —
    # that is strictly more evidence — but an authority already established is
    # never demoted by a later stub. Writing it unconditionally would let a
    # fallback stub erase a real registry answer; first-writer-wins would let a
    # stub pin the report below the evidence actually obtained. Neither is
    # reachable on today's control flow (the fallback loop only runs when the
    # primary returned nothing at all), and that is exactly why it is pinned
    # here rather than left to the caller to keep true.
    if status is not None:
        _current = RegistryStatus.coerce(report.identity.registry_status)
        if _current is None or (is_authority and not _current.is_authority()):
            report.identity.registry_status = status.value

    # R-F3232 — the caveats the adapter wrote for exactly this case. Eighteen
    # adapters build `result["data_gaps"]` — "US has no federal company
    # registry", "UBO is NOT public; request the FinCEN BOI report", the exact
    # manual-search URL — and nothing read a single one of them. De-duplicated
    # because the identity layer may apply a primary and then a fallback result.
    for gap in (reg_result.get("data_gaps") or []):
        text = str(gap).strip()
        if text and text not in report.identity.data_gaps:
            report.identity.data_gaps.append(text)

    report.identity.meta.subcalls += 1

    if not is_authority:
        # Say it plainly. An auditor asking "was this entity registry-verified?"
        # must not have to infer the answer from a `_stub` suffix in a title.
        report.identity.findings.append(Finding(
            severity="info",
            title="Registry not verified — no registry answered for this entity",
            detail=(
                f"The {adapter or 'registry'} path produced a result but it is "
                f"not an authority ({(status.value if status else 'unknown')}): "
                f"no national registry confirmed this entity. Identity is "
                f"UNVERIFIED and must be established by hand — see the data gaps "
                f"for the manual steps this adapter supplied."
            ),
            source=f"registry_adapters.{adapter or 'unknown'}",
            confidence="UNCERTAIN",
        ))
        return False

    report.identity.registration_number = (
        report.identity.registration_number or profile.get("company_number")
        or registration_number)
    report.identity.registration_status = (
        report.identity.registration_status or profile.get("company_status"))
    report.identity.incorporation_date = (
        report.identity.incorporation_date or profile.get("date_of_creation"))
    report.identity.registered_address = (
        report.identity.registered_address or profile.get("registered_office_address"))
    report.identity.declared_activity = (
        report.identity.declared_activity
        or ", ".join(profile.get("sic_codes") or [])[:200])
    report.identity.directors = (
        report.identity.directors or reg_result.get("officers") or [])
    report.identity.shareholders = (
        report.identity.shareholders or reg_result.get("psc") or [])
    report.identity.findings.append(Finding(
        severity="info",
        title=(f"Registry lookup: {adapter or 'registry'} "
               f"({profile.get('company_status', 'unknown')})"),
        detail=f"Source: {reg_result.get('source_url', 'registry adapter')}",
        source=f"registry_adapters.{adapter or 'unknown'}",
        confidence="CONFIRMED",
    ))
    return True


async def _consult_vault_sources(name: str, jurisdiction: str, report: "ARKDDReport") -> int:
    """R-F2195 (Pipeline 3 of the vault review) — DD consults the operator-curated
    Agent Signup Vault for the entity.

    Operators trust manually-added websites as a reliable data source; this makes a DD
    run actually CONSULT them: each ingestable vault website/feed is fetched (bounded,
    SSRF-guarded via researcher.extract_url_text) and, if it mentions the entity, cited
    as an INFO finding so the manual source informs the report.

    BULLETPROOF by construction: fully best-effort, time-bounded, capped at a small
    number of sources, never raises, and only ever ADDS info-severity findings — it can
    never block, slow materially, or alter the hard-stop logic of the core DD path.
    Returns the number of citations added.
    """
    try:
        from .agent_signup_vault import get_vault
        entries = get_vault().list(limit=200) or []
    except Exception:
        return 0

    eligible = [
        e for e in entries
        if (e.get("site_type") or "").lower() in ("website", "rss")
        and (e.get("status") or "").lower() not in ("failed", "expired", "cancelled")
        and str(e.get("site_url") or "").startswith(("http://", "https://"))
    ]
    _CAP = 6
    sites = eligible[:_CAP]      # cap the per-run fetch
    # R-F3233 — NO SILENT CAPS. Dropping sources without saying so reads as "we
    # checked the curated sources", which is exactly what an operator who added
    # them would believe. State what was not consulted.
    if len(eligible) > _CAP:
        report.identity.data_gaps.append(
            f"Curated vault sources: {len(sites)} of {len(eligible)} eligible "
            f"sources were consulted this run (per-run cap {_CAP}); "
            f"{len(eligible) - _CAP} were not read."
        )
    if not sites or not (name or "").strip():
        return 0

    added = 0

    async def _check(entry: dict) -> None:
        nonlocal added
        url = str(entry.get("site_url") or "")
        try:
            from . import researcher as _r
            res = await asyncio.wait_for(_r.extract_url_text(url, timeout=10.0), timeout=12.0)
        except Exception:
            return
        text = str((res or {}).get("text", "") or "")
        # R-F3233 — the page must NAME the subject, not merely contain its
        # letters. See _vault_text_names_subject.
        if not text or not _vault_text_names_subject(name, text):
            return
        # Anchor the snippet on the first token of the matched name so the
        # quoted context is the mention itself, not an unrelated fragment.
        _first = (re.split(r"[^A-Za-z0-9&]+", name.strip()) or [name])[0].lower()
        idx = text.lower().find(_first)
        if idx < 0:
            idx = 0
        snippet = text[max(0, idx - 120): idx + 200].strip().replace("\n", " ")
        try:
            report.identity.findings.append(Finding(
                severity="info",
                title=f"Mentioned in curated source: {entry.get('site_name') or url}",
                detail=f"'{name}' appears in an operator-curated vault source. Context: …{snippet}…",
                source=f"vault:{entry.get('site_id') or url}",
                confidence="ASSESSED",
            ))
            added += 1
        except Exception:
            return

    try:
        await asyncio.gather(*[_check(e) for e in sites], return_exceptions=True)
    except Exception:
        return added
    return added



@fail_wire(module="dd_orchestrator", gap_type="engine_failure")
def resolve_jurisdiction_iso2(
    target: dict, name: str, registration_number: str | None = None
) -> str | None:
    """Resolve the jurisdiction ISO2, with DECLARATION beating INFERENCE.

    R-F2838 — this ordering is the whole point. Before it, identity resolution only
    consulted ``target["jurisdiction_iso2"]`` and, finding it empty, went straight to
    ``_infer_jurisdiction``. A caller passing ``jurisdiction="CH"`` — already a valid
    ISO2 — never populated that field, so the suffix clue won.

    Live consequence (run dd_7bd81330d43d, SOCAR Trading SA, declared CH):
    the "SA" suffix (Sociedade Anonima) inferred PT, so the compliance layer scored
    PORTUGAL (cpi 62; Switzerland is ~82), the UBO walk searched a PT registry, and
    the report advised checking a Portuguese database for a Swiss company. "SA" is
    also the standard suffix in FR/BE/LU/ES/BR/AR/PL, so the blast radius was most
    of the non-UK market.

    Precedence, most explicit first:
      1. ``jurisdiction_iso2``      — the dedicated field
      2. ``jurisdiction``           — a declaration, as ISO2 ("CH") or name ("Portugal")
      3. ``_infer_jurisdiction``    — clues, and ONLY to fill a genuine gap
      4. None                       — UNKNOWN. Never a default: a confident wrong
                                      country is the same family of harm as a false
                                      clean, and worse than admitting we don't know.
    """
    explicit = (target.get("jurisdiction_iso2") or "").strip() if isinstance(
        target.get("jurisdiction_iso2"), str) else target.get("jurisdiction_iso2")
    if explicit:
        return str(explicit).strip().upper()

    declared = target.get("jurisdiction")
    if isinstance(declared, str) and declared.strip():
        d = declared.strip()
        # A two-letter alpha declaration IS an ISO2 — the caller said so, and this
        # field means jurisdiction, not legal form.
        if len(d) == 2 and d.isalpha():
            return d.upper()
        # Otherwise treat it as a country NAME and reverse-map.
        rev = {str(v).lower(): k for k, v in _ISO2_TO_COUNTRY.items() if v}
        hit = rev.get(d.lower())
        if hit:
            return hit
        # Unparseable declaration: fall through to inference rather than inventing.

    return _infer_jurisdiction(target, name, registration_number)


class _ScopeWaived(Exception):
    """R-F3411 — control-flow signal: the operator declined this check.

    Used only to skip a long inline block without re-indenting it. Every raise has a
    matching `except _ScopeWaived` placed ABOVE the generic handler, so a declined check
    is never logged or reported as a failure. It never escapes a layer.
    """


def _dd_scope_from_target(target: dict) -> dict:
    """R-F3411 — read the run's SCOPE off the DD request.

    `routes/aria.py` passes `target=body`, i.e. the whole request body reaches the
    orchestrator, so scope needs no new endpoint and no signature change. Two shapes are
    accepted so the form and the API can each send what is natural:

        {"dd_scope": {"tier": ..., "waivers": [...], "elections": [...]}}
        {"tier": ..., "waivers": [...], "elections": [...]}      (top level)

    Returns a plain dict, always — a run with no scope is a full-scope run with nothing
    declined and nothing ordered, which is the correct default. Never raises: a
    malformed scope must not cost the caller their DD, and because an unparsable waiver
    is DROPPED rather than honoured, the failure direction is "we screened anyway".
    """
    if not isinstance(target, dict):
        return {}
    raw = target.get("dd_scope")
    if not isinstance(raw, dict):
        raw = target
    tier = str(raw.get("tier") or target.get("tier") or "STANDARD").strip().upper()
    if tier not in ("SIMPLIFIED", "STANDARD", "ENHANCED"):
        tier = "STANDARD"

    def _rows(key: str) -> list[dict]:
        v = raw.get(key)
        if v is None:
            v = target.get(key)
        out: list[dict] = []
        for item in (v or []):
            if isinstance(item, str):
                out.append({"question_id": item.strip()})
            elif isinstance(item, dict) and item.get("question_id"):
                out.append({str(k): v2 for k, v2 in item.items()})
        return out

    return {"tier": tier, "waivers": _rows("waivers"), "elections": _rows("elections")}


def _scope_waived(report: ARKDDReport, question_id: str) -> dict | None:
    """The waiver for `question_id` on this run, or None.

    A waiver only counts when it names WHO and WHY — the same validity rule
    `dd_standard.Waiver.is_valid` applies, restated here rather than imported so this
    gate cannot silently diverge if the module is unavailable. An anonymous opt-out is
    NOT honoured: the check runs, which is the safe direction.

    An ELECTION for the same question beats the waiver (money changed hands), matching
    `dd_standard.assess`; otherwise the engine and the checklist would disagree about
    whether the work should have happened.
    """
    try:
        scope = getattr(report, "dd_scope", None) or {}
        qid = str(question_id)
        for e in (scope.get("elections") or []):
            if isinstance(e, dict) and str(e.get("question_id")) == qid:
                return None                      # ordered — never skip it
        for w in (scope.get("waivers") or []):
            if not isinstance(w, dict) or str(w.get("question_id")) != qid:
                continue
            if str(w.get("waived_by") or "").strip() and str(w.get("reason") or "").strip():
                return w
        return None
    except Exception:
        return None                              # unreadable scope -> run the check


def _record_waived_screen(report: ARKDDReport, waiver: dict, *, what: str) -> None:
    """Record a screen the operator declined, so it is STATED and never merely absent.

    THE OMISSION THIS PREVENTS. If a waived screen simply does not run,
    `report.identity.sanctions_screen` stays empty — and `render_markdown` gates the
    whole "Sanctions screen:" line on that dict being truthy, so the report would carry
    NO sanctions line at all. A reader cannot distinguish a declined screen from a
    section nobody thought about. `screened: False` also routes through the R-F3229
    branch, so it can never render as "CLEAN".
    """
    _by = str(waiver.get("waived_by") or "?")
    _why = str(waiver.get("reason") or "")
    _screen_blob = {
        "matches": [],
        "variants_screened": [],
        "verified_sources": [],
        "screened": False,
        "waived": True,
        "waived_by": _by,
        "waived_reason": _why,
        "waived_at": str(waiver.get("waived_at") or ""),
        "screened_at": None,
    }
    _record_sanctions_screen(report, _screen_blob)   # R-F3535
    report.identity.data_gaps.append(
        f"{what} WAIVED by {_by}: {_why} — not screened on this run "
        f"(a declined check is not a clear one)"
    )
    logger.info("[R-F3411] %s waived by %s (%s) on %s", what, _by, _why[:60], report.run_id)


def _gated_search_permitted(report: ARKDDReport, question_id: str) -> tuple[bool, str]:
    """R-F3441 — may a METERED search be spent on this run? Default is NO.

    Operator directive: a paid search is "only carried out when the user select as a
    requirement on their DD for that specific company or individual." So the permission
    is per-run and per-question, and the default is refusal — the opposite of the usual
    scope rule, where an unreadable waiver means "screen anyway" because screening is the
    safe direction. For metered spend the safe direction is the other way: not spending
    someone's money is recoverable, spending it is not.

    Every PAID_PER_SEARCH adapter MUST call this before issuing a billable request.
    Registry Trust has no adapter yet, so today this gates nothing — the seam exists now
    so that binding one is a two-line change rather than a rediscovery, and
    test_rf3441_* asserts a paid resolver cannot be wired around it.
    """
    try:
        scope = getattr(report, "dd_scope", None) or {}
        qid = str(question_id)
        for e in (scope.get("elections") or []):
            if isinstance(e, dict) and str(e.get("question_id")) == qid:
                who = str(e.get("elected_by") or "").strip()
                if not who:
                    # An anonymous election cannot authorise spend: there is nobody to
                    # attribute the charge to, and R-F3406 applies the same rule to waivers.
                    return (False, f"{qid} elected but no elected_by — cannot authorise spend")
                return (True, "")
        return (False, f"{qid} was not selected as a requirement for this subject")
    except Exception as e:
        return (False, f"scope unreadable ({type(e).__name__}) — refusing metered spend")


def _preflight_elections(report: ARKDDReport) -> None:
    """R-F3436 — say UP FRONT when an ordered section cannot possibly be searched.

    The operator's requirement is that a selected paid section is actually searched. When
    it can't be — no adapter, no credential, allowance spent — the only honest thing is to
    say so at the START of the run rather than let the reader discover a silent hole.

    `assess` already catches this after the fact (R-F3408 marks the election unfulfilled
    and non-billable), and that stays the enforcement. This is the disclosure: an election
    made against an unusable source is recorded as a data gap immediately, so the failure
    is visible even if the run is cut short before the checklist is ever computed — which
    is exactly the case where a silent hole would otherwise survive into a delivered report.

    Never raises: a pre-flight that could kill the run would be worse than the gap.
    """
    try:
        from .dd_standard import QUESTIONS_BY_ID, RESOLVERS

        scope = getattr(report, "dd_scope", None) or {}
        for el in (scope.get("elections") or []):
            if not isinstance(el, dict):
                continue
            qid = str(el.get("question_id") or "").strip()
            q = QUESTIONS_BY_ID.get(qid)
            if q is None:
                report.identity.data_gaps.append(
                    f"ORDERED SECTION {qid!r} is not a question in this Standard — "
                    f"nothing was searched for it and it must not be charged for")
                continue
            specs = [RESOLVERS[r] for r in q.resolvers if r in RESOLVERS]
            usable = [s for s in specs if s.availability()[0]]
            if usable:
                continue
            why = "; ".join(f"{s.name}: {s.availability()[1]}" for s in specs) or "no resolver declared"
            report.identity.data_gaps.append(
                f"ORDERED SECTION {qid} ({q.text}) CANNOT BE SEARCHED on this run — {why}. "
                f"It is not covered and must not be charged for")
            logger.warning("[R-F3436] elected %s is unfulfillable on %s: %s", qid, report.run_id, why[:120])
    except Exception as e:                                   # never cost the caller their DD
        logger.debug("[R-F3436] election pre-flight skipped: %s", e)


async def _run_ch_free_registers(report: ARKDDReport, profile: dict | None) -> None:
    """R-F3422 — run the three free Companies House registers and put the result in the
    report: CHARGES (#12), INSOLVENCY (#11) and DISQUALIFIED OFFICERS (#16).

    All three are free on the key already deployed and none had ever been consulted by a
    DD. Before this, charges and insolvency were answerable only from two BOOLEANS on
    the company profile — `has_charges` / `has_insolvency_history` — which cannot tell a
    buyer whether a debenture sits over the assets they are about to pay for, who holds
    it, when an insolvency happened or what kind it was. Disqualification was not
    checked at all: `disqualified-directors` appeared exactly once in the tree, as a
    domain fragment in an adverse-media allowlist.

    THE RULE THIS FUNCTION EXISTS TO KEEP. For every one of these an EMPTY result is a
    real finding — no charges, no insolvency, no disqualification — and an empty result
    is only a finding when the register actually ANSWERED. R-F3404's adapters carry
    `checked: bool` for exactly that reason, so a register we could not reach becomes a
    data gap, never a clean line.

    Never raises: a register that fails must cost the DD its answer, never the report.
    """
    number = str((profile or {}).get("company_number") or
                 report.identity.registration_number or "").strip()
    if not number:
        return
    from . import companies_house as _ch

    # ── #12 charges ──────────────────────────────────────────────────────────
    try:
        ch_res = await _ch.get_charges(number)
        report.identity.meta.subcalls += 1
        if not ch_res.get("checked"):
            report.identity.data_gaps.append(
                f"Charges register NOT checked — {ch_res.get('reason', 'unavailable')} "
                f"(no view of security over the assets; not a clear result)"
            )
        elif ch_res.get("outstanding_count"):
            _holders = sorted({h for c in ch_res.get("items", [])
                               for h in (c.get("persons_entitled") or []) if h})
            report.identity.findings.append(Finding(
                severity="amber",
                title=(f"{ch_res['outstanding_count']} outstanding charge(s) registered "
                       f"over the company's assets"),
                detail=(
                    f"Companies House records {ch_res['outstanding_count']} outstanding or "
                    f"part-satisfied charge(s) of {ch_res.get('total_count')} total. "
                    + (f"Secured party/parties: {', '.join(_holders[:6])}. " if _holders else "")
                    + "A charge is a prior claim over the assets: it does not imply "
                      "distress, but it ranks ahead of an unsecured counterparty and "
                      "belongs in any payment or security decision."
                ),
                source="companies_house.charges",
                confidence="CONFIRMED",
                url=ch_res.get("source_url"),
                source_tier="OFFICIAL",
            ))
        else:
            report.identity.findings.append(Finding(
                severity="info",
                title="No outstanding charges registered",
                detail=(f"The Companies House charges register was consulted and records "
                        f"{ch_res.get('total_count', 0)} charge(s), none outstanding."),
                source="companies_house.charges",
                confidence="CONFIRMED",
                url=ch_res.get("source_url"),
                source_tier="OFFICIAL",
            ))
    except Exception as exc:
        report.identity.data_gaps.append(
            f"Charges register raised {type(exc).__name__} — NOT checked (not a clear result)")

    # ── #11 insolvency ───────────────────────────────────────────────────────
    try:
        ins = await _ch.get_insolvency(number)
        report.identity.meta.subcalls += 1
        if not ins.get("checked"):
            report.identity.data_gaps.append(
                f"Insolvency register NOT checked — {ins.get('reason', 'unavailable')} "
                f"(not a clear result)"
            )
        elif ins.get("case_count"):
            _kinds = sorted({str(c.get("type") or "case").replace("-", " ")
                             for c in ins.get("cases", [])})
            report.identity.findings.append(Finding(
                severity="red",
                title=f"{ins['case_count']} insolvency case(s) on the register",
                detail=(
                    f"Companies House records {ins['case_count']} insolvency case(s): "
                    f"{', '.join(_kinds[:5])}. This is a formal proceeding against the "
                    f"company itself, not an inference from filings."
                ),
                source="companies_house.insolvency",
                confidence="CONFIRMED",
                url=ins.get("source_url"),
                source_tier="OFFICIAL",
            ))
        else:
            report.identity.findings.append(Finding(
                severity="info",
                title="No insolvency case on the register",
                detail=ins.get("detail") or "The insolvency register was consulted and is empty.",
                source="companies_house.insolvency",
                confidence="CONFIRMED",
                source_tier="OFFICIAL",
            ))
    except Exception as exc:
        report.identity.data_gaps.append(
            f"Insolvency register raised {type(exc).__name__} — NOT checked (not a clear result)")

    # ── #16 disqualified officers ────────────────────────────────────────────
    #
    # NAME-MATCH DISCIPLINE. This register matches on NAME ALONE, so a hit is a
    # CANDIDATE and never an identification — the R-F3089 name-coincidence class, about a
    # named human being. The finding says so in its own text, carries the candidate's
    # DOB/address so a reader can discriminate, and is capped at amber: an accusation
    # dressed as a red is exactly the false positive that destroys the USP.
    _officers = [o for o in (report.identity.directors or []) if isinstance(o, dict)]
    # R-F3426 — a CLEAN check must leave a trace. Counting the officers the register
    # actually answered for, so "checked and nothing found" is distinguishable from
    # "nobody looked". Without this the silent-clean path produced NO finding and NO
    # gap, and the DD Standard read IS-16b as NOT_RUN on a run where every officer HAD
    # been searched — a clean check reported as an unrun one, which is the same
    # certify-by-absence failure this file keeps closing, inverted.
    _dq_cleared: list[str] = []
    for _o in _officers[:8]:                     # same cost bound as the officer screen
        _nm = str(_o.get("name") or "").strip()
        if len(_nm) < 4 or _o.get("resigned_on"):
            continue
        try:
            dq = await _ch.search_disqualified_officers(_nm, limit=5)
            report.identity.meta.subcalls += 1
            if not dq.get("checked"):
                report.identity.data_gaps.append(
                    f"Disqualification check '{_nm}' NOT performed — "
                    f"{dq.get('reason', 'unavailable')} (not a clear result)")
                continue
            if not dq.get("total_results"):
                _dq_cleared.append(_nm)           # answered, genuinely nothing on file
                continue
            _cands = dq.get("candidates") or []
            report.identity.findings.append(Finding(
                severity="amber",
                title=(f"Officer {_nm}: {dq['total_results']} NAME MATCH(ES) on the "
                       f"disqualified-directors register — identity NOT confirmed"),
                detail=(
                    f"The Companies House register of disqualifications returns "
                    f"{dq['total_results']} entr(ies) sharing the surname of {_nm!r}. "
                    f"{dq.get('corroboration_required', '')} "
                    + "Candidates: "
                    + "; ".join(
                        f"{c.get('title')}"
                        + (f" ({c.get('address_snippet')})" if c.get("address_snippet") else "")
                        + (" [forename also matches]" if c.get("forename_also_matches") else "")
                        for c in _cands[:3]
                    )
                    + ". This is a name match, not a determination that this officer is "
                      "that person. "
                    + (dq.get("filter_note") or "")
                    + (f" {dq['discarded_name_coincidence']} further row(s) returned by the "
                       f"register were discarded as name coincidences (they do not carry "
                       f"this officer's surname)."
                       if dq.get("discarded_name_coincidence") else "")
                ),
                source="companies_house.disqualified_officers",
                confidence="ASSESSED",
                url=dq.get("source_url"),
                source_tier="OFFICIAL",
            ))
        except Exception as exc:
            report.identity.data_gaps.append(
                f"Disqualification check '{_nm}' raised {type(exc).__name__} — "
                f"NOT performed (not a clear result)")

    # R-F3426 — one summary line for the officers the register cleared. ONE finding
    # rather than N, because a per-officer "nothing found" would bury the report in
    # non-findings; but SOME finding, because silence is indistinguishable from
    # never having looked.
    if _dq_cleared:
        report.identity.findings.append(Finding(
            severity="info",
            title=(f"{len(_dq_cleared)} serving officer(s) checked against the "
                   f"disqualified-directors register — no match"),
            detail=(
                f"The Companies House register of disqualifications was searched for: "
                f"{', '.join(_dq_cleared[:8])}. No entry carrying any of these surnames "
                f"is on the register. The register matches on name, so this is the "
                f"absence of a name match rather than proof that no officer has ever "
                f"been disqualified — a disqualification recorded under a former or "
                f"married surname, or under another spelling, would not be found this way."
            ),
            source="companies_house.disqualified_officers",
            confidence="CONFIRMED",
            url="https://find-and-update.company-information.service.gov.uk/register-of-disqualifications",
            source_tier="OFFICIAL",
        ))


async def _run_find_case_law(report: ARKDDReport) -> None:
    """R-F3442 — UK judgments naming the subject as a PARTY (National Archives).

    Gated on the LICENCE, not on an election, because it costs nothing: there is no spend
    to authorise, only permission to establish (Open Justice Licence — see the module
    docstring). Silent when unlicensed: this is not a failure to report on every DD, it
    is a decision the operator has not taken, and the DD form already states it.
    """
    from .sources import find_case_law as _fcl

    if not _fcl.is_configured():
        return
    name = (report.identity.entity_name or "").strip()
    if len(name) < 3:
        return

    try:
        res = await _fcl.search_by_party(name)
        report.identity.meta.subcalls += 1
    except Exception as exc:
        report.identity.data_gaps.append(
            f"Find Case Law search raised {type(exc).__name__} — NOT searched "
            f"(not a clear result)")
        return

    if not res.get("searched"):
        report.identity.data_gaps.append(
            f"Find Case Law was NOT searched ({res.get('reason') or 'unknown'}) — no "
            f"view of UK judgments naming this subject as a party (not a clear result)")
        return

    judgments = res.get("judgments") or []
    if not judgments:
        report.identity.findings.append(Finding(
            severity="info",
            title="No UK judgment naming this subject as a party",
            detail=("The National Archives' Find Case Law was searched by PARTY name and "
                    "returned no judgments. This is a party search, not a keyword match, "
                    "so the result is about this subject rather than about its words."),
            source="find_case_law.judgments",
            confidence="ASSESSED",
            url=res.get("citation_url"),
            source_tier="OFFICIAL",
        ))
        return

    report.identity.findings.append(Finding(
        # Capped at amber deliberately: being a party to litigation is ordinary for any
        # trading company and says nothing on its own about which side, or the outcome.
        # The cases are the finding; the judgement stays with the reader (R-F3412).
        severity="amber",
        title=f"{len(judgments)} UK judgment(s) name this subject as a party",
        detail=("Find Case Law entries: "
                + "; ".join(j.get("title", "")[:80] for j in judgments[:4])
                + ". A party appearance does not indicate which side the subject was on "
                  "or how the matter ended."),
        source="find_case_law.judgments",
        confidence="ASSESSED",
        url=res.get("citation_url"),
        source_tier="OFFICIAL",
    ))


async def _run_ccj_search(report: ARKDDReport) -> None:
    """R-F3442 — County Court Judgments, but ONLY when the user ordered them.

    IS-17b's pass condition is the reason this is not optional-by-omission: *"A CCJ is a
    money judgment: its ABSENCE is a material finding, so an unsearched register is not a
    clean one."* So there are exactly three honest outcomes and this function must produce
    the right one every time:

      not elected      -> nothing runs, nothing is spent, and the report SAYS so
                          (`_gated_requirement_lines`, R-F3441)
      elected, no key  -> a data gap naming the obstacle. The user asked and we could not
                          deliver; that is our failure and it must never look like "clean"
      elected + backed -> the register is read and the answer, including a genuine NIL,
                          is a finding

    Metered by nature, so the gate is `_gated_search_permitted`: refusal is the default
    and an election is the only thing that authorises spend.
    """
    permitted, why = _gated_search_permitted(report, "IS-17b")
    if not permitted:
        return                      # not ordered — R-F3441 states it on the report

    name = (report.identity.entity_name or "").strip()
    if len(name) < 2:
        return
    from .sources import registry_trust as _rt

    if not _rt.is_configured():
        report.identity.data_gaps.append(
            f"CCJ search was ORDERED for this subject but could not run: "
            f"{_rt.configuration_hint()} Not searched — an unsearched judgment register "
            f"is not a clean one, and this section must not be charged for.")
        logger.warning("[R-F3442] CCJ ordered on %s but no backend configured", report.run_id)
        return

    postcode = ""
    try:
        addr = getattr(report.identity, "registered_office_address", None) or {}
        if isinstance(addr, dict):
            postcode = str(addr.get("postal_code") or addr.get("postcode") or "").strip()
    except Exception:
        postcode = ""

    try:
        res = await _rt.search_judgments(name, postcode=postcode)
        report.identity.meta.subcalls += 1
    except Exception as exc:
        report.identity.data_gaps.append(
            f"CCJ search raised {type(exc).__name__} — NOT searched (not a clear result)")
        return

    if not res.get("searched"):
        report.identity.data_gaps.append(
            f"CCJ register was NOT searched ({res.get('reason') or 'unknown'}) — "
            f"no view of County Court Judgments against this subject. An unsearched "
            f"register is not a clean one.")
        return

    judgments = res.get("judgments") or []
    _asof = f" Data as of {res['as_of']}." if res.get("as_of") else ""
    if not judgments:
        # A genuine NIL. This is a FINDING, not an absence — it is one of the few places
        # in this engine where "nothing found" is itself the evidence, because the
        # register is authoritative and complete for its jurisdiction.
        report.identity.findings.append(Finding(
            severity="info",
            title="No County Court Judgment on record against this subject",
            detail=(f"The Register of Judgments, Orders and Fines was searched by name"
                    + (f" and postcode {postcode}" if postcode else "")
                    + f" and returned no judgments.{_asof}"),
            source="registry_trust.ccj",
            confidence="CONFIRMED",
            source_tier="OFFICIAL",
        ))
        return

    unsatisfied = [j for j in judgments
                   if str(j.get("satisfied", "")).strip().lower() not in ("satisfied", "yes", "true", "1")]
    _tot = "; ".join(
        f"{j.get('currency','GBP')} {j.get('amount','?')} on {j.get('judgment_date','?')}"
        f" ({j.get('court') or 'court not stated'}"
        + (f", case {j['case_number']}" if j.get("case_number") else "") + ")"
        for j in judgments[:6])
    report.identity.findings.append(Finding(
        # A CCJ is a court's FINAL ruling on a debt, not an allegation, so unsatisfied
        # judgments are graded red. Satisfied ones are historic and stay amber. This is
        # the R-F3412 rule applied honestly: grade the procedural stage the evidence has
        # actually reached — here, judgment given.
        severity="red" if unsatisfied else "amber",
        title=(f"{len(judgments)} County Court Judgment(s) on record"
               + (f", {len(unsatisfied)} UNSATISFIED" if unsatisfied else ", all satisfied")),
        detail=(f"Register of Judgments, Orders and Fines entries against {name}: {_tot}."
                + (" An unsatisfied CCJ is a final money judgment the debtor has not paid."
                   if unsatisfied else " All recorded judgments are marked satisfied.")
                + _asof),
        source="registry_trust.ccj",
        confidence="CONFIRMED",
        source_tier="OFFICIAL",
    ))


async def _run_employment_tribunal(report: ARKDDReport) -> None:
    """R-F3424 — published employment tribunal decisions naming the subject as employer.

    WHY IT MATTERS TO A DD. Fundamental #17 was answered by CourtListener (US federal)
    and a BAILII proxy (senior UK courts). Neither carries employment tribunals, which
    is where a UK services employer — facilities management, security, cleaning — is
    actually sued. A counterparty can hold a clean High Court record and a long tribunal
    history, and only the second tells you how they treat the workforce that will
    deliver your contract.

    THE ONLY HONEST SIGNAL IS `respondent_count`. gov.uk OR-matches query words, so the
    result total is not about the subject. MEASURED 2026-07-29: "Silverbrook Capital
    Management" returns 31,098 index matches and a first page of twenty entirely
    unrelated decisions (an NHS trust, a food manufacturer, a charity) because "Capital"
    and "Management" match on their own. Reporting a count would have put "31,098
    employment tribunal results" against a small asset manager.

    So this reads ONLY the decisions whose title places the subject on the RESPONDENT
    side of the "v" — a claim brought AGAINST them. A claimant-side appearance is a
    different fact and is not litigation against the subject; a body-only appearance is
    noise. On that same query respondent_count was zero, which is the correct answer.

    Severity is deliberately capped at AMBER regardless of volume. Employment claims are
    ordinary for any large employer and most are settled or dismissed; a red here would
    equate "has staff disputes" with "is a compliance risk", which is exactly the kind
    of false signal that destroys trust in the report. The COUNT and the case numbers
    are the finding; the judgement stays with the reader.
    """
    name = (report.identity.entity_name or "").strip()
    if len(name) < 3:
        return
    from .sources import employment_tribunal as _et

    try:
        res = await _et.search_decisions(name, limit=20)
        report.identity.meta.subcalls += 1
    except Exception as exc:
        report.identity.data_gaps.append(
            f"Employment tribunal search raised {type(exc).__name__} — NOT searched "
            f"(not a clear result)")
        return

    if not res.get("ok") and res.get("outcome") != "skipped":
        report.identity.data_gaps.append(
            f"Employment tribunal search did not complete "
            f"({res.get('error') or res.get('outcome')}) — no view of tribunal claims "
            f"against this employer (not a clear result)")
        return

    respondent_hits = [h for h in (res.get("hits") or []) if h.get("side") == "respondent"]
    if not respondent_hits:
        report.identity.findings.append(Finding(
            severity="info",
            title="No employment tribunal decision naming this company as respondent",
            detail=(
                "The published employment tribunal decisions were searched and none on "
                "the first page names this company as the respondent. Note that gov.uk "
                "matches query words independently, so a raw result count is not a "
                "signal about this subject."
            ),
            source="employment_tribunal.decisions",
            confidence="ASSESSED",
            url=res.get("citation_url"),
            source_tier="OFFICIAL",
        ))
        return

    _cases = [h.get("case_number") for h in respondent_hits if h.get("case_number")]
    _recent = sorted((h.get("decided") or "") for h in respondent_hits if h.get("decided"))
    report.identity.findings.append(Finding(
        severity="amber",
        title=(f"{len(respondent_hits)} employment tribunal decision(s) name this "
               f"company as RESPONDENT"),
        detail=(
            f"Published decisions in which {name} appears as the respondent (the party "
            f"claimed against): "
            + "; ".join(h.get("title", "")[:70] for h in respondent_hits[:4])
            + (f". Case number(s): {', '.join(_cases[:6])}" if _cases else "")
            + (f". Most recent decision: {_recent[-1]}" if _recent else "")
            + ". Employment claims are ordinary for any sizeable employer and most are "
              "settled or dismissed, so this is context on workforce practice rather "
              "than a compliance finding. "
            + str(res.get("corroboration_required") or "")
        ),
        source="employment_tribunal.decisions",
        confidence="ASSESSED",
        url=res.get("citation_url"),
        source_tier="OFFICIAL",
    ))


#: R-F3403 — how many natural persons get a personal-insolvency search. Same bound as
#: the officer sanctions screen, and truncation is DISCLOSED rather than silent.
_GAZETTE_PERSON_CAP = 6


async def _run_gazette_insolvency(report: ARKDDReport) -> None:
    """R-F3403 — search The Gazette, the UK's statutory publication of record.

    WHY, GIVEN R-F3422 ALREADY WIRED COMPANIES HOUSE /insolvency. That endpoint answers
    for the COMPANY, while it remains on the register. The Gazette adds the half no
    company register can hold: PERSONAL insolvency — bankruptcy orders and IVAs against
    the natural persons who own and run the subject. A DD whose whole discipline is
    "resolve the chain to real people" cannot ask "is this director bankrupt?" without
    it. That question was previously unanswerable.

    THE HAZARD, AND WHY THE FINDINGS ARE WORDED AS THEY ARE. The Gazette is a FREE-TEXT
    search over notice text, so a hit can be a notice that merely MENTIONS the name — an
    insolvency practitioner's other case, a creditor schedule. Measured live: all 20
    corporate hits for "Carillion" were titled "Notice of Intended Dividends", i.e. body
    matches. Reported flatly they read as twenty insolvency notices ABOUT the subject.
    So findings distinguish title matches from body matches, are capped at AMBER for the
    company and never assert identity for a person, and every one carries the
    corroboration requirement. Wrongly attaching a winding-up notice to a solvent
    counterparty ends a commercial relationship; that is the cost being avoided.

    Never raises. A source that does not answer becomes a data gap, never a clean line —
    the same rule the CH registers follow, and the reason `outcome` distinguishes
    `empty` (answered, nothing on file) from `timeout` (never answered).
    """
    name = (report.identity.entity_name or "").strip()
    if len(name) < 3:
        return
    from .sources import gazette as _gz

    # ── the company ──────────────────────────────────────────────────────────
    try:
        corp = await _gz.search_insolvency(name, personal=False)
        report.identity.meta.subcalls += 1
        if not corp.get("ok") and corp.get("outcome") != "skipped":
            report.identity.data_gaps.append(
                f"Gazette corporate-insolvency search did not complete "
                f"({corp.get('error') or corp.get('outcome')}) — no view of the "
                f"statutory record (not a clear result)"
            )
        elif corp.get("hit_count"):
            _hits = corp.get("hits") or []
            _titled = [h for h in _hits if h.get("subject_in_title")]
            # A title match names the subject; a body match merely mentions it. Only
            # the first is worth an amber, and even that is not a determination.
            report.identity.findings.append(Finding(
                severity="amber" if _titled else "info",
                title=(f"Gazette: {len(_titled)} insolvency notice(s) NAMING "
                       f"{name} in the title"
                       if _titled else
                       f"Gazette: {len(_hits)} insolvency notice(s) mention "
                       f"{name} in the notice text only"),
                detail=(
                    (f"The Gazette, the UK's statutory publication of record, carries "
                     f"{len(_titled)} corporate-insolvency notice(s) whose title names "
                     f"this company: "
                     + "; ".join(h.get("title", "")[:60] for h in _titled[:3]) + ". "
                     if _titled else
                     f"{len(_hits)} corporate-insolvency notice(s) contain this name in "
                     f"their TEXT but not in their title — typically a creditor "
                     f"schedule or a practitioner's other case, not a proceeding "
                     f"against this company. ")
                    + corp.get("corroboration_required", "")
                ),
                source="gazette.corporate_insolvency",
                confidence="ASSESSED",
                url=corp.get("citation_url"),
                source_tier="OFFICIAL",
            ))
        else:
            report.identity.findings.append(Finding(
                severity="info",
                title="No corporate insolvency notice in The Gazette",
                detail=("The Gazette's insolvency notices were searched for this "
                        "company name and returned nothing."),
                source="gazette.corporate_insolvency",
                confidence="CONFIRMED",
                url=corp.get("citation_url"),
                source_tier="OFFICIAL",
            ))
    except Exception as exc:
        report.identity.data_gaps.append(
            f"Gazette corporate search raised {type(exc).__name__} — NOT searched "
            f"(not a clear result)")

    # ── the natural persons ──────────────────────────────────────────────────
    #
    # This is the part no company register can answer. Directors and PSCs both, because
    # a beneficial owner's bankruptcy bears on control just as a director's does.
    _people: list[str] = []
    for _src in (report.identity.directors, report.identity.shareholders):
        for _p in (_src or []):
            if not isinstance(_p, dict) or _p.get("resigned_on") or _p.get("ceased_on"):
                continue
            _nm = " ".join(str(_p.get("name") or "").split()).strip()
            if len(_nm) >= 4 and _nm.casefold() not in {x.casefold() for x in _people}:
                _people.append(_nm)

    if len(_people) > _GAZETTE_PERSON_CAP:
        report.identity.data_gaps.append(
            f"Personal-insolvency search capped at {_GAZETTE_PERSON_CAP} of "
            f"{len(_people)} people — {', '.join(_people[_GAZETTE_PERSON_CAP:][:4])} "
            f"NOT searched (not a clear result)"
        )

    for _nm in _people[:_GAZETTE_PERSON_CAP]:
        try:
            per = await _gz.search_insolvency(_nm, personal=True)
            report.identity.meta.subcalls += 1
            if not per.get("ok") and per.get("outcome") != "skipped":
                report.identity.data_gaps.append(
                    f"Personal-insolvency search '{_nm}' did not complete "
                    f"({per.get('error') or per.get('outcome')}) — not a clear result")
                continue
            _titled = [h for h in (per.get("hits") or []) if h.get("subject_in_title")]
            if not _titled:
                continue          # answered; nothing naming this person
            report.identity.findings.append(Finding(
                severity="amber",
                title=(f"{_nm}: {len(_titled)} personal-insolvency notice(s) matching "
                       f"this NAME — identity NOT confirmed"),
                detail=(
                    f"The Gazette carries {len(_titled)} personal-insolvency notice(s) "
                    f"(bankruptcy order or IVA) whose title matches the name {_nm!r}: "
                    + "; ".join(h.get("title", "")[:60] for h in _titled[:3])
                    + ". Personal names are far less distinctive than company names, so "
                      "this is a NAME MATCH and not a determination that this "
                      "officeholder is that person. "
                    + per.get("corroboration_required", "")
                ),
                source="gazette.personal_insolvency",
                confidence="ASSESSED",
                url=per.get("citation_url"),
                source_tier="OFFICIAL",
            ))
        except Exception as exc:
            report.identity.data_gaps.append(
                f"Personal-insolvency search '{_nm}' raised {type(exc).__name__} — "
                f"NOT searched (not a clear result)")


async def _screen_psc_sanctions(report: ARKDDReport) -> bool:
    """Screen every CURRENT PSC (beneficial owner) against sanctions.

    Returns True if a hard-stop match was found (short-circuits the DD).

    R-F3353 — this loop previously awaited a `screen_entity` attribute on the
    sanctions module: a function that has NEVER existed there (the real entrypoints
    are `screen_with_aliases` / `fuzzy_screen` / `screen_with_relationships`;
    `git log -S` over sanctions.py finds no such definition, ever). Every PSC of
    every UK DD therefore raised AttributeError into a bare `except` that logged
    a warning and recorded NOTHING — so a report listing beneficial owners with
    no sanctions finding and no data gap was indistinguishable from "screened,
    clean". That is a never-false-clean breach, not merely a dead feature.

    Two STRUCTURAL changes, so the class cannot recur — not one rename:

      1. the call goes to a VERIFIED entrypoint (§3b), declaring
         `source="registry"` because a PSC name is resolved off the Companies
         House PSC register. Screening it as untrusted free text would re-run
         the search-query shape heuristic that produced the R-F3217 false clean.

      2. EVERY non-performed outcome — source unavailable, an `error` key, or
         any throw — appends the `SANCTIONS_SOURCE_UNVERIFIED` marker that the
         synthesis gate already keys off to force the headline GREEN→AMBER_LIGHT.
         So a screen that did not run can never again read as a clean one,
         *including* if someone renames the entrypoint a second time: the
         failure then lands in the report instead of in a swallowed log line.

    Extracted from `_run_identity` so it is directly drivable by a capability
    test, the same pattern `_check_domain_ownership` uses (R-F1836) — the full
    identity layer needs live Companies House + sanctions to reach this code.
    """
    # R-F3411 — beneficial owners are officeholders for scope purposes: declining
    # IS-13b declines their screen too. Same gate, same wording, so the two paths cannot
    # drift into disagreeing about what was declined.
    _w = _scope_waived(report, "IS-13b")
    if _w is not None:
        report.identity.data_gaps.append(
            f"PSC (beneficial owner) sanctions screen WAIVED by {_w.get('waived_by')}: "
            f"{_w.get('reason')} — beneficial owners not screened on this run "
            f"(a declined check is not a clear one)"
        )
        return False

    psc_list = report.identity.shareholders or []
    if not psc_list:
        return False

    from . import sanctions as _san
    from ._sanctions_classify import classify_matches as _cm_psc, SEVERITY_RANK

    hard_stop = False
    for psc_member in psc_list[:10]:            # cap at 10 to control cost
        psc_name = (psc_member.get("name") or "").strip()
        if not psc_name or len(psc_name) < 3:
            continue
        if psc_member.get("ceased_on"):
            continue                            # skip former PSCs
        try:
            screen = await _san.screen_with_aliases(psc_name, source="registry") or {}
            report.identity.meta.subcalls += 1
            # R-F1696: an empty match list is a CLEARANCE only when the screen
            # actually reached the source. `screened=False` (or any error) means
            # it did not run, and an unperformed screen is not a clean one.
            if not (screen.get("screened") and not screen.get("error")):
                _reason = str(screen.get("error") or "source unavailable")[:80]
                report.identity.data_gaps.append(
                    f"PSC sanctions screen '{psc_name}': SANCTIONS_SOURCE_UNVERIFIED "
                    f"— {_reason}, NOT screened (re-screen required, not a clearance)"
                )
                logger.warning(
                    "dd_orchestrator: PSC sanctions screen NOT performed for %s: %s",
                    psc_name, _reason,
                )
                continue

            psc_matches = screen.get("matches") or []
            if not psc_matches:
                continue                        # screened and genuinely clean

            psc_classified = _cm_psc(psc_matches, query_name=psc_name)
            psc_worst = psc_classified["worst_severity"]
            if SEVERITY_RANK.get(psc_worst, 0) >= SEVERITY_RANK.get("amber", 1):
                natures = ", ".join(psc_member.get("natures_of_control") or [])[:120]
                report.identity.findings.append(Finding(
                    severity=psc_worst,
                    title=f"PSC (beneficial owner) {psc_name} flagged: {psc_worst}",
                    detail=(
                        f"Person of Significant Control '{psc_name}' "
                        f"(control: {natures or 'not specified'}) "
                        f"matched: {psc_classified['summary'][:300]}"
                    ),
                    source="sanctions.psc_reverse",
                    confidence="PROBABLE",
                ))
                if psc_worst == "hard_stop":
                    hard_stop = True
        except Exception as _psc_e:
            # R-F3353 — the original defect swallowed AttributeError HERE and
            # left no trace in the report. A throw is now evidence, never silence.
            report.identity.data_gaps.append(
                f"PSC sanctions screen '{psc_name}': SANCTIONS_SOURCE_UNVERIFIED "
                f"— screen raised {type(_psc_e).__name__}: {str(_psc_e)[:100]}, "
                f"NOT screened (re-screen required, not a clearance)"
            )
            logger.warning(
                "R-F886 PSC (ownership) screen failed for %s: %s "
                "(R-F3353: recorded as a data gap, not a silent clean)",
                psc_name, _psc_e,
            )
    return hard_stop


def _officer_screen_candidates(report: ARKDDReport, target: dict) -> list[dict]:
    """Every natural person who must be screened as an officeholder, de-duplicated.

    Two provenances, and the distinction is load-bearing rather than cosmetic:
    `registry` names came off a company register, `operator` names were typed into
    the DD request. Both are trusted (`sanctions._TRUSTED_NAME_SOURCES`), so both
    skip the R-F3228 search-query shape heuristic — but they are different claims
    about where a name came from, and the finding says which.

    Registry officers come FIRST so that when the cap bites it truncates the
    caller's guesses, never the register's record.
    """
    seen: set[str] = set()
    out: list[dict] = []

    def _add(name: str, role: str, provenance: str) -> None:
        nm = " ".join(str(name or "").split()).strip()
        if len(nm) < 4:
            return
        key = nm.casefold()
        if key in seen:
            return          # the same person on both lists costs one API call
        seen.add(key)
        out.append({"name": nm, "role": role or "Officer", "provenance": provenance})

    # 1. Registry-discovered officers. This is the set the DEFECT could not see:
    #    `report.identity.directors` is written by the Companies House block and by
    #    `_apply_registry_result`, both of which run AFTER the old inline screen.
    for _o in (report.identity.directors or []):
        if isinstance(_o, str):
            _add(_o, "Officer", "registry")
            continue
        if not isinstance(_o, dict):
            continue
        # A resigned officer is not a current control relationship. Mirrors the
        # PSC screen's `ceased_on` skip so the two paths agree on what "current"
        # means and neither burns quota on history.
        if _o.get("resigned_on"):
            continue
        _add(_o.get("name") or "", _o.get("officer_role") or _o.get("role") or "Officer",
             "registry")

    # 2. Caller-supplied directors / representatives, and names derivable from the
    #    contact details. Preserved verbatim from the block this replaces so the
    #    supplied path is not lost in the move.
    for _d in (target.get("directors") or []):
        if isinstance(_d, str):
            _add(_d, "Director (supplied)", "operator")
        elif isinstance(_d, dict):
            _add(_d.get("name") or "", _d.get("role") or "Director (supplied)", "operator")
    for _email_field in ("email", "contact_email"):
        _em = target.get(_email_field) or ""
        if "@" in str(_em):
            _local = str(_em).split("@")[0]
            # firstname.lastname or firstname_lastname patterns
            _parts = re.split(r"[._\-]", _local)
            if len(_parts) >= 2:
                _add(" ".join(p.capitalize() for p in _parts if len(p) > 1),
                     "Contact (from email)", "operator")
    for _cn_field in ("contact_name", "contact", "representative"):
        _add((target.get(_cn_field) or "").strip(), "Contact", "operator")

    return out


#: Cost bound carried over from the inline block this replaces. Truncation is
#: DISCLOSED (see below) rather than silent — an unscreened officer nobody
#: mentions is indistinguishable from a screened clean one.
_OFFICER_SCREEN_CAP = 8


async def _screen_officer_sanctions(report: ARKDDReport, target: dict) -> bool:
    """Screen every CURRENT officeholder against sanctions. True on a hard stop.

    R-F3397 — this replaces an inline block in `_run_identity` that carried three
    faults, all of which the PSC sibling had already been given a fix for:

      1. POSITION. It ran at :4503 over `target["directors"]` alone, while the
         registry does not write `report.identity.directors` until :4765. A DD
         launched by company name screened ZERO officers and said nothing about it.

      2. It never checked `screened`/`error`, so an unreachable source returned
         `matches: []` and the block emitted "<role> <name> — sanctions screen
         CLEAN" at confidence CONFIRMED. A screen that reached no list, certifying
         a named human being clean.

      3. It passed no `source=`, so register-sourced names went through the
         free-text shape heuristic that produced the R-F3217 false clean.

    Extracted (rather than moved) for the R-F3353/R-F1836 reason: the full identity
    layer needs live Companies House + sanctions to reach this code, so an inline
    loop is not drivable by a capability test and its honesty rules cannot be
    asserted. Callers: `_run_identity`, once, after every registry write.
    """
    # R-F3411 — IS-13b (officeholder screening) may be declined for this run. Checked
    # before the candidate walk so no name reaches a metered source.
    _w = _scope_waived(report, "IS-13b")
    if _w is not None:
        report.identity.data_gaps.append(
            f"Officer sanctions screen WAIVED by {_w.get('waived_by')}: "
            f"{_w.get('reason')} — officers not screened on this run "
            f"(a declined check is not a clear one)"
        )
        return False

    candidates = _officer_screen_candidates(report, target)
    if not candidates:
        return False

    from . import sanctions as _san
    from ._sanctions_classify import classify_matches as _cm_off

    hard_stop = False
    _screened = candidates[:_OFFICER_SCREEN_CAP]
    if len(candidates) > _OFFICER_SCREEN_CAP:
        # Never a silent truncation: the report states who was NOT reached.
        _unscreened = [c["name"] for c in candidates[_OFFICER_SCREEN_CAP:]]
        report.identity.data_gaps.append(
            f"Officer sanctions screen capped at {_OFFICER_SCREEN_CAP} of "
            f"{len(candidates)} officeholders — SANCTIONS_SOURCE_UNVERIFIED for "
            f"{', '.join(_unscreened[:6])}"
            f"{f' and {len(_unscreened) - 6} more' if len(_unscreened) > 6 else ''} "
            f"(not screened, not a clearance). WHY: the per-run screening cap bounds "
            f"cost; it is not a statement about these people. WHAT CLOSES IT: re-run "
            f"with a raised cap, or screen the remaining officeholders individually."
        )

    # R-F3456 — accumulated across the loop so the group is reported once.
    _off_unscreened: list[tuple[str, str]] = []

    for _c in _screened:
        _nm, _role = _c["name"], _c["role"]
        _src = "registry" if _c["provenance"] == "registry" else "operator"
        try:
            screen = await _san.screen_with_aliases(_nm, source=_src) or {}
            report.identity.meta.subcalls += 1
            # R-F1696: an empty match list is a CLEARANCE only when the screen
            # actually reached the source.
            if not (screen.get("screened") and not screen.get("error")):
                _reason = str(screen.get("error") or "source unavailable")[:80]
                # R-F3456 — COLLECTED, not appended one-per-officer. Eight officeholders
                # produced eight near-identical 180-character lines carrying the same
                # reason, which is most of why the gaps block read as a wall of text.
                _off_unscreened.append((_nm, _reason))
                logger.warning(
                    "dd_orchestrator: officer sanctions screen NOT performed for %s: %s",
                    _nm, _reason,
                )
                continue

            _cls = _cm_off(screen.get("matches") or [], query_name=_nm)
            _worst = _cls["worst_severity"]
            # `source` stays "sanctions.director_screen" — two consumers key off
            # that exact string (the SAR cross-board trigger and the ACH shell
            # hypothesis). Both were starved by the defect and are fed for the
            # first time by this fix; renaming it would re-starve them.
            if _worst == "hard_stop":
                report.identity.findings.append(Finding(
                    severity="hard_stop",
                    title=f"{_role} {_nm} on active sanctions list",
                    detail=_cls["summary"],
                    source="sanctions.director_screen",
                    confidence="CONFIRMED",
                ))
                hard_stop = True
            elif _worst == "red":
                report.identity.findings.append(Finding(
                    severity="red",
                    title=f"{_role} {_nm} linked to crime/debarment list",
                    detail=_cls["summary"],
                    source="sanctions.director_screen",
                    confidence="PROBABLE",
                ))
            elif _worst == "amber":
                report.identity.findings.append(Finding(
                    severity="amber",
                    title=f"{_role} {_nm} on PEP / adverse-media list",
                    detail=_cls["summary"] + " — enhanced DD required on individual.",
                    source="sanctions.director_screen",
                    confidence="ASSESSED",
                ))
            else:
                report.identity.findings.append(Finding(
                    severity="info",
                    title=f"{_role} {_nm} — sanctions screen CLEAN",
                    detail=(
                        f"No matches for {_nm} across the sanctions/PEP datasets "
                        f"reached by this screen. Name resolved from "
                        f"{'the company register' if _src == 'registry' else 'the DD request'}."
                    ),
                    source="sanctions.director_screen",
                    confidence="CONFIRMED",
                ))
        except Exception as _off_e:
            # A throw is evidence, never silence — the R-F3353 rule, applied to the
            # path that never received it.
            _off_unscreened.append(
                (_nm, f"screen raised {type(_off_e).__name__}: {str(_off_e)[:100]}"))
            logger.warning(
                "R-F3397 officer sanctions screen failed for %s: %s "
                "(recorded as a data gap, not a silent clean)",
                _nm, _off_e,
            )

    # R-F3456 — ONE gap for the whole group, stating who, why, and what closes it.
    #
    # CRITICAL: the marker `SANCTIONS_SOURCE_UNVERIFIED` MUST survive here. The synthesis
    # freshness gate greps identity.data_gaps for that exact substring to force the
    # headline non-GREEN, so grouping these lines without carrying the marker would
    # silently remove the AMBER override — a false clearance created by a formatting
    # change. Distinct reasons are listed rather than collapsed, because "source
    # unavailable" and "screen raised TimeoutError" call for different actions.
    if _off_unscreened:
        _reasons_seen: list[str] = []
        for _, _r in _off_unscreened:
            if _r not in _reasons_seen:
                _reasons_seen.append(_r)
        _names = ", ".join(n for n, _ in _off_unscreened)
        report.identity.data_gaps.append(
            f"Officer sanctions screen: SANCTIONS_SOURCE_UNVERIFIED — "
            f"{len(_off_unscreened)} officeholder(s) NOT screened "
            f"({'; '.join(_reasons_seen[:3])}). "
            f"NOT a clearance: nothing is known about these individuals' sanctions "
            f"status on this run, and a designated officer would not appear. "
            f"WHAT CLOSES IT: re-run the screen once the source is reachable. "
            f"WHO: {_names}"
        )
    return hard_stop


def _export_control_is_unsupported_negative(
    *, product_supplied: bool, military_sic_present: bool, recommendation: str,
) -> bool:
    """R-F3454 — is this "civilian" verdict a CONCLUSION, or just an empty input?

    A pure predicate, and pure deliberately: the same question is asked by the report
    renderer and by the R-F3040 military-SIC contradiction check further down, and the
    first version of this fix rewrote the recommendation string BEFORE R-F3040 read it —
    which silently disarmed R-F3040's amber finding, because it detects a contradiction by
    looking for the words "civilian"/"unclassified" in that very string. One predicate,
    consulted by both, is what stops that.

    Returns True only when ALL of:
      * no product/goods/transaction was supplied, so nothing about the goods was
        classified — what got classified was the entity's registered or self-described
        activity, which for a group holding company describes administration whatever its
        subsidiaries manufacture (the Babcock case);
      * no military SIC is on the registry, since that IS evidence bearing on export
        control and must keep its R-F3040 treatment;
      * and the recommendation is the classifier's no-hits value.

    The asymmetry is the point: a POSITIVE classification from a weak input still stands,
    because it is evidence. Only an unsupported NEGATIVE is withdrawn.
    """
    if product_supplied or military_sic_present:
        return False
    rec = (recommendation or "").lower()
    return "civilian" in rec or "unclassified" in rec


#: R-F3452 — the primary adapters that ARE sanctions lists. sec_edgar (filings),
#: wb_debarred (debarment) and acled (conflict events) are useful elsewhere and are NOT
#: sanctions lists; counting them toward sanctions coverage would be the same
#: certify-by-something-else move this function exists to remove.
_SANCTIONS_PRIMARY_LISTS: dict[str, str] = {
    "ofac_sdn": "OFAC SDN",
    "uk_ofsi": "UK OFSI consolidated list",
    "un_sc": "UN Security Council consolidated list",
}


def _record_sanctions_screen(report, screen: dict) -> None:
    """R-F3535 — assign the sanctions screen AND run the evidence shadow. ONE place.

    THE DEFECT THIS CLOSES, and it is my own from R-F3510. `sanctions_evidence_shadow`
    was written to prove the R-F3474 evidence contract reproduces live behaviour before
    anything depends on it — its docstring says "a caller records it and reads it later".
    **It had no caller.** A dormant guard against a dormant specification: phase 2 of the
    consolidation could never be evidence-based, because no evidence was ever collected.

    WHY A RECORDER AND NOT FOUR CALLS. There are FOUR sites that assign
    `identity.sanctions_screen` — the variant path, the registered-name path, the WAIVER
    path, and the alias/OFSI path that a company DD actually takes. R-F3038 exists
    because R-F3031 stamped only the first of them and a live report still could not date
    its own screen. Wiring the shadow at one site would repeat that exactly, and the
    disagreement data would be silently partial — which is worse than none, because it
    would look like coverage.

    The comparison is stored ON the screen under `_evidence_shadow`, so it travels with
    the stored report and can be read back from any run. Shadow means shadow: no finding,
    no verdict and no wording changes, and a failure here can never cost a screen.
    """
    report.identity.sanctions_screen = screen
    try:
        if isinstance(screen, dict):
            screen["_evidence_shadow"] = sanctions_evidence_shadow(screen)
    except Exception as _e:  # noqa: BLE001 — a diagnostic must never break a DD
        logger.debug("[R-F3535] evidence shadow skipped: %s", _e)


@fail_wire(module="dd_orchestrator", gap_type="engine_failure")
def sanctions_evidence_shadow(screen: dict) -> dict:
    """R-F3510 — derive the sanctions state through the EVIDENCE CONTRACT, in SHADOW.

    PHASE 1 OF A CONSOLIDATION, and deliberately inert. R-F3474 built an orthogonal
    four-axis contract that nothing calls; the live sanctions state is expressed ad hoc
    across `screened` / `source_unavailable` / `partial_coverage` / `error`. Two ways of
    saying the same thing is the phase-gate fork that produced fabricated passes, so the
    end state is ONE measure.

    Getting there safely means proving the contract REPRODUCES today's behaviour before
    anything depends on it. This function maps the live state onto the four axes, derives
    a verdict with production contract code, and returns the comparison. It changes no
    finding, no verdict and no wording — a caller records it and reads it later.

    A DISAGREEMENT IS A FINDING, not a licence to switch. Either the mapping is wrong or
    one of the two measures is, and both are worth knowing before the ad-hoc path is
    deleted.
    """
    from .dd_evidence_standard import (
        AttemptOutcome, ConfigurationState, EvidenceAssessment, MatchOutcome, SourceState,
    )
    if not isinstance(screen, dict) or not screen:
        return {"mapped": False, "reason": "no screen"}

    err = str(screen.get("error") or "").strip()
    screened = bool(screen.get("screened"))
    unavailable = bool(screen.get("source_unavailable"))
    partial = bool(screen.get("partial_coverage"))
    blocked = bool(screen.get("blocked"))
    matches = screen.get("matches") or []

    # ── configuration ──
    if err == "not_entity_shaped":
        # The subject name was refused by the screening guard, so no list was queried.
        config = ConfigurationState.NOT_APPLICABLE
    else:
        config = ConfigurationState.CONFIGURED

    # ── source ──
    if screen.get("stale"):
        source = SourceState.STALE
    elif partial:
        # Some primary lists answered, the consolidated aggregate did not (R-F3452).
        source = SourceState.DEGRADED
    elif unavailable:
        source = SourceState.UNAVAILABLE
    elif screened:
        source = SourceState.CURRENT
    else:
        source = SourceState.UNKNOWN

    # ── attempt ──
    if config == ConfigurationState.NOT_APPLICABLE:
        attempt = AttemptOutcome.NOT_ATTEMPTED
    elif partial:
        attempt = AttemptOutcome.PARTIAL
    elif screened:
        attempt = AttemptOutcome.SUCCEEDED
    elif unavailable or err:
        attempt = AttemptOutcome.SOURCE_FAILED
    else:
        attempt = AttemptOutcome.NOT_ATTEMPTED

    # ── match ──
    if attempt in (AttemptOutcome.NOT_ATTEMPTED, AttemptOutcome.SOURCE_FAILED):
        match = MatchOutcome.NOT_EVALUATED
    elif blocked:
        match = MatchOutcome.MATCH
    elif matches:
        # Scored hits that were NOT corroborated into a block (R-F2840): named, but not
        # a designation. `ambiguous` is the contract's word for exactly that.
        match = MatchOutcome.AMBIGUOUS
    else:
        match = MatchOutcome.NO_MATCH

    try:
        assessment = EvidenceAssessment(
            configuration_state=config, source_state=source,
            attempt_outcome=attempt, match_outcome=match)
        verdict = assessment.derive_verdict().value
    except Exception as e:  # a rejected combination is itself a finding
        return {"mapped": False, "reason": f"contract rejected the mapping: {e}",
                "axes": {"configuration_state": config.value, "source_state": source.value,
                         "attempt_outcome": attempt.value, "match_outcome": match.value}}

    # What the LIVE path says today, in the contract's vocabulary.
    if partial:
        # Some lists answered: the evidence is impaired, not absent.
        live = "degraded"
    elif unavailable or (err and not screened):
        # NOTHING answered, so the check did not run. The contract's word is `blocked`,
        # and the distinction is real: `degraded` claims evidence was gathered and
        # weakened, which would overstate what a failed screen actually produced.
        # My first mapping said `degraded` here and the shadow comparison caught it —
        # which is the entire reason this phase exists.
        live = "blocked"
    elif blocked:
        live = "completed_match"
    elif screened and not matches:
        live = "completed_no_match"
    elif screened:
        live = "completed_partial"
    else:
        live = "not_run"

    return {
        "mapped": True,
        "axes": {"configuration_state": config.value, "source_state": source.value,
                 "attempt_outcome": attempt.value, "match_outcome": match.value},
        "contract_verdict": verdict,
        "live_equivalent": live,
        "agrees": verdict == live,
        # Inert by construction. Nothing reads this to decide anything.
        "shadow_only": True,
    }


def _reconcile_sanctions_coverage(name: str, report: ARKDDReport) -> None:
    """R-F3452 — say WHICH lists were screened, instead of "no screen was performed".

    THE DEFECT, from a delivered report on Babcock International Group PLC. The screen
    reported::

        Sanctions screen NOT performed — UNVERIFIED
        the sanctions source (OpenSanctions / primary lists) could not be reached,
        so NO screen was performed.

    while THE SAME REPORT printed an OFAC SDN result three sections later. Both came from
    the same run. The aggregate (`sanctions.fuzzy_screen`) consults OpenSanctions and
    nothing else, so `screened` goes false the moment that one free third-party is
    unreachable — but `_identity_primary_source_screen` had separately queried OFAC SDN,
    UK OFSI and UN SC, and recorded per-list availability.

    Two different statements were true at once and the report published the more alarming
    one as if it were the whole picture. "Nothing was screened" and "the consolidated
    cross-list screen did not run, but three primary lists did" lead a compliance reader
    to opposite actions.

    WHAT THIS DOES NOT DO. It does not upgrade the verdict, clear the entity, or remove
    the AMBER override — partial coverage is not a clearance, and every gap stays. It
    changes only the CLAIM, from a false one to a true one, and names what is still
    missing so the reader can close it.

    Never raises: a wording reconciliation must not be able to fail a report.
    """
    try:
        screen = getattr(report.identity, "sanctions_screen", None)
        if not isinstance(screen, dict) or not screen.get("source_unavailable"):
            return
        snaps = screen.get("primary_snapshots")
        if not isinstance(snaps, dict):
            return

        screened = [k for k in _SANCTIONS_PRIMARY_LISTS if snaps.get(k) == "ok"]
        if not screened:
            # Nothing answered. The existing wording is already true — leave it alone.
            return
        missed = [k for k in _SANCTIONS_PRIMARY_LISTS if k not in screened]

        did = ", ".join(_SANCTIONS_PRIMARY_LISTS[k] for k in screened)
        not_done = ", ".join(_SANCTIONS_PRIMARY_LISTS[k] for k in missed)
        reasons = ", ".join((screen.get("source_reasons") or [])[:4]) or "source unreachable"

        # Machine-readable, so a renderer never has to parse the prose back out.
        screen["partial_coverage"] = True
        screen["lists_screened"] = list(screened)
        screen["lists_not_screened"] = list(missed)
        screen["lists_screened_labels"] = [_SANCTIONS_PRIMARY_LISTS[k] for k in screened]
        screen["lists_not_screened_labels"] = [_SANCTIONS_PRIMARY_LISTS[k] for k in missed]

        detail = (
            f"{name} — the OpenSanctions consolidated aggregate could not be reached "
            f"({reasons}), so the cross-list screen did not run. ARIA's own snapshots of "
            f"these primary lists DID answer and were screened: {did}."
            + (f" NOT screened: {not_done}." if not_done else "")
            + " This is PARTIAL COVERAGE and is NOT a clearance: the EU consolidated list "
              "and any list not named above were not checked on this run, and a "
              "designation made since the last snapshot refresh would not appear. "
              "Re-screen against the full set before relying on this."
        )
        for f in (getattr(report.identity, "findings", None) or []):
            if getattr(f, "title", "") == "Sanctions screen NOT performed — UNVERIFIED":
                f.title = (f"Sanctions screen PARTIAL — {did} screened, "
                           f"consolidated aggregate unavailable")
                f.detail = detail
                break

        gaps = getattr(report.identity, "data_gaps", None)
        if isinstance(gaps, list):
            for i, g in enumerate(gaps):
                if str(g).startswith("sanctions screen did not complete"):
                    gaps[i] = (
                        f"sanctions screen PARTIAL — the OpenSanctions consolidated "
                        f"aggregate did not complete ({reasons}); {did} were screened"
                        + (f"; {not_done} were NOT" if not_done else "")
                        + ". Not a clearance — re-screen against the full set."
                    )
                    break
    except Exception as _e:  # noqa: BLE001 — never fail a report over wording
        logger.debug("[R-F3452] sanctions coverage reconciliation skipped: %s", _e)


async def _run_identity(
    target: dict,
    report: ARKDDReport,
) -> bool:
    """Layer 1 — Identity. Returns True if a hard-stop was triggered
    (sanctions hit), signalling the orchestrator to short-circuit."""
    entity_type = target.get("type") or EntityType.UNKNOWN.value
    # Person branch — separate logic path because persons don't have
    # Companies House, CUI, ghost score, or address pattern checks.
    # They DO need name-variant resolution, multi-variant sanctions
    # screening, and PEP classification.
    if entity_type == EntityType.PERSON.value or entity_type == "person":
        return await _run_identity_person(target, report)

    t0 = time.time()
    report.identity.meta.started_at = datetime.now(timezone.utc).isoformat()

    name = target.get("name") or target.get("entity") or target.get("query", "")
    jurisdiction = target.get("jurisdiction")
    jurisdiction_iso2 = target.get("jurisdiction_iso2")
    # R-F2976 — normalize a caller-SUPPLIED jurisdiction alias to ISO2 so the
    # GB-gated registry / officer / UBO paths fire. Live DD 2026-07-24 (Silverbrook,
    # a real UK company, Companies House 04300718): jurisdiction_iso2="UK" was used
    # RAW — "UK" != "GB", so the Companies House lookup (~line 3560), the officer
    # walk (network_walker), and the UBO walk (~line 10029) were ALL skipped → no
    # directors / no incorporation date → identity incomplete → confidence gate
    # stuck at AMBER / grade D. resolve_jurisdiction_iso2() below only runs when NO
    # value is supplied, so a supplied alias never got normalized. to_iso2 maps
    # UK→GB / USA→US / UAE→AE and returns None for junk (then keep the raw value).
    if jurisdiction_iso2:
        try:
            from .country_taxonomy import to_iso2 as _to_iso2_norm
            _norm_j = _to_iso2_norm(jurisdiction_iso2)
            if _norm_j:
                jurisdiction_iso2 = _norm_j
        except Exception:
            pass
    registration_number = target.get("registration_number")
    # Jurisdiction-specific registration IDs flow into registration_number
    # when the caller didn't supply one explicitly. This keeps the
    # downstream renderer, ghost scorer, and manual-registry hint
    # working on any jurisdiction we recognise.
    if not registration_number:
        for _k in ("cui", "nip", "cnpj", "cvr", "kvk", "siret", "vat"):
            if target.get(_k):
                registration_number = str(target[_k])
                break

    # ── Auto-detect jurisdiction from clues when not provided ──
    # R-F2838 — routed through resolve_jurisdiction_iso2 so a DECLARED jurisdiction
    # beats a suffix clue. Previously a caller passing jurisdiction="CH" still got
    # PT inferred from the "SA" suffix, and the entire compliance layer scored the
    # wrong country on a live customer report.
    if not jurisdiction_iso2:
        jurisdiction_iso2 = resolve_jurisdiction_iso2(target, name, registration_number)
        if jurisdiction_iso2:
            jurisdiction = jurisdiction or _ISO2_TO_COUNTRY.get(jurisdiction_iso2, "")
            logger.info("Jurisdiction inferred: %s → %s", jurisdiction_iso2, jurisdiction)

    # ── Also try IČO / ico key as registration number for SK/CZ ──
    if not registration_number:
        for _k in ("ico", "ičo", "IČO", "ICO"):
            if target.get(_k):
                registration_number = str(target[_k]).replace(" ", "")
                if not jurisdiction_iso2:
                    jurisdiction_iso2 = "SK"
                    jurisdiction = "Slovak Republic"
                break

    report.identity.entity_name = _coerce_entity_text(name)   # R-F3268
    report.identity.entity_type = entity_type
    report.identity.jurisdiction = jurisdiction
    report.identity.jurisdiction_iso2 = jurisdiction_iso2
    report.identity.registration_number = registration_number

    # R-F1876 (direct-source-first R2): GLEIF authoritative enrichment. Fill any
    # registration fields the caller didn't supply with AUTHORITATIVE data from
    # the free, global, key-less GLEIF LEI registry — legal name / LEI /
    # jurisdiction / registered-as id / status / legal address. Independent of
    # web search. Matching is CONSERVATIVE (gleif.best_match) so a near-miss can
    # never inject another entity's data — the exact failure mode behind the
    # 2026-04-09 Modirum fabrication incident. Only fills EMPTY fields (never
    # overwrites caller/registry data). Best-effort; never raises.
    if entity_type != EntityType.PERSON.value and name:
        try:
            from . import gleif as _gleif
            _gl_hits = await _gleif.search_lei(name, country=jurisdiction_iso2)
            if not _gl_hits and jurisdiction_iso2:
                _gl_hits = await _gleif.search_lei(name)  # retry without the country filter
            _gl = _gleif.best_match(name, _gl_hits)
            if _gl:
                _filled = []
                if not report.identity.registration_number and _gl.get("registered_as"):
                    report.identity.registration_number = _gl["registered_as"]; _filled.append("reg#")
                if not report.identity.jurisdiction_iso2 and _gl.get("jurisdiction"):
                    report.identity.jurisdiction_iso2 = _gl["jurisdiction"]; _filled.append("jurisdiction")
                if not report.identity.registration_status and _gl.get("status"):
                    report.identity.registration_status = (_gl["status"] or "").lower(); _filled.append("status")
                if not report.identity.registered_address and _gl.get("legal_address"):
                    report.identity.registered_address = _gl["legal_address"]; _filled.append("address")
                # R-F3021 — record the LEI registration state STRUCTURALLY before
                # the prose finding. A LAPSED/RETIRED LEI means the holder stopped
                # renewing it: for a regulated counterparty that is a real
                # maintenance signal, and it was previously visible only inside a
                # sentence of an info-severity finding — unreadable to the
                # scorecard, the PDF, or any filter. Recorded for EVERY status
                # (ISSUED included) so "not lapsed" is an observation, not a
                # silence, and `lapsed` is only True when GLEIF actually said so.
                _lei_reg_status = str(_gl.get("registration_status") or "").upper()
                report.identity.lei_registration = {
                    "lei": _gl.get("lei") or "",
                    "registration_status": _lei_reg_status or "UNKNOWN",
                    "entity_status": str(_gl.get("status") or "").upper() or "UNKNOWN",
                    "lapsed": _lei_reg_status in {"LAPSED", "RETIRED", "ANNULLED"},
                    "source_url": _gl.get("source_url") or "",
                }
                if report.identity.lei_registration["lapsed"]:
                    report.identity.findings.append(Finding(
                        severity="low",
                        title=(f"LEI {_gl.get('lei')} is {_lei_reg_status} — the entity has "
                               "not renewed its Legal Entity Identifier"),
                        detail=(
                            f"GLEIF reports LEI registration status {_lei_reg_status} for "
                            f"'{_gl.get('legal_name')}'. An LEI lapses when the holder stops "
                            "paying/confirming the annual renewal; GLEIF then stops validating "
                            "the reference data. This is NOT a sanctions, solvency or legality "
                            "signal and the entity may be trading normally — it does mean the "
                            "LEI-sourced fields below are no longer GLEIF-validated, and that a "
                            "counterparty required to hold a current LEI for regulated "
                            "transactions would need to renew it. "
                            f"Entity status per GLEIF: {_gl.get('status') or 'unknown'}. "
                            f"Source: {_gl.get('source_url')}."
                        ),
                        source="gleif.search_lei",
                        confidence="CONFIRMED",
                    ))
                report.identity.findings.append(Finding(
                    severity="info",
                    title=f"GLEIF: LEI {_gl.get('lei')} — {_gl.get('legal_name')}",
                    detail=(
                        f"Authoritative GLEIF record (free global LEI registry): legal name "
                        f"'{_gl.get('legal_name')}', jurisdiction {_gl.get('jurisdiction') or '?'}, "
                        f"registered as '{_gl.get('registered_as') or '?'}', entity status "
                        f"{_gl.get('status') or '?'}, LEI registration {_gl.get('registration_status') or '?'}. "
                        f"Source: {_gl.get('source_url')}. Fields filled from GLEIF: "
                        f"{', '.join(_filled) if _filled else 'none (all already known)'}."
                    ),
                    source="gleif.search_lei",
                    confidence="PROBABLE",
                ))
                logger.info("R-F1876 GLEIF match for %r: LEI=%s filled=%s", name[:60], _gl.get("lei"), _filled)
        except Exception as _gl_e:
            logger.debug("R-F1876 GLEIF enrichment failed (non-fatal): %s", _gl_e)

    # R-F1895 (review #4): if jurisdiction is STILL unknown after GLEIF, mine the
    # entity's OWN site for a self-reported HQ/office footprint. A stated
    # "Finland Helsinki HQ" is a LEGITIMATE jurisdiction indicator (unlike the
    # TLD/language the Clause-14 guard rejects) — and without it the compliance
    # layer stays wired-but-silent (no jurisdiction → no country risk → the thin
    # 'INSUFFICIENT EVIDENCE' the operator saw). Tagged SELF-REPORTED (registry
    # verification still required — no fabrication). Mined pages are stashed on
    # target so _run_digital reuses them (no double-mine).
    if entity_type != EntityType.PERSON.value and not report.identity.jurisdiction_iso2:
        _site_id = ""
        for _c in (target.get("website"), target.get("url"), target.get("domain")):
            if _c and isinstance(_c, str) and _c.strip():
                _site_id = _c.strip(); break
        if _site_id:
            if not _site_id.lower().startswith(("http://", "https://")):
                _site_id = "https://" + _site_id
            try:
                _mined_id = await _mine_entity_website(_site_id)
                if _mined_id:
                    target["_mined_pages"] = _mined_id  # R-F1895: reuse in _run_digital
                    # R-F1903: also seed declared_activity from the site's OWN
                    # description (homepage title) when empty, so the export-control
                    # classifier (compliance 4b) has a product/activity to classify
                    # instead of being skipped — the same under-extraction as the
                    # jurisdiction gap. Self-reported; the EC result is tagged as
                    # classified-from-self-description, not an authoritative ECCN.
                    if not report.identity.declared_activity:
                        _home = next((p for p in _mined_id if p.get("label") == "homepage"), _mined_id[0])
                        _act = (_home.get("title") or "").strip() or (_home.get("text") or "")[:160].strip()
                        # strip a trailing " | Brand" / " — Brand" boilerplate
                        _act = re.split(r"\s*[|—–]\s*", _act)[0].strip()
                        if _act and len(_act) > 3:
                            report.identity.declared_activity = _act[:200]
                    _loc = _extract_site_locations(" ".join(p.get("text", "") for p in _mined_id))
                    if _loc.get("hq_iso2"):
                        report.identity.jurisdiction_iso2 = _loc["hq_iso2"]
                        if not report.identity.jurisdiction:
                            report.identity.jurisdiction = (_loc.get("hq_country") or "").title()
                        _offices = ", ".join(_loc.get("countries") or [])
                        report.identity.findings.append(Finding(
                            severity="info",
                            title=f"Self-reported HQ: {(_loc.get('hq_country') or '').title()} ({_loc['hq_iso2']})",
                            detail=(
                                f"The entity's own website states its HQ is in "
                                f"{(_loc.get('hq_country') or '?').title()}; office footprint: {_offices or 'n/a'}. "
                                f"SELF-REPORTED (site, not registry-verified) — used to seed jurisdiction so "
                                f"compliance/country-risk can run. Registry confirmation still required."
                            ),
                            source="entity_site:locations",
                            confidence="ASSESSED",
                        ))
                        report.identity.data_gaps.append(
                            f"R-F1895: jurisdiction {_loc['hq_iso2']} is SELF-REPORTED from the entity's site "
                            f"(stated HQ) — NOT registry-verified; confirm against the national registry."
                        )
                        logger.info("R-F1895 site-derived HQ jurisdiction for %r: %s (offices=%s)",
                                    name[:60], _loc["hq_iso2"], _loc.get("countries"))
            except Exception as _loc_e:
                logger.debug("R-F1895 site-location extraction failed (non-fatal): %s", _loc_e)

    hard_stop = False

    # Romanian CUI → incorporation-date analyzer. If the caller
    # supplies a CUI (directly, via registration_number on a RO
    # jurisdiction, or in free text extracted by the chat intent
    # detector), run the sequential-CUI analysis and emit a finding.
    # This runs BEFORE the ghost scorer so the orchestrator can
    # surface the CUI-derived incorporation estimate as a first-class
    # identity signal, not just as an internal input to ghost
    # indicator 11.
    if (jurisdiction_iso2 == "RO" or (jurisdiction or "").lower() == "romania") and (target.get("cui") or registration_number):
        try:
            from . import _romanian_cui as _ro_cui
            _analysis = _ro_cui.analyse_cui(target.get("cui") or registration_number)
            if _analysis and _analysis.estimated_incorporation:
                report.identity.incorporation_date = _analysis.estimated_incorporation.isoformat()
                report.identity.findings.append(Finding(
                    severity="info",
                    title=f"Romanian CUI {_analysis.cui} estimates incorporation ≈ {_analysis.estimated_incorporation.isoformat()}",
                    detail=(
                        f"Sequential-CUI analysis places incorporation at "
                        f"{_analysis.estimated_incorporation.isoformat()} "
                        f"(±{_analysis.uncertainty_months} months). "
                        f"Company age: {_analysis.age_months_now} months. "
                        f"{_analysis.notes}. "
                        f"VERIFY against ONRC portal (https://portal.onrc.ro) "
                        f"before relying on this date."
                    ),
                    source="_romanian_cui.analyse_cui",
                    confidence="ASSESSED",
                ))
                # Also cross-check claimed founding year if supplied
                _claimed = target.get("claimed_founding_year")
                if _claimed is not None:
                    _cmp = _ro_cui.compare_claimed_founding(_analysis.cui, int(_claimed))
                    if _cmp["severity"] in ("red", "hard_stop"):
                        report.identity.findings.append(Finding(
                            severity=_cmp["severity"],
                            title=f"Founding-year misrepresentation: claimed {_claimed} vs CUI-estimated {_cmp['estimated_incorporation_year']}",
                            detail=_cmp["detail"],
                            source="_romanian_cui.compare_claimed_founding",
                            confidence="PROBABLE",
                        ))
                        if _cmp["severity"] == "hard_stop":
                            hard_stop = True
        except Exception as e:
            logger.debug("Romanian CUI analysis failed (non-fatal): %s", e)

    # If the caller supplied a registered address (via chat intent or
    # direct API), use it as the initial identity signal. Registry
    # lookup may overwrite it with authoritative data later.
    supplied_address = target.get("registered_address")
    if supplied_address and not report.identity.registered_address:
        report.identity.registered_address = supplied_address
        # Residential-apartment pattern detection. A registered office
        # at a specific apartment number inside a named block is a
        # ghost-indicator signal (indicator 2 — no verifiable physical
        # premises). We add it as an amber finding so the LLM sees it
        # without the orchestrator having to ship an expensive registry
        # lookup first.
        _addr_lower = supplied_address.lower()
        _residential_patterns = (
            "apt.", "apt ", " ap.", " ap ", " ap,", "apartment",
            "flat ", "unit ", "sc. ", "bl. ", "et. ", "etaj ", "floor ",
        )
        if any(p in _addr_lower for p in _residential_patterns):
            report.identity.findings.append(Finding(
                severity="amber",
                title=f"Registered address is a residential apartment",
                detail=(
                    f"'{supplied_address}' — the address decodes to an apartment "
                    f"inside a named block/staircase/floor, not a commercial office. "
                    f"This matches ghost-indicator 2 (no verifiable physical premises). "
                    f"Not a refusal ground on its own; requires verification against "
                    f"the national registry and cross-check against the number of "
                    f"other entities registered at the same address."
                ),
                source="dd_orchestrator.residential_address_pattern",
                confidence="ASSESSED",
            ))

        # ── Virtual-office / mail-drop detection ──
        # Catches CMRA addresses (e.g. North Miami Beach corridor,
        # Cheyenne WY mass-registration), PMB markers, and registered-
        # agent towers. Added 2026-04-17 after the F3 / SERBAN DD
        # learnings — a US LLC at a virtual-office address should
        # always carry an explicit signal.
        try:
            from . import virtual_office_registry
            _vo = virtual_office_registry.check_address(supplied_address)
            if _vo.get("is_virtual_office"):
                _sev = "red" if _vo.get("risk") == "high" else "amber"
                _provider = _vo.get("provider") or "virtual-office / mail-drop"
                _signals = " ".join(_vo.get("signals") or [])
                _notes = _vo.get("notes") or ""
                report.identity.findings.append(Finding(
                    severity=_sev,
                    title=f"Registered address is a virtual office / mail drop",
                    detail=(
                        f"'{supplied_address}' matches a known virtual-office "
                        f"or CMRA pattern: {_provider}. {_signals} {_notes} "
                        f"Operating business is unlikely to be physically at "
                        f"this address. Require counterparty to disclose the "
                        f"actual principal place of business before proceeding."
                    ).strip(),
                    source="dd_orchestrator.virtual_office_detector",
                    confidence="ASSESSED",
                ))
        except Exception as _vo_err:
            logger.debug("Virtual-office check failed (non-fatal): %s", _vo_err)

    # ── FinCEN BOI caveat for US entities ──
    # MOVED OUT of the `if supplied_address` guard 2026-04-17 PM so the
    # caveat also fires on URL-based / name-only DDs where the address
    # may only surface later from the registry adapter. US state registries
    # disclose registered agent + managers but NOT ultimate beneficial
    # ownership. UBO lives in FinCEN BOI filings (Corporate Transparency
    # Act, 2024) — not public.
    _all_address_hint = " ".join(filter(None, [
        (supplied_address or ""),
        (report.identity.registered_address or ""),
        (target.get("address") or ""),
    ])).lower()
    _jur_hint = (
        (target.get("jurisdiction_iso2") or "")
        or (jurisdiction_iso2 or "")
        or (target.get("jurisdiction") or "")
        or (jurisdiction or "")
    ).upper()
    _is_us = (
        _jur_hint in ("US", "USA", "UNITED STATES")
        or any(kw in _all_address_hint for kw in (
            "united states", "usa", "florida", "delaware", "california",
            "new york", "texas", "nevada", "wyoming",
        ))
        # LLC shape in entity name + no other jurisdiction inferred
        or ((name or "").lower().rstrip(".").endswith((" llc", ",llc", " inc", " inc."))
            and not _jur_hint)
    )
    if _is_us:
        report.identity.data_gaps.append(
            "UBO not visible on US public registry — US state Secretary "
            "of State records disclose registered agent + managers only. "
            "Ultimate beneficial ownership lives in FinCEN BOI filings "
            "(Corporate Transparency Act, effective 2024) which are NOT "
            "public. Require the counterparty to provide a copy of its "
            "FinCEN BOI report during KYC before contracting."
        )

    # ── 1a. Sanctions screen (always runs) ──
    #
    # Classification is by BOTH score AND OpenSanctions topic labels.
    # Not every match at score 1.00 is a hard stop — legitimate
    # corporate entities (BAE Systems, Lockheed Martin, Rolls-Royce)
    # routinely hit at 1.00 against transparency data like `corp.state`
    # (state-owned / strategic industry lists), which is NOT a sanction.
    # See _classify_sanctions_match() for the topic → severity mapping.
    # R-F3411 — IS-13 (subject sanctions) may be DECLINED for this run. Checked before
    # the call, not after, because the operational point of declining a metered check is
    # that the quota is not spent. The report still STATES it (_record_waived_screen),
    # so a declined screen is visible and can never read as clean.
    _is13_waiver = _scope_waived(report, "IS-13")
    if _is13_waiver is not None:
        _record_waived_screen(report, _is13_waiver, what="Subject sanctions screen")
    try:
        if _is13_waiver is not None:
            # Skip the ~90-line screen block without re-indenting it. `_ScopeWaived` is
            # caught by its OWN handler immediately below, which must stay ABOVE the
            # generic `except Exception` — otherwise a declined screen would be logged
            # as "sanctions screen failed" and land in the report as an ERROR rather
            # than as the operator's decision.
            raise _ScopeWaived()
        from . import sanctions
        if hasattr(sanctions, "screen_with_aliases"):
            # R-F3228 — this name is the DD subject: operator-supplied or
            # registry-resolved, never a search query. Declaring that is what
            # lets "Marks & Spencer Group plc" be screened at all.
            screen = await sanctions.screen_with_aliases(name, source="dd_subject")
        elif hasattr(sanctions, "fuzzy_screen"):
            screen = await sanctions.fuzzy_screen(name)
        else:
            screen = {"error": "no sanctions module entrypoint"}
            report.identity.data_gaps.append("sanctions module not exposing expected API")

        # R-F287 (2026-05-11) — attach explicit per-source verification
        # status so the renderer NEVER fabricates "NOT CHECKED" gaps for
        # sources OpenSanctions did query. A screen with no "error" key
        # AND with a "matches" array (even empty) counts as succeeded.
        from ._sanctions_classify import (
            classify_matches,
            derive_verified_sources as _dvs_co,
        )
        _matches_for_dvs = screen.get("matches") or []
        # R-F1696: a source-unavailable screen has error="sanctions_source_unavailable"
        # AND source_unavailable=True — it must NOT count as succeeded (else the
        # renderer fabricates verified-clean sources for a screen that never ran).
        _screen_ok_co = (
            not screen.get("error")
            and not screen.get("source_unavailable")
            and isinstance(_matches_for_dvs, list)
        )
        screen["verified_sources"] = _dvs_co(
            _matches_for_dvs, screen_succeeded=_screen_ok_co,
        )

        # R-F740 (2026-05-20) — explicit UK OFSI primary-source check
        # alongside the OpenSanctions aggregate screen. OpenSanctions
        # DOES include UK OFSI data transitively, but UK DD clients
        # need a citation_url anchored at ofsi.gov.uk, not at a
        # third-party aggregator. Pre-R-F740 dd_orchestrate's gap-table
        # listed "OFSI UK sanctions | tool has no OFSI adapter" — a
        # false claim because fcdo_sanctions.lookup() IS wired (live
        # since R-F569+) just not called from this orchestrator path.
        # Fail-open: OFSI failures don't block the OpenSanctions
        # verdict — the screen still completes and we just lose the
        # explicit primary-source citation.
        try:
            from .sources import fcdo_sanctions as _fcdo
            _ofsi_result = await _fcdo.lookup(name)
            _ofsi_hits = (_ofsi_result or {}).get("hits") or []
            if _ofsi_hits:
                _existing = list(screen.get("matches") or [])
                # Normalise OFSI hits into the same shape the
                # downstream classifier expects (name + list label
                # + score).
                for h in _ofsi_hits:
                    _existing.append({
                        "name":   h.get("name") or name,
                        "list":   "UK_OFSI",
                        "score":  float(h.get("score") or 1.0),
                        "regime": h.get("regime") or "",
                        "source": "uk_ofsi",
                        "citation_url": h.get("citation_url") or
                            "https://ofsistorage.blob.core.windows.net/publishlive/2022format/ConList.xml",
                        "designation_date": h.get("designation_date") or "",
                    })
                screen["matches"] = _existing
            # Declare uk_ofsi a verified source ONLY when the lookup ran against
            # CURRENT data (zero hits is then a verified clean). R-F2460: a STALE /
            # unavailable OFSI snapshot (mark_stale_if_expired sets stale=True +
            # source_unavailable=True but leaves error=None) did NOT freshly
            # screen — labelling it verified-clean in the per-source table is a
            # never-false-clean breach. The direct-adapter loop already writes the
            # SANCTIONS_SOURCE_UNVERIFIED marker that forces the headline non-GREEN;
            # this guard stops the misleading "verified" label on the same outage.
            _ofsi = _ofsi_result or {}
            if not _ofsi.get("error") and not _ofsi.get("stale") and not _ofsi.get("source_unavailable"):
                # R-F2590 — verified_sources is a dict[str, dict] (derive_verified_sources,
                # _sanctions_classify.py:196). The old `list(screen.get("verified_sources"))`
                # collapsed that dict to a LIST OF KEYS, so downstream `.items()` at
                # _run_verification (dd_orchestrator.py:6086) crashed the whole DD with
                # "'list' object has no attribute 'items'" — deterministically, whenever the
                # OFSI lookup returned clean (as it did for Modirum Gespi / BR). Add uk_ofsi
                # as a proper dict entry matching the schema so the shape is preserved and
                # uk_ofsi is honestly credited as a checked source.
                _vs = screen.get("verified_sources")
                if not isinstance(_vs, dict):
                    _vs = {}
                if "uk_ofsi" not in _vs:
                    _vs["uk_ofsi"] = {
                        "label": "UK OFSI — HM Treasury Consolidated List",
                        "status": "HIT" if _ofsi_hits else "CLEAN",
                        "match_count": len(_ofsi_hits),
                        "matched_entities": [(h.get("name") or name) for h in _ofsi_hits][:5],
                    }
                screen["verified_sources"] = _vs
        except Exception as _ofsi_e:
            logger.debug(
                "R-F740: fcdo_sanctions.lookup failed for %s: %s",
                name, _ofsi_e,
            )

        # R-F3038 — completes R-F3019/R-F3031. There are TWO places that assign
        # identity.sanctions_screen; R-F3031 stamped only the first. This is the
        # alias/OFSI path, and it is the one a company DD actually takes — proven
        # live on dd_71553f511d72 (Supacat): 11 lists screened, `screened_at: None`,
        # so the report still could not date its own screen. Stamped here too, and
        # never overwritten if the screen already carries one.
        if isinstance(screen, dict) and not screen.get("screened_at"):
            screen["screened_at"] = datetime.now(timezone.utc).isoformat(timespec="seconds")
        _record_sanctions_screen(report, screen)   # R-F3535
        report.identity.meta.subcalls += 1

        matches = screen.get("matches") or []
        classified = classify_matches(matches, query_name=name)
        # R-F3090 — PERSIST the classification. `classify_matches` already separates
        # real hits from name-overlap noise, but only the prose `summary` survived
        # onto the report; the structured view then rendered a "Sanctions matches"
        # chip from `len(screen["matches"])` — the RAW pre-filter count. On the Mitie
        # report that printed "Sanctions matches 2" directly above a finding reading
        # "no entity-name match … No real hits." Same screen, two numbers, and the
        # alarming one won the reader's eye. Persist the arithmetic so every surface
        # renders the filtered truth instead of re-deriving a raw count.
        _noise = int(classified.get("noise_filtered") or 0)
        _total = int(classified.get("total_matches") or len(matches))
        screen["match_classification"] = {
            "total": _total,
            "noise_filtered": _noise,
            "actionable": max(0, _total - _noise),
            "worst_severity": classified.get("worst_severity"),
        }
        # The overall severity is the worst single match.
        if classified["worst_severity"] == "hard_stop":
            report.identity.findings.append(Finding(
                severity="hard_stop",
                title=f"Subject on active sanctions list",
                detail=classified["summary"],
                source="sanctions.screen_with_aliases",
                confidence="CONFIRMED",
            ))
            hard_stop = True
        elif classified["worst_severity"] == "red":
            report.identity.findings.append(Finding(
                severity="red",
                title=f"Subject linked to crime/debarment/export-risk list",
                detail=classified["summary"],
                source="sanctions.screen_with_aliases",
                confidence="PROBABLE",
            ))
        elif classified["worst_severity"] == "amber":
            report.identity.findings.append(Finding(
                severity="amber",
                title=f"Subject on PEP or adverse-media list",
                detail=classified["summary"] + " — enhanced DD required, not a refusal ground.",
                source="sanctions.screen_with_aliases",
                confidence="ASSESSED",
            ))
        elif classified["worst_severity"] == "info":
            # Build detailed breakdown of each info-level match (datasets + topics)
            _info_matches = classified.get("per_match") or []
            # R-F2362: count/show ONLY real info matches (share a meaningful
            # token with the query). Acronym-collision noise ("MG"→"MG Corp")
            # is excluded — otherwise the header said "(5)" while the body
            # (which already skips noise) showed nothing.
            _real_info = [
                m for m in _info_matches
                if m.get("severity") == "info" and not m.get("noise_filtered")
            ]
            # R-F2994 — an info/state-ownership "match" that shares only GENERIC
            # corporate words with the subject (e.g. "System Capital Management" vs
            # "Silverbrook Capital Management") is a name-coincidence, not a match.
            # OpenSanctions' raw score (up to 1.00) is passed through and is NOT gated
            # by name similarity, so these render as alarming high-score matches on an
            # unrelated entity. Require a shared DISTINCTIVE (non-generic) token; drop
            # coincidences from the DISPLAYED transparency set. Display-only — the
            # never-false-clean BLOCKING path (fuzzy_screen corroboration) is untouched.
            _subj_disc = _distinctive_tokens(getattr(report.identity, "entity_name", "") or "")
            # R-F3579 — a REVERSAL is a coincidence too. The token-set test below
            # cannot see it (the sets overlap fully), so it is checked explicitly.
            # DISPLAY-ONLY, like R-F2994: the never-false-clean BLOCKING path
            # (fuzzy_screen corroboration) is untouched, so nothing is suppressed
            # from the screen itself — only from the transparency list a reader
            # scans, and the count printed above it.
            _subj_name_for_order = getattr(report.identity, "entity_name", "") or ""
            _coincidences = [
                m for m in _real_info
                if (_subj_disc and not (_subj_disc & _distinctive_tokens(m.get("name") or "")))
                or _is_name_reversal(_subj_name_for_order, m.get("name") or "")
            ]
            if _coincidences:
                _drop_ids = {id(m) for m in _coincidences}
                _real_info = [m for m in _real_info if id(m) not in _drop_ids]
            _noise_info_n = len([m for m in _info_matches if m.get("noise_filtered")]) + len(_coincidences)
            # ── R-F3581 — FEED THE ARITHMETIC BACK, or the panel contradicts the report.
            #
            # PROVEN on dd_7b37d9a5e3cd, verifying R-F3579: the finding correctly read
            # "Sanctions/PEP screen — no entity-name match" while the identity chip
            # printed "1". `_sanctions_match_metric` renders from
            # `match_classification`, which is persisted BEFORE this filter runs, so a
            # coincidence dropped here was invisible to it — one screen, two numbers,
            # and the alarming one wins the reader's eye.
            #
            # That is precisely the defect R-F3090 exists to prevent ("persist the
            # arithmetic so every surface renders the filtered truth instead of
            # re-deriving a raw count"). R-F2994's coincidence drop had the same gap
            # from the day it shipped; R-F3579 only made it visible by producing a
            # report where the two surfaces disagreed out loud.
            #
            # The chip already has the honest rendering — with actionable=0 and
            # noise>0 it prints "none — N name-overlap match(es) filtered", which
            # ACCOUNTS for the dropped hit rather than hiding it. It just was never
            # given the numbers.
            if _coincidences:
                _mc = screen.get("match_classification")
                if isinstance(_mc, dict):
                    _mc["noise_filtered"] = int(_mc.get("noise_filtered") or 0) + len(_coincidences)
                    _mc["actionable"] = max(
                        0, int(_mc.get("total") or 0) - int(_mc["noise_filtered"]))
            if _real_info:
                _info_detail_parts = [classified["summary"]]
                for _im in _real_info[:5]:
                    _ds = ", ".join(_im.get("datasets", [])[:3]) or "unspecified"
                    _tp = ", ".join(_im.get("topics", [])[:3]) or "untagged"
                    _info_detail_parts.append(
                        f"  → {_im.get('name', '?')} (score {_im.get('score', 0):.2f}, datasets: {_ds}, topics: {_tp})"
                    )
                report.identity.findings.append(Finding(
                    severity="info",
                    title=f"Transparency/state-ownership matches ({len(_real_info)})",
                    detail="\n".join(_info_detail_parts) + "\n— informational only, not a refusal ground.",
                    source="sanctions.screen_with_aliases",
                    confidence="ASSESSED",
                ))
            elif _noise_info_n:
                # All fuzzy hits were name-overlap noise (no shared token with
                # the query) — screened, nothing real. Honest, not silent.
                report.identity.findings.append(Finding(
                    severity="info",
                    title="Sanctions/PEP screen — no entity-name match",
                    detail=(
                        classified["summary"]
                        + "\n— screened via name + aliases; the fuzzy hits share no "
                        "meaningful token with the entity and are not the subject."
                    ),
                    source="sanctions.screen_with_aliases",
                    confidence="ASSESSED",
                ))
        elif (
            screen.get("source_unavailable")
            or screen.get("error")
            or screen.get("screened") is not True
        ):
            # ── R-F3217 — FAIL CLOSED ON *ANY* UNPERFORMED SCREEN ───────────
            #
            # THE DEFECT, live on the Rossi DD (subject
            # "Rossi Security (Rossi Facility Services Ltd)"). This branch tested
            # exactly TWO keys — `source_unavailable` and the single error string
            # "sanctions_source_unavailable" — so every OTHER way a screen can fail
            # to run fell through to the CLEAN `else` below and was published as
            # "Sanctions screen CLEAN · CONFIRMED".
            #
            # The name never reached OpenSanctions at all: `_looks_like_entity_name`
            # rejects a token beginning "(" (sanctions.py), so `screen_with_aliases`
            # returned `{"error": "not_entity_shaped"}` with ZERO calls made. Neither
            # tested key was set. The "CLEAN" prose then named a list — "UK OFSI —
            # HM Treasury Consolidated List" — purely because R-F740's OFSI direct
            # adapter writes its entry OUTSIDE the entity-shape gate, so one real
            # lookup dressed an unperformed screen as an evidenced clearance.
            #
            # The decision scorecard was right the whole time (`dd_schema` rejects
            # ANY error), which is exactly why the report contradicted itself: the
            # body said CLEAN on the same page the scorecard said UNRESOLVED.
            #
            # Enumerating failure keys is the bug. A screen is CLEAN only when it
            # PROVABLY ran — `screened is True` and no error — and anything else is
            # UNVERIFIED. That closes the class, not this one instance:
            # "no valid names to screen", a future error string, or a screen dict
            # that carries no `screened` field at all now all fail closed.
            #
            # R-F1696: ZERO matches but the source NEVER ANSWERED. This is the
            # catastrophic false-negative class — pre-fix this branch stamped
            # "Sanctions screen CLEAN — CONFIRMED — treat as clearance" on an
            # entity that was never actually screened (OpenSanctions down/auth/
            # rate-limited/breaker-open). NEVER report an unscreenable entity as
            # clear: surface it as UNVERIFIED + a hard data-gap so the verdict
            # cannot read as a clearance.
            # R-F3217 — name the REASON THIS screen failed. Telling a reader the
            # source was unreachable when the truth is "we never asked, because the
            # name we were given is not screenable" sends them to check a system
            # that is working (the R-F3125 wrong-obstacle defect).
            _err = str(screen.get("error") or "").strip()
            _reasons = ", ".join((screen.get("source_reasons") or [])[:4])
            if _err == "not_entity_shaped":
                _why = (
                    f"the subject name as supplied ({name!r}) was not accepted as an "
                    "entity name by the screening guard, so NO list was queried. "
                    "Re-run with the registered legal name (no bracketed or "
                    "descriptive text) to screen it."
                )
            elif _err and _err != "sanctions_source_unavailable":
                _why = (
                    f"the screen did not run ({_err}), so NO list was queried."
                )
            else:
                _why = (
                    "the sanctions source (OpenSanctions / primary lists) could not "
                    f"be reached ({_reasons or 'source unreachable'}), so NO screen "
                    "was performed."
                )
            report.identity.findings.append(Finding(
                severity="amber",
                title="Sanctions screen NOT performed — UNVERIFIED",
                detail=(
                    f"{name} — {_why} "
                    f"This is UNVERIFIED — it is NOT a clearance. A re-screen against "
                    f"OFAC SDN / UK OFSI / EU / UN is required before relying on this."
                ),
                source="sanctions.screen_with_aliases",
                confidence="UNCERTAIN",
            ))
            report.identity.data_gaps.append(
                f"sanctions screen did not complete — {_err or 'source unavailable'} "
                "(UNVERIFIED, must re-screen; not a clearance)"
            )
            # §21e — a screen that cannot run on a normal customer-supplied name is a
            # capability gap, not a one-off: record it so the loop can see the class.
            if _err and _err != "sanctions_source_unavailable":
                try:
                    from . import capability_gaps
                    _sg = asyncio.create_task(capability_gaps.record_gap(
                        gap_type="module_bug",
                        detail=(f"[R-F3217] sanctions screen skipped for {name!r}: "
                                f"{_err} — no list queried"),
                        source="dd_orchestrator._run_identity:sanctions",
                    ))
                    _sg.add_done_callback(
                        lambda t: t.result()
                        if not t.cancelled() and not t.exception() else None)
                except Exception:
                    pass
        else:
            # Clean screen — zero matches across the full alias/variant set,
            # AND the source actually answered (screened=True / no error).
            # Emit an explicit INFO-tier finding so consumers can see the
            # screen actually RAN and came back clean. Previously an empty
            # matches list produced no finding at all, which the LLM
            # (correctly) read as "sanctions screen not completed".
            # ── R-F3129 — NAME ONLY THE LISTS YOU CAN EVIDENCE ──────────────
            #
            # THE DEFECT, live on the QinetiQ DD (dd_a56444e7647e) and the Mitie
            # report before it. This finding HARDCODED five authorities — "OFAC SDN,
            # UK OFSI, EU Consolidated, UN 1267, OpenSanctions" — and asserted "treat
            # as clearance under standard commercial DD" at confidence=CONFIRMED,
            # regardless of what `verified_sources` actually recorded. On both
            # reports that structure was EMPTY (neither rendered a per-list block),
            # so the prose named five authorities the report could not show were
            # queried.
            #
            # The decision scorecard was already honest about this: `sanctions_ok`
            # requires `verified_sources` (dd_schema.py), which is why QinetiQ read
            # "Sanctions and export-control exposure — UNRESOLVED" on the same page
            # as "CLEAN … treat as clearance". The SCORECARD was right; the PROSE was
            # the overclaim — the same shape as R-F3089's "subject-named" assertion
            # that nothing established.
            #
            # A clean screen is still reported — going silent would be the R-F1696
            # defect in reverse — but it now states exactly what answered, and it
            # does not offer clearance it cannot evidence.
            _vs_clean = screen.get("verified_sources")
            _vs_clean = _vs_clean if isinstance(_vs_clean, dict) else {}
            _named = [
                str((v or {}).get("label") or k)
                for k, v in _vs_clean.items()
                if isinstance(v, dict) and str(v.get("status") or "").upper() == "CLEAN"
            ]
            _when = str(screen.get("screened_at") or "").strip()
            if _named:
                _detail = (
                    f"{name} — no matches on the list(s) that answered: "
                    + "; ".join(_named[:8])
                    + (f" · screened {_when}" if _when else "")
                    + ". Fuzzy variants / aliases screened. This is a clean result for "
                      "those lists — check the data gaps for any list that did not answer."
                )
                _conf = "CONFIRMED"
            else:
                _detail = (
                    f"{name} — the screen ran and returned NO matches, but this report "
                    "carries no per-list record of which authorities answered, so the "
                    "coverage behind this result cannot be shown. Treat as NOT YET "
                    "EVIDENCED rather than a clearance: re-screen, or confirm the "
                    "list coverage, before relying on it."
                )
                _conf = "UNVERIFIED"
            report.identity.findings.append(Finding(
                severity="info",
                title=("Sanctions screen CLEAN" if _named
                       else "Sanctions screen returned no matches — list coverage NOT evidenced"),
                detail=_detail,
                source="sanctions.screen_with_aliases",
                confidence=_conf,
            ))
    except _ScopeWaived:
        # R-F3411 — the operator declined this screen. Already recorded by
        # `_record_waived_screen` (marker blob + data gap); nothing further to do, and
        # emphatically NOT an error. This handler must precede `except Exception`.
        pass
    except Exception as e:
        logger.warning("Identity: sanctions screen failed: %s", e)
        report.identity.findings.append(Finding(
            severity="amber", title="Sanctions screen failed", detail=str(e)[:200],
            source="sanctions", confidence="UNCERTAIN",
        ))
        report.identity.data_gaps.append("sanctions screen did not complete")

    # ── 1a1. Primary-source parallel screen (SEC, OFAC, OFSI, UN, WB, ACLED) ──
    # R-F1844: extracted to _identity_primary_source_screen (pure). It sets a
    # hard-stop on a real OFAC/UN/OFSI match; OR-combine so we never unset one.
    if await _identity_primary_source_screen(name, jurisdiction, report):
        hard_stop = True

    # R-F3452 — reconcile what the report SAYS was screened with what was screened.
    _reconcile_sanctions_coverage(name, report)

    # ── 1a1b. R-F2195 — consult operator-curated VAULT sources (Pipeline 3). Bounded,
    # best-effort, additive INFO findings only; never blocks or alters the hard-stop.
    try:
        await _consult_vault_sources(name, jurisdiction, report)
    except Exception as e:
        logger.debug("Identity: vault-source consult skipped: %s", e)

    # ── 1a2. Named-officeholder sanctions screen — MOVED, see below ──
    # R-F3397: this is where the officer screen used to run, over
    # `target["directors"]` only. `report.identity.directors` is not populated
    # until the Companies House block (~260 lines below) and
    # `_apply_registry_result`, so every officer the DD itself DISCOVERED was
    # invisible to it: a run launched with just a company name screened nobody.
    # The screen is now `_screen_officer_sanctions`, called once after every
    # registry write (search this file for it). Do not re-add a screen here —
    # at this point in the layer there is nothing to screen but the caller's
    # own input, and a second screening site is a second aggregator.

    # ── 1b. Companies House lookup (UK COMPANIES only) ──
    #
    # R-F3063 (P0) — NEVER company-search a PERSON'S NAME. Companies House is a
    # COMPANY register; resolving an individual's name against it is a name match,
    # and the result is attributed to a named human being.
    #
    # LIVE PROOF (dd_7ac19aa7941d / dd_17ef831d42fe, subject "Charles Woodburn",
    # entity_type=person): this branch and the R-F2515 backfill both ran, matched
    # company 15016136, and wrote onto the PERSON:
    #   registration_number 15016136
    #   directors           WOODBURN, Amy Louise / WOODBURN, Andrew John  ← other people
    #   shareholders        Mr Andrew John Woodburn / Mrs Amy Louise Woodburn
    #   financial verdict   DISTRESSED                                    ← their company
    # A named private individual was presented as financially distressed and tied to
    # two unrelated named individuals, purely because a surname matched. That is the
    # fabrication class R-F2726/R-F2993/R-F3014 removed elsewhere, at its most
    # damaging: about a person.
    #
    # The gate is an explicit PERSON exclusion rather than a company requirement, so
    # a subject whose type is genuinely unknown keeps its existing behaviour.
    if jurisdiction_iso2 == "GB" and not _subject_is_person(report):
        try:
            from . import companies_house
            # R-F2501 — surface the ROOT cause of GB data-starvation. Without the (free)
            # COMPANIES_HOUSE_API_KEY the CH REST API 401s and returns NOTHING, so every
            # GB DD misses directors/incorporation/PSC and data-starves to INSUFFICIENT.
            # Make it VISIBLE + actionable in the report instead of a vague "registry
            # incomplete" (proven live: search_companies=0, get_officers=0 with no key).
            _ch_gap = companies_house.missing_key_gap()
            if _ch_gap:
                report.identity.data_gaps.append(_ch_gap)
                try:
                    from . import capability_gaps
                    _cht = asyncio.create_task(capability_gaps.record_gap(
                        gap_type="api_missing",
                        detail="COMPANIES_HOUSE_API_KEY not set — GB registry lookups return no data (401)",
                        source="dd_orchestrator._run_identity:companies_house",
                    ))
                    _cht.add_done_callback(lambda t: t.result() if not t.cancelled() and not t.exception() else None)
                except Exception:
                    pass
            if hasattr(companies_house, "investigate_uk_entity"):
                ch_result = await companies_house.investigate_uk_entity(
                    company_number=registration_number,
                    company_name=None if registration_number else name,
                )
                report.identity.meta.subcalls += 1
                if isinstance(ch_result, dict):
                    # R-F2511 — parse investigate_uk_entity's ACTUAL shape. It returns
                    # officers/psc as {current,past,total} DICTS (not flat lists) and the
                    # profile carries `registered_address` (a dict), NOT
                    # registered_office_address.address_snippet. The old parse assigned the
                    # summary dict to `directors` and read the wrong address key, so even a
                    # SUCCESSFUL GB lookup mis-shaped the data (and psc_list[:10] TypeError'd).
                    _ch_unavail = companies_house.consume_unavailable()
                    # ── R-F3123 — AN INFERRED SUBJECT MUST BE DECLARED ──────────
                    #
                    # MEASURED on two runs of the SAME query (Mitie, 2026-07-26):
                    # "MITIE FACILITIES MANAGEMENT LIMITED" matches SIX Companies
                    # House records. One run resolved 07281729 (exact name,
                    # DISSOLVED); an earlier report resolved 02938041 (matched on a
                    # FORMER name — actually MITIE LIMITED, ACTIVE). Two different
                    # legal entities from one query, and NEITHER report said the name
                    # was ambiguous. Identity is the field every other layer hangs
                    # off; asserting one that was merely inferred fabricates the
                    # subject. Disclose it as a finding AND a data gap so it reaches
                    # the scorecard, not just the prose.
                    _res = ch_result.get("resolution") or {}
                    if _res.get("ambiguous"):
                        _alts = "; ".join(
                            f"{c['company_number']} {c['title']} ({c['status']})"
                            for c in (_res.get("candidates") or [])[:4]
                            if c.get("company_number") != _res.get("resolved")
                        )
                        report.identity.findings.append(Finding(
                            severity="amber",
                            title=("Company name is AMBIGUOUS — subject was inferred, "
                                   "not confirmed"),
                            detail=(
                                f"'{_res.get('query')}' matches "
                                f"{_res.get('candidate_count')} Companies House "
                                f"records. This report resolved "
                                f"{_res.get('resolved')} ({_res.get('resolved_title')}, "
                                f"{_res.get('resolved_status')}). "
                                + " ".join(_res.get("reasons") or [])
                                + (f" Other candidates: {_alts}." if _alts else "")
                                + " CONFIRM the registration number before relying on "
                                  "this file — every other section describes the "
                                  "entity named here."
                            ),
                            source="companies_house.resolve:R-F3123",
                            confidence="UNVERIFIED",
                        ))
                        report.identity.data_gaps.append(
                            f"Subject identity INFERRED from an ambiguous name: "
                            f"{_res.get('candidate_count')} Companies House records "
                            f"match '{_res.get('query')}'. Resolved "
                            f"{_res.get('resolved')} ({_res.get('resolved_status')}). "
                            "Confirm the registration number."
                        )
                    profile = ch_result.get("profile") or ch_result.get("company") or {}
                    # R-F3015 — Companies House answered LIVE this run when it returned a
                    # real profile with a company number and was NOT flagged unavailable
                    # (timeout / rate-limit / officers-truncated). The identity is then
                    # registry-verified, so the R-F1636 "registry unavailable" enrichment
                    # (~:4060) must NOT fire — it falsely failed the identity question for
                    # real companies whose CH lookup fully succeeded (e.g. Cohort 05684823:
                    # active, 7 current officers, yet read "not registry-verified"). Only a
                    # genuine live CH profile clears the flag — GLEIF/vault fallback cannot
                    # populate a CH profile — so this stays never-false-clean.
                    _ch_registry_verified_live = _ch_verified_live(profile, _ch_unavail)
                    # ── R-F3219 — ADOPT THE NAME THE REGISTER ACTUALLY HOLDS ────
                    #
                    # THE DEFECT (Rossi, 07101898). This block adopts the company
                    # NUMBER, STATUS, DATE and ADDRESS from the resolved Companies
                    # House profile — but never the NAME. `entity_name` stayed the
                    # raw string the customer typed, "Rossi Security (Rossi Facility
                    # Services Ltd)", for the whole run. Everything downstream that
                    # resolves BY NAME then ran on a string that exists in no
                    # register:
                    #   · the FCA Register lookup (:4318 below, which runs AFTER this
                    #     block) searched the composite and of course matched nothing,
                    #     reported as "no authorised firm matched";
                    #   · the R-F1631 press-relevance tokens were derived from it;
                    #   · the R-F3123 ambiguity finding scored a 0.67 "no exact
                    #     distinctive-name match" against the composite — an artefact
                    #     of our own input handling, printed as a fact about the
                    #     register.
                    # Once the registry has RESOLVED the subject, the registered name
                    # is the authoritative one. The supplied string is kept (target.*
                    # already persists it) and the swap is disclosed, so this narrows
                    # nothing and hides nothing — R-F3123's ambiguity disclosure is
                    # untouched and still fires.
                    _ch_name = str(profile.get("company_name") or "").strip()
                    _supplied_name = str(report.identity.entity_name or "").strip()
                    if (_ch_name and _ch_registry_verified_live
                            and _ch_name.casefold() != _supplied_name.casefold()):
                        report.identity.entity_name = _coerce_entity_text(_ch_name)   # R-F3268
                        report.identity.findings.append(Finding(
                            severity="info",
                            title="Subject name resolved to the registered legal name",
                            detail=(
                                f"Searched as {_supplied_name!r}; Companies House "
                                f"holds this entity as {_ch_name!r} "
                                f"({profile.get('company_number') or '?'}). Later "
                                "name-resolved checks (FCA Register, press and "
                                "adverse-media relevance) use the registered name. "
                                "Where the supplied text is a trading or brand name, "
                                "coverage found under it may describe the wider group."
                            ),
                            source="companies_house.profile:R-F3219",
                            confidence="CONFIRMED",
                        ))
                        # The sanctions screen already ran, on the supplied string.
                        # Re-screen under the registered name rather than assert the
                        # earlier result covers it (§22 — do not claim coverage you
                        # cannot show). Additive: a HIT escalates, a clean result only
                        # records that this name was screened too.
                        try:
                            if await _rescreen_under_registered_name(
                                    report, _ch_name, _supplied_name):
                                hard_stop = True
                        except Exception as _rs_e:      # noqa: BLE001
                            logger.debug(
                                "[R-F3219] re-screen under registered name skipped: %s",
                                _rs_e)
                    if profile.get("company_number"):
                        report.identity.registration_number = profile.get("company_number")
                    report.identity.registration_status = profile.get("company_status") or report.identity.registration_status
                    report.identity.incorporation_date = profile.get("date_of_creation") or report.identity.incorporation_date
                    _addr = profile.get("registered_address") or profile.get("registered_office_address")
                    if isinstance(_addr, dict):
                        report.identity.registered_address = ", ".join(
                            str(v) for v in (_addr.get("line1"), _addr.get("address_snippet"),
                                             _addr.get("locality"), _addr.get("postal_code"),
                                             _addr.get("country")) if v
                        ) or report.identity.registered_address
                    elif isinstance(_addr, str) and _addr:
                        report.identity.registered_address = _addr
                    report.identity.declared_activity = ", ".join(profile.get("sic_codes") or [])[:200] or report.identity.declared_activity
                    # ── R-F3024 — name history is EVIDENCE, not trivia ──
                    _prev_names = profile.get("previous_company_names") or []
                    if isinstance(_prev_names, list) and _prev_names:
                        report.identity.previous_names = _prev_names[:10]
                        _recent = _recent_name_changes(_prev_names, within_days=365)
                        for _pn in (_recent or [])[:3]:
                            report.identity.findings.append(Finding(
                                severity="amber" if _recent else "info",
                                title=(f"Recent name change: traded as "
                                       f"'{_pn.get('name')}' until {_pn.get('ceased_on')}"),
                                detail=(
                                    f"Companies House records that {report.identity.entity_name} "
                                    f"was named '{_pn.get('name')}' from "
                                    f"{_pn.get('effective_from') or 'an unstated date'} until "
                                    f"{_pn.get('ceased_on')} — within the last 12 months. A recent "
                                    "rename is not wrongdoing, but it materially affects this file: "
                                    "(a) filed accounts, contracts and press before that date sit "
                                    "under the OLD name, (b) adverse-media and registry searches on "
                                    "the CURRENT name will miss that history, and (c) if another "
                                    "company has taken the old name, evidence found under it may "
                                    "belong to a different legal entity. Search both names."
                                ),
                                source="companies_house.get_company_profile:R-F3024",
                                confidence="CONFIRMED",
                            ))
                        if _recent:
                            report.identity.data_gaps.append(
                                "Adverse-media and press searches covered the CURRENT name only — "
                                "this company was renamed within the last 12 months and its history "
                                "under "
                                + ", ".join(f"'{p.get('name')}'" for p in _recent[:2])
                                + " has NOT been separately screened."
                            )
                    _off = ch_result.get("officers")
                    report.identity.directors = (_off.get("current") if isinstance(_off, dict) else _off) or []
                    _psc_raw = ch_result.get("psc")
                    report.identity.shareholders = (_psc_raw.get("current") if isinstance(_psc_raw, dict) else _psc_raw) or []
                    # R-F2730 — carry the ANCHORED controlled_by edges (R-F2726) onto the
                    # report so the relationship-graph writer can persist them. These are
                    # grade-A (a corporate PSC anchored by its own registry number), the
                    # REAL source R-F2703 was waiting for — NOT the disabled name-match one.
                    _cb = ch_result.get("controlled_by")
                    if isinstance(_cb, list) and _cb:
                        report.network.controlled_by.extend(_cb)
                    # R-F3027 — un-anchored corporate controllers (CH gave no registry
                    # number). Kept OUT of `controlled_by` so Grade A keeps meaning
                    # "anchored", but recorded and stated: a 75-100% controller that
                    # nothing renders is the same failure as one that was never found.
                    _cbu = ch_result.get("controlled_by_unanchored")
                    if isinstance(_cbu, list) and _cbu:
                        report.network.controlled_by_unanchored.extend(_cbu)
                        for _u in _cbu[:5]:
                            _nat = ", ".join(_u.get("natures_of_control") or [])[:160]
                            report.network.findings.append(Finding(
                                severity="info",
                                title=(f"Corporate controller disclosed: {_u.get('controller_name') or '?'} "
                                       "— not resolvable to a registry entity"),
                                detail=(
                                    f"The subject's own PSC filing names '{_u.get('controller_name')}' as a "
                                    f"corporate person with significant control"
                                    + (f" ({_nat})" if _nat else "")
                                    + ". Companies House supplies NO registration number for it, so this "
                                      "control edge cannot be anchored to a primary-source registry id "
                                      "and the controller was NOT traversed. Resolving the name against "
                                      "the register would be a name match, not an identification "
                                      "(R-F2703). Verify the controller manually before relying on the "
                                      "ownership picture."
                                ),
                                source="companies_house.investigate_uk_entity:R-F3027",
                                confidence="CONFIRMED",
                            ))
                        report.identity.data_gaps.append(
                            "Ownership NOT fully traced — corporate controller(s) "
                            + ", ".join(str(_u.get("controller_name") or "?") for _u in _cbu[:3])
                            + " are disclosed with significant control but carry no Companies House "
                              "registration number, so the chain above them was not walked."
                        )
                    # never-false-clean: an empty CH result caused by a rate-limit/timeout
                    # (after retries) must SURFACE as a gap, not read as "verified: no
                    # directors/PSC". A genuine not-found still surfaces its error.
                    if _ch_unavail and not report.identity.directors:
                        report.identity.data_gaps.append(
                            f"Companies House {_ch_unavail} — directors/PSC NOT confirmed "
                            f"(registry lookup could not complete); re-run when available")
                    elif not ch_result.get("found") and ch_result.get("error"):
                        report.identity.data_gaps.append(f"Companies House: {ch_result.get('error')}")

                    # R-F2918 — record GB coverage HERE, where the real registry call
                    # happens. GB is deliberately _COVERED_ELSEWHERE
                    # (registry_coverage.py:50): it has no entry in the adapter
                    # dispatch table, so `lookup_entity("…","GB")` never touches
                    # Companies House and falls straight through to the GLEIF
                    # fallback. Nothing on this branch reported an outcome, so GB
                    # could NEVER move off `unproven` — while being, in fact, the
                    # best-covered jurisdiction we have.
                    #
                    # Proven live 2026-07-23 on aria-intel: is_enabled=True,
                    # BAE SYSTEMS PLC -> company_number 01470151, active,
                    # incorporated 1979-12-31, 13 current officers. The R-F2911 sweep
                    # nonetheless showed GB as FALLBACK (GLEIF answered) because it
                    # probes the adapter path, which GB is not on.
                    #
                    # The fix is to record where the work is, NOT to bolt a duplicate
                    # GB adapter onto the dispatch table — two code paths to the same
                    # registry is how they drift.
                    #
                    # `success` requires a real company_number: an empty/errored CH
                    # response is `empty`, never liveness. Reuses registry_adapters'
                    # fire-and-forget recorder so there is ONE implementation of the
                    # scheduling + never-raise contract.
                    try:
                        from .registry_adapters import _record_coverage_outcome
                        _ch_num = (profile or {}).get("company_number")
                        _record_coverage_outcome(
                            "GB", "companies_house",
                            "success" if _ch_num else "empty",
                        )
                    except Exception:
                        pass        # bookkeeping must never break a DD run

                    # ── PSC-reverse: screen each beneficial owner against sanctions ──
                    # 2026-04-12: "Which people control this company, and are any of
                    # them sanctioned?" Surfaces hidden risk from beneficial owners.
                    # R-F3353 — extracted to `_screen_psc_sanctions` so the screen is
                    # drivable by a capability test and so every failure path leaves a
                    # data_gap instead of a swallowed warning. See that docstring: this
                    # loop had never actually run (it called a phantom entrypoint).
                    if await _screen_psc_sanctions(report):
                        hard_stop = True

                    # ── R-F3422 — three free registers the DD has never consulted ──
                    await _run_ch_free_registers(report, profile)
                    # ── R-F3403 — the statutory record, incl. PERSONAL insolvency ──
                    await _run_gazette_insolvency(report)
                    # ── R-F3424 — employment tribunals: where a UK employer is sued ──
                    await _run_employment_tribunal(report)
        except Exception as e:
            logger.warning("Identity: companies_house lookup failed: %s", e)
            report.identity.data_gaps.append(f"companies_house lookup failed: {str(e)[:120]}")
            # R-F2918 — a thrown GB lookup is a real failure signal for coverage.
            # Recording only the happy path would make the inventory incapable of
            # ever showing GB as `failing`, which is the same one-sided reporting
            # this whole surface exists to avoid.
            try:
                from .registry_adapters import _record_coverage_outcome
                _record_coverage_outcome("GB", "companies_house", "error")
            except Exception:
                pass

        # ── 1b-FCA. R-F3002 — FCA Financial Services Register (GB) ──
        # Authorisation status is the FIRST question for a UK 'Capital Management' /
        # investment firm; SIC 64999 evidences nothing. DORMANT until FCA_API_EMAIL +
        # FCA_API_KEY are set — then a real authorisation lookup; until then an honest
        # "not checked" gap, never a fabricated authorised/not-authorised status.
        _fca_name = (getattr(report.identity, "entity_name", "") or "").strip()
        if _fca_name:
            try:
                from . import fca_register
                # R-F3025 — hand the registry-verified postcode down so a same-ish
                # name in a different town cannot be attributed to the subject.
                _fca_pc = ""
                try:
                    _addr = report.identity.registered_address or ""
                    _m_pc = re.search(
                        r"\b([A-Z]{1,2}\d[A-Z\d]?\s*\d[A-Z]{2})\b", str(_addr).upper())
                    _fca_pc = _m_pc.group(1) if _m_pc else ""
                except Exception:
                    _fca_pc = ""
                _fca = await fca_register.lookup_firm(_fca_name, postcode=_fca_pc)
                report.identity.meta.subcalls += 1
                if not _fca.get("configured"):
                    report.identity.data_gaps.append(
                        "FCA Register not checked — FCA_API_EMAIL/FCA_API_KEY not configured; "
                        "FCA authorisation status UNKNOWN (not a clean bill)."
                    )
                elif _fca.get("error"):
                    report.identity.data_gaps.append(f"FCA Register lookup error: {_fca['error']}")
                elif _fca.get("matched") and _fca.get("clone_warning") and _fca.get("is_authorised") is None:
                    # R-F3011 — FCA returned ONLY clone-firm scam warnings for this
                    # name. The legitimate firm was not resolved by name; NEVER report
                    # the subject as "Unauthorised" off a clone warning (that is a
                    # false accusation — the real firm is the one being impersonated).
                    report.identity.findings.append(Finding(
                        severity="info",
                        title=f"FCA Register: clone-firm scam warning(s) for names resembling '{_fca_name}'",
                        detail=(str(_fca.get("reason") or "")
                                + " Verify the genuine firm's authorisation by FRN on register.fca.org.uk."),
                        source="fca_register.lookup_firm",
                        confidence="ASSESSED",
                    ))
                elif _fca.get("matched"):
                    _auth = _fca.get("is_authorised")   # True / False / None (unknown)
                    # AMBER only for a GENUINE firm confirmed NOT authorised; an
                    # unknown/unconfirmed status is INFO, never a false accusation.
                    _sev = "info" if (_auth or _auth is None) else "amber"
                    _clone_note = (" NOTE: FCA also lists clone-firm scam warning(s) for similar names — "
                                   "verify you are dealing with this FRN, not an impersonator."
                                   if _fca.get("clone_warning") else "")
                    report.identity.findings.append(Finding(
                        severity=_sev,
                        title=(f"FCA Register: {_fca.get('firm_name') or _fca_name} — "
                               f"{_fca.get('status', '?')} (FRN {_fca.get('frn', '?')})"),
                        detail=(f"FCA Financial Services Register status '{_fca.get('status', '?')}'. "
                                + ("Authorised firm." if _auth
                                   else ("Authorisation status could not be confirmed on the register — "
                                         "verify by FRN." if _auth is None
                                         else "NOT currently authorised — verify before any regulated dealing."))
                                + _clone_note
                                + f" Source: {_fca.get('detail_url', '')}"),
                        source="fca_register.lookup_firm",
                        confidence="CONFIRMED" if _auth is not None else "ASSESSED",
                    ))
                elif _fca.get("best_candidate"):
                    # R-F3025 — a firm was returned but is NOT the subject (name match
                    # below threshold, or a contradicting postcode). Report it as an
                    # explicit non-attribution: the candidate is named so a human can
                    # check, and nothing about its status is asserted of the subject.
                    _bc = _fca.get("best_candidate") or {}
                    report.identity.findings.append(Finding(
                        severity="info",
                        title=(f"FCA Register: no firm identified as '{_fca_name}' "
                               f"(closest: {_bc.get('firm_name') or '?'} — NOT this subject)"),
                        detail=(str(_fca.get("reason") or "")
                                + f" [name match {_fca.get('name_match')} vs threshold "
                                  f"{_fca.get('name_match_threshold')}]"),
                        source="fca_register.lookup_firm",
                        confidence="ASSESSED",
                    ))
                    report.identity.data_gaps.append(
                        "FCA authorisation UNKNOWN — no FCA-registered firm could be "
                        "identified as this subject (a similarly-named firm was found and "
                        "deliberately NOT attributed)."
                    )
                else:
                    report.identity.findings.append(Finding(
                        severity="info",
                        title=f"FCA Register: no authorised firm matched '{_fca_name}'",
                        detail=("No firm on the FCA Financial Services Register matched this name. "
                                "May simply mean the entity conducts no FCA-regulated activity; but if "
                                "it holds itself out as providing regulated financial services, absence "
                                "of authorisation is material — verify by FRN. Not conclusive on name alone."),
                        source="fca_register.lookup_firm",
                        confidence="ASSESSED",
                    ))
            except Exception as _fca_e:  # noqa: BLE001 — never break identity on the add-on
                logger.debug("FCA register wiring failed (non-fatal): %s", _fca_e)

        # ── 1c. Financial DD — shell company detection (UK) ──────────
        # 2026-04-13: pulls Companies House filing history, detects dormant,
        # micro-entity, overdue, formation agent addresses.
        if registration_number:
            try:
                from . import financial_dd
                fin_profile = await financial_dd.get_financial_profile(registration_number)
                report.identity.meta.subcalls += 1
                if not fin_profile.get("error"):
                    for f in financial_dd.financial_findings(fin_profile):
                        report.identity.findings.append(Finding(**f))
                    report.identity.attributes = report.identity.attributes if hasattr(report.identity, 'attributes') and report.identity.attributes else {}
                    if isinstance(report.identity.attributes, dict):
                        report.identity.attributes["financial"] = {
                            "accounts_type": fin_profile.get("accounts_type"),
                            "shell_risk_score": fin_profile.get("shell_risk_score"),
                            "shell_indicators": fin_profile.get("shell_indicators", []),
                            "financial_summary": fin_profile.get("financial_summary"),
                        }
            except Exception as _fin_err:
                logger.debug("Financial DD failed (non-fatal): %s", _fin_err)
    else:
        # Try multi-jurisdiction registry adapter
        try:
            from . import registry_adapters
            _addr_for_adapter = (
                target.get("registered_address")
                or target.get("address")
                or report.identity.registered_address
                or ""
            )
            # R-F1815: try primary jurisdiction, then fallback chain
            reg_result = await registry_adapters.lookup_entity(
                name=name,
                jurisdiction_iso2=jurisdiction_iso2,
                registration_number=registration_number,
                address=_addr_for_adapter,
            )
            # If primary returned None, try fallback jurisdictions
            if not reg_result and jurisdiction_iso2:
                _fallbacks = _JURISDICTION_FALLBACK_CHAINS.get(jurisdiction_iso2, [])
                for _fb_iso2 in _fallbacks:
                    if _fb_iso2 == jurisdiction_iso2:
                        continue
                    logger.info(
                        "R-F1815: primary jurisdiction %s returned no result, "
                        "trying fallback %s", jurisdiction_iso2, _fb_iso2,
                    )
                    reg_result = await registry_adapters.lookup_entity(
                        name=name,
                        jurisdiction_iso2=_fb_iso2,
                        registration_number=registration_number,
                        address=_addr_for_adapter,
                    )
                    if reg_result:
                        logger.info(
                            "R-F1815: fallback jurisdiction %s returned result for %s",
                            _fb_iso2, name,
                        )
                        # Record the fallback as a finding so the DD report
                        # shows which jurisdiction actually had the data
                        report.identity.findings.append(Finding(
                            severity="info",
                            title=f"Registry lookup via fallback jurisdiction: {_fb_iso2}",
                            detail=(
                                f"Primary jurisdiction {jurisdiction_iso2} had no adapter "
                                f"or returned no result. Found data in {_fb_iso2}."
                            ),
                            source="dd_orchestrator.jurisdiction_fallback",
                            confidence="CONFIRMED",
                        ))
                        break
            if reg_result:
                profile = reg_result.get("profile", {})
                # R-F3231 — ONE authority path. See _apply_registry_result: the
                # decision "did a registry actually confirm this?" is made in a
                # single place, from RegistryStatus, and never from truthiness.
                _apply_registry_result(report, reg_result, registration_number)

                # ── Virtual-office re-check on registry-returned address ──
                # If the registry returned an address and the supplied_address
                # check earlier did not fire (e.g. no address was supplied
                # initially), now is the time to check. This catches the
                # F3 case where the address only comes from Sunbiz/registry.
                _reg_address = profile.get("registered_office_address") or ""
                # data_gaps may include a US stub — also probe for any FL/DE
                # address pattern there so the detector has material.
                if _reg_address:
                    try:
                        from . import virtual_office_registry
                        _vo = virtual_office_registry.check_address(_reg_address)
                        if _vo.get("is_virtual_office"):
                            _sev = "red" if _vo.get("risk") == "high" else "amber"
                            report.identity.findings.append(Finding(
                                severity=_sev,
                                title=f"Virtual-office match on registry address",
                                detail=(
                                    f"'{_reg_address}' matches known virtual-office "
                                    f"corridor: {_vo.get('provider') or '?'}. "
                                    f"{' '.join(_vo.get('signals') or [])}"
                                ),
                                source="dd_orchestrator.virtual_office_detector.registry",
                                confidence="ASSESSED",
                            ))
                    except Exception as _vo_err:
                        logger.debug("Virtual-office check on registry addr failed: %s", _vo_err)
            else:
                # Adapter returned None — jurisdiction not supported or lookup failed
                # R-F2365: don't claim "GB only" — the registry adapter supports
                # 24 jurisdictions. State the accurate reason: supported-but-empty
                # (usually needs a reg number) vs genuinely-not-covered.
                jur_hint = _national_registry_hint(jurisdiction_iso2, jurisdiction)
                _ji = (jurisdiction_iso2 or "").upper()
                try:
                    from .registry_adapters import _SUPPORTED_JURISDICTIONS as _SJ
                except Exception:
                    _SJ = set()
                if _ji and _ji in _SJ:
                    _cov = (
                        f"the {_ji} registry is supported but returned no data — a "
                        f"registration number is often required (e.g. a CNPJ for BR) "
                        f"or the lookup failed; supplied registration_number="
                        f"{registration_number or 'not supplied'}"
                    )
                else:
                    _cov = (
                        f"jurisdiction={jurisdiction or _ji or 'unspecified'} is not among "
                        f"ARIA's {len(_SJ)} automated registries yet (GB via Companies House "
                        f"is a separate path)"
                    )
                report.identity.data_gaps.append(
                    f"Registry lookup unavailable for "
                    f"{jurisdiction or jurisdiction_iso2 or 'unspecified jurisdiction'}"
                    f" — {_cov}. Manual action: {jur_hint}"
                )
                # Track as capability gap.
                # R-F150 2026-05-10: removed local `import asyncio` here.
                # Python's local-binding rule treats any `import X` inside
                # a function as a marker that X is local FOR THE WHOLE
                # FUNCTION — so this import shadowed the module-level
                # `import asyncio` at line 46, and the earlier reference
                # at line 732 (asyncio.gather in primary-source parallel
                # screen) raised UnboundLocalError. Live evidence
                # 2026-05-10 11:39:28: dd_orchestrator.py:732 traceback.
                # Same pattern as F28 (lifespan_smoke_test_required.md).
                # Module-level import is sufficient — no re-import needed.
                try:
                    from . import capability_gaps
                    _t = asyncio.create_task(capability_gaps.record_gap(
                        gap_type="registry_lookup",
                        detail=f"No automated registry adapter for {jurisdiction_iso2 or jurisdiction or 'unknown'}",
                        source="dd_orchestrator._run_identity",
                    ))
                    _t.add_done_callback(lambda t: t.result() if not t.cancelled() and not t.exception() else None)
                except Exception:
                    pass
        except Exception as e:
            logger.warning("Registry adapter failed: %s", e)
            jur_hint = _national_registry_hint(jurisdiction_iso2, jurisdiction)
            report.identity.data_gaps.append(
                f"Registry lookup failed for {jurisdiction or jurisdiction_iso2}: {str(e)[:100]}. "
                f"Manual action: {jur_hint}"
            )

    # ── R-F3515 — the ONE call site for the empty-PSC explanation ──
    # Placed after BOTH the Companies House branch and the multi-jurisdiction adapter
    # branch have finished writing `identity`, so it sees the final shareholder list
    # regardless of which path found the company. R-F3504 had it inside the non-UK
    # branch only; see `_explain_empty_psc_register` for why that could never fire.
    await _explain_empty_psc_register(report)

    # ── R-F3542 — WALK the ownership chain, don't stop at hop one ────────────
    #
    # `get_psc` has always returned the subject's corporate PSCs with an anchoring
    # registration number (R-F2726), and nothing ever called it again with one. So the
    # chain stopped at hop one and "who ultimately owns this" had no answer on four
    # consecutive delivered reports. On Bidvest Noonan the corporate PSC Crane Midco
    # Limited (06648599) was walkable and terminates at a listed parent.
    #
    # Placed HERE, at the converged identity point, for the R-F3515 reason: the
    # PSC-exemption block was first written inside one jurisdiction branch and could
    # never fire. Same converged site, same single call, same reachability.
    _own_reg = str(report.identity.registration_number or "").strip()
    if _own_reg and str(report.identity.jurisdiction_iso2 or "").upper() in ("GB", "UK", ""):
        try:
            from . import companies_house as _ch_own
            _chain = await _ch_own.walk_psc_ownership(_own_reg)
            report.identity.psc_ownership_chain = _chain if isinstance(_chain, dict) else {}
            # Every stop is DECLARED. A truncated chain that reads as complete is a
            # false clean on the most consequential question in the report.
            for _g in (_chain.get("gaps") or [])[:4]:
                report.identity.data_gaps.append(f"Ownership chain: {_g}")
            _ult = _chain.get("ultimate") or []
            if _chain.get("complete") and _ult:
                report.identity.findings.append(Finding(
                    severity="info",
                    title=("Ownership chain traced to its ultimate holder(s): "
                           + "; ".join(str(u.get("name")) for u in _ult[:3])),
                    detail=(
                        "Walked upward through corporate PSCs, anchored at every hop by "
                        "the controller's own Companies House registration number — not "
                        "by name matching. "
                        + "; ".join(
                            f"{e.get('from')} → {e.get('to')} ({e.get('controller_name')})"
                            for e in (_chain.get("edges") or [])[:4])
                        + f". {len(_ult)} ultimate holder(s) identified."),
                    source="companies_house.walk_psc_ownership:R-F3542",
                    confidence="CONFIRMED",
                    source_tier="OFFICIAL",
                ))
        except Exception as _own_e:  # noqa: BLE001 — never cost a report
            logger.debug("[R-F3542] ownership walk skipped: %s", _own_e)

    # ── 1c. Ghost-score from available signals ──
    # Feed whatever we've collected into the programmatic scorer. The
    # scorer treats MISSING keys as data gaps, so only include keys
    # where we actually have a non-None value. (Including None values
    # crashes the scorer because its `_need(key)` only checks key
    # presence, not truthiness — int(None) then raises.)
    try:
        from . import due_diligence_playbooks as _dd
        profile: dict = {
            "name": report.identity.entity_name,
            "jurisdiction": report.identity.jurisdiction_iso2 or report.identity.jurisdiction,
            "registration_number": report.identity.registration_number,
        }
        _age = _age_months(report.identity.incorporation_date)
        if _age is not None:
            profile["age_months"] = _age
        # R-F1636 — registry-gap enrichment: when the registry lookup was
        # absent/thin/junk, enrich identity from OSINT (Wayback vintage) + the
        # intel vault and persist it so the next DD recalls it at $0 (§15).
        # locals().get avoids a NameError if reg_result never bound on an error
        # path; never breaks the identity layer.
        try:
            # R-F3015 — do NOT enrich-as-unavailable when Companies House already
            # verified the identity LIVE this run. Absent this gate a fully-verified
            # company still read "registry unavailable", because the GB `reg_result`
            # is the GLEIF fallback (GB never hits CH via the adapter path — see :3702)
            # and so looks thin even though the real CH lookup at :3653 succeeded.
            if _registry_result_is_thin(locals().get("reg_result")) and not locals().get("_ch_registry_verified_live"):
                _enr_name = (report.identity.entity_name or target.get("name")
                             or target.get("entity") or "").strip()
                if _enr_name:
                    await _enrich_registry_gap(target, report, _enr_name)
        except Exception as _enr_e:
            logger.debug("R-F1636 registry-gap enrichment failed (non-fatal): %s", _enr_e)

        _act = _map_activity(report.identity.declared_activity)
        if _act is not None:
            profile["declared_activity"] = _act
        _tval = target.get("transaction_value_usd")
        if _tval:
            profile["transaction_value_usd"] = _tval

        # Serban-case detectors — CUI, website, claimed founding year.
        # Any of these passed via the target dict (from chat intent
        # detection, API body, or autonomous task watchlist entry)
        # gets threaded into the ghost scorer so indicators 11 and 12
        # fire when the evidence is there.
        _cui = target.get("cui") or target.get("registration_number")
        if _cui:
            profile["cui"] = _cui
        _website = target.get("website") or target.get("domain")
        if _website:
            profile["website"] = _website
        _claimed_year = target.get("claimed_founding_year")
        if _claimed_year is not None:
            profile["claimed_founding_year"] = _claimed_year
        _residential_address = report.identity.registered_address
        if _residential_address and any(p in _residential_address.lower() for p in (
            "apt.", "apt ", " ap.", " ap ", " ap,", "apartment", "flat ",
            "unit ", "sc. ", "bl. ", "et. ", "etaj ", "floor ",
        )):
            profile["registered_address_type"] = "residential"

        ghost = _dd.score_ghost_indicators(profile)
        report.identity.ghost_score = ghost.as_dict()
        report.identity.meta.subcalls += 1
        if ghost.classification in ("RED", "HARD STOP"):
            hard_stop = True
            report.identity.findings.append(Finding(
                severity="hard_stop" if ghost.classification == "HARD STOP" else "red",
                title=f"Ghost score {ghost.total}/20 — {ghost.classification}",
                detail=ghost.recommendation,
                source="due_diligence_playbooks.score_ghost_indicators",
                confidence="PROBABLE",
            ))
        elif ghost.classification.startswith("AMBER"):
            report.identity.findings.append(Finding(
                severity="amber",
                title=f"Ghost score {ghost.total}/20 — {ghost.classification}",
                detail=ghost.recommendation,
                source="due_diligence_playbooks.score_ghost_indicators",
                confidence="ASSESSED",
            ))

        # ── R-F602 — Formalised shell-co indicator breakdown ──
        # Past observation 2026-05-16: ghost detector ran a 12-indicator
        # scoring model but only the TOTAL was surfaced as a Finding row.
        # The individual triggered indicators ("mail-drop address",
        # "no website", "nominee director", etc.) were buried inside the
        # identity.ghost_score dict and invisible to a client reading
        # the DD report. For credibility each triggered indicator gets
        # its own auditable Finding row, so the operator can SEE why a
        # score of 12/20 was reached and challenge specific points if
        # the underlying data is wrong.
        for f in _emit_ghost_indicator_findings(ghost):
            report.identity.findings.append(f)
    except Exception as e:
        logger.warning("Identity: ghost scoring failed: %s", e)
        report.identity.data_gaps.append(f"ghost score failed: {str(e)[:120]}")

    # ── R-F3397 — officeholder sanctions screen, AFTER every registry write ──
    # Placed here, not inside the GB/Companies-House branch, because
    # `report.identity.directors` is also written by `_apply_registry_result`
    # for the ~30 non-GB adapters and by the R-F1636 enrichment above. Screening
    # inside the CH branch would leave every non-GB DD screening nobody — the
    # same shape as the defect this fix closes, one jurisdiction over.
    # R-F3442 — CCJ search, ordered-only. Placed beside the officer screen for the same
    # reason (R-F3397): it must run after every registry write and OUTSIDE the GB branch,
    # because Registry Trust covers UK and Ireland and IS-17b applies to individuals too.
    # Inside the CH block, every non-GB and every person subject would silently skip it.
    try:
        await _run_ccj_search(report)
    except Exception as _ccj_e:
        report.identity.data_gaps.append(
            f"CCJ search failed ({type(_ccj_e).__name__}) — NOT searched (not a clear result)")

    try:
        await _run_find_case_law(report)
    except Exception as _fcl_e:
        report.identity.data_gaps.append(
            f"Find Case Law search failed ({type(_fcl_e).__name__}) — NOT searched "
            f"(not a clear result)")

    try:
        if await _screen_officer_sanctions(report, target):
            hard_stop = True
    except Exception as _off_block_e:
        # The screen owns its own per-name gaps; this catches only a failure of
        # the loop itself, which must still leave evidence rather than silence.
        logger.warning("Identity: officer screen block failed: %s", _off_block_e)
        report.identity.data_gaps.append(
            f"Officer sanctions screen: SANCTIONS_SOURCE_UNVERIFIED — block raised "
            f"{type(_off_block_e).__name__}, officers NOT screened (not a clearance)"
        )

    # R-F1836 — domain-ownership (RDAP) as a Layer 1 signal (moved from digital,
    # which is skipped in quick mode / on hard-stop). Non-fatal, guarded.
    await _check_domain_ownership(target, report)

    report.identity.meta.duration_ms = int((time.time() - t0) * 1000)
    report.identity.meta.status = LayerStatus.OK.value
    return hard_stop


async def _run_network(target: dict, report: ARKDDReport) -> None:
    """Layer 2 — Network. Composes network_walker.walk_network."""
    t0 = time.time()
    report.network.meta.started_at = datetime.now(timezone.utc).isoformat()
    try:
        from . import network_walker
        result = await network_walker.walk_network(
            entity_name=report.identity.entity_name,
            entity_type=report.identity.entity_type,
            jurisdiction_iso2=report.identity.jurisdiction_iso2,
            registration_number=report.identity.registration_number,
            pre_resolved_officers=report.identity.directors or [],
        )
        report.network.director_graph = result.get("director_graph", {})
        report.network.cross_linked_entities = result.get("cross_linked_entities", [])
        report.network.address_cluster = result.get("address_cluster", {})
        report.network.pep_connections = result.get("pep_connections", [])
        report.network.sanctions_network = result.get("sanctions_network", [])
        report.network.findings = [Finding(**f) for f in result.get("findings", [])]
        report.network.data_gaps = result.get("data_gaps", [])
        report.network.meta.subcalls = result.get("stats", {}).get("sanctions_screens", 0) + result.get("stats", {}).get("entities_walked", 0)
        report.network.meta.status = LayerStatus.OK.value

        # ── Multi-hop entity graph (2026-04-13) ──────────────────────
        # Build a traversable graph from the walk result and run multi-hop
        # risk search. This finds indirect sanctions exposure through shared
        # directors, PSCs, and family/associate relationships.
        try:
            from . import entity_graph
            graph = entity_graph.build_from_walk_result(
                seed_name=report.identity.entity_name,
                seed_type=report.identity.entity_type,
                seed_jurisdiction=report.identity.jurisdiction_iso2,
                seed_reg_number=report.identity.registration_number,
                walk_result=result,
                sanctions_results=report.identity.sanctions_screen.get("matches") if hasattr(report.identity, "sanctions_screen") and report.identity.sanctions_screen else None,
            )
            # Multi-hop search: find all paths to flagged entities (up to 3 hops)
            hop_results = graph.multi_hop_search(
                start_id=list(graph.nodes.keys())[0] if graph.nodes else "",
                max_depth=3,
            )
            # Store graph summary in report
            report.network.director_graph["multi_hop"] = hop_results.get("risk_summary", {})
            report.network.director_graph["graph_stats"] = hop_results.get("graph_stats", {})

            # Generate findings from multi-hop paths
            for path in hop_results.get("paths", [])[:5]:
                if path.get("terminal_risk") in ("red", "hard_stop"):
                    hops = path.get("length", 0)
                    terminal = path.get("nodes", [{}])[-1] if path.get("nodes") else {}
                    report.network.findings.append(Finding(
                        severity=path["terminal_risk"],
                        title=f"Indirect sanctions exposure ({hops}-hop): {terminal.get('label', 'unknown')}",
                        detail=f"Path: {' → '.join(n.get('label', '?') for n in path.get('nodes', []))}. Reason: {path.get('terminal_reason', '')[:200]}",
                        source="entity_graph.multi_hop",
                        confidence="PROBABLE",
                    ))

            # Persist graph for re-screening
            await graph.save(report.run_id)
            logger.info("Entity graph built: %d nodes, %d edges, %d flagged paths",
                        hop_results.get("graph_stats", {}).get("total_nodes", 0),
                        hop_results.get("graph_stats", {}).get("total_edges", 0),
                        hop_results.get("risk_summary", {}).get("flagged_nodes", 0))
        except Exception as eg_err:
            logger.warning("Entity graph construction failed (non-fatal): %s", eg_err)

        # ── R-F435 (2026-05-13) — UBO chain walker auto-trigger ─────
        # network_walker.walk_ubo_chain() exists but was previously only
        # invoked from tests. Wire it as part of Layer 2 so every company
        # DD attempts a recursive UBO walk. The walker has its own budget
        # caps (max_hops=3, max_total_nodes=50, officers_per_entity=10)
        # and self-terminates fast on uncovered jurisdictions, recording
        # an explicit coverage_gap entry — which is itself valuable
        # signal (operator sees "no registry adapter for jurisdiction X"
        # instead of silent failure). Persons skip this layer (no UBO).
        # Opt-out via ARIA_UBO_WALK_DISABLED=1 for ops.
        if (
            report.identity.entity_type == EntityType.COMPANY.value
            and not os.getenv("ARIA_UBO_WALK_DISABLED", "").strip()
        ):
            try:
                ubo_result = await network_walker.walk_ubo_chain(
                    entity_name=report.identity.entity_name,
                    entity_type="company",
                    jurisdiction_iso2=report.identity.jurisdiction_iso2,
                    registration_number=report.identity.registration_number,
                )
                # Flat node list preserves the existing reader contract at
                # line 4252 (iterates u.get("name")).
                report.network.ubo_chain = (
                    (ubo_result.get("graph") or {}).get("nodes") or []
                )
                report.network.ubo_chain_walk = ubo_result
                _stats = ubo_result.get("stats") or {}
                report.network.meta.subcalls += (
                    _stats.get("sanctions_screens", 0)
                    + _stats.get("registry_lookups", 0)
                )

                # Surface sanctioned_in_chain as Network findings
                for _s in (ubo_result.get("sanctioned_in_chain") or [])[:5]:
                    _sev = _s.get("severity") or "red"
                    if _sev not in ("hard_stop", "red", "amber"):
                        _sev = "red"
                    report.network.findings.append(Finding(
                        severity=_sev,
                        title=(
                            f"UBO chain sanctions: {_s.get('name', '?')} "
                            f"({_sev}, hop {_s.get('hop', '?')})"
                        ),
                        detail=(
                            f"Discovered via UBO walk from "
                            f"{_s.get('parent_entity', report.identity.entity_name)}. "
                            f"{_s.get('summary', '')[:240]}"
                        ),
                        source="network_walker.walk_ubo_chain",
                        confidence="PROBABLE",
                    ))
                # PEP-in-chain → amber findings
                for _p in (ubo_result.get("pep_in_chain") or [])[:5]:
                    report.network.findings.append(Finding(
                        severity="amber",
                        title=(
                            f"UBO chain PEP: {_p.get('name', '?')} "
                            f"(hop {_p.get('hop', '?')})"
                        ),
                        detail=(
                            f"PEP / adverse-media match discovered via UBO walk "
                            f"from {_p.get('parent_entity', report.identity.entity_name)}. "
                            f"{_p.get('summary', '')[:240]}"
                        ),
                        source="network_walker.walk_ubo_chain",
                        confidence="ASSESSED",
                    ))
                # Coverage gaps → data_gaps (operator-actionable: tells them
                # which jurisdictions ARIA can't yet walk)
                for _g in (ubo_result.get("coverage_gaps") or [])[:10]:
                    report.network.data_gaps.append(
                        f"UBO walk hop {_g.get('hop', '?')} "
                        f"({_g.get('entity_name', '?')}): "
                        f"{_g.get('reason', 'unknown')}"
                    )
                if _stats.get("budget_exhausted"):
                    report.network.data_gaps.append(
                        f"UBO walk budget exhausted at "
                        f"{_stats.get('total_nodes', '?')} nodes — increase "
                        f"max_total_nodes for deeper trace"
                    )

                logger.info(
                    "UBO walk %s: verdict=%s, %d nodes, %d edges, "
                    "%d sanctioned_in_chain, %d PEP_in_chain, %d coverage_gaps",
                    report.identity.entity_name[:40],
                    ubo_result.get("verdict", "?"),
                    _stats.get("total_nodes", 0),
                    _stats.get("total_edges", 0),
                    len(ubo_result.get("sanctioned_in_chain") or []),
                    len(ubo_result.get("pep_in_chain") or []),
                    len(ubo_result.get("coverage_gaps") or []),
                )
            except Exception as ubo_err:
                logger.warning(
                    "UBO walk failed (non-fatal): %s", ubo_err,
                )
                report.network.data_gaps.append(
                    f"UBO walk failed: {str(ubo_err)[:120]}"
                )

    except Exception as e:
        logger.warning("Network layer failed: %s", e)
        report.network.meta.status = LayerStatus.ERROR.value
        report.network.meta.error = str(e)[:200]
    report.network.meta.duration_ms = int((time.time() - t0) * 1000)


# ── R-F601 — Formalised FATF jurisdiction-risk Finding builder ────────────
#
# Past observation 2026-05-16: ARIA's self-assessment claimed "no FATF
# formalised layer". Verified — FATF status WAS loaded at
# risk_indices.FATF_STATUS_2025_FEB:178 but only surfaced as an embedded
# "FATF=grey" substring inside a single country-risk detail line, AND
# only when the overall headline hit RED/HARD_STOP. Grey-list
# jurisdictions (BG, NG, KE, PH, etc.) never got their own row, so a
# client reading the DD report didn't see FATF as an explicit signal.
#
# This pure helper builds the Finding regardless of overall country
# headline:
#   black  → hard_stop  (Call for Action — DPRK / IR / MM)
#   grey   → amber      (Increased Monitoring)
#   clear  → None       (silent — clean jurisdiction, no clutter)
#
# Pure function: no I/O, no async, deterministic — testable in
# isolation. Called from _run_compliance.
def _build_fatf_finding(
    *,
    fatf_status: Optional[str],
    iso2: Optional[str],
    jurisdiction: Optional[str],
) -> Optional[Finding]:
    """Return a Finding for FATF-listed jurisdictions, or None for clear.

    Inputs:
      fatf_status: 'black' | 'grey' | 'clear' | None — case-insensitive
      iso2:        ISO-3166-1 alpha-2 country code (display only)
      jurisdiction: Human-readable country name (display only)

    Source citation follows Clause 15 (inline URL); confidence is
    CONFIRMED because FATF is a Tier-1a authoritative source (Clause 24
    — government-publication anchor).
    """
    status = (fatf_status or "").lower().strip()
    if status not in ("black", "grey"):
        return None

    iso2_disp = iso2 or "?"
    juris_disp = jurisdiction or iso2_disp

    if status == "black":
        label = "FATF Call for Action (high-risk jurisdiction)"
        list_description = "high-risk / Call for Action list"
        implications = (
            "TRANSACTIONS BLOCKED by most major banks; "
            "DSP licence likely refused; reputational risk severe. "
            "Treat as HARD STOP unless explicit FCDO/OFSI authorisation."
        )
        severity = "hard_stop"
    else:  # grey
        label = "FATF Increased Monitoring (grey-list)"
        list_description = "jurisdictions under increased monitoring list"
        implications = (
            "Enhanced Due Diligence (EDD) required; "
            "UK banks apply friction on USD/EUR clearing; "
            "Tier-1 source for current status must be re-verified."
        )
        severity = "amber"

    detail = (
        f"Jurisdiction {iso2_disp} ({juris_disp}) appears on the FATF "
        f"{list_description}. Implications for defence broking: {implications} "
        "Snapshot: risk_indices.FATF_STATUS_2025_FEB (FATF updates 3x/year — "
        "verify currency against the live page)."
    )

    return Finding(
        severity=severity,
        title=f"FATF status: {status.upper()} — {label}",
        detail=detail,
        source=(
            "risk_indices.FATF_STATUS_2025_FEB "
            "[from https://www.fatf-gafi.org/en/countries/black-and-grey-lists.html]"
        ),
        confidence="CONFIRMED",
    )


async def _run_compliance(target: dict, report: ARKDDReport) -> None:
    """Layer 4 — Compliance. Composes risk_indices + tech_classifier +
    international_law / global_export_control / regional_compliance via
    RAG queries through rag_store."""
    t0 = time.time()
    report.compliance.meta.started_at = datetime.now(timezone.utc).isoformat()

    # ── 4a. Country risk (qualitative — risk_indices) ──
    try:
        from . import risk_indices
        iso2 = report.identity.jurisdiction_iso2 or target.get("destination_iso2")
        if iso2:
            risk = risk_indices.get_country_risk(iso2, name=report.identity.jurisdiction or iso2)
            report.compliance.country_risk = risk.as_dict()
            report.compliance.meta.subcalls += 1
            headline = risk.headline_risk()
            if headline in ("RED", "HARD_STOP"):
                report.compliance.findings.append(Finding(
                    severity="hard_stop" if headline == "HARD_STOP" else "red",
                    title=f"Country risk: {headline}",
                    detail=f"CPI={risk.cpi_score} · Basel AML={risk.basel_aml} · FATF={risk.fatf_status} · OECD CRC={risk.oecd_crc}",
                    source="risk_indices.get_country_risk",
                    confidence="ASSESSED",
                ))

            # ── 4a-FATF (R-F601). Formalised FATF status finding. ──
            _fatf_finding = _build_fatf_finding(
                fatf_status=risk.fatf_status,
                iso2=iso2,
                jurisdiction=report.identity.jurisdiction or iso2,
            )
            if _fatf_finding is not None:
                report.compliance.findings.append(_fatf_finding)
                report.compliance.meta.subcalls += 1
    except Exception as e:
        logger.warning("Compliance: country risk failed: %s", e)
        report.compliance.data_gaps.append(f"country risk lookup failed: {str(e)[:120]}")

    # ── 4a-ter. US federal procurement footprint (R-F2273 — USASpending, free API) ──
    # Decision-grade signal for a defence entity: does it actually hold US federal
    # contracts, how much, and from which agencies? A positive contract history is
    # corroborating substance; absence for a non-US entity is expected (lookup returns
    # None → no finding, no gap). Datacenter-friendly API (verified 200 + real awards).
    try:
        _proc_name = (target.get("name") or target.get("entity")
                      or getattr(report.identity, "entity_name", "") or "").strip()
        if len(_proc_name) >= 3:
            from .sources import usaspending as _usa
            _proc = await _bounded_dd_op(_usa.lookup(_proc_name), _OP_T_USASPENDING, report.compliance, "US procurement (USASpending)")
            if _proc and _proc.get("award_count"):
                report.compliance.meta.subcalls += 1
                _val = float(_proc.get("total_value_usd") or 0)
                _ags = ", ".join(_proc.get("top_agencies") or []) or "n/a"
                report.compliance.findings.append(Finding(
                    severity="info",
                    title=f"US federal contracts: {_proc['award_count']} award(s), ${_val:,.0f}",
                    detail=f"Top awarding agencies: {_ags}. Source: USASpending.gov (federal award records).",
                    source="usaspending",
                    confidence="CONFIRMED",
                    # R-F3098 — a procurement record is a COMMERCIAL fact. Filed under
                    # "Compliance & Sanctions" it read as a compliance signal; it is
                    # neither adverse nor exculpatory, and it is not what that section
                    # is for.
                    context_only=True,
                    context_kind="Commercial footprint",
                ))
    except Exception as _pe:
        logger.debug("Compliance: usaspending lookup failed: %s", _pe)

    # ── 4a-quater. Financial health (R-F2322 — SEC EDGAR + search + vault) ──
    # Decision-grade: is this counterparty solvent + a going concern? Structured US
    # financials (SEC EDGAR) → ratios + Altman Z'' + distress flags; a cross-jurisdiction
    # web-search footprint when it isn't US-listed; the merged profile is registered to the
    # vault (pay-once, ANY jurisdiction — operator directive 2026-07-02). HONEST: UNKNOWN
    # when no data is found anywhere — never a false clean bill of health.
    try:
        _fin_name = (target.get("name") or target.get("entity")
                     or getattr(report.identity, "entity_name", "") or "").strip()
        # R-F3063 (P0) — defence in depth. Corporate financial health is a COMPANY
        # property: filed accounts, SEC filings, solvency ratios. Running it for an
        # individual can only produce a company's figures under a person's name —
        # live, that printed "financial verdict: DISTRESSED" against a named human.
        # Blocking the contamination at source (above) already prevents this, but a
        # verdict this defamatory must not depend on one upstream guard holding.
        if len(_fin_name) >= 3 and not _subject_is_person(report):
            # R-F3131 — the issuer-annual-report route (R-F3124/R-F3128) fetches a
            # large PDF, extracts its text and calls Claude with ~120k chars. In 25s
            # it cannot finish, so on the live Babcock DD this op reported "did not
            # complete within 25s (bounded)" and financial capacity stayed UNKNOWN —
            # for exactly the counterparty class the route exists to answer. Read the
            # mode off the report so the signature is unchanged.
            _fin_op_budget = (
                _OP_T_FINANCIAL_DEEP
                if str(getattr(report, "orchestrator_mode", "") or "").lower() == "deep"
                else _OP_T_FINANCIAL
            )
            from . import financial_health as _fh
            _fin = await _bounded_dd_op(_fh.assess(
                _fin_name,
                jurisdiction_iso2=(report.identity.jurisdiction_iso2 or target.get("jurisdiction_iso2") or ""),
                registration_number=(getattr(report.identity, "registration_number", "")
                                     or target.get("registration_number") or ""),
                entity_type=(target.get("type") or "company"),
            ), _fin_op_budget, report.compliance, "financial health", default={})
            report.compliance.financial_health = _fin
            report.compliance.meta.subcalls += 1
            for _f in _fh.financial_health_findings(_fin):
                report.compliance.findings.append(Finding(**_f))
            if not _fin.get("data_available"):
                report.compliance.data_gaps.append(
                    f"Financial health: {_fin.get('reason') or 'no structured financials found'} "
                    "— UNKNOWN, not a clean result.")
    except Exception as _fe:
        logger.debug("Compliance: financial health failed: %s", _fe)

    # ── 4a-bis. Country macro overlay (quantitative — World Bank Indicators v2) ──
    # R-F160 (2026-05-10) — wires the WB Indicators v2 + Data360 adapter
    # (R-F158) into the jurisdiction_country_risk discipline (R-F152). Free
    # endpoint, no auth, complements the qualitative risk_indices output
    # with quantitative macro context (GDP, debt/GDP, military spend, WGI
    # governance scores). Only fires when an ISO code is available — for
    # entities with no jurisdiction (Layer 1 inferred to UNKNOWN), this
    # block is skipped per Clause 7 (knowing limits).
    try:
        from .sources import worldbank_indicators as _wbi
        iso2_for_overlay = report.identity.jurisdiction_iso2 or target.get("destination_iso2")
        if iso2_for_overlay:
            overlay = await _bounded_dd_op(_wbi.country_risk_overlay(iso2_for_overlay), _OP_T_WORLDBANK, report.compliance, "World Bank country overlay", default={})
            if overlay.get("ok"):
                report.compliance.macro_overlay = overlay
                report.compliance.meta.subcalls += 1
                # Surface anomalous values as findings
                _gov = overlay.get("governance_wgi", {}) or {}
                _macro = overlay.get("macro", {}) or {}
                _defence = overlay.get("defence", {}) or {}
                # WGI <-1.0 = below 16th percentile globally on that dimension
                for _wgi_key, _wgi_val in _gov.items():
                    if isinstance(_wgi_val, (int, float)) and _wgi_val < -1.0:
                        report.compliance.findings.append(Finding(
                            severity="amber",
                            title=f"WGI low: {_wgi_key} = {_wgi_val:.2f}",
                            detail=(
                                f"World Bank Worldwide Governance Indicator '{_wgi_key}' for "
                                f"{iso2_for_overlay} is {_wgi_val:.2f} (below -1.0 = bottom 16% "
                                f"globally). Indicates structural governance weakness on this "
                                f"dimension — adds context to country-risk assessment."
                            ),
                            source=f"worldbank_indicators.country_risk_overlay [from {overlay.get('primary_source_url','')}]",
                            confidence="CONFIRMED",
                        ))
                # Debt/GDP > 100% = elevated sovereign-stress signal
                _debt = _macro.get("debt_to_gdp_pct")
                if isinstance(_debt, (int, float)) and _debt > 100:
                    report.compliance.findings.append(Finding(
                        # R-F3000 — sovereign macro debt is CONTEXT, not a counterparty
                        # risk flag on a private-company DD. As amber it fired for the
                        # UK/US/Japan (all >100%) and inflated the risk picture with a
                        # signal the reviewer must then discount. INFO surfaces it without
                        # polluting the verdict. (A sovereign/state-entity DD surfaces
                        # fiscal stress through its own counterparty path.)
                        severity="info",
                        title=f"Sovereign macro context: central-govt debt {_debt:.1f}% of GDP",
                        detail=(
                            f"Central government debt for {iso2_for_overlay} = {_debt:.1f}% of GDP"
                            # R-F3462 — STATE THE VINTAGE. The World Bank request asks for
                            # the most recent NON-EMPTY value, which for this series is
                            # routinely several years old; an undated macro figure invites
                            # a reader to treat stale data as current.
                            + (f" ({(overlay.get('vintage') or {}).get('debt_to_gdp_pct')} data — "
                               f"the most recent year the World Bank publishes for this series)"
                               if (overlay.get("vintage") or {}).get("debt_to_gdp_pct")
                               else " (year not reported by the source on this run)")
                            + f". WB threshold for fiscal-stress concern: ~100%. Country-level "
                            f"context for sovereign-counterparty + payment-currency risk — not a "
                            f"finding against this entity."
                        ),
                        source=f"worldbank_indicators.country_risk_overlay [from {overlay.get('primary_source_url','')}]",
                        confidence="CONFIRMED",
                        # R-F3098 — R-F3000 already established this is CONTEXT and cut
                        # the severity to info, but left it sitting in the compliance
                        # findings list, where POSITION still asserted what the wording
                        # denied ("not a finding against this entity"). A reader who
                        # scans headings carries away the impression the placement
                        # created. Group it where it belongs.
                        context_only=True,
                        context_kind="Country & market context",
                    ))
                # Military spend > 5% of GDP = elevated militarisation signal
                _mil = _defence.get("military_spend_pct_gdp")
                if isinstance(_mil, (int, float)) and _mil > 5.0:
                    report.compliance.findings.append(Finding(
                        severity="amber",
                        title=f"Military spend elevated: {_mil:.1f}% of GDP",
                        detail=(
                            f"Military expenditure for {iso2_for_overlay} = {_mil:.1f}% of GDP "
                            f"(global average ~2-2.5%). Defence-sector context for procurement "
                            f"DD; not necessarily adverse but informs market-sizing + sanctions "
                            f"context."
                        ),
                        source=f"worldbank_indicators.country_risk_overlay [from {overlay.get('primary_source_url','')}]",
                        confidence="CONFIRMED",
                    ))
            elif overlay.get("error"):
                report.compliance.data_gaps.append(
                    f"WB Indicators overlay unavailable for {iso2_for_overlay}: {str(overlay.get('error'))[:120]}"
                )
            # R-F3222 — the country-risk CHIP is computed from the sanctions/embargo
            # regime alone, so it renders (e.g. "GREEN") whether or not the governance
            # overlay answered. Live on the Rossi DD the chip read GREEN two lines
            # above its own gap saying the overlay timed out — a complete-looking
            # verdict standing on a check that did not finish. Flag it so the chip can
            # say which inputs it actually had.
            if not overlay.get("ok") and isinstance(report.compliance.country_risk, dict):
                report.compliance.country_risk["governance_overlay_complete"] = False
    except Exception as e:
        logger.debug("Compliance: WB Indicators overlay failed (non-fatal): %s", e)

    # ── 4a-CULTURAL (R-F635) — cultural read for non-UK/US jurisdictions ──
    # Pulls a population-level cultural profile from cultural_atlas
    # (R-F634) when the counterparty jurisdiction is seeded and is
    # outside the operator's default-familiar west (GB/US).
    # Tagged PROBABLE + population-level by the atlas renderer —
    # never deterministic about the individual counterparty.
    try:
        _cult_iso2 = report.identity.jurisdiction_iso2 or target.get("destination_iso2") or ""
        _cult_iso2 = (_cult_iso2 or "").upper().strip()
        if _cult_iso2 and _cult_iso2 not in ("GB", "US"):
            from . import cultural_atlas as _ca
            _cult_block = _ca.render_context_block(_cult_iso2, depth="full")
            if _cult_block:
                report.compliance.cultural_context = _cult_block
                report.compliance.meta.subcalls += 1
    except Exception as e:
        logger.debug("Compliance: cultural_atlas lookup failed (non-fatal): %s", e)

    # ── 4a-EXPERT-KNOWLEDGE (R-F644) — wire R-F638..F643 expert layers ──
    # Direct response to the 2026-05-17 ADSM case. When the target dict
    # carries `goods_list`, `mou_text` or `end_user_statement`, fire the
    # six expert-knowledge modules and append their findings to
    # report.compliance.findings.
    #
    # Modules wired:
    #   R-F638 weapon_origin_catalogue        — per-item OEM+sanctions
    #   R-F639 eliminated_weapons_watchlist   — INF/CWC/BWC/Ottawa/CCM
    #   R-F640 evasion_typology_detector      — TR-RU-MENA + composites
    #   R-F641 end_user_granularity           — Saudi-Gov-generic catch
    #   R-F642 mou_clause_gate_analyser       — 4.5(e)-style gates
    #   R-F643 goods_list_aggregator_detector — calibre-mix + diversion
    #
    # All wired defensively — any single failure does NOT break compliance.
    try:
        from . import weapon_origin_catalogue as _woc
        from . import eliminated_weapons_watchlist as _ewl
        from . import evasion_typology_detector as _etd
        from . import end_user_granularity as _eug
        from . import mou_clause_gate_analyser as _mcga
        from . import goods_list_aggregator_detector as _glad

        # Parse goods_list from target — accept list[str] OR multi-line str
        _goods_list_raw = target.get("goods_list")
        _goods_items: list[str] = []
        if isinstance(_goods_list_raw, list):
            _goods_items = [str(x) for x in _goods_list_raw if x]
        elif isinstance(_goods_list_raw, str):
            _goods_items = [
                line.strip() for line in _goods_list_raw.splitlines()
                if line.strip()
            ]

        # Aggregate weapon-origin + sanctions matches per line
        _weapon_origins: list[str] = []
        _weapon_statuses: list[str] = []
        _has_inf = False
        _has_cwc_bwc = False
        _ewl_err_logged = False   # R-F886: record a banned-weapon engine failure once/run

        for _item in _goods_items[:30]:  # cap line-items processed
            # Weapon catalogue (R-F638)
            try:
                _w_finding = _woc.render_finding_for_text(_item)
                if _w_finding:
                    report.compliance.findings.append(Finding(
                        severity=_w_finding["severity"],
                        title=_w_finding["title"],
                        detail=_w_finding["detail"],
                        source=_w_finding["source"],
                        confidence=_w_finding["confidence"],
                    ))
                    _weapon_origins.append(_w_finding.get("origin_iso2", ""))
                    _weapon_statuses.append(_w_finding.get("sanctions_status", ""))
                    report.compliance.meta.subcalls += 1
                    _absorb_dd_compliance_catch(  # R-F896
                        report, target, _w_finding.get("severity", ""),
                        f"DD weapon-origin flag: {_w_finding.get('title', '')}",
                        _w_finding.get("detail", ""),
                    )
            except Exception as _e1:
                logger.warning("R-F886 weapon-catalogue line failed: %s", _e1)

            # Eliminated/banned watchlist (R-F639)
            try:
                _e_finding = _ewl.render_finding_for_text(_item)
                if _e_finding:
                    report.compliance.findings.append(Finding(
                        severity=_e_finding["severity"],
                        title=_e_finding["title"],
                        detail=_e_finding["detail"],
                        source=_e_finding["source"],
                        confidence=_e_finding["confidence"],
                    ))
                    if "inf" in (_e_finding.get("treaty") or "").lower():
                        _has_inf = True
                    if "chemical" in (_e_finding.get("treaty") or "").lower() \
                       or "biological" in (_e_finding.get("treaty") or "").lower():
                        _has_cwc_bwc = True
                    report.compliance.meta.subcalls += 1
                    # R-F892 — record the CATCH to the brain. A treaty-banned/
                    # eliminated weapon on a procurement list is ARIA's highest-
                    # value compliance action, but the success side was invisible
                    # to the brain (only the report carried it) — she never
                    # "remembered" what she screened out. Fire-and-forget so DD
                    # never blocks on the brain fan-out.
                    try:
                        from . import brain_hook as _bh892
                        _t892 = asyncio.create_task(_bh892.absorb_silent(
                            module="dd_orchestrator",
                            summary=(
                                "Banned/eliminated-weapon screen HIT: "
                                f"{_e_finding.get('title', '')}"
                            ),
                            detail=(_e_finding.get("detail", "") or "")[:600],
                            entity_name=str((target or {}).get("name", ""))[:120],
                            success=True,
                            confidence="CONFIRMED",
                            source_id="eliminated_weapons_watchlist:R-F639",
                        ))
                        _t892.add_done_callback(
                            lambda t: t.result()
                            if not t.cancelled() and not t.exception() else None
                        )
                    except Exception:
                        pass
            except Exception as _e2:
                # R-F886 — a banned-weapon (INF/CWC/BWC/Ottawa/CCM) screen
                # failing SILENTLY is a compliance miss nobody sees. Raise to
                # WARNING + record to error_log so the reconnected coder
                # (R-F884) sees it. NOTE (R-F891): the error_log_handler now
                # also catches the "ARIA.*" logger tree, so this WARNING reaches
                # the ledger per-line on its own; record_error is the higher-
                # signal structured alert (kept once/run for flood protection).
                logger.warning(
                    "eliminated-weapons watchlist FAILED on a goods line "
                    "(banned-weapon screen miss) [%s]: %s",
                    str(_item)[:80], _e2,
                )
                if not _ewl_err_logged:
                    _ewl_err_logged = True
                    try:
                        from . import self_improve as _si886
                        await _si886.record_error(
                            "compliance_engine_failure",
                            f"eliminated_weapons_watchlist.render_finding_for_text raised: {_e2}",
                            file="aria_service/intel/dd_orchestrator.py",
                            function="orchestrate_dd:eliminated_weapons",
                        )
                    except Exception as _e892:
                        # Below WARNING so it can't recurse through the ledger.
                        logger.debug("R-F892: failed to record EWL engine error: %s", _e892)

        # Aggregator pattern (R-F643)
        if _goods_items:
            try:
                _agg_finding = _glad.render_finding(
                    _goods_items,
                    buyer_country_iso2=(report.identity.jurisdiction_iso2
                                        or target.get("destination_iso2")),
                )
                if _agg_finding:
                    report.compliance.findings.append(Finding(
                        severity=_agg_finding["severity"],
                        title=_agg_finding["title"],
                        detail=_agg_finding["detail"],
                        source=_agg_finding["source"],
                        confidence=_agg_finding["confidence"],
                    ))
                    report.compliance.meta.subcalls += 1
                    _absorb_dd_compliance_catch(  # R-F896
                        report, target, _agg_finding.get("severity", ""),
                        f"DD aggregation-pattern flag: {_agg_finding.get('title', '')}",
                        _agg_finding.get("detail", ""),
                    )
            except Exception as _e3:
                logger.warning("R-F886 aggregator failed: %s", _e3)

        # Evasion typology (R-F640)
        try:
            _routing_iso2 = (target.get("routing_location_iso2")
                             or target.get("stockholding_location_iso2"))
            _eu_statement = target.get("end_user_statement") or ""
            _buyer_iso2 = (report.identity.jurisdiction_iso2
                           or target.get("destination_iso2"))
            # Best-effort: is the buyer's end-user specific?
            _eu_specific = False
            if _eu_statement and _buyer_iso2:
                _eu_specific = _eug.is_sufficient_for_euc(_eu_statement, _buyer_iso2)

            _ctx = _etd.DealContext(
                weapon_origins_iso2=tuple(o for o in _weapon_origins if o),
                weapon_sanctions_statuses=tuple(_weapon_statuses),
                routing_location_iso2=_routing_iso2,
                buyer_country_iso2=_buyer_iso2,
                buyer_named_end_user_specific=_eu_specific,
                has_inf_eliminated_items=_has_inf,
                has_categorically_banned_items=_has_cwc_bwc,
                goods_list_mixed_nato_and_non_nato_calibres=False,
                no_timeline_indicated=bool(target.get("no_timeline_indicated")),
                no_commission_discussed=bool(target.get("no_commission_discussed")),
                informal_channel_received=bool(target.get("informal_channel_received")),
            )
            for _typ_f in _etd.render_findings_for_ctx(_ctx):
                report.compliance.findings.append(Finding(
                    severity=_typ_f["severity"],
                    title=_typ_f["title"],
                    detail=_typ_f["detail"],
                    source=_typ_f["source"],
                    confidence=_typ_f["confidence"],
                ))
                report.compliance.meta.subcalls += 1
                _absorb_dd_compliance_catch(  # R-F896
                    report, target, _typ_f.get("severity", ""),
                    f"DD evasion-typology flag: {_typ_f.get('title', '')}",
                    _typ_f.get("detail", ""),
                )
        except Exception as _e4:
            logger.warning("R-F886 typology detector failed: %s", _e4)

        # End-user granularity (R-F641)
        try:
            _eu_statement = target.get("end_user_statement") or ""
            if _eu_statement:
                _buyer_iso2 = (report.identity.jurisdiction_iso2
                               or target.get("destination_iso2"))
                _eu_f = _eug.render_finding(_eu_statement, country_iso2=_buyer_iso2)
                report.compliance.findings.append(Finding(
                    severity=_eu_f["severity"],
                    title=_eu_f["title"],
                    detail=_eu_f["detail"],
                    source=_eu_f["source"],
                    confidence=_eu_f["confidence"],
                ))
                report.compliance.meta.subcalls += 1
                _absorb_dd_compliance_catch(  # R-F896
                    report, target, _eu_f.get("severity", ""),
                    f"DD end-user-granularity flag: {_eu_f.get('title', '')}",
                    _eu_f.get("detail", ""),
                )
        except Exception as _e5:
            logger.warning("R-F886 end-user granularity failed: %s", _e5)

        # MOU clause-gate analysis (R-F642)
        try:
            _mou_text = target.get("mou_text") or ""
            if _mou_text and len(_mou_text) > 200:
                for _gate_f in _mcga.render_finding(_mou_text)[:5]:
                    report.compliance.findings.append(Finding(
                        severity=_gate_f["severity"],
                        title=_gate_f["title"],
                        detail=_gate_f["detail"],
                        source=_gate_f["source"],
                        confidence=_gate_f["confidence"],
                    ))
                    report.compliance.meta.subcalls += 1
                    _absorb_dd_compliance_catch(  # R-F896
                        report, target, _gate_f.get("severity", ""),
                        f"DD MOU clause-gate flag: {_gate_f.get('title', '')}",
                        _gate_f.get("detail", ""),
                    )
        except Exception as _e6:
            logger.warning("R-F886 mou-gate analyser failed: %s", _e6)
    except Exception as _expert_err:
        logger.warning("R-F886 expert-knowledge compliance block failed (non-fatal): %s", _expert_err)

    # ── 4b. Export control classification ──
    # R-F1903: fall back to the entity's declared_activity (seeded from its OWN
    # site by R-F1895/R-F1903) when no explicit product/goods was supplied — so a
    # URL-only DD of a defence/dual-use entity ("C2 and ISR solutions") still gets
    # an export-control read instead of being skipped. Tagged self-described.
    # R-F3040 — the REGISTRY's own activity code outranks self-description.
    #
    # THE DEFECT (live, dd_71553f511d72 — SUPACAT LIMITED, maker of the Jackal and
    # Coyote high-mobility vehicles for the British Army). The report said
    # "Export control: civilian or unclassified". Its own identity section carried
    # `declared_activity: "30400, 30990, 33170, 71129"` — because the GB path sets
    # declared_activity to the raw SIC CODES — and UK SIC 30400 is, verbatim,
    # "Manufacture of military fighting vehicles". The classifier was handed bare
    # DIGITS, found no military words in them, and returned civilian.
    #
    # A registry-declared SIC code is a primary-source statement by the company
    # itself, and it is machine-readable. Expanding it costs nothing and is the
    # difference between "we classified from the website" and "the register says
    # this is a military manufacturer".
    _sic_codes = [c for c in (report.identity.sic_codes or []) if c] \
        if hasattr(report.identity, "sic_codes") else []
    if not _sic_codes:
        _sic_codes = [c.strip() for c in str(report.identity.declared_activity or "").split(",")
                      if c.strip().isdigit()]
    _sic_text = _describe_sic_codes(_sic_codes)
    product_text = (target.get("product_description") or target.get("goods")
                    or _sic_text or (report.identity.declared_activity or ""))
    _ec_from_self_desc = (not (target.get("product_description") or target.get("goods"))
                          and not _sic_text and bool(report.identity.declared_activity))
    if product_text:
        try:
            from . import tech_classifier
            ec = tech_classifier.classify_export_control(product_text)
            if isinstance(ec, dict) and _ec_from_self_desc:
                ec["basis"] = "classified from the entity's SELF-DESCRIBED activity (website), not a supplied product spec — indicative only"
            if isinstance(ec, dict) and _sic_text:
                ec["registry_sic"] = _sic_text          # R-F3040 — show the input
            # ── R-F3454 — "civilian" is a CONCLUSION and needs a product to reach it ──
            #
            # THE DEFECT (live, Babcock International Group PLC). The report stated
            # "Export control: civilian or unclassified" for one of the UK's largest
            # defence primes — nuclear submarines, warships, the Type 31 frigate.
            #
            # R-F3040 already catches a MILITARY SIC code, but it could not fire here:
            # the legal entity 02342138 is the GROUP HOLDING company, so its registered
            # activity is head-office administration and carries no military words. The
            # classifier was handed that, found no hits, and returned its no-hits value.
            # Every layer behaved correctly and the report still printed the single most
            # misleading sentence a defence-DD product can print.
            #
            # The error is asserting a NEGATIVE from an input that could never have
            # produced a positive. No product or transaction was supplied, so nothing
            # about the goods was assessed. "No military words in a head-office SIC code"
            # is an absence of COVERAGE, not evidence of civilian use — the same rule this
            # report applies to adverse media and to an unsearched register.
            #
            # A positive hit from SIC/self-description still stands: that is real
            # evidence, and only the negative is downgraded.
            if _export_control_is_unsupported_negative(
                    product_supplied=bool(target.get("product_description")
                                          or target.get("goods")),
                    military_sic_present=bool(_military_sic_codes(_sic_codes)),
                    recommendation=str((ec or {}).get("recommendation") or "")):
                if isinstance(ec, dict):
                    ec["assessed"] = False
                    ec["not_assessed_reason"] = (
                        "no product or transaction was specified for this run, so the "
                        "goods themselves were never classified"
                    )
                    ec["recommendation"] = (
                        "NOT ASSESSED — no product or transaction specified"
                    )
                    ec["confidence"] = 0.0
                    report.compliance.findings.append(Finding(
                        severity="amber",
                        title="Export-control exposure NOT ASSESSED — no product or "
                              "transaction was specified",
                        detail=(
                            "No product, goods or transaction context was supplied for "
                            "this run, so no export-control classification of the goods "
                            "was performed. What was classified instead was the entity's "
                            + ("registered activity (" + _sic_text + "). "
                               if _sic_text else "self-described activity. ")
                            + "That input cannot establish that a subject is civilian: a "
                              "group holding company's registered activity is "
                              "administration whatever its subsidiaries manufacture. This "
                              "is an absence of coverage, NOT a finding of civilian use. "
                              "Re-run with the specific goods or services being contracted "
                              "to obtain a classification, and treat the entity as "
                              "potentially in scope until then."
                        ),
                        source="tech_classifier.classify_export_control:R-F3454",
                        confidence="UNCERTAIN",
                    ))
                    report.compliance.data_gaps.append(
                        "Export-control classification NOT PERFORMED — no product or "
                        "transaction was specified, so the goods were never classified. "
                        "The entity's registered activity was used instead and cannot "
                        "establish civilian status (a holding company's SIC describes "
                        "administration, not what the group manufactures). Supply the "
                        "goods or services being contracted to close this."
                    )
            report.compliance.export_control = ec
            # R-F3040 — a registry-declared MILITARY activity is stated outright and
            # NEVER depends on the text classifier agreeing. Without this, a company
            # whose own SIC code reads "Manufacture of military fighting vehicles"
            # could still be summarised as "civilian or unclassified" — the single
            # most misleading sentence a defence-DD product can print.
            _mil_sics = _military_sic_codes(_sic_codes)
            if _mil_sics:
                _rec = str((ec or {}).get("recommendation") or "")
                _contradiction = ("civilian" in _rec.lower() or "unclassified" in _rec.lower())
                report.compliance.findings.append(Finding(
                    severity="amber" if _contradiction else "info",
                    title=("Registry-declared MILITARY activity: "
                           + "; ".join(f"SIC {c} — {d}" for c, d in _mil_sics[:3])),
                    detail=(
                        "Companies House records this entity's own declared activity under "
                        + ", ".join(f"SIC {c} ({d})" for c, d in _mil_sics)
                        + ". This is the company's primary-source declaration to the registrar, "
                          "not an inference."
                        + (" It CONTRADICTS the automated export-control read of "
                           f"'{_rec}', which is derived from free-text activity description and "
                           "must not be relied on here: treat this entity as in scope for "
                           "military/dual-use export control until a product-level "
                           "classification says otherwise."
                           if _contradiction else
                           " Export-control scope should be confirmed at product level.")
                    ),
                    source="companies_house.sic_codes:R-F3040",
                    confidence="CONFIRMED",
                ))
                if _contradiction:
                    report.compliance.data_gaps.append(
                        "Export-control classification says 'civilian or unclassified' while the "
                        "registry SIC code declares military manufacture — the automated read is "
                        "NOT reliable for this entity; obtain a product-level classification."
                    )
            report.compliance.meta.subcalls += 1
            if ec.get("multilateral"):
                for hit in ec.get("multilateral", []):
                    report.compliance.sanctions_regimes.append(hit.get("regime", ""))
            if ec.get("recommendation", "").startswith("ITAR"):
                report.compliance.licence_path = "DSP-5 / TAA (ITAR)"
            elif "EAR" in (ec.get("recommendation", "") or ""):
                report.compliance.licence_path = "BIS-748P / Licence Exception"
            elif ec.get("wassenaar_ml"):
                report.compliance.licence_path = "SIEL / SITCL (UK) or equivalent national ML route"
        except Exception as e:
            logger.warning("Compliance: export control classification failed: %s", e)
            report.compliance.data_gaps.append(f"export control classify failed: {str(e)[:120]}")
    else:
        report.compliance.data_gaps.append("No product/goods description — export control classification skipped")

    # ── 4c. Regional bloc matching via RAG ──
    try:
        from . import rag_store
        country = report.identity.jurisdiction or target.get("destination") or ""
        if country:
            regional = await rag_store.get_rag_context(
                f"{country} regional compliance framework defence arms transfer",
                max_chars=2000,
            )
            if regional and regional.strip():
                report.compliance.regional_bloc_requirements = [{
                    "query": f"{country} regional bloc",
                    "excerpt": regional[:800],
                    "source": "RAG:regional_compliance",
                }]
                report.compliance.meta.subcalls += 1
    except Exception as e:
        logger.warning("Compliance: regional bloc RAG failed: %s", e)
        report.compliance.data_gaps.append(f"regional bloc RAG failed: {str(e)[:120]}")

    report.compliance.meta.duration_ms = int((time.time() - t0) * 1000)
    report.compliance.meta.status = LayerStatus.OK.value


def _entity_distinctive_tokens(*names: str) -> list[str]:
    """R-F1631 — distinctive (non-generic) tokens of an entity name, accent-
    normalized + lowercased. Used to gate search results for ACTUAL entity-
    relevance so noise (unrelated academic papers, generic 'security' hits,
    tangential procurement notices) doesn't enter the DD as 'press coverage'.
    Returns [] for an all-generic name — the caller then keeps everything, so
    we never silently drop all coverage for an un-discriminable name.

    R-F3227 — the private `_GENERIC` set that used to live here is gone. It
    disagreed with the sanctions-side list about 'capital' and 'management',
    which is what let two generic finance words satisfy the R-F3221 two-token
    rule. Both gates now read `_GENERIC_ENTITY_TOKENS`; the ORDER-PRESERVING
    list return and the >=3-char rule stay, because callers index into this."""
    import unicodedata
    _GENERIC = _GENERIC_ENTITY_TOKENS
    def _norm(s: str) -> str:
        return "".join(
            c for c in unicodedata.normalize("NFKD", s or "")
            if not unicodedata.combining(c)
        ).lower()
    toks: list[str] = []
    for nm in names:
        for t in re.split(r"[^a-z0-9]+", _norm(nm)):
            if len(t) >= 3 and t not in _GENERIC and t not in toks:
                toks.append(t)
    return toks


def _press_hit_is_relevant(title: str, snippet: str, url: str, distinctive_tokens: list[str]) -> bool:
    """R-F1631 / R-F2366 — True if a search hit is actually ABOUT the entity.

    R-F2366: relevance is now aboutness, not a passing mention. The distinctive
    token must appear in the TITLE or the URL (host/slug) — NOT merely in the
    search snippet. A snippet-only mention (e.g. a RocketReach contact page for
    an unrelated person whose bio happens to name the entity) is a passing
    reference, not coverage, and was inflating the press count with noise like
    the "Nordic Nano Group" hit on the Modirum Gespi DD.

    With no distinctive tokens (all-generic name) returns True — never drop
    everything."""
    if not distinctive_tokens:
        return True
    import unicodedata

    def _norm(s: str) -> str:
        return "".join(
            c for c in unicodedata.normalize("NFKD", s or "")
            if not unicodedata.combining(c)
        ).lower()

    # Aboutness signal: title or URL (host + slug), excluding the snippet.
    hay = _norm(f"{title or ''} {url or ''}")
    hits = [t for t in distinctive_tokens if t in hay]
    if not hits:
        return False
    # ── R-F3583 — A NAMESAKE PERSON IN SURNAME-FIRST FORM IS NOT THE COMPANY ──
    #
    # LIVE, in a delivered report's Cited sources (dd_acaee511f0f4, Wilson James
    # Limited — a London security contractor):
    #   "Roseburg names Wilson, James to board of directors | Woodworking Network"
    # A US wood-products company appointing an individual called James Wilson.
    #
    # R-F3221's two-token rule cannot see it: BOTH distinctive tokens are present, so
    # it reads as strong aboutness. ORDER cannot see it either — "Wilson, James" runs
    # wilson→james, the same order as the company, which is why the order test that
    # fixed R-F3576 and R-F3579 does not transfer here. The one thing separating them
    # is the COMMA: "Wilson, James" is the surname-first PERSON format — the same
    # convention Companies House uses, and the same inversion behind R-F3030.
    #
    # Narrow and additive: reject ONLY when the title carries the tokens exclusively
    # as "tok, tok" and NEVER as the plain phrase. "Home - Wilson James" and
    # "Gary Sullivan - Wilson James Limited | LinkedIn" are unaffected.
    #
    # The URL is deliberately NOT consulted: a slug normalises "Wilson, James" to
    # "wilson-james", destroying the very punctuation the decision rests on.
    if len(distinctive_tokens) > 1 and len(hits) > 1:
        _t = _norm(title or "")
        _esc = [re.escape(_h) for _h in hits]
        _plain = re.search(r"\b" + r"[\s-]+".join(_esc) + r"\b", _t)
        _inverted = re.search(r"\b" + r"\s*,\s*".join(_esc) + r"\b", _t)
        if _inverted and not _plain:
            return False
    # ── R-F3221 — ONE token is not aboutness when that token is a SURNAME ────
    #
    # THE DEFECT (Rossi, 07101898). The gate returned True on any single token
    # hit. For "Rossi Security (Rossi Facility Services Ltd)" the distinctive set
    # is {rossi, facility}, so a bare "rossi" carried:
    #   · "George Rossi" — an unrelated individual
    #   · "Unsealed suits against Rossi, Reditus allege widespread fraud and
    #      corruption" — a US case about different people entirely
    # Both were published in Cited sources of a report whose adverse-media section
    # said "nothing found in the sources searched". A partner reading that page
    # sees a fraud headline sitting inside a clean file; the two filters disagreed
    # because they were never the same filter.
    #
    # When the entity has MORE THAN ONE distinctive token, requiring two of them
    # (or one that is not merely a family name in a name-shaped title) is the
    # difference between "about this company" and "shares a surname". Single-token
    # entities are unchanged — there is nothing stronger to ask of them.
    if len(distinctive_tokens) > 1 and len(hits) < 2:
        # A single token IS aboutness when it is in the HOST: rossisecurity.co.uk
        # is the entity's own domain, whereas ciproud.com/rossi-reditus only
        # mentions the word in a slug. This keeps the subject's own site and
        # directory entries (which a one-token rule would otherwise drop along with
        # the noise) without readmitting third-party coverage of a namesake.
        _host = ""
        try:
            from urllib.parse import urlparse as _up
            _host = _norm(_up(str(url or "")).netloc)
        except Exception:                                   # noqa: BLE001
            _host = ""
        if not any(t in _host for t in hits):
            return False
    return True


# ── R-F1636 — registry-gap enrichment (rich data for no-registry targets) ────
def _extract_domain(target: dict, name: str) -> str:
    """Best-effort apex domain for the entity, for Wayback vintage enrichment."""
    from urllib.parse import urlparse
    for cand in (target.get("website"), target.get("url"), target.get("domain"),
                 target.get("name"), name):
        if not cand:
            continue
        s = str(cand).strip()
        if "://" in s:
            s = urlparse(s).netloc or s
        s = s.removeprefix("www.").split("/")[0].strip().lower()
        if "." in s and " " not in s and len(s) <= 80:
            return s
    return ""


def _registry_result_is_thin(reg_result) -> bool:
    """True when the registry adapter gave nothing usable: None, or a 'success'
    with no real identity (empty company number AND no directors). Catches the
    scrape-returns-boilerplate-junk case (e.g. the TR/MERSIS homepage scrape) —
    surfacing that as identity is worse than honestly enriching from OSINT."""
    if not reg_result:
        return True
    profile = reg_result.get("profile") or {}
    has_number = bool((profile.get("company_number") or "").strip())
    has_directors = bool(reg_result.get("officers"))
    return not (has_number or has_directors)


def _ch_verified_live(profile, ch_unavail) -> bool:
    """R-F3015 — True when Companies House verified the identity LIVE this run: it
    returned a real profile carrying a company number and was NOT flagged unavailable
    (timeout / rate-limit / officers-truncated). Only a genuine live CH profile clears
    it — GLEIF/vault fallback cannot populate a CH profile — so a caller can suppress
    the R-F1636 'registry unavailable' enrichment WITHOUT risking a false clean (the
    mirror-image of a false clean: a false negative on a real, verified identity)."""
    return bool((profile or {}).get("company_number")) and not ch_unavail


async def _wayback_earliest(domain: str) -> dict | None:
    """Earliest archived snapshot of a domain via the Wayback availability API
    (free, no key). The first-seen date is a vintage proxy when no registry
    incorporation date exists (a very young domain + recent contact = ghost
    risk). Returns {first_seen, snapshot_url} or None. Never raises."""
    if not domain:
        return None
    import httpx
    try:
        url = f"http://archive.org/wayback/available?url={domain}&timestamp=19960101"
        async with httpx.AsyncClient(timeout=12.0, follow_redirects=True) as client:  # no-breaker: best-effort per-DD wayback lookup, returns None on any failure
            r = await client.get(url)
            if r.status_code != 200:
                return None
            snap = ((r.json() or {}).get("archived_snapshots") or {}).get("closest") or {}
            ts = snap.get("timestamp") or ""
            if len(ts) < 8:
                return None
            return {"first_seen": f"{ts[0:4]}-{ts[4:6]}-{ts[6:8]}", "snapshot_url": snap.get("url", "")}
    except Exception:
        return None


async def _enrich_registry_gap(target: dict, report, name: str) -> None:
    """R-F1636 — when registry data is absent/thin/junk, enrich identity from
    FREE OSINT (Wayback vintage) + the intel VAULT (prior DDs), and WRITE the
    enrichment back to the vault so the next DD on this entity recalls it at $0
    (§15 pay-once-remember-forever). Never raises."""
    domain = _extract_domain(target, name)
    bits: list[str] = []

    # A-guard (folded in): a thin result may have populated identity with empty/
    # boilerplate values — clear obviously-unusable ones so the DD shows honest
    # "MISSING" instead of junk (e.g. a homepage-scrape fragment as 'address').
    _addr = (report.identity.registered_address or "")
    if _addr and (len(_addr) > 160 or "veri taban" in _addr.lower() or "mersis)" in _addr.lower()):
        report.identity.registered_address = ""
        report.identity.data_gaps.append("R-F1636: discarded non-address registry text (homepage-scrape artifact)")

    # 1. Vault recall first (§15) — did a prior DD already enrich this entity?
    try:
        from . import rag_store as _rs
        hits = await _rs.search(f"{name} registry enrichment vintage", top_k=3)
        if hits:
            report.identity.findings.append(Finding(
                severity="info",
                title=f"Vault recall: {len(hits)} prior memory hit(s) on {name}",
                detail="Prior DD intel recalled from the intel vault (§15 pay-once-remember-forever).",
                source="intel_vault", confidence="ASSESSED",
            ))
            bits.append("vault_recall")
    except Exception:
        pass

    # 2. Wayback domain vintage — proxy for entity age (no incorporation date).
    if domain:
        wb = await _wayback_earliest(domain)
        if wb and wb.get("first_seen"):
            report.identity.findings.append(Finding(
                severity="info",
                title=f"Domain vintage (Wayback): first archived {wb['first_seen']}",
                detail=(f"Domain {domain} first archived {wb['first_seen']} — vintage proxy "
                        f"(no registry incorporation date available)."),
                source=wb.get("snapshot_url") or "web.archive.org",
                confidence="ASSESSED",
            ))
            bits.append(f"wayback:{wb['first_seen']}")
        else:
            report.identity.data_gaps.append(
                f"R-F1636: no Wayback archive for {domain} — possibly a very new domain (age-risk signal)"
            )
            bits.append("wayback:none")

    # 3. Write enrichment to the VAULT so the next DD recalls it ($0) — §15.
    if bits:
        try:
            from . import brain_hook as _bh
            await _bh.absorb(
                module="dd_registry_enrichment",
                summary=f"Registry-gap enrichment for {name}: {', '.join(bits)}",
                detail=f"domain={domain}; jurisdiction={target.get('jurisdiction_iso2', '?')}",
                entity_name=name, success=True, confidence="ASSESSED", source_id="R-F1636",
            )
        except Exception:
            pass

    report.identity.data_gaps.append(
        "R-F1636: registry unavailable — identity enriched from OSINT/vault, NOT registry-verified; "
        "manual registry check still required before transacting."
    )


# ─────────────────────────────────────────────────────────────────────────
# R-F2294 — multi-angle digital research for DD. The single generic query
# ("<name> defence procurement") surfaced mostly the entity's own site + one
# facet; adverse-media / ownership / sanctions-adjacent / regulatory coverage was
# systematically under-retrieved (the confirmed _run_digital weakness). This
# plans the facets a defence-DD analyst searches by hand and retrieves them IN
# PARALLEL through ARIA's own free backends — Brave-API-class breadth, natively.
# §21a-wired, enabled by default (ARIA_DD_MULTIQUERY_ENABLED, kill-switch=0).
# ─────────────────────────────────────────────────────────────────────────
_DD_MULTIQUERY_ENABLED = os.getenv(
    "ARIA_DD_MULTIQUERY_ENABLED", "1").strip().lower() not in ("0", "false", "no", "off")
_DD_MULTIQUERY_PER_ANGLE = max(3, int(os.getenv("ARIA_DD_MULTIQUERY_PER_ANGLE", "6")))
_DD_MULTIQUERY_CONCURRENCY = max(1, int(os.getenv("ARIA_DD_MULTIQUERY_CONCURRENCY", "4")))


def _plan_digital_queries(name_for_search: str, target: dict) -> list[tuple]:
    """R-F2294 — plan the DD digital-research angles for `name_for_search`. Pure +
    deterministic (free, fast, always works) → unit-testable. Returns a list of
    (query, angle_label, multilingual). Covers the facets a defence-DD analyst
    searches by hand: procurement, sanctions-adjacent, adverse media, ownership,
    leadership, and — when known — jurisdiction-regulatory + product context."""
    n = (name_for_search or "").strip()
    jur = str(target.get("jurisdiction") or target.get("country") or "").strip()
    product = str(target.get("product_description") or target.get("goods") or "").strip()
    q: list[tuple] = [
        (f"{n} defence procurement", "procurement", True),  # original angle (multilingual)
        (f'"{n}" sanctions OR OFAC OR sanctioned OR embargo OR designated', "sanctions_adverse", False),
        (f'"{n}" fraud OR investigation OR lawsuit OR corruption OR bribery OR "money laundering"', "adverse_media", False),
        (f'"{n}" owner OR shareholder OR "parent company" OR subsidiary OR "beneficial owner"', "ownership", False),
        (f'"{n}" director OR CEO OR founder OR chairman OR "board of directors"', "leadership", False),
    ]
    if jur:
        q.append((f'"{n}" {jur} regulator OR licence OR license OR fine OR penalty OR enforcement', "regulatory", False))
    if product:
        q.append((f'"{n}" {product}', "product_context", False))
    return q


async def _multi_query_search(name_for_search: str, target: dict) -> list:
    """R-F2294 — run the planned DD angles in parallel, aggregate + dedupe by URL.
    Each angle is best-effort (a blocked/failed angle is skipped, never fatal),
    concurrency-bounded so we don't hammer the datacenter IP. §21a-wired: success
    → metric (angles / unique / independent), zero-yield or error → capability gap.
    Returns a combined, de-duplicated list of SearchResult."""
    from . import web_search
    plan = _plan_digital_queries(name_for_search, target)
    sem = asyncio.Semaphore(_DD_MULTIQUERY_CONCURRENCY)

    async def _one(query: str, label: str, multilingual: bool):
        async with sem:
            try:
                if multilingual:
                    return await web_search.search_multilingual(query, max_results=_DD_MULTIQUERY_PER_ANGLE)
                return await web_search.search(query, max_results=_DD_MULTIQUERY_PER_ANGLE)
            except Exception as _e:  # best-effort per angle
                logger.debug("[R-F2294] digital angle %s failed: %s", label, _e)
                return []

    results = await asyncio.gather(*[_one(qq, ll, ml) for (qq, ll, ml) in plan])
    seen: set = set()
    merged: list = []
    for lst in results:
        for h in (lst or []):
            u = (getattr(h, "url", None) or "").strip().lower()
            key = u or (getattr(h, "title", "") or "")[:80].lower()
            if key and key not in seen:
                seen.add(key)
                merged.append(h)
    try:
        from .engine_wiring import wire_success, wire_failure
        n_unique = len(merged)
        _ent_site = str(target.get("website") or target.get("website_url") or "").lower()
        _ent_dom = _ent_site.split("//")[-1].split("/")[0] if _ent_site else ""
        n_independent = (sum(1 for h in merged if _ent_dom and _ent_dom not in (getattr(h, "url", "") or "").lower())
                         if _ent_dom else n_unique)
        if n_unique > 0:
            wire_success(
                module="dd_digital_multiquery",
                summary=f"{len(plan)} angles -> {n_unique} unique sources ({n_independent} independent) for {name_for_search[:60]}",
                entity_name=name_for_search[:80], source_id="dd_orchestrator:R-F2294")
        else:
            wire_failure(
                module="dd_digital_multiquery",
                detail=f"multi-angle digital search returned ZERO sources for {name_for_search[:80]} across {len(plan)} angles (backends blocked/silent?)",
                gap_type="source_failure", source="dd_orchestrator:_multi_query_search")
    except Exception:
        pass
    return merged


#: R-F3569 — how many results to take per register. A statutory listing either names
#: the subject or it does not; asking for more only buys near-duplicates and budget.
_REGISTER_SWEEP_PER_HOST = 3
_REGISTER_SWEEP_CONCURRENCY = 3


async def _register_credential_sweep(name_for_search: str, target: dict) -> tuple[list, dict]:
    """R-F3569 — ASK each curated register whether the subject is on it.

    THE GAP THIS CLOSES. R-F3553/R-F3566 promote a register credential only if some
    OTHER search happened to return that page. The sweeps that run are adverse ones —
    they query wrongdoing terms — so an SIA Approved Contractor listing or an Armed
    Forces Covenant signature is surfaced by luck, not by design. A DD that can only
    find fault by construction is not neutral, and the operator asked for exactly this.

    ONE site-scoped query per register, so cost is bounded and legible: 6 hosts x 3
    results, run concurrently, each best-effort. A failed register never fails the DD.

    Returns (evidence_rows, meta). The META IS NOT OPTIONAL: an empty result list must
    be distinguishable from a sweep that never ran, or "no credentials found" becomes an
    unverified absence — the same false-clean shape this file fights everywhere else.
    """
    from . import web_search

    hosts = [h for h in _POSITIVE_REGISTERS if h not in _NOT_A_CREDENTIAL]
    meta: dict = {"queried": [], "answered": [], "failed": [], "hits": 0,
                  "framework_version": "R-F3569 register sweep"}
    if not (name_for_search or "").strip():
        meta["skipped_reason"] = "no subject name to query"
        return [], meta

    sem = asyncio.Semaphore(_REGISTER_SWEEP_CONCURRENCY)

    async def _one(host: str):
        async with sem:
            try:
                res = await web_search.search(
                    f'site:{host} "{name_for_search}"',
                    max_results=_REGISTER_SWEEP_PER_HOST)
                return host, (res or []), None
            except Exception as _e:      # noqa: BLE001 — one register never fails the DD
                return host, [], _e

    out: list = []
    seen_urls: set = set()
    for host, res, err in await asyncio.gather(*[_one(h) for h in hosts]):
        meta["queried"].append(host)
        if err is not None:
            meta["failed"].append(host)
            logger.debug("[R-F3569] register sweep %s failed: %s", host, err)
            continue
        meta["answered"].append(host)
        for r in res:
            u = str(getattr(r, "url", "") or "").strip()
            # A backend can return anything; only keep what is genuinely ON the register.
            if not u.startswith("http") or host not in u.lower():
                continue
            if u in seen_urls:
                continue
            seen_urls.add(u)
            out.append(Evidence(
                source=str(getattr(r, "title", "") or "")[:300],
                source_tier="OFFICIAL",
                url=u,
                snippet=str(getattr(r, "snippet", "") or "")[:400],
                retrieved_at=datetime.now(timezone.utc).isoformat(),
            ))
    meta["hits"] = len(out)

    try:
        from .engine_wiring import wire_success, wire_failure
        if meta["answered"]:
            wire_success(
                module="dd_register_sweep",
                summary=f"{len(meta['answered'])}/{len(hosts)} registers answered, "
                        f"{len(out)} listing(s) for {name_for_search[:60]}",
                detail=f"failed={meta['failed']}", entity_name=name_for_search[:80],
                source_id="dd_orchestrator:R-F3569")
        else:
            wire_failure(
                module="dd_register_sweep",
                detail=f"NO register answered for {name_for_search[:80]} "
                       f"({len(hosts)} queried) — positive evidence is unavailable, "
                       f"not absent",
                gap_type="source_failure", source="dd_orchestrator:_register_credential_sweep")
    except Exception:                    # noqa: BLE001
        pass
    return out, meta


def _coerce_entity_text(raw: object) -> str:
    """R-F3258 — an entity name that reaches the search layer must be a string.

    Returns "" for anything unusable so the caller's `or` chain falls through to
    the next source, exactly as it would for an empty string. A dict is NOT
    unwrapped: guessing which key held the name is the kind of silent repair that
    produces a confidently wrong subject, and a wrong search subject is worse than
    no search — it looks like a completed check.

    A list picks the first non-empty string member: a list-shaped name is a
    malformed SINGLE name (observed live: the AZURE PARKING LTD DD), not a request
    to research several entities.
    """
    if isinstance(raw, str):
        return raw.strip()
    if isinstance(raw, (list, tuple)):
        for item in raw:
            if isinstance(item, str) and item.strip():
                return item.strip()
    return ""


def _surface_research_disclosures(dr: object, section: Any) -> None:
    """R-F3258/R-F3259/R-F3260 — carry deep research's self-reported failures into
    the report's data gaps.

    `investigate()` already returns `topic_coerced_from`, `synthesis_error` and
    `verification_summary.failed`, but NOTHING read them: `verification_summary`
    was a producer with no consumer, so even a recorded failure could not reach the
    report. A step that did not run must never be indistinguishable from one that
    ran and found nothing — that is the false-clean class this repo keeps meeting.
    """
    if not isinstance(dr, dict):
        return
    coerced = dr.get("topic_coerced_from")
    if coerced:
        section.data_gaps.append(
            f"R-F3258: the search subject arrived as {coerced}, not text — it was "
            "coerced to run the search, but the caller supplied a malformed entity name"
        )
    synth_err = dr.get("synthesis_error")
    if synth_err:
        section.data_gaps.append(
            f"R-F3259: the research assessment could not be produced ({synth_err}) — "
            "the articles and facts below are real, but they were NOT summarised"
        )
    vs = dr.get("verification_summary")
    if isinstance(vs, dict) and vs.get("failed"):
        section.data_gaps.append(
            f"R-F3260: fact verification did NOT run ({vs['failed']}) — citation "
            "downgrading, contradiction detection and past-fact cross-checks were "
            "skipped, so confidence labels on these findings are UNVERIFIED"
        )


async def _run_digital(target: dict, report: ARKDDReport, llm: Any, _mode_is_deep: bool = False) -> None:
    """Layer 5 — Digital. web_search multilingual + RAG + neural + (opt.) deep_research.

    When _mode_is_deep is True (orchestrator mode="deep"), deep_researcher
    runs with depth="thorough" (8 search angles × 3 articles, ~30-60s
    and ~$0.10). Otherwise depth="quick" (3 × 2 = 6 articles, ~15s and
    ~$0.03). This keeps the default "standard" DD run under the
    per-run cost cap even with the LLM-backed investigation firing.
    """
    t0 = time.time()
    report.digital.meta.started_at = datetime.now(timezone.utc).isoformat()
    # R-F3258 — coerce BEFORE use. `target` is the caller-supplied DD request and
    # is never type-validated, and `entity_name: str = ""` is a dataclass
    # annotation, which Python does not enforce at runtime. `name` feeds ~20
    # downstream uses in this function (query planning, brandification, the
    # deep_researcher call), so it has to be a string here — guarding only at the
    # investigate() call would leave the other nineteen exposed.
    name = _coerce_entity_text(report.identity.entity_name) or _coerce_entity_text(target.get("query"))

    # R-F299: when name was derived from a hostname (R-F153 fallback) the
    # search query "modirumgespi.com defence procurement" returns nothing
    # useful — same-domain mentions only. Derive a brand-friendly form by
    # stripping the TLD and converting separators to spaces, then run the
    # search against THAT. The original hostname is still preserved in
    # target["name"] for storage/audit.
    name_for_search = _brandify_name_for_search(name, target)

    # ── 5a. Web search — R-F2294 multi-angle (Brave-class breadth) by default,
    #        single generic query only when the kill-switch is set. ──
    try:
        from . import web_search
        if _DD_MULTIQUERY_ENABLED:
            hits = await _bounded_dd_op(_multi_query_search(name_for_search, target), _OP_T_MULTIQUERY, report.digital, "multi-angle web search", default=[])
        else:
            hits = await _bounded_dd_op(web_search.search_multilingual(
                f"{name_for_search} defence procurement",
                max_results=12,
            ), _OP_T_WEBSEARCH, report.digital, "web search (fallback)", default=[])
        # R-F1880 (search best-effort honesty): a BLOCKED search (all engines
        # 403/CAPTCHA the datacenter IP) must NOT be read as "no adverse media →
        # clean entity". Inspect the backend ecosystem; when search is DEAD/
        # DEGRADED, flag the absence of press findings as a COVERAGE GAP, loudly,
        # so the BLUF/footer never implies a clean bill from an un-searchable web.
        # Primary sources (entity site R-F1874, GLEIF R-F1876) carry the report.
        try:
            _eco = web_search.get_last_search_ecosystem() or {}
            _eco_public = dict(_eco)
            _eco_public["backends"] = []
            for _backend in (_eco.get("backends") or []):
                if not isinstance(_backend, dict):
                    continue
                _b_public = dict(_backend)
                if _b_public.get("name") == "brave":
                    _b_public["name"] = "primary_user_search"
                _eco_public["backends"].append(_b_public)
            report.digital.search_ecosystem = _eco_public
            _eco_health = (_eco.get("health_signal") or "").upper()
            _eco_active = (_eco.get("summary") or {}).get("active_backends")
            _primary = next(
                (
                    b for b in (_eco.get("backends") or [])
                    if isinstance(b, dict) and b.get("name") == "brave"
                ),
                None,
            )
            if _primary and _primary.get("state") != "active":
                report.digital.data_gaps.append(
                    "Primary user-facing search backend produced no usable result "
                    f"(state={_primary.get('state') or 'unknown'}"
                    f"{', reason=' + str(_primary.get('error_reason'))[:80] if _primary.get('error_reason') else ''})."
                )
            if _eco_health in ("DEAD", "DEGRADED") or _eco_active == 0:
                report.digital.data_gaps.append(
                    "⚠️ ADVERSE-MEDIA SEARCH UNAVAILABLE — all/most web-search backends were "
                    f"blocked or silent this run (health={_eco_health or 'unknown'}). The ABSENCE "
                    "of press/adverse-media findings does NOT indicate a clean entity; it means the "
                    "open web could not be searched. Findings rely on PRIMARY sources (entity "
                    "website, GLEIF) — a dedicated adverse-media check is still required."
                )
                report.digital.findings.append(Finding(
                    severity="info",
                    title="Web-search coverage gap — adverse media not searchable this run",
                    detail=(
                        f"Search ecosystem health={_eco_health or 'unknown'}, "
                        f"active_backends={_eco_active}. Treat 'no adverse media' as UNKNOWN, "
                        f"not clean (R-F1880)."
                    ),
                    source="web_search.get_last_search_ecosystem",
                    confidence="ASSESSED",
                ))
                logger.warning("R-F1880 DD digital: search ecosystem %s (active=%s) — "
                               "flagged coverage gap, NOT clean", _eco_health, _eco_active)
        except Exception as _eco_e:
            logger.debug("R-F1880 search-ecosystem check failed (non-fatal): %s", _eco_e)
        # Convert SearchResult objects to Evidence dataclasses where possible
        press: list[Evidence] = []
        tier_counts: dict[str, int] = {}
        # R-F1631 — entity-relevance gate: drop search noise at ingestion so the
        # report's "press coverage" actually references the entity (not unrelated
        # academic papers / generic 'security' hits / tangential notices).
        _distinctive = _entity_distinctive_tokens(name_for_search, name, str(target.get("name") or ""))
        _dropped_irrelevant = 0
        for h in hits or []:
            if not _press_hit_is_relevant(
                getattr(h, "title", "") or "", getattr(h, "snippet", "") or "",
                getattr(h, "url", "") or "", _distinctive,
            ):
                _dropped_irrelevant += 1
                continue
            tier = getattr(h, "source_tier", None) or "UNVERIFIED"
            _url_for_tier = getattr(h, "url", None) or ""
            # R-F316 (2026-05-11): apply web_explorer._classify_tier to
            # every press URL. The 21:11 chat output reported 12 press
            # items, ALL tagged UNVERIFIED — the search-aggregator was
            # not classifying Reuters/BBC/Janes/etc. Now the tier
            # classifier runs ON the URL even if the upstream backend
            # didn't supply a source_tier.
            # R-F3183 — a memory:// URL is ARIA'S OWN RAG, not an external source.
            #
            # THE DEFECT (live, Babcock dd_788e6f3ca2c3): the digital evidence pool
            # contained `memory://7d38a9c87a8b` tiered UNVERIFIED, while the report's
            # own `memory_only_sources` metric read 0. So a SELF-CITATION was counted
            # in the external-source pool, and the tier built to exclude it recorded
            # none present.
            #
            # MEMORY_ONLY is only ever assigned in the R-F188 fallback below, which
            # fires when live search returns ZERO hits. But per R-F2346 `web_search`
            # mixes RAG hits INTO normal results, so any memory:// arriving on the
            # normal path missed the tier entirely — the mechanism existed, just not
            # on the path that produces the answer.
            #
            # Tier by the SOURCE, not by the code path that fetched it: a memory://
            # URL is ARIA quoting herself no matter which branch surfaced it. Checked
            # BEFORE _classify_tier, which cannot classify a non-http scheme and
            # would leave it in the UNVERIFIED remainder.
            if _url_for_tier.startswith("memory://"):
                tier = "MEMORY_ONLY"
            elif tier == "UNVERIFIED" and _url_for_tier:
                try:
                    from .web_explorer import _classify_tier as _ct
                    _tier_guess = _ct(_url_for_tier)
                    if _tier_guess and _tier_guess != "UNVERIFIED":
                        tier = _tier_guess
                except Exception:
                    pass
            tier_counts[tier] = tier_counts.get(tier, 0) + 1
            press.append(Evidence(
                source=getattr(h, "title", "") or getattr(h, "url", ""),
                source_tier=tier,
                url=getattr(h, "url", None),
                snippet=(getattr(h, "snippet", "") or "")[:400],
                retrieved_at=datetime.now(timezone.utc).isoformat(),
            ))
        # R-F1874 (direct-source-first): mine the entity's OWN website as PRIMARY
        # evidence. A company's own site rarely blocks the datacenter IP the way
        # search engines do, so this is the independence backbone (CLAUDE.md §6) —
        # the DD has real content even when general web search is 403'd/empty.
        # Prepended so primary self-reported content leads the digital evidence.
        _site = ""
        for _c in (target.get("website"), target.get("url"), target.get("domain")):
            if _c and isinstance(_c, str) and _c.strip():
                _site = _c.strip()
                break
        if _site:
            if not _site.lower().startswith(("http://", "https://")):
                _site = "https://" + _site
            try:
                # R-F1895: reuse the pages the identity layer already mined (it
                # mines the site to derive jurisdiction); avoid a second fetch.
                _mined = target.get("_mined_pages")
                if not _mined:
                    _mined = await _bounded_dd_op(_mine_entity_website(_site), _OP_T_WEBSITE_MINE, report.digital, "entity website mining")
            except Exception as _mine_e:
                _mined = []
                logger.debug("R-F1874 site-mine failed: %s", _mine_e)
            if _mined:
                _primary: list[Evidence] = []
                for _pg in _mined:
                    _primary.append(Evidence(
                        source=f"{_pg.get('label', 'page')}: {_pg.get('title') or _pg.get('url')}"[:200],
                        source_tier="ENTITY_SITE",   # primary, self-reported
                        url=_pg.get("url"),
                        snippet=(_pg.get("text") or "")[:400],
                        retrieved_at=datetime.now(timezone.utc).isoformat(),
                    ))
                tier_counts["ENTITY_SITE"] = tier_counts.get("ENTITY_SITE", 0) + len(_primary)
                press = _primary + press     # primary content leads the digital layer
                logger.info("R-F1874: mined %d primary page(s) from entity site %s",
                            len(_primary), _site[:80])
        report.digital.press_coverage = press[:15]
        report.digital.source_tier_breakdown = tier_counts
        # R-F3569 — ask the registers DIRECTLY. Runs here, in the layer that already
        # searches: `_run_synthesis` is capped at 10s (see the wait_for at its call
        # site), so six web queries could never live there.
        try:
            _reg_rows, _reg_meta = await _register_credential_sweep(name_for_search, target)
            report.digital.register_checks = _reg_rows
            report.digital.register_checks_meta = _reg_meta
            if _reg_meta.get("failed"):
                report.digital.data_gaps.append(
                    "R-F3569: register(s) did not answer — "
                    f"{', '.join(_reg_meta['failed'])}; positive evidence from these is "
                    "UNAVAILABLE, not absent"
                )
        except Exception as _rs_e:       # noqa: BLE001 — a positive never costs a report
            logger.debug("[R-F3569] register sweep skipped: %s", _rs_e)
        if _dropped_irrelevant:
            report.digital.data_gaps.append(
                f"R-F1631: {_dropped_irrelevant} search result(s) excluded as not "
                f"referencing '{name_for_search}' (entity-relevance filter)"
            )
        report.digital.meta.subcalls += 1
        # R-F188 (2026-05-11): when web_search returned 0 hits, run a
        # RAG-only fallback so the report still has SOMETHING for the
        # digital layer rather than rendering "no press coverage" as if
        # the entity were invisible. Tagged MEMORY_ONLY so the caller
        # can see the evidence came from cached memory, not live web.
        if not hits:
            try:
                from . import rag_store as _rs_dd
                rag_results = await _bounded_dd_op(_rs_dd.search(name, top_k=10), _OP_T_RAG, report.digital, "RAG search", default=[])
                if rag_results:
                    memory_press: list[Evidence] = []
                    for hit in rag_results[:10]:
                        if not isinstance(hit, dict):
                            continue
                        memory_press.append(Evidence(
                            source=hit.get("source", "rag_memory"),
                            source_tier="MEMORY_ONLY",
                            url=hit.get("url"),
                            snippet=(hit.get("text") or hit.get("excerpt") or "")[:400],
                            retrieved_at=datetime.now(timezone.utc).isoformat(),
                        ))
                    report.digital.press_coverage = memory_press
                    tier_counts["MEMORY_ONLY"] = len(memory_press)
                    report.digital.source_tier_breakdown = tier_counts
                    report.digital.data_gaps.append(
                        "R-F188: live web returned 0 — served from RAG memory only"
                    )
                    # Flag on meta so report consumers see degradation
                    setattr(report.digital.meta, "degraded_search", True)
                    logger.info(
                        "[dd] R-F188 RAG-only fallback for %s — %d memory hits",
                        name[:60], len(memory_press),
                    )
            except Exception as _rfe:
                logger.debug("R-F188 RAG fallback failed: %s", _rfe)
    except Exception as e:
        logger.warning("Digital: web_search failed: %s", e)
        report.digital.data_gaps.append(f"web_search failed: {str(e)[:120]}")

    # ── 5b. RAG context ──
    try:
        from . import rag_store
        # R-F3066 — was UNBOUNDED. Bounded blocks alone could not keep the layer
        # inside its budget while blocks like this ran free.
        rag_ctx = await _bounded_dd_op(
            rag_store.get_rag_context(f"{name}", max_chars=2500),
            _OP_T_RAG, report.digital, "RAG context", default="")
        if rag_ctx and rag_ctx.strip():
            report.digital.knowledge_base_hits = [{"query": name, "excerpt": rag_ctx[:1500]}]
            report.digital.meta.subcalls += 1
    except Exception as e:
        logger.warning("Digital: rag_store failed: %s", e)

    # ── 5c. Neural associations ──
    try:
        from . import neural_memory
        # R-F3066 — was UNBOUNDED (the neural graph can be slow under load).
        neural = await _bounded_dd_op(
            neural_memory.get_neural_context(name),
            _OP_T_KB, report.digital, "neural associations", default="")
        if neural and neural.strip():
            # Pull out first N concept names from the neural block
            for line in neural.split("\n")[:8]:
                if line.strip().startswith("["):
                    report.digital.neural_associations.append(line.strip()[:200])
            report.digital.meta.subcalls += 1
    except Exception as e:
        logger.warning("Digital: neural_memory failed: %s", e)

    # ── 5d. Knowledge base ──
    try:
        from . import knowledge
        # R-F2056 — offload the synchronous knowledge scan to a worker thread (it
        # self-yields the GIL via R-F939, and to_thread lets the event loop run
        # during the scan) so concurrent DDs don't serialize on it. Mirrors the
        # deep_researcher pattern.
        kb = await _bounded_dd_op(asyncio.to_thread(knowledge.search_knowledge, name), _OP_T_KB, report.digital, "knowledge-base search", default=[])
        if kb and kb.strip():
            report.digital.knowledge_base_hits.append({"query": name, "excerpt": kb[:1500], "tier": "aria_knowledge"})
            report.digital.meta.subcalls += 1
    except Exception as e:
        logger.warning("Digital: knowledge search failed: %s", e)

    # ── 5e. Deep research (opt-in, LLM-backed) ──
    # Real signature: investigate(llm, topic, depth="quick"|"thorough"|"exhaustive").
    # depth is a STRING enum, not an int, and there is no max_pages or
    # context kwarg. Previous code passed max_pages=10 depth=1 and
    # crashed with "unexpected keyword argument 'max_pages'" on every
    # DD run with DEEP_RESEARCH_ENABLED. Reported silently in
    # digital.data_gaps so the Serban v3 chat output surfaced it.
    #
    # DD orchestrator uses "quick" by default (3 search angles × 2
    # articles = 6 LLM calls — ~30s and ~$0.03 per run) so the
    # digital layer stays within the per-run cost cap. Callers who
    # want the full "thorough" or "exhaustive" depth can pass the
    # mode="deep" flag at orchestration time; the orchestrator maps
    # deep → "thorough" and all other modes → "quick".
    if DEEP_RESEARCH_ENABLED and llm is not None:
        try:
            from . import deep_researcher
            # Always "quick" inside DD — deep mode's value-add is the
            # link_investigator tree walk (rule-based, zero LLM cost).
            # "thorough" was firing 24 LLM calls that exhausted provider
            # rate limits before chat synthesis could run (New Akord
            # Security 2026-04-12 — 3 consecutive timeouts).
            # R-F3093 — deep mode now HAS the budget to be thorough (the digital
            # layer is raised to _DEEP_DIGITAL_BUDGET_S alongside this), and DD is
            # pinned to Claude (R-F2917/R-F3087), not the DeepSeek chain whose rate
            # limits the 2026-04-12 note above was written against. Standard/quick
            # stay on "quick" — unchanged cost, unchanged wall-clock.
            dr_depth = "thorough" if _mode_is_deep else "quick"
            # R-F1812 — base research stays "quick" (cost), but DO run the
            # bounded recursive person drill-down: it's the highest-value DD
            # signal ("who is behind it") and often the ONLY way to name people
            # when the corporate registry is missing/stubbed (e.g. Portugal).
            # Time-guarded inside investigate(); count env-tunable for cost.
            try:
                _dd_people = int(os.getenv("ARIA_DD_PEOPLE", "2"))
            except (ValueError, TypeError):
                _dd_people = 2
            # R-F1823 — seed the drill-down with people the DD ALREADY knows
            # (registry-listed directors), so a director with no web footprint is
            # still PEP/sanctions-investigated, not just listed. Names are
            # taint-sanitized inside investigate().
            _seed = []
            try:
                for _d in (report.identity.directors or []):
                    _nm = _d.get("name") if isinstance(_d, dict) else (_d if isinstance(_d, str) else None)
                    if _nm:
                        _seed.append(_nm)
            except Exception:
                _seed = []
            # R-F3018 — hand deep research a COOPERATIVE budget slightly inside the
            # hard per-op bound. Before this, the bound was a pure `wait_for` cancel:
            # at 40s every article read and fact learned was thrown away and the DD
            # got `{}` while the report claimed a "partial result". Now the engine
            # owns the clock, returns what it gathered, and the outer bound is only
            # a backstop for a genuinely wedged call.
            # R-F3093 — deep mode gets _OP_T_DEEPRESEARCH_DEEP (300s default) instead
            # of the 40s that produced "0 article(s) analysed, 0 fact(s) retained" on
            # a DEEP Mitie run. Still cooperative: the engine owns the clock and
            # returns what it gathered (R-F3018).
            _dr_op_budget = _OP_T_DEEPRESEARCH_DEEP if _mode_is_deep else _OP_T_DEEPRESEARCH
            _dr_deadline = max(5.0, _dr_op_budget - 3.0)
            # R-F3316 — this dict is OURS. investigate() writes its current stage
            # into it, so when the wait_for backstop cancels the call (destroying
            # its stack and returning {}), the report can still name the stage that
            # consumed the budget instead of only "did not complete within 300s".
            _dr_progress: dict = {}
            dr = await _bounded_dd_op(deep_researcher.investigate(
                llm, name, depth=dr_depth, investigate_people=_dd_people,
                seed_people=_seed or None, deadline_s=_dr_deadline,
                progress=_dr_progress),
                _dr_op_budget, report.digital, "deep research", default={},
                progress=_dr_progress)
            if isinstance(dr, dict) and dr.get("partial"):
                # R-F3502 — the LAYER is partial, not just the gap list. A bounded sweep
                # that analysed 0 articles was still rendering "COMPLETED" in the section
                # header, because the status was set unconditionally at the end. A reader
                # scanning headers saw a finished screen; the truncation was one gap
                # buried in a long list.
                report.digital.meta.status = LayerStatus.PARTIAL.value
                # Honest, specific, and — unlike the old wording — TRUE: name what
                # was gathered before the cut, not just that a timer expired.
                # R-F3507 — say what CLOSES it, not only what happened.
                #
                # R-F3093 and R-F3131 both established, deliberately, that standard and
                # quick modes keep the small budget: the 660s total is what guarantees a
                # WhatsApp async push inside the 15-minute poll window, and moving it
                # breaks delivery. So in standard mode this stage CANNOT reach article
                # analysis — that is a designed trade-off, not a failure.
                #
                # But the gap only described the cut. A reader saw "0 articles analysed"
                # with no way to know that a Deep run is the remedy and that the search
                # fan-out they DID get is still real. Per R-F3456, a gap owes the reader
                # WHY and WHAT CLOSES IT; without the remedy this reads as a broken
                # sweep rather than a tier boundary.
                _mode_note = (
                    " This is the STANDARD-mode research budget, which is sized for "
                    "delivery inside the async-push window and cannot reach article "
                    "analysis. Re-run in DEEP mode for article-level reading; the "
                    "citations gathered here are real and remain valid."
                    if not _mode_is_deep else
                    " This was a DEEP run, so the budget was already the larger one — "
                    "treat the sweep as genuinely incomplete rather than tier-limited."
                )
                report.digital.data_gaps.append(
                    f"deep research was bounded at {int(_dr_deadline)}s and stopped after "
                    f"{dr.get('stopped_after') or 'an earlier stage'} — "
                    f"{dr.get('articles_read', 0)} article(s) analysed, "
                    f"{dr.get('facts_learned', 0)} fact(s) retained; "
                    "the results below are real but NOT an exhaustive sweep."
                    + _mode_note
                )
            # R-F3258/R-F3259/R-F3260 — surface what the engine reported about
            # ITSELF before reading its results, so a degraded run is visible in
            # the report even when it still returned usable findings.
            _surface_research_disclosures(dr, report.digital)
            if isinstance(dr, dict):
                synth = dr.get("synthesis") or {}
                report.digital.web_footprint = {
                    "summary": (
                        dr.get("summary")
                        or synth.get("executive_summary")
                        or ""
                    )[:1500],
                    "articles_read": dr.get("articles_read", 0),
                    "facts_learned": dr.get("facts_learned", 0),
                    "search_angles": dr.get("search_angles", []),
                    "depth": dr_depth,
                }
                report.digital.meta.subcalls += 1
                # R-F1816 — carry the recursive person drill-down (R-F1812) into
                # the report so named individuals reach WA + web. Without this the
                # dossiers were computed then dropped ("Zero named individuals").
                _people = dr.get("people") or []
                if isinstance(_people, list) and _people:
                    report.digital.people = _people
                    # Surface a HIGH/CRITICAL person as a network-level finding so
                    # it drives the verdict, not just the digital section.
                    for _pp in _people:
                        _dos = _pp.get("dossier") or {} if isinstance(_pp, dict) else {}
                        _risk = (_dos.get("risk_assessment") or "").upper() if isinstance(_dos, dict) else ""
                        if _risk in ("HIGH", "CRITICAL"):
                            report.digital.findings.append(Finding(
                                severity="high" if _risk == "HIGH" else "critical",
                                title=f"Named individual {_pp.get('name','?')} ({_pp.get('role') or 'role unknown'}) — risk {_risk}",
                                source="deep_researcher.investigate_person",
                                confidence="ASSESSED",
                            ))
                # If investigate surfaced its own findings, merge them in.
                for f in (synth.get("key_findings") or [])[:5]:
                    if isinstance(f, str):
                        report.digital.findings.append(Finding(
                            severity="info",
                            title=f[:200],
                            source="deep_researcher.investigate",
                            confidence="ASSESSED",
                        ))
        except Exception as e:
            # ── R-F3296 — AN ERROR HANDLER MUST NOT DISCARD WHERE THE ERROR WAS ──
            #
            # This recorded only str(e)[:120], so the live AZURE PARKING LTD report
            # said exactly "deep_research failed: 'list' object has no attribute
            # 'lower'" and nothing more. That message is true and useless: the
            # engine has ~20 `.lower()` calls across two modules, and locating the
            # real one (researcher.py:2111, R-F3295) took three attempts and two
            # wrong fixes. The traceback existed at the moment of the catch and
            # was thrown away.
            #
            # Records the innermost frame INSIDE aria_service, which is the line
            # that actually raised rather than this catch site.
            _where = ""
            try:
                import traceback as _tb
                _frames = [f for f in _tb.extract_tb(e.__traceback__)
                           if "aria_service" in (f.filename or "")]
                if _frames:
                    _f = _frames[-1]
                    # basename by string, NOT pathlib: `Path` is not imported in
                    # this module, and the NameError would have been swallowed by
                    # the except below, leaving _where empty. The fix would have
                    # looked applied and reported nothing.
                    _name = str(_f.filename).replace("\\", "/").rsplit("/", 1)[-1]
                    _where = f" at {_name}:{_f.lineno} in {_f.name}()"
            except Exception:      # noqa: BLE001 — diagnostics must never mask the error
                pass
            logger.warning("Digital: deep_research failed%s: %s", _where, e, exc_info=True)
            report.digital.data_gaps.append(
                f"deep_research failed{_where}: {str(e)[:120]}")

    # ── 5e-bis. Domain ownership verification (RDAP) ──
    # MOVED to Layer 1 / identity as of R-F1836 (see _check_domain_ownership):
    # domain ownership is an identity signal, and the digital layer is skipped
    # in quick mode / on hard-stop, so the check never ran there in those modes.
    # It now runs unconditionally inside _run_identity / _run_identity_person.

    # ── 5f. Link-investigator (deep mode only) ──
    # Recursive URL-tree walk seeded from the target's own website (if
    # supplied) or the top-tier press-coverage hit. Rule-based extraction
    # only by default — no LLM cost. Budgets enforced inside the module.
    if _mode_is_deep:
        seed_url = target.get("website") or target.get("domain")
        if not seed_url and report.digital.press_coverage:
            seed_url = next(
                (e.url for e in report.digital.press_coverage if e.url),
                None,
            )
        if seed_url:
            if not seed_url.startswith(("http://", "https://")):
                seed_url = "https://" + seed_url
            try:
                from . import link_investigator
                # R-F340 (2026-05-11): enable LLM-based fact extraction
                # for prose-heavy corporate pages. The rule-based
                # extractor only catches dates / amounts / emails /
                # registration numbers — it can't read prose like
                # "Mehmet Kibar, Chairman" or "Assan manufactures cold-
                # rolled aluminum coils". Live 23:06 evidence:
                # assangroup.com.tr DD fetched 6 corporate pages but
                # the fact list was just "year:1959 amount:$0".
                # When llm is available + we're in deep mode, pass it
                # through with a $0.20 budget cap (40-50 pages of LLM
                # extraction). Gated by ARIA_LINKTREE_LLM_ENABLED=0
                # for cost-sensitive deploys.
                _llm_for_linktree = None
                _llm_budget = 0.0
                if (llm is not None
                        and (os.getenv("ARIA_LINKTREE_LLM_ENABLED", "1") or "1")
                            .lower() not in ("0", "false", "no")):
                    _llm_for_linktree = llm
                    _llm_budget = _env_float(
                        "ARIA_LINKTREE_LLM_BUDGET_USD", 0.20,
                    )
                # R-F3066 — the link tree claimed a FLAT 90s wall budget inside a
                # 180s layer that had already spent ~82s on bounded ops (multi-query
                # 45 + deep research 37). 82 + 90 > 180, so a deep-mode DD was
                # arithmetically certain to blow the layer — which is what every
                # live deep report showed. Its budget is now DERIVED from what the
                # layer actually has left, and the call is bounded like every other
                # heavy op so it degrades to a data_gap instead of taking the layer
                # down with it.
                # (R-F340 remains in force below: the LLM is passed through with a
                # cost cap for prose-heavy corporate pages — R-F3066 changes only
                # the WALL BUDGET, never whether the LLM is supplied.)
                # R-F3066 — take at most a FRACTION of what is left. A trailing op
                # that claims the entire remainder starves every block after it, which
                # is how the person path (90s budget) still overran even once the
                # budget was derived rather than flat.
                _lt_budget = min(90.0, _layer_budget_left(default=90.0) * 0.6)
                tree = None
                if _lt_budget < 15.0:
                    report.digital.data_gaps.append(
                        "link-tree investigation SKIPPED — insufficient layer budget "
                        "remained. Not attempted, so treat as unchecked, not as clean.")
                else:
                    tree = await _bounded_dd_op(link_investigator.investigate_link_tree(
                        seed_url=seed_url,
                        query_context=name,
                        max_depth=2,
                        max_pages=20,
                        wall_budget_s=min(90.0, _lt_budget),
                        cost_budget_usd=_llm_budget,
                        llm=_llm_for_linktree,
                    ), min(90.0, _lt_budget) + 5.0, report.digital,
                        "link-tree investigation", default=None)
                if tree is None:
                    # R-F3066 — bounded out or skipped. The consuming block below
                    # dereferences `tree`, so bail through the enclosing handler
                    # rather than re-indenting ~200 lines; the data_gap explaining
                    # WHY was already recorded by _bounded_dd_op / the skip branch.
                    raise RuntimeError("link-tree investigation not completed within budget")
                report.digital.web_footprint = dict(report.digital.web_footprint or {})
                report.digital.web_footprint["link_tree"] = {
                    "tree_id": tree.tree_id,
                    "seed_url": tree.seed_url,
                    "pages_fetched": tree.pages_fetched,
                    "pages_failed": tree.pages_failed,
                    "max_depth_reached": tree.max_depth_reached,
                    "fused_fact_count": len(tree.fused_facts),
                    "budget_exceeded": tree.budget_exceeded,
                    "duration_ms": tree.duration_ms,
                }
                # Surface high-confidence triangulated facts as findings.
                for ff in tree.fused_facts[:8]:
                    if ff.triangulation >= 2:
                        report.digital.findings.append(Finding(
                            severity="info",
                            title=f"link-tree: {ff.kind}={ff.value[:120]} (×{ff.triangulation} sources)",
                            source=f"link_investigator.{tree.tree_id}",
                            confidence="ASSESSED",
                        ))
                report.digital.meta.subcalls += 1

                # R-F301: post-link-tree jurisdiction detection. If the
                # identity layer couldn't infer jurisdiction (no phone,
                # no address, no email, no reg-num pattern), the website
                # text often contains the answer. Set jurisdiction_iso2
                # + country name from the link-tree page text so any
                # downstream layer (Layer 4 country-risk, registry
                # adapters, etc.) can use them.
                try:
                    if not report.identity.jurisdiction_iso2:
                        # R-F301 follow-up (live ev. 2026-05-11): try ALL
                        # detected jurisdictions, not just the winner.
                        # Modirum GESPI page mentions BR + FI + AE + RS +
                        # MK — winner was BR but the Finnish PRH adapter
                        # never got asked. Now we try each adapter in
                        # rank order; whichever returns data wins.
                        all_juris = _detect_all_jurisdictions_in_link_tree(tree)
                        winning_iso2 = None
                        winning_evidence = ""
                        adapter_attempts: list[dict] = []
                        if all_juris:
                            # Always set the highest-voted as the default
                            # jurisdiction for the record (so country-risk
                            # etc. have something to read), even if no
                            # adapter returns data.
                            winning_iso2 = all_juris[0]["iso2"]
                            winning_evidence = all_juris[0]["evidence"]
                            try:
                                from . import registry_adapters as _ra
                                for _candidate in all_juris[:4]:  # cap at top-4 jurisdictions
                                    _cand_iso2 = _candidate["iso2"]
                                    try:
                                        ra_result = await _ra.lookup_entity(
                                            name=name,
                                            jurisdiction_iso2=_cand_iso2,
                                            registration_number=None,
                                        )
                                    except Exception as _ra_inner:
                                        adapter_attempts.append({
                                            "iso2": _cand_iso2,
                                            "status": "errored",
                                            "reason": str(_ra_inner)[:120],
                                        })
                                        continue
                                    found = bool(
                                        ra_result and (
                                            ra_result.get("profile")
                                            or ra_result.get("found")
                                        )
                                    )
                                    adapter_attempts.append({
                                        "iso2": _cand_iso2,
                                        "status": "found" if found else "no_match",
                                    })
                                    if found:
                                        _ra_profile = ra_result.get("profile") or {}
                                        # First adapter to return data WINS
                                        # — it gets to set jurisdiction.
                                        winning_iso2 = _cand_iso2
                                        winning_evidence = _candidate["evidence"]
                                        if not report.identity.directors:
                                            report.identity.directors = (
                                                ra_result.get("officers") or []
                                            )
                                        if not report.identity.registration_number:
                                            report.identity.registration_number = (
                                                _ra_profile.get("company_number")
                                                or ra_result.get("registration_number")
                                            )
                                        if not report.identity.incorporation_date:
                                            report.identity.incorporation_date = (
                                                _ra_profile.get("date_of_creation")
                                                or ra_result.get("incorporation_date")
                                            )
                                        if not report.identity.registered_address:
                                            report.identity.registered_address = (
                                                _ra_profile.get("registered_office_address")
                                                or report.identity.registered_address
                                            )
                                        break
                            except Exception as _ra_e:
                                logger.debug(
                                    "R-F301 multi-juris registry backfill failed: %s",
                                    _ra_e,
                                )

                        if winning_iso2:
                            report.identity.jurisdiction_iso2 = winning_iso2
                            if not report.identity.jurisdiction:
                                report.identity.jurisdiction = (
                                    _ISO2_TO_COUNTRY_HINT.get(winning_iso2, winning_iso2)
                                )
                            _all_iso2s = ", ".join(
                                f"{j['iso2']}({j['score']})" for j in all_juris[:6]
                            )
                            _attempt_summary = ", ".join(
                                f"{a['iso2']}={a['status']}" for a in adapter_attempts
                            )
                            report.identity.findings.append(Finding(
                                severity="info",
                                title=(
                                    f"R-F301: multi-jurisdiction backfill — "
                                    f"all detected: {_all_iso2s}; winning: "
                                    f"{winning_iso2} "
                                    f"({_ISO2_TO_COUNTRY_HINT.get(winning_iso2, '?')})"
                                ),
                                detail=(
                                    f"Evidence: {winning_evidence[:200]}. "
                                    f"Adapter attempts: "
                                    f"{_attempt_summary or 'none'}"
                                ),
                                source="dd_orchestrator.jurisdiction_backfill",
                                confidence="ASSESSED",
                            ))
                            logger.info(
                                "R-F301: multi-juris backfill: candidates=[%s] "
                                "winner=%s (%s); adapter_attempts=[%s]",
                                _all_iso2s,
                                winning_iso2,
                                _ISO2_TO_COUNTRY_HINT.get(winning_iso2, "?"),
                                _attempt_summary or "none",
                            )

                            # R-F312 (2026-05-11): when the identity layer
                            # ran with jurisdiction=None and the sanctions
                            # screen got rejected because `modirumgespi.com`
                            # looked like a hostname (R-F311), we never got
                            # a real screen. Now that R-F301 has resolved
                            # the entity, re-fire the sanctions screen with
                            # the brandified name + UK Ltd alias (if we
                            # also did R-F295 UK backfill on the same run).
                            # This closes the "CLEAN ✅ but hollow" hole the
                            # operator saw on the 21:11 modirumgespi run.
                            try:
                                _brand_name = _brandify_name_for_search(
                                    name, target,
                                )
                                if _brand_name and _brand_name != name:
                                    from . import sanctions as _sanc2
                                    _refire = await _sanc2.screen_with_aliases(
                                        _brand_name,
                                        known_aliases=[name] if name else None,
                                    )
                                    if (_refire and not _refire.get("error")
                                            and _refire.get("matches")):
                                        # Promote findings into identity
                                        from ._sanctions_classify import (
                                            classify_matches as _cm_re,
                                            SEVERITY_RANK as _sr_re,
                                        )
                                        _classified_re = _cm_re(
                                            _refire["matches"],
                                            query_name=_brand_name,
                                        )
                                        _worst_re = _classified_re["worst_severity"]
                                        if _sr_re.get(_worst_re, 0) >= _sr_re.get("amber", 1):
                                            report.identity.findings.append(Finding(
                                                severity=_worst_re,
                                                title=(
                                                    f"R-F312: re-fired sanctions screen "
                                                    f"on brandified name '{_brand_name}' "
                                                    f"after R-F301 backfill — {_worst_re}"
                                                ),
                                                detail=_classified_re["summary"][:400],
                                                source="sanctions.r_f312_refire",
                                                confidence="PROBABLE",
                                            ))
                                            logger.info(
                                                "R-F312: brandified sanctions re-fire "
                                                "surfaced %s match on %r",
                                                _worst_re, _brand_name,
                                            )
                                        else:
                                            report.identity.findings.append(Finding(
                                                severity="info",
                                                title=(
                                                    f"R-F312: re-fired sanctions screen "
                                                    f"on brandified '{_brand_name}' — CLEAN"
                                                ),
                                                detail=(
                                                    f"Original identity-layer screen was "
                                                    f"rejected as 'not entity-shaped' "
                                                    f"because the hostname was passed raw "
                                                    f"(R-F311). After brandify the screen "
                                                    f"ran and returned no risk matches."
                                                ),
                                                source="sanctions.r_f312_refire",
                                                confidence="CONFIRMED",
                                            ))
                                    elif _refire and not _refire.get("error"):
                                        # Clean — emit honest "screen ran"
                                        # finding so chat output stops saying
                                        # "CLEAN ✅" without explanation.
                                        report.identity.findings.append(Finding(
                                            severity="info",
                                            title=(
                                                f"R-F312: re-fired sanctions screen "
                                                f"on brandified '{_brand_name}' — CLEAN"
                                            ),
                                            detail=(
                                                f"Original identity-layer screen was "
                                                f"rejected because the hostname was "
                                                f"passed raw (R-F311 entity-shape gate). "
                                                f"Brandified name screened CLEAN."
                                            ),
                                            source="sanctions.r_f312_refire",
                                            confidence="CONFIRMED",
                                        ))
                            except Exception as _refire_e:
                                logger.debug(
                                    "R-F312 sanctions re-fire failed: %s", _refire_e,
                                )
                except Exception as _jur_e:
                    logger.debug("R-F301 jurisdiction backfill skipped: %s", _jur_e)

                # R-F295: post-link-tree UK detection + CH backfill.
                # The live modirumgespi.com DD (2026-05-11) missed the UK
                # subsidiary `Modirum Defence Consultancy Ltd` because the
                # identity layer's jurisdiction inference fires BEFORE the
                # link-tree runs, so the UK signals on the company page are
                # never seen by the CH gate. Scan fused facts + page titles
                # now; if we find a UK Ltd/plc/LLP suffix paired with a UK
                # address signal AND the identity layer didn't already run
                # CH, fire a deferred CH lookup using the discovered name.
                try:
                    uk_name, uk_evidence = _detect_uk_entity_in_link_tree(tree)
                    if uk_name and not report.identity.registration_number:
                        from . import companies_house as _ch
                        ch_result = await _ch.investigate_uk_entity(
                            company_name=uk_name,
                        )
                        report.digital.meta.subcalls += 1
                        if isinstance(ch_result, dict) and ch_result.get("profile"):
                            profile = ch_result.get("profile") or {}
                            report.identity.registration_number = (
                                profile.get("company_number")
                                or report.identity.registration_number
                            )
                            report.identity.registration_status = (
                                profile.get("company_status")
                                or report.identity.registration_status
                            )
                            report.identity.incorporation_date = (
                                profile.get("date_of_creation")
                                or report.identity.incorporation_date
                            )
                            _addr = profile.get("registered_office_address")
                            if isinstance(_addr, dict):
                                report.identity.registered_address = (
                                    _addr.get("address_snippet")
                                    or report.identity.registered_address
                                )
                            elif _addr and not report.identity.registered_address:
                                report.identity.registered_address = _addr
                            if not report.identity.directors:
                                _o5251 = ch_result.get("officers")  # R-F2511 {current,past,total} dict
                                report.identity.directors = (_o5251.get("current") if isinstance(_o5251, dict) else _o5251) or []
                            if not report.identity.shareholders:
                                _p5253 = ch_result.get("psc")
                                report.identity.shareholders = (_p5253.get("current") if isinstance(_p5253, dict) else _p5253) or []
                            if not report.identity.jurisdiction_iso2:
                                report.identity.jurisdiction_iso2 = "GB"
                                report.identity.jurisdiction = (
                                    report.identity.jurisdiction or "United Kingdom"
                                )
                            report.identity.findings.append(Finding(
                                severity="info",
                                title=(
                                    f"R-F295: UK entity '{uk_name}' identified via "
                                    f"link-tree backfill — CH={profile.get('company_number')}"
                                ),
                                detail=(
                                    f"Evidence: {uk_evidence[:180]}. "
                                    f"Companies House profile loaded post-digital-layer "
                                    f"because identity layer ran before web content was fetched."
                                ),
                                source="dd_orchestrator.uk_backfill",
                                confidence="PROBABLE",
                            ))
                            logger.info(
                                "R-F295: UK entity backfilled via link-tree: %s → CH=%s",
                                uk_name, profile.get("company_number"),
                            )
                except Exception as _ukfb_e:
                    logger.debug("R-F295 UK backfill skipped: %s", _ukfb_e)

                # ── R-F436 (2026-05-13) — page entity extraction → sanctions ──
                # Pre-R-F436 the rule extractor produced 0 person_name facts
                # from prose-heavy pages, so directors / chairmen / contacts
                # mentioned on the crawled site never re-fed sanctions
                # screening. The rule patterns now emit `person_name` facts
                # (title-prefix, role-suffix, role-prefix). Here we harvest
                # them, dedupe across pages, cap at 8, and per-name screen
                # against OpenSanctions with the entity name passed as
                # legal-name corroboration (R-F434 cap therefore does NOT
                # fire because the screen IS corroborated by the verified
                # entity context).
                try:
                    # R-F449 (2026-05-13) — kill-switch for consistency
                    # with the rest of the Digital chain. Operator can
                    # skip the page-entity sanctions screen if upstream
                    # rate-limited.
                    if os.getenv("ARIA_PAGE_ENTITY_SCREEN_DISABLED", "").strip():
                        # Re-use the existing R-F436 try/except so the
                        # `raise` is caught + debug-logged consistently
                        # with every other R-block kill-switch path.
                        raise RuntimeError(
                            "R-F449: page entity screen disabled via env"
                        )
                    _names_seen: set[str] = set()
                    _candidate_persons: list[str] = []
                    for ff in (tree.fused_facts or []):
                        if ff.kind != "person_name":
                            continue
                        _v = (ff.value or "").strip()
                        _vn = _v.lower()
                        if not _v or _vn in _names_seen:
                            continue
                        # Also skip if it matches the entity name itself
                        if name and _vn == (name or "").lower():
                            continue
                        # R-F3126 (D1) — a scraped job-title fragment is not a
                        # person. 'Senior Vice' reached a sanctions screen and a RED
                        # finding on the live QinetiQ DD; require two distinctive,
                        # non-role tokens before anyone can be accused.
                        if not _is_screenable_person_name(_v):
                            logger.debug(
                                "[R-F3126] not a screenable person name, skipped: %r",
                                _v[:60])
                            continue
                        _names_seen.add(_vn)
                        _candidate_persons.append(_v)
                        if len(_candidate_persons) >= 8:
                            break
                    if _candidate_persons:
                        from . import sanctions as _sanc_p
                        from ._sanctions_classify import (
                            classify_matches as _cm_p,
                            SEVERITY_RANK as _sr_p,
                        )
                        _extracted_persons_screened: list[dict] = []
                        for _person in _candidate_persons:
                            try:
                                _scr = await _sanc_p.screen_with_aliases(
                                    _person,
                                    # Passing the entity name as a known
                                    # alias sets _has_caller_supplied_aliases
                                    # to True (R-F444 renamed flag). This is
                                    # honest corroboration because the person
                                    # was named ON the entity's own website
                                    # — same context.
                                    known_aliases=[name] if name else None,
                                )
                            except Exception as _spe:
                                # R-F1348: a screen that THREW must be VISIBLE in
                                # the report — never silently dropped (a false
                                # negative the operator can't see is the worst
                                # failure mode for a compliance product).
                                logger.warning(
                                    "R-F436 person screen %r failed: %s",
                                    _person[:40], _spe,
                                )
                                _note_dd_screen_gap(report, _person, _spe)
                                continue
                            _matches = (_scr or {}).get("matches") or []
                            # R-F3126 (D2) — DROP name-coincidence matches before
                            # they can be classified. The same guard R-F2994 applies
                            # to company matches and R-F3089 to adverse media; person
                            # screening was the one path without it, which is how a
                            # California medical-exclusions entry became a RED on a
                            # UK defence group. Counted, never silently discarded.
                            _coincident = [
                                _m for _m in _matches
                                if _person_match_is_coincidence(
                                    _person, str((_m or {}).get("name") or ""))
                            ]
                            if _coincident:
                                _drop_ids = {id(_m) for _m in _coincident}
                                _matches = [_m for _m in _matches
                                            if id(_m) not in _drop_ids]
                                logger.info(
                                    "[R-F3126] dropped %d name-coincidence match(es) "
                                    "for site-extracted person %r",
                                    len(_coincident), _person[:40])
                            if not _matches:
                                _extracted_persons_screened.append({
                                    "person": _person,
                                    "severity": "info",
                                    "matched": False,
                                })
                                continue
                            _classified = _cm_p(_matches, query_name=_person)
                            _worst = _classified.get("worst_severity") or "info"
                            _extracted_persons_screened.append({
                                "person": _person,
                                "severity": _worst,
                                "matched": True,
                                "summary": _classified.get("summary", "")[:240],
                            })
                            # ── R-F3130 — A HOMONYM IS NOT AN IDENTIFICATION ────
                            #
                            # LIVE on the Babcock DD (dd_8c7242c2b45b, 2026-07-26):
                            #     RED  Site-extracted person Kevin Smith → sanctions red
                            #     KEVIN SMITH (score 1.00, topics: debarment,
                            #     lists: us_hhs_exclusions,us_sam_exclusions,
                            #     matched_via=primary_name)
                            # and that finding drove the whole ENTITY to RED — "very
                            # likely unsuitable for onboarding" — on a FTSE-250
                            # defence group whose sanctions screen, adverse media and
                            # ownership were all ANSWERED and clean.
                            #
                            # "Kevin Smith" clears the R-F3126 gates: it IS a real
                            # name shape and it DOES share distinctive tokens with the
                            # listed entry. Those gates were never the problem here.
                            # The problem is that a bare COMMON name screened against
                            # a debarment list will always hit, and `score 1.00` means
                            # the STRING matched — not that it is the same human.
                            # `matched_via=primary_name` says so explicitly: no DOB,
                            # no nationality, no passport, no address corroborated it.
                            #
                            # A person scraped off a website and matched by NAME ALONE
                            # is not evidence about the COUNTERPARTY. It is a lead
                            # requiring identity verification. So it is still SURFACED
                            # (going silent would be the R-F1696 defect in reverse),
                            # but capped at INFO and framed as an unconfirmed homonym,
                            # and it can no longer drag the entity verdict. This is the
                            # R-F2828 principle — resolve by identifier, never by name
                            # — applied to people instead of companies.
                            #
                            # A match carrying a REAL secondary identifier keeps its
                            # severity: that is an identification, not a coincidence.
                            _identified = any(
                                str((_m or {}).get("match_field") or "").strip().lower()
                                not in ("", "primary_name", "alias", "weak_match", "name")
                                for _m in _matches if isinstance(_m, dict)
                            )
                            _eff_worst = _worst if _identified else "info"
                            if _sr_p.get(_eff_worst, 0) >= _sr_p["amber"] or not _identified:
                                _ftitle = (
                                    f"Site-extracted person {_person} → "
                                    f"sanctions {_worst}"
                                    if _identified else
                                    f"Site-extracted person {_person} — possible "
                                    f"NAME MATCH on a watchlist (identity NOT confirmed)"
                                )
                                _fconf = {
                                    "hard_stop": "CONFIRMED",
                                    "red": "PROBABLE",
                                    "amber": "ASSESSED",
                                }.get(_worst, "ASSESSED") if _identified else "UNVERIFIED"
                                report.digital.findings.append(Finding(
                                    severity=_eff_worst,
                                    title=_ftitle,
                                    detail=(
                                        f"Name '{_person}' was extracted "
                                        f"from {name}'s own site (link-tree "
                                        f"{tree.tree_id}) and screened "
                                        f"against OpenSanctions with the "
                                        f"entity as legal-name "
                                        f"corroboration. "
                                        f"{_classified.get('summary', '')[:280]}"
                                        + ("" if _identified else
                                           " ⚠ MATCHED ON NAME ALONE — no date of "
                                           "birth, nationality or document number "
                                           "corroborated it, and a common name will "
                                           "match a watchlist by coincidence. This is "
                                           "a LEAD to verify, NOT a finding against "
                                           "this counterparty, and it does not affect "
                                           "the risk classification. Confirm the "
                                           "individual's identity against the cited "
                                           "record before acting on it.")
                                    ),
                                    source=(
                                        f"page_entity_extractor + "
                                        f"sanctions.screen_with_aliases "
                                        f"[{tree.tree_id}]"
                                    ),
                                    confidence=_fconf,
                                ))
                        # Persist the per-person screen result on the
                        # web_footprint dict so renderers + audit can
                        # cite which names were actually screened.
                        report.digital.web_footprint["extracted_persons"] = (
                            _extracted_persons_screened
                        )
                        report.digital.meta.subcalls += len(_candidate_persons)
                        logger.info(
                            "R-F436: link-tree extracted %d persons, "
                            "screened against sanctions, %d non-info hits",
                            len(_candidate_persons),
                            sum(
                                1 for p in _extracted_persons_screened
                                if p.get("severity") not in ("info", None)
                            ),
                        )
                except Exception as _r436_e:
                    logger.warning(
                        "R-F436 page-entity screen skipped: %s", _r436_e,
                    )
                    _note_dd_screen_gap(report, "page-entity screening block", _r436_e)

                # ── R-F437 (2026-05-13) — Wayback historical pivot ────────
                # Live-only crawl misses the case where a now-clean entity
                # was a sanctioned shell five years ago, or where a director
                # resigned to cover an embarrassing affiliation. We fetch
                # snapshots of the seed URL at ~1y and ~3y back, run the
                # SAME person-name extractor, and surface persons who
                # appeared historically but are absent from the current
                # site. Each new historical person is sanctions-screened
                # with entity-name corroboration. Opt-out via
                # ARIA_WAYBACK_PIVOT_DISABLED=1.
                if not os.getenv("ARIA_WAYBACK_PIVOT_DISABLED", "").strip():
                    try:
                        from .crawl_enhancements import (
                            fetch_historical_snapshots as _fhs,
                        )
                        from .link_investigator import (
                            _extract_facts_rules as _efr,
                        )
                        _current_persons_lc: set[str] = {
                            (ff.value or "").lower()
                            for ff in (tree.fused_facts or [])
                            if ff.kind == "person_name" and ff.value
                        }
                        _snaps = await _fhs(seed_url)
                        # R-F449 — count wayback HTTP fetches that
                        # actually returned content. Pre-R-F449 only
                        # the per-person sanctions screens were counted
                        # so cost dashboards under-reported the chain.
                        report.digital.meta.subcalls += sum(
                            1 for s in _snaps if s.get("ok")
                        )
                        _historical_persons: list[dict] = []
                        for _snap in _snaps:
                            if not _snap.get("ok") or not _snap.get("html"):
                                continue
                            # Strip HTML naively — link_investigator's
                            # extractor expects plain text. The rule patterns
                            # are robust enough for HTML noise; we just
                            # remove tags to reduce false positives in
                            # attribute strings.
                            _html = _snap["html"]
                            _text = re.sub(r"<[^>]+>", " ", _html)
                            _text = re.sub(r"\s+", " ", _text)
                            _hist_facts = _efr(_text[:60000], _snap.get("snapshot_url") or seed_url)
                            for ff in _hist_facts:
                                if ff.kind != "person_name":
                                    continue
                                _v = (ff.value or "").strip()
                                if not _v:
                                    continue
                                _vn = _v.lower()
                                if _vn in _current_persons_lc:
                                    continue  # also on live site → R-F436 covered it
                                if name and _vn == (name or "").lower():
                                    continue
                                if _vn in {p["person"].lower() for p in _historical_persons}:
                                    continue  # dedupe across snapshots
                                _historical_persons.append({
                                    "person": _v,
                                    "snapshot_url": _snap.get("snapshot_url", ""),
                                    "snapshot_timestamp": _snap.get(
                                        "snapshot_timestamp", "",
                                    ),
                                    "years_back": _snap.get("years_back"),
                                })
                                if len(_historical_persons) >= 8:
                                    break
                            if len(_historical_persons) >= 8:
                                break
                        if _historical_persons:
                            from . import sanctions as _sanc_h
                            from ._sanctions_classify import (
                                classify_matches as _cm_h,
                                SEVERITY_RANK as _sr_h,
                            )
                            _hist_screened: list[dict] = []
                            for _hp in _historical_persons:
                                try:
                                    _scr = await _sanc_h.screen_with_aliases(
                                        _hp["person"],
                                        known_aliases=[name] if name else None,
                                    )
                                except Exception as _hspe:
                                    logger.warning(
                                        "R-F437 historical person screen %r failed: %s",
                                        _hp["person"][:40], _hspe,
                                    )
                                    _note_dd_screen_gap(report, _hp.get("person", "historical person"), _hspe)
                                    continue
                                _hmatches = (_scr or {}).get("matches") or []
                                _hclassified = _cm_h(_hmatches, query_name=_hp["person"]) if _hmatches else {"worst_severity": "info", "summary": ""}
                                _hworst = _hclassified.get("worst_severity") or "info"
                                _hist_screened.append({
                                    **_hp,
                                    "severity": _hworst,
                                    "summary": _hclassified.get("summary", "")[:240],
                                })
                                if _sr_h.get(_hworst, 0) >= _sr_h["amber"]:
                                    _hconf = {
                                        "hard_stop": "CONFIRMED",
                                        "red": "PROBABLE",
                                        "amber": "ASSESSED",
                                    }.get(_hworst, "ASSESSED")
                                    report.digital.findings.append(Finding(
                                        severity=_hworst,
                                        title=(
                                            f"Historical (~{_hp.get('years_back')}y) "
                                            f"site person {_hp['person']} → "
                                            f"sanctions {_hworst}"
                                        ),
                                        detail=(
                                            f"Name '{_hp['person']}' appears on the "
                                            f"Wayback snapshot of {seed_url} dated "
                                            f"{_hp.get('snapshot_timestamp', 'unknown')} "
                                            f"but NOT on the current live site. "
                                            f"Sanctions screen post-corroboration: "
                                            f"{_hclassified.get('summary', '')[:280]}"
                                        ),
                                        source=(
                                            f"wayback {_hp.get('snapshot_url', '')}"
                                        ),
                                        confidence=_hconf,
                                    ))
                            report.digital.web_footprint["historical_persons"] = (
                                _hist_screened
                            )
                            report.digital.meta.subcalls += len(_historical_persons)
                            logger.info(
                                "R-F437: wayback pivot found %d historical-only "
                                "persons (snapshots: %d), %d non-info hits",
                                len(_historical_persons),
                                sum(1 for s in _snaps if s.get("ok")),
                                sum(
                                    1 for h in _hist_screened
                                    if h.get("severity") not in ("info", None)
                                ),
                            )
                        else:
                            # Record the attempt + snapshot coverage even
                            # when no new persons surfaced — operator can
                            # see the wayback pivot ran.
                            report.digital.web_footprint["historical_persons"] = []
                            report.digital.web_footprint["wayback_snapshots"] = [
                                {
                                    "years_back": s.get("years_back"),
                                    "ok": s.get("ok"),
                                    "snapshot_timestamp": s.get("snapshot_timestamp", ""),
                                    "error": (s.get("error") or "")[:120],
                                }
                                for s in _snaps
                            ]
                    except Exception as _r437_e:
                        logger.warning(
                            "R-F437 wayback pivot skipped: %s", _r437_e,
                        )
                        _note_dd_screen_gap(report, "historical (wayback) screening block", _r437_e)

                # ── R-F438 (2026-05-13) — Certificate Transparency pivot ──
                # Operators commonly bundle several brand domains onto a
                # single TLS cert, which makes the CT log a free reverse-
                # WHOIS proxy. A sanctioned operator who rebrands behind
                # `freshcorp.com` typically still shares a cert with the
                # embarrassing `oldshell.com` for weeks. We query crt.sh
                # (community-run, no key), extract sibling hostnames from
                # SAN lists, exclude CDN/PaaS infra, and surface the top
                # related domains. Cost: 1 HTTP call per DD.
                # Opt-out via ARIA_CT_PIVOT_DISABLED=1.
                if not os.getenv("ARIA_CT_PIVOT_DISABLED", "").strip():
                    try:
                        from .domain_pivots import (
                            crtsh_lookup as _crtsh,
                            extract_related_domains as _erd,
                        )
                        # Derive apex from seed_url. NOTE: must use
                        # removeprefix("www.") not lstrip("www.") — the
                        # latter strips any of {w, .} from the left and
                        # mangles legitimate hostnames like "wedding.com"
                        # → "edding.com". Verifier caught pre-deploy.
                        from urllib.parse import urlparse as _urlparse
                        _parsed = _urlparse(seed_url)
                        _apex = (_parsed.netloc or "").lower()
                        if _apex.startswith("www."):
                            _apex = _apex[4:]
                        if _apex and "." in _apex:
                            _ct = await _crtsh(_apex)
                            if _ct.get("ok"):
                                _related = _erd(_ct.get("records") or [], _apex)
                                report.digital.web_footprint["ct_log_records"] = len(
                                    _ct.get("records") or []
                                )
                                report.digital.web_footprint["related_domains"] = (
                                    _related
                                )
                                report.digital.meta.subcalls += 1
                                # Surface a single info finding summarising
                                # the pivot — concrete data goes into the
                                # web_footprint for renderer detail.
                                if _related:
                                    _peers_str = ", ".join(
                                        r["host"] for r in _related[:6]
                                    )
                                    _suffix = (
                                        f" (+{len(_related) - 6} more)"
                                        if len(_related) > 6 else ""
                                    )
                                    report.digital.findings.append(Finding(
                                        severity="info",
                                        title=(
                                            f"CT pivot: {len(_related)} related "
                                            f"domain(s) share a TLS cert with "
                                            f"{_apex}"
                                        ),
                                        detail=(
                                            f"Sample: {_peers_str}{_suffix}. "
                                            f"Operator may want to re-DD any "
                                            f"that look ownership-related "
                                            f"(shared registrable root flagged "
                                            f"in web_footprint.related_domains)."
                                        ),
                                        source=(
                                            f"domain_pivots.crtsh_lookup "
                                            f"[crt.sh?q={_apex}]"
                                        ),
                                        confidence="ASSESSED",
                                    ))
                                logger.info(
                                    "R-F438: CT pivot on %s — %d records, "
                                    "%d related domains surfaced",
                                    _apex,
                                    len(_ct.get("records") or []),
                                    len(_related),
                                )
                            else:
                                report.digital.web_footprint["ct_log_error"] = (
                                    _ct.get("error") or "unknown"
                                )[:200]
                    except Exception as _r438_e:
                        logger.debug(
                            "R-F438 CT pivot skipped: %s", _r438_e,
                        )

                # ── R-F439 (2026-05-13) — unified procurement history ─────
                # Pre-R-F439 tender_monitor.py scanned NEW tenders per
                # portal on a schedule; the DD pipeline never asked
                # "what has this entity ever won/bid anywhere?". V1
                # backends (free, no key): USAspending (US federal
                # awards since FY2008) + UK Contracts Finder OCDS. Run
                # in parallel; treat per-backend failure as missing data
                # not "clean". Results land on the pre-existing
                # report.digital.procurement_history field plus a
                # web_footprint summary for renderers.
                # Opt-out: ARIA_PROCUREMENT_HISTORY_DISABLED=1.
                if (
                    report.identity.entity_type == EntityType.COMPANY.value
                    and not os.getenv("ARIA_PROCUREMENT_HISTORY_DISABLED", "").strip()
                ):
                    try:
                        from .procurement_history import query_entity_history
                        _ph = await query_entity_history(
                            report.identity.entity_name or name,
                            jurisdiction_iso2=report.identity.jurisdiction_iso2,
                        )
                        report.digital.procurement_history = (
                            _ph.get("consolidated") or []
                        )
                        report.digital.web_footprint["procurement_history_summary"] = {
                            "total_records": _ph.get("total_records", 0),
                            "by_buyer":      _ph.get("by_buyer", {}),
                            "backends_ok":   [
                                k for k, v in (_ph.get("backends") or {}).items()
                                if v.get("ok")
                            ],
                            "errors":        _ph.get("errors", []),
                        }
                        report.digital.meta.subcalls += 2  # 2 backends
                        # If history is found, emit an info finding so
                        # operator sees the pivot ran + headline figure.
                        _total = _ph.get("total_records", 0)
                        if _total > 0:
                            _buyers = list((_ph.get("by_buyer") or {}).keys())
                            _buyer_sample = ", ".join(_buyers[:4])
                            _suffix = (
                                f" (+{len(_buyers) - 4} more)"
                                if len(_buyers) > 4 else ""
                            )
                            report.digital.findings.append(Finding(
                                severity="info",
                                title=(
                                    f"Procurement history: {_total} award(s) "
                                    f"across "
                                    f"{len(_ph.get('backends', {}))} backends"
                                ),
                                detail=(
                                    f"Buyers: {_buyer_sample}{_suffix}. "
                                    f"Full list in "
                                    f"report.digital.procurement_history."
                                ),
                                source=(
                                    "procurement_history.query_entity_history "
                                    "[USAspending + UK Contracts Finder]"
                                ),
                                confidence="ASSESSED",
                            ))
                        else:
                            # Record the gap so operator can tell
                            # "queried, no results" from "never queried"
                            if not _ph.get("ok"):
                                report.digital.data_gaps.append(
                                    f"Procurement history backends all "
                                    f"failed: {'; '.join(_ph.get('errors', []))[:240]}"
                                )
                        logger.info(
                            "R-F439: procurement history for %s — "
                            "%d records, backends_ok=%s",
                            (report.identity.entity_name or name)[:40],
                            _total,
                            [
                                k for k, v in (_ph.get("backends") or {}).items()
                                if v.get("ok")
                            ],
                        )
                    except Exception as _r439_e:
                        logger.debug(
                            "R-F439 procurement history skipped: %s",
                            _r439_e,
                        )

                # ── R-F440 (2026-05-13) — DNS fingerprint + ASN owner ─────
                # Knowing the hosting ASN reveals shared infrastructure
                # (a "British" entity served from a sanctioned-jurisdiction
                # ASN, or two ostensibly-unrelated entities sharing an
                # obscure ASN). MX/NS records reveal mail + nameserver
                # providers that don't appear in WHOIS. Uses Cloudflare
                # DNS-over-HTTPS (no dependency) + api.iptoasn.com (free,
                # no key). Cost: ~5 HTTP requests per DD.
                # Opt-out: ARIA_DNS_FINGERPRINT_DISABLED=1.
                if not os.getenv("ARIA_DNS_FINGERPRINT_DISABLED", "").strip():
                    try:
                        from .domain_pivots import dns_fingerprint as _dnsfp
                        # Reuse the apex from R-F438; if R-F438 was skipped
                        # we derive it from seed_url.
                        from urllib.parse import urlparse as _urlparse2
                        _parsed2 = _urlparse2(seed_url)
                        _apex2 = (_parsed2.netloc or "").lower()
                        if _apex2.startswith("www."):
                            _apex2 = _apex2[4:]
                        if _apex2 and "." in _apex2:
                            _dns = await _dnsfp(_apex2)
                            if _dns.get("ok"):
                                report.digital.web_footprint["dns_fingerprint"] = {
                                    "domain":      _dns.get("domain"),
                                    "mx_count":    len(_dns.get("mx") or []),
                                    "ns_count":    len(_dns.get("ns") or []),
                                    "txt_count":   len(_dns.get("txt") or []),
                                    "primary_ip":  _dns.get("primary_ip"),
                                    "primary_asn": _dns.get("primary_asn"),
                                    "mx":          _dns.get("mx") or [],
                                    "ns":          _dns.get("ns") or [],
                                    "errors":      _dns.get("errors") or [],
                                }
                                report.digital.meta.subcalls += 5  # 4 DoH + 1 ASN
                                _asn = _dns.get("primary_asn") or {}
                                _asn_desc = _asn.get("description") or ""
                                _asn_cc = _asn.get("country") or ""
                                if _asn_desc:
                                    report.digital.findings.append(Finding(
                                        severity="info",
                                        title=(
                                            f"DNS/ASN: {_apex2} hosted on "
                                            f"AS{_asn.get('as_number')} "
                                            f"({_asn_desc[:80]}, {_asn_cc})"
                                        ),
                                        detail=(
                                            f"Primary IP {_dns.get('primary_ip')}; "
                                            f"MX records: {len(_dns.get('mx') or [])}; "
                                            f"NS records: {len(_dns.get('ns') or [])}; "
                                            f"TXT records: {len(_dns.get('txt') or [])}. "
                                            f"ASN country differing from declared "
                                            f"jurisdiction can indicate shared "
                                            f"or undisclosed hosting."
                                        ),
                                        source=(
                                            "domain_pivots.dns_fingerprint "
                                            "[Cloudflare DoH + api.iptoasn.com]"
                                        ),
                                        confidence="CONFIRMED",
                                    ))
                                # If declared jurisdiction differs from ASN
                                # country, surface as amber (worth checking).
                                _decl_iso2 = (
                                    report.identity.jurisdiction_iso2 or ""
                                ).upper()
                                if (
                                    _decl_iso2 and _asn_cc
                                    and _decl_iso2 != _asn_cc.upper()
                                    # Allow common multi-jurisdiction hosters
                                    # without crying wolf — pure heuristic.
                                    and _asn_cc.upper() not in ("US", "GB", "DE", "NL", "FR", "IE")
                                ):
                                    report.digital.findings.append(Finding(
                                        severity="amber",
                                        title=(
                                            f"ASN country {_asn_cc} differs "
                                            f"from declared jurisdiction "
                                            f"{_decl_iso2}"
                                        ),
                                        detail=(
                                            f"{_apex2} resolves to an IP in "
                                            f"AS{_asn.get('as_number')} "
                                            f"({_asn_desc[:80]}), registered "
                                            f"in {_asn_cc}. Entity declares "
                                            f"jurisdiction {_decl_iso2}. "
                                            f"Could be legitimate (CDN edge, "
                                            f"shared hoster) but worth checking "
                                            f"if combined with other red flags."
                                        ),
                                        source=(
                                            "domain_pivots.dns_fingerprint "
                                            "[ASN-vs-jurisdiction mismatch]"
                                        ),
                                        confidence="ASSESSED",
                                    ))
                                logger.info(
                                    "R-F440: DNS fingerprint %s — IP=%s "
                                    "ASN=%s (%s, %s)",
                                    _apex2,
                                    _dns.get("primary_ip"),
                                    _asn.get("as_number"),
                                    _asn_desc[:40],
                                    _asn_cc,
                                )
                            elif _dns.get("errors"):
                                report.digital.web_footprint["dns_fingerprint_error"] = (
                                    "; ".join(_dns.get("errors") or [])[:240]
                                )
                    except Exception as _r440_e:
                        logger.debug(
                            "R-F440 DNS fingerprint skipped: %s", _r440_e,
                        )

                # ── R-F441 (2026-05-13) — source-language adverse media ──
                # The 11-lang fanout (_LANG_FANOUT_TRIGGERS) detects which
                # target languages a query is relevant for but passes a
                # GENERIC search string. R-F441 builds adverse-media-
                # specific queries per language (corruption/sanctions/
                # fraud/money-laundering/bribery/embezzlement/investigation
                # in the native script) so the search probes the
                # untranslated reporting where the real evidence lives.
                # Opt-out: ARIA_ADVERSE_POLYGLOT_DISABLED=1.
                # R-F449 (2026-05-13) — empty-name guard. Pre-R-F449 an
                # entity with no resolved name would build polyglot
                # queries against an empty entity string — the OR-block
                # of bare adverse terms would dredge up unrelated
                # corruption / sanctions news and pollute
                # adverse_media_hits. Skip the block entirely instead.
                _r441_entity = (
                    report.identity.entity_name or name or ""
                ).strip()
                if (
                    not os.getenv("ARIA_ADVERSE_POLYGLOT_DISABLED", "").strip()
                    and _r441_entity
                ):
                    try:
                        from .adverse_media_polyglot import (
                            build_queries_for_languages as _bqfl,
                        )
                        from .web_explorer import (
                            detect_language_fanout as _dlf,
                        )
                        # Compose a "language hint" from entity name +
                        # declared country so the fanout fires per
                        # country/region. We don't run the actual
                        # cross-language search here (would add 10s+)
                        # — instead we surface the QUERIES on the
                        # web_footprint so the operator + downstream
                        # researchers know what to probe + dashboards
                        # can render the polyglot reach. The autonomous
                        # researcher already runs polyglot queries
                        # asynchronously via search_multilingual; this
                        # block exposes the per-DD adverse-media plan.
                        _lang_hint = (
                            f"{_r441_entity} "
                            f"{report.identity.jurisdiction or ''}"
                        ).strip()
                        _langs_detected = _dlf(_lang_hint)
                        # Always probe English baseline + auto-detected langs
                        _langs_to_query = ["en"] + [
                            l for l in _langs_detected if l != "en"
                        ]
                        _queries = _bqfl(_r441_entity, _langs_to_query)
                        if _queries:
                            report.digital.web_footprint["adverse_media_queries"] = [
                                {"lang": l, "query": q}
                                for l, q in _queries
                            ]
                            logger.info(
                                "R-F441: polyglot adverse-media — %d queries "
                                "across langs %s",
                                len(_queries),
                                [l for l, _ in _queries],
                            )

                            # ── R-F445 (2026-05-13) — execute the polyglot queries ──
                            # Pre-R-F445 R-F441 only SURFACED the queries on
                            # web_footprint with no executor — operator-visibility
                            # only, no actual search recall improvement.
                            # R-F445 wires them through search_multilingual so
                            # the adverse-media probes actually run. Cap at top 4
                            # languages and 5 results per language to bound cost.
                            # Opt-out via ARIA_ADVERSE_POLYGLOT_EXECUTE_DISABLED=1.
                            _adverse_hits: list[dict] = []
                            if not os.getenv(
                                "ARIA_ADVERSE_POLYGLOT_EXECUTE_DISABLED",
                                "",
                            ).strip():
                                try:
                                    from . import web_search as _ws
                                    import asyncio as _aio_p

                                    async def _run_one(lang, q):
                                        try:
                                            return lang, await _ws.search_multilingual(
                                                q,
                                                languages=[lang],
                                                max_results=5,
                                                translate_query=False,
                                            )
                                        except Exception as _wse:
                                            logger.debug(
                                                "R-F445 search_multilingual %r/%r failed: %s",
                                                lang, q[:40], _wse,
                                            )
                                            return lang, []

                                    _capped = _queries[:4]
                                    _results = await _aio_p.gather(
                                        *(_run_one(l, q) for l, q in _capped),
                                        return_exceptions=False,
                                    )
                                    for _lang, _res_list in _results:
                                        for _r in (_res_list or [])[:5]:
                                            _adverse_hits.append({
                                                "lang":    _lang,
                                                "title":   getattr(_r, "title", "")[:240],
                                                "url":     getattr(_r, "url", "")[:500],
                                                "snippet": (
                                                    getattr(_r, "snippet", "")
                                                    or getattr(_r, "summary", "")
                                                    or ""
                                                )[:400],
                                            })
                                    report.digital.web_footprint["adverse_media_hits"] = (
                                        _adverse_hits
                                    )
                                    report.digital.meta.subcalls += len(_capped)
                                    logger.info(
                                        "R-F445: polyglot adverse-media executed — "
                                        "%d langs probed, %d hits aggregated",
                                        len(_capped),
                                        len(_adverse_hits),
                                    )
                                except Exception as _r445_e:
                                    logger.debug(
                                        "R-F445 polyglot execute skipped: %s",
                                        _r445_e,
                                    )

                            _detail = (
                                f"Per-language adverse-term probes from "
                                f"source-language dictionaries (corruption / "
                                f"sanctions / fraud / money-laundering / "
                                f"bribery / etc). {len(_queries)} queries "
                                f"prepared; R-F445 executed top {min(4, len(_queries))} "
                                f"and aggregated "
                                f"{len(_adverse_hits)} hit(s) into "
                                f"web_footprint.adverse_media_hits."
                            )
                            report.digital.findings.append(Finding(
                                severity="info",
                                title=(
                                    f"Polyglot adverse-media: "
                                    f"{len(_queries)} language(s) — "
                                    f"{', '.join(l for l, _ in _queries)} "
                                    f"({len(_adverse_hits)} hit(s))"
                                ),
                                detail=_detail,
                                source=(
                                    "adverse_media_polyglot + "
                                    "web_search.search_multilingual"
                                ),
                                confidence="ASSESSED",
                            ))
                    except Exception as _r441_e:
                        logger.debug(
                            "R-F441 polyglot adverse media skipped: %s",
                            _r441_e,
                        )
            except Exception as e:
                logger.warning("Digital: link_investigator failed: %s", e)
                report.digital.data_gaps.append(f"link_investigator failed: {str(e)[:120]}")

    report.digital.meta.duration_ms = int((time.time() - t0) * 1000)
    # R-F3502 — do NOT overwrite a status the layer already earned. This assigned OK
    # unconditionally, so every degraded signal recorded earlier in the layer (a bounded
    # deep-research sweep, a skipped sub-stage) was erased at the last line and the
    # section rendered COMPLETED. Only promote to OK from an unset/OK state.
    if str(report.digital.meta.status or "") in ("", LayerStatus.OK.value):
        report.digital.meta.status = LayerStatus.OK.value


# R-F2662 — ARIA's OWN compute / memory / RAG. NEVER an independent external witness;
# counting it (as grounded_rate does) over-states corroboration. Pass-2 caught that the
# analysis engines (ghost_scorer / network_walker / tech_classifier) are ARIA's own
# compute, NOT external sources — they belong here.
_INTERNAL_VERIFY_SOURCES = frozenset({
    "aria_knowledge", "neural_memory", "memory", "rag", "internal",
    "ghost_scorer", "network_walker", "tech_classifier", "risk_indices", "press",
})

# Named DISTINCT external authorities — each is a genuinely independent origin (a
# different registry / a specific sanctions list / a specific country-risk index). Two
# of these corroborate a claim independently. Anything NOT here (press publisher strings,
# unclassified labels) collapses to a single 'external_unclassified' group, so ambiguous
# / same-family / wire-syndicated sources can NEVER OVER-count as independent — moat-safe
# (undercounts press until a v2 does real domain/family-modelling via verified_intel).
_KNOWN_INDEPENDENT_AUTHORITIES = frozenset({
    "companies_house", "sec_edgar", "gleif", "opencorporates",
    "transparency_intl_cpi", "basel_aml_index", "fatf", "worldbank_wgi", "oecd_crc",
})


def _claim_independence_group(source: str) -> str:
    """R-F2662 — map a triangulation source label to its INDEPENDENCE ORIGIN, CONSERVATIVELY.

    - ARIA's own compute / memory / RAG → 'internal' (never independent).
    - a NAMED distinct external authority (registry / a specific sanctions list / a
      specific country-risk index) → its own origin.
    - anything else (press publisher labels, unclassified) → one 'external_unclassified'
      group, so we NEVER over-claim independence we cannot verify from a bare label.
    Deliberately conservative: it undercounts rather than risk a false corroboration.
    """
    s = (source or "").strip().lower()
    if (s in _INTERNAL_VERIFY_SOURCES
            or s.startswith(("rag:", "neural", "aria_", "ghost", "network_", "tech_classifier"))):
        return "internal"
    if s.startswith("sanctions:") or s in _KNOWN_INDEPENDENT_AUTHORITIES:
        return s  # a specific, named, independent external authority
    return "external_unclassified"


def _independent_corroboration(triangulated: list[dict]) -> tuple[int, "float | None"]:
    """R-F2662 — count claims backed by >=2 DISTINCT EXTERNAL origins (internal echo
    excluded). Returns (independently_corroborated_count, rate). Also stamps each claim
    with independent_source_count so the report can show WHICH claims are corroborated.
    Pure/synchronous; a step toward — NOT — full independent re-verification (R-F2413)."""
    if not triangulated:
        return 0, None
    _ok = 0
    for t in triangulated:
        _groups = {_claim_independence_group(s) for s in (t.get("sources") or [])}
        _groups.discard("internal")
        t["independent_source_count"] = len(_groups)
        if len(_groups) >= 2:
            _ok += 1
    return _ok, round(_ok / len(triangulated), 2)


async def _run_verification(target: dict, report: ARKDDReport) -> None:
    """Layer 3 — Source triangulation + conflict detection (NOT
    independent source verification).

    R-F393 (2026-05-13): the legacy "verification" name was a Phase A
    honesty bug — ARIA self-reported the layer as "wired-but-silent"
    after a Lukoil DD returned 0% grounded. The honest description is
    what this function actually does:

      (a) Count how many independent sources back each claim that
          Layers 1/2/4/5 already collected — `triangulated_claims`.
      (b) Compute `grounded_rate` = fraction of claims with >= 2
          sources (NOT a URL-verification rate).
      (c) Detect conflicts between sections (e.g. ghost=GREEN while
          country=HARD_STOP).
      (d) Pick the weakest confidence tag across all sections.

    What this function does NOT do (operator-visible via the new
    scope-flag fields on VerificationSection):

      *  Independent claim re-check: it does NOT re-fetch external
         sources to re-confirm each claim's truth. `source_verifier` IS
         invoked (R-F2282) but only for citation grounding — checking
         that URLs the report CITES were actually fetched into the
         evidence set, not re-verifying the claims themselves. So
         `independent_source_verification_run` stays False to surface
         this honestly; citation grounding is reported separately via
         `citation_grounding_rate`.
    """
    t0 = time.time()
    report.verification.meta.started_at = datetime.now(timezone.utc).isoformat()
    # R-F393: pin the honest scope on the section the moment the
    # function fires, so a mid-flight crash still leaves the truth
    # visible to downstream consumers.
    # R-F2282: safe default — set True only if source_verifier actually runs below.
    report.verification.independent_source_verification_run = False
    report.verification.scope_note = (
        "Layer 3 = source triangulation + conflict detection over Layers 1/2/4/5 "
        "outputs (scope finalised after source_verifier runs)."
    )

    # Count sources per material claim. A "claim" here is a distinct
    # piece of evidence/finding from any section. The verifier counts
    # how many independent sources back each.
    sources_for_claim: dict[str, set[str]] = {}
    def _add(claim: str, src: str):
        sources_for_claim.setdefault(claim, set()).add(src)

    # Identity claims
    # R-F2282: count the REAL distinct sources that back the sanctions claim.
    # A screen queries MANY independent lists (OFAC SDN, UK OFSI, EU Consolidated,
    # UN 1267, ICC, Interpol, OpenSanctions PEP …); the old code hard-coded ONE
    # label ("sanctions"), so this claim could NEVER reach source_count>=2 —
    # structurally capping grounded_rate regardless of how many lists corroborated.
    _ss = report.identity.sanctions_screen or {}
    if _ss:
        # R-F2411: the live pipeline sets sanctions_screen as a dict (see
        # _screen_identity), but guard the shape so a legacy/list-shaped screen
        # can never crash the grounded-rate honesty metric for the whole report.
        # R-F2590 — guard the INNER shape too (R-F2411 only checked the outer _ss). A
        # non-dict verified_sources (e.g. a legacy/corrupted list) must never reach
        # `.items()` below and crash the whole report; fall through to the else-branch.
        _vsrc_raw = _ss.get("verified_sources") if isinstance(_ss, dict) else None
        _vsrc = _vsrc_raw if isinstance(_vsrc_raw, dict) else {}
        # count only lists actually QUERIED (CLEAN/HIT), never UNAVAILABLE ones.
        _checked_lists = [
            k for k, v in _vsrc.items()
            if isinstance(v, dict) and str(v.get("status", "")).upper() in ("CLEAN", "HIT")
        ]
        if _checked_lists:
            for _lst in _checked_lists:
                _add("identity:sanctions_checked", f"sanctions:{_lst}")
        else:
            _add("identity:sanctions_checked", "sanctions")
    if report.identity.directors:
        _add("identity:directors_known", "companies_house")
    if report.identity.ghost_score:
        _add("identity:ghost_scored", "ghost_scorer")
    # Network claims
    if report.network.director_graph.get("nodes"):
        _add("network:graph_built", "network_walker")
    if report.network.pep_connections:
        _add("network:pep_checked", "sanctions")
    # Compliance
    # R-F2282: country risk is corroborated by MULTIPLE independent indices
    # (Transparency Intl CPI, Basel AML Index, FATF, World Bank WGI, OECD CRC).
    # Count each index actually present, not a single hard-coded "risk_indices".
    _cr = report.compliance.country_risk or {}
    if _cr:
        _idx_sources = {
            "transparency_intl_cpi": _cr.get("cpi_score"),
            "basel_aml_index": _cr.get("basel_aml"),
            "fatf": _cr.get("fatf_status"),
            "worldbank_wgi": _cr.get("wgi"),
            "oecd_crc": _cr.get("oecd_crc"),
        }
        _present_idx = [k for k, v in _idx_sources.items()
                        if v not in (None, "", "unknown", "n/a")]
        if _present_idx:
            for _k in _present_idx:
                _add("compliance:country_risk_known", _k)
        else:
            _add("compliance:country_risk_known", "risk_indices")
    if report.compliance.export_control:
        _add("compliance:export_classified", "tech_classifier")
    if report.compliance.regional_bloc_requirements:
        _add("compliance:regional_framework_cited", "rag:regional_compliance")
    # Digital
    if report.digital.press_coverage:
        for p in report.digital.press_coverage[:10]:
            _add("digital:press_coverage", p.source or "press")
    if report.digital.knowledge_base_hits:
        _add("digital:knowledge_base_hits", "aria_knowledge")
    if report.digital.neural_associations:
        _add("digital:neural_associations", "neural_memory")

    triangulated = [
        {"claim": k, "sources": sorted(list(v)), "source_count": len(v)}
        for k, v in sources_for_claim.items()
    ]
    report.verification.triangulated_claims = triangulated

    # Grounded rate: fraction of claims backed by at least 2 independent
    # sources. Not identical to source_verifier's URL-based rate, but
    # the right shape for a DD report.
    if triangulated:
        grounded = sum(1 for t in triangulated if t["source_count"] >= 2)
        report.verification.grounded_rate = round(grounded / len(triangulated), 2)
    else:
        report.verification.grounded_rate = None

    # R-F2662 — independent-corroboration signal: fraction of claims backed by >=2
    # DISTINCT EXTERNAL origins (ARIA's own memory/RAG never counts). Stricter + honester
    # than grounded_rate; a genuine step toward independent verification. Does NOT flip
    # independent_source_verification_run — that still requires full re-fetch re-check
    # (R-F2413), so the honest scope flag below stays as source_verifier sets it.
    _indep_count, _indep_rate = _independent_corroboration(triangulated)
    report.verification.independent_corroborated_count = _indep_count
    report.verification.independent_corroboration_rate = _indep_rate

    # Conflict detection — look for contradictions in ghost score
    # classification vs country risk headline
    ghost_cls = (report.identity.ghost_score or {}).get("classification", "")
    country_headline = (report.compliance.country_risk or {}).get("headline_risk", "")
    if ghost_cls in ("GREEN",) and country_headline in ("RED", "HARD_STOP"):
        report.verification.conflicts.append({
            "type": "classification_mismatch",
            "detail": f"ghost={ghost_cls} but country={country_headline}",
            "resolution": "use worst-case — promote overall to country's level",
        })

    # Confidence floor: worst tag across all sections.
    # Includes Layer 5c (commercial_coherence) -- it runs BEFORE verification
    # in the orchestrator (lines 2737 vs 2845), so its anomalies/findings
    # are already populated by this point. Excluding it meant a HIGH-tier
    # commercial_coherence anomaly (e.g. licence-chain gap) wouldn't drag
    # the report's confidence floor down, which it should.
    # `report.verification` is included for consistency but contributes
    # nothing today (no findings populated until later in this same call).
    all_confidences = ["ASSESSED"]  # baseline
    for section in (
        report.identity,
        report.network,
        report.verification,
        report.compliance,
        report.digital,
        report.commercial_coherence,
    ):
        for f in getattr(section, "findings", []) or []:
            all_confidences.append(getattr(f, "confidence", "ASSESSED"))
    report.verification.confidence_floor = weakest_confidence(all_confidences)

    report.verification.unverified_claim_count = sum(
        1 for t in triangulated if t["source_count"] < 2
    )

    # R-F2282: ACTUALLY invoke source_verifier (previously "not invoked" — a
    # standing Phase-A honesty gap). It checks that every URL the report CITES in
    # its findings was genuinely fetched into the evidence set (exact/domain match)
    # — a real citation-grounding rate, not a triangulation proxy. Network-free:
    # it only cross-references URLs already present in the report. Any finding that
    # cites a URL absent from the fetched evidence is surfaced as unverified.
    try:
        from . import source_verifier as _sv
        # R-F2286: build the fetched-evidence set from EVERY source/evidence field
        # across ALL layers. R-F2282 used press_coverage[].url ONLY, so URLs ARIA
        # genuinely consulted (registry, cert-transparency, GLEIF, RAG hits …)
        # looked "ungrounded" and citation_grounding_rate under-reported to ~0 — a
        # FALSE NEGATIVE, itself a Phase-A honesty bug. response_text = the report's
        # prose claims (finding `detail`); tool_context = every consulted URL
        # (finding `source`/`sources`, evidence `url`/`snippet`/`link`, anywhere in
        # the report). verify_response.extract_urls filters non-URL strings, so
        # dumping source labels ("companies_house") is harmless.
        _cited_bits: list[str] = []
        _fetched_bits: list[str] = []
        try:
            _rd = report.as_dict()
        except Exception:
            _rd = {}

        def _walk_ev(_o):
            if isinstance(_o, dict):
                for _k, _v in _o.items():
                    if isinstance(_v, str):
                        if _k == "detail":
                            _cited_bits.append(_v)            # prose claim — CHECKED
                        elif _k in ("url", "source", "snippet", "link", "href"):
                            _fetched_bits.append(_v)          # consulted source — EVIDENCE
                    elif _k == "sources" and isinstance(_v, list):
                        _fetched_bits.extend(str(_s) for _s in _v)
                    else:
                        _walk_ev(_v)
            elif isinstance(_o, (list, tuple)):
                for _it in _o:
                    _walk_ev(_it)

        _walk_ev(_rd)
        _tool_context = "\n".join(_fetched_bits)
        _response_text = "\n".join(_cited_bits)
        _sv_res = _sv.verify_response(_response_text, _tool_context)
        # R-F2413: source_verifier does CITATION GROUNDING (were the URLs the
        # report CITES actually fetched into the evidence set?), NOT full
        # independent re-verification of each claim against external sources.
        # So independent_source_verification_run stays False (honest); the
        # citation-grounding result is surfaced by its own fields below.
        report.verification.citation_grounding_rate = _sv_res.get("grounded_rate")
        report.verification.citation_verdict = _sv_res.get("verdict") or ""
        report.verification.citations_checked = len(_sv_res.get("cited_urls") or [])
        report.verification.citations_grounded = len(_sv_res.get("grounded") or [])
        report.verification.scope_note = (
            "Layer 3 = (a) source triangulation: grounded_rate = fraction of "
            "material claims backed by >=2 independent sources (real per-list "
            "sanctions + per-index country-risk counting, R-F2282); (b) citation "
            "grounding via source_verifier: citation_grounding_rate = fraction of "
            "URLs cited in the report's findings that were actually retrieved into "
            "the evidence set. It does NOT independently re-fetch external sources "
            "to re-confirm each claim's truth (only that cited URLs are present in "
            "the fetched evidence), so independent_source_verification_run is False."
        )
    except Exception as _sv_e:
        logger.warning("[R-F2282] source_verifier grounding failed: %s", _sv_e)
        report.verification.independent_source_verification_run = False
        report.verification.scope_note = (
            "Layer 3 = source triangulation + conflict detection over Layers "
            "1/2/4/5. Independent citation grounding (source_verifier) errored "
            "this run — grounded_rate is the triangulation source-count metric."
        )

    report.verification.meta.duration_ms = int((time.time() - t0) * 1000)
    report.verification.meta.status = LayerStatus.OK.value


async def _run_synthesis(target: dict, report: ARKDDReport) -> None:
    """Layer 6 — Synthesis. ACH matrix + final ghost score + risk
    classification + SAR trigger."""
    t0 = time.time()
    report.synthesis.meta.started_at = datetime.now(timezone.utc).isoformat()

    # ── 6a. Ghost score roll-up (authoritative) ──
    # Person DD doesn't have a ghost score — ghost detection is a
    # company-only signal (founding date, registered address pattern,
    # website age, etc.). Skip for persons so the synthesis layer
    # doesn't emit "Ghost score: 0/20 — GREEN" which is misleading.
    _is_person = (report.identity.entity_type or "").lower() == "person"
    ghost = report.identity.ghost_score or {}
    if _is_person:
        report.synthesis.ghost_score_total = 0
        report.synthesis.ghost_classification = ""
    else:
        report.synthesis.ghost_score_total = int(ghost.get("total") or 0)
        report.synthesis.ghost_classification = str(ghost.get("classification") or "GREEN")
    # R-F1924: incremental BLUF write — preserves partial result if synthesis times out
    report.synthesis.key_findings.append(Finding(
        severity="info",
        title=f"Ghost score: {report.synthesis.ghost_score_total}/20 — {report.synthesis.ghost_classification}",
        detail=f"Ghost classification for {report.identity.entity_name or 'entity'}: {report.synthesis.ghost_classification}",
        source="dd_orchestrator:_run_synthesis:6a",
        confidence="ASSESSED",
    ))

    # ── 6b. Risk classification — worst-case aggregation ──
    # Tiers in ascending severity
    severity_rank = {
        "GREEN":       0,
        "AMBER-LIGHT": 1,
        "AMBER":       1,
        "AMBER-DARK":  2,
        "RED":         3,
        "HARD STOP":   4,
        "HARD_STOP":   4,
    }
    candidates: list[str] = []
    if report.synthesis.ghost_classification and not _is_person:
        candidates.append(report.synthesis.ghost_classification)
    if report.compliance.country_risk.get("headline_risk"):
        candidates.append(report.compliance.country_risk["headline_risk"])
    # Any hard_stop finding anywhere? Includes digital, verification, and
    # commercial_coherence -- the prior list of three layers missed
    # hard-stops surfaced by Layer 5c (e.g. licence-chain gaps that
    # constitute strict-liability offences in some jurisdictions) and
    # by digital-layer OSINT findings (e.g. confirmed sanctions match
    # surfaced by deep_research that didn't propagate up to identity).
    for section in (report.identity, report.network, report.compliance,
                    report.digital, report.verification,
                    report.commercial_coherence):
        for f in getattr(section, "findings", []) or []:
            if getattr(f, "severity", "") == "hard_stop":
                candidates.append("HARD_STOP")
                break

    # R-F3084 — an explicit RED finding is a risk signal, not presentation
    # decoration. The Measure Group Europe report carried a CONFIRMED red
    # balance-sheet-insolvency finding while this aggregator considered only
    # hard stops, ghost/country risk and commercial coherence, so the customer
    # headline remained GREEN and claimed "no blocking risk". Aggregate the
    # severity the evidence layer already assigned; do not independently
    # reinterpret finding text here.
    if any(
        str(getattr(f, "severity", "") or "").strip().lower() == "red"
        for section in (
            report.identity, report.network, report.compliance,
            report.digital, report.verification, report.commercial_coherence,
        )
        for f in (getattr(section, "findings", []) or [])
    ):
        candidates.append("RED")

    # R-F3084 — financial capacity being ANSWERED does not mean it passed.
    # Consume the structured verdict directly as well as the finding severity,
    # so a caller cannot accidentally suppress the risk merely by omitting the
    # display finding. UNKNOWN stays neutral and is handled by readiness.
    _financial_verdict_for_risk = str(
        (report.compliance.financial_health or {}).get("health_verdict") or ""
    ).strip().upper()
    if _financial_verdict_for_risk == "DISTRESSED":
        candidates.append("RED")
    elif _financial_verdict_for_risk == "WEAK":
        candidates.append("AMBER-LIGHT")

    # Commercial coherence contribution (2026-04-22, Layer 5c)
    # HIGH + sector_mismatch (fronting pattern) → RED.
    # HIGH alone → AMBER-DARK. ELEVATED → AMBER-LIGHT. GREEN → neutral.
    _cc_tier_for_risk = (report.commercial_coherence.tier or "GREEN").upper()
    _cc_has_sector_mismatch = any(
        a.get("kind") == "sector_mismatch"
        for a in (report.commercial_coherence.anomalies or [])
    )
    if _cc_tier_for_risk == "HIGH" and _cc_has_sector_mismatch:
        candidates.append("RED")
    elif _cc_tier_for_risk == "HIGH":
        candidates.append("AMBER-DARK")
    elif _cc_tier_for_risk == "ELEVATED":
        candidates.append("AMBER-LIGHT")

    if candidates:
        worst = max(candidates, key=lambda c: severity_rank.get(c, 0))
    else:
        worst = "GREEN"

    # R-F1924: incremental BLUF write — risk classification available even if synthesis times out
    report.synthesis.key_findings.append(Finding(
        severity="info",
        title=f"Risk classification: {worst}",
        detail=f"Aggregated from {len(candidates)} signal(s): {', '.join(candidates) if candidates else 'no signals'}",
        source="dd_orchestrator:_run_synthesis:6b",
        confidence="ASSESSED",
    ))

    # Normalise to canonical RiskClassification values
    canonical_map = {
        "GREEN":        RiskClassification.GREEN.value,
        "AMBER-LIGHT":  RiskClassification.AMBER_LIGHT.value,
        "AMBER":        RiskClassification.AMBER_LIGHT.value,
        "AMBER-DARK":   RiskClassification.AMBER_DARK.value,
        "RED":          RiskClassification.RED.value,
        "HARD STOP":    RiskClassification.HARD_STOP.value,
        "HARD_STOP":    RiskClassification.HARD_STOP.value,
    }
    report.synthesis.risk_classification = canonical_map.get(worst, RiskClassification.GREEN.value)
    report.risk_classification = report.synthesis.risk_classification

    # ── 6b1. Sanctions-freshness gate (R-F2167) — a primary sanctions source
    # that served STALE/unavailable data means we could NOT confirm "not
    # sanctioned". That is a MANDATORY non-GREEN trigger — independent of the
    # _is_person flag and the _total_gaps>=3 threshold below — because a single
    # un-refreshed sanctions feed makes a GREEN headline a false clearance (the
    # worst output a compliance tool can emit). Keys off the marker the
    # identity primary-source loop writes when an adapter flags stale.
    if report.risk_classification == RiskClassification.GREEN.value:
        _sanctions_unverified = [
            g for g in (getattr(report.identity, "data_gaps", []) or [])
            if "SANCTIONS_SOURCE_UNVERIFIED" in str(g)
        ]
        if _sanctions_unverified:
            report.risk_classification = RiskClassification.AMBER_LIGHT.value
            report.synthesis.risk_classification = RiskClassification.AMBER_LIGHT.value
            report.identity.findings.append(Finding(
                severity="amber",
                title="Sanctions screen UNVERIFIED — GREEN overridden to AMBER",
                detail=(
                    "A primary sanctions source served stale/unavailable data, so "
                    "the entity could NOT be confirmed clear of sanctions. Re-screen "
                    "required before any clearance. "
                    + "; ".join(str(g)[:160] for g in _sanctions_unverified[:3])
                ),
                source="dd_orchestrator.sanctions_freshness_gate",
                confidence="ASSESSED",
            ))

    # ── R-F3553 — PROMOTE the positive register evidence already captured ─────
    #
    # Four consecutive delivered reports carried T1 positives in the citation list — an
    # SIA Approved Contractor entry for the correct legal entity, an Armed Forces
    # Covenant listing, a gov.uk supplier record — and promoted none of them. A report
    # that names every gap and no verified credential gives a systematically negative
    # picture built from a complete evidence set.
    #
    # Runs HERE because it needs the adverse-media sweep's captured sources, which is the
    # only place external URLs with title+snippet accumulate. Attribution is STRICT and
    # fails closed (see `_positive_names_subject`): a fabricated credential is worse than
    # a missed one.
    try:
        # R-F3566 — read EVERY producer populated by now, not `adverse_media`, which
        # `_run_synthesis` reaches before it is ever assigned.
        _pos_src = _positive_source_rows(report)
        _pos_tokens = _adverse_subject_tokens(
            report.identity.entity_name or "",
            getattr(report.identity, "aliases", None) or [])
        for _pf in positive_register_findings(
                _pos_src, _pos_tokens,
                as_of=str(getattr(report, "generated_at", "") or "")[:10]):
            report.identity.findings.append(Finding(**_pf))
    except Exception as _pos_e:  # noqa: BLE001 — a positive must never cost a report
        logger.debug("[R-F3553] positive register promotion skipped: %s", _pos_e)

    # ── 6b1a. R-F3455 — the report must not contradict its own cited sources ──
    try:
        _am_blob = getattr(report, "adverse_media", None) or {}
        _am_mat = _am_blob.get("materiality") if isinstance(_am_blob, dict) else None
        _am_mat = _am_mat if isinstance(_am_mat, dict) else {}
        _reviewed = (_am_mat.get("review_findings")
                     or (_am_blob.get("findings_for_review") if isinstance(_am_blob, dict) else None)
                     or [])
        # Only fires when the adverse section is CLAIMING nothing. If items are already
        # queued for review the reader has not been told a false clean.
        if not _reviewed:
            _contra = _adverse_citation_contradictions(report)
            if _contra:
                if isinstance(_am_blob, dict):
                    _am_blob["unreviewed_adverse_citations"] = _contra[:10]
                report.digital.findings.append(Finding(
                    severity="amber",
                    title=(f"{len(_contra)} cited source(s) carry adverse markers but are "
                           f"absent from the adverse-media review set"),
                    detail=(
                        "The adverse-media sweep concluded that nothing was found, while "
                        "these sources — cited by this same report — name the subject AND "
                        "carry adverse content by the sweep's own tests: "
                        + "; ".join(str(c.get("title"))[:120] for c in _contra[:3])
                        + ". The sweep and the citation list are populated by different "
                          "paths, so an item can be missing from one and present in the "
                          "other. This is NOT a determination that the items are material "
                          "— it is a statement that the report's evidence and its "
                          "conclusion disagree, and the disagreement must be settled by a "
                          "reader rather than resolved silently in favour of the clean "
                          "answer."
                    ),
                    source="dd_orchestrator.adverse_citation_coherence:R-F3455",
                    confidence="ASSESSED",
                ))
                report.digital.data_gaps.append(
                    f"adverse-media conclusion CONTRADICTED by {len(_contra)} of this "
                    f"report's own cited source(s), which name the subject and carry "
                    f"adverse content. Open them before relying on the clean reading."
                )
    except Exception as _cc_err:  # noqa: BLE001
        logger.debug("[R-F3455] adverse citation coherence gate skipped: %s", _cc_err)

    # ── 6b2. Confidence gate — never GREEN when verification is insufficient ──
    # If risk landed on GREEN but key identity signals are missing, bump
    # to AMBER-LIGHT with MANUAL REVIEW flag. This prevents a clean bill
    # when ARIA couldn't actually verify the entity.
    if report.risk_classification == RiskClassification.GREEN.value and not _is_person:
        _needs_manual = False
        _gate_reasons: list[str] = []

        # Registry not verified? Require actual substance — status alone is not enough.
        _has_registry_status = bool(report.identity.registration_status)
        _has_directors = bool(report.identity.directors)
        _has_inc_date = bool(report.identity.incorporation_date)
        _has_substance = _has_directors or (_has_registry_status and _has_inc_date)
        if not _has_substance:
            _needs_manual = True
            _missing = []
            if not _has_registry_status:
                _missing.append("registration status")
            if not _has_directors:
                _missing.append("directors/officers")
            if not _has_inc_date:
                _missing.append("incorporation date")
            _gate_reasons.append(f"registry verification incomplete (missing: {', '.join(_missing)})")

        # Too many data gaps? Fallback iteration includes
        # commercial_coherence so a Layer 5c gap (e.g. unknown payment
        # market, untraceable corporate substance) actually counts toward
        # the manual-review trigger.
        _total_gaps = len(report.data_gaps_summary) if hasattr(report, "data_gaps_summary") else 0
        if not hasattr(report, "data_gaps_summary"):
            _total_gaps = sum(
                len(getattr(s, "data_gaps", []) or [])
                for s in (report.identity, report.network, report.verification,
                          report.compliance, report.digital,
                          report.commercial_coherence)
            )
        if _total_gaps >= 3:
            _needs_manual = True
            _gate_reasons.append(f"{_total_gaps} unresolved data gaps")

        # Ghost score has unresolved indicators?
        _ghost = report.identity.ghost_score or {}
        _indicators = _ghost.get("indicators", [])
        if isinstance(_indicators, list):
            _unresolved = sum(1 for ind in _indicators if isinstance(ind, dict) and ind.get("value") == "?")
        else:
            _unresolved = sum(1 for v in _indicators.values() if v == "?") if isinstance(_indicators, dict) else 0
        if _unresolved >= 4:
            _needs_manual = True
            _gate_reasons.append(f"ghost score has {_unresolved} unresolved indicators")

        if _needs_manual:
            report.risk_classification = RiskClassification.AMBER_LIGHT.value
            report.synthesis.risk_classification = RiskClassification.AMBER_LIGHT.value
            report.identity.findings.append(Finding(
                severity="amber",
                title="Confidence gate: GREEN overridden to AMBER — manual review required",
                detail=f"Reasons: {'; '.join(_gate_reasons)}. ARIA cannot issue a GREEN clearance without sufficient verification.",
                source="dd_orchestrator.confidence_gate",
                confidence="ASSESSED",
            ))
            # R-F298: stamp the report so the BLUF assembly can tell the
            # difference between "AMBER because of a real risk finding"
            # and "AMBER because the data was too thin to issue GREEN".
            # The current AMBER-LIGHT BLUF says "can proceed with enhanced
            # DD" — that's wrong for confidence-gate-only AMBER, where
            # the honest reading is "INSUFFICIENT EVIDENCE, can't issue
            # a verdict either way".
            report.confidence_gate_triggered = True
            report.confidence_gate_reasons = list(_gate_reasons)
            _entity_name = report.identity.entity_name or target.get("name", "?")
            logger.info("Confidence gate: GREEN → AMBER for %s (%s)", _entity_name, "; ".join(_gate_reasons))

    # ── 6b3. R-F2779 — adverse-media never-false-clean disclosure ──
    # A GREEN / clean-looking verdict must NOT imply "no adverse media" unless a
    # dedicated adverse-media pass actually produced a result. The DEAD/DEGRADED
    # web-search case is already disclosed in _run_digital; this covers the case
    # where search WORKED but no adverse-media screen ran (or was skipped) — so the
    # ABSENCE of adverse-media findings is NOT evidence of a clean entity. Mirrors
    # the sanctions / Companies-House never-false-clean guards. Company path only;
    # the person path has its own PEP/adverse handling.
    if not _is_person:
        _wf = report.digital.web_footprint if isinstance(report.digital.web_footprint, dict) else {}
        _am_inline = _wf.get("adverse_media_hits")            # list (even empty) once R-F445 executed
        _am_deep = getattr(report, "adverse_media", None)     # deep follow-up blob
        _am_deep_ran = (isinstance(_am_deep, dict) and bool(_am_deep)
                        and not _am_deep.get("error"))
        _am_screened = (_am_inline is not None) or _am_deep_ran
        if not _am_screened:
            _am_gap = ("R-F2779: adverse-media screening did NOT complete this run — the ABSENCE of "
                       "adverse-media / litigation / corruption findings is NOT a clean bill. A dedicated "
                       "adverse-media check is required before relying on this verdict.")
            if _am_gap not in report.digital.data_gaps:
                report.digital.data_gaps.append(_am_gap)
            # Attach to digital.findings (persists) — synthesis.key_findings is
            # rebuilt later in this function, so an append there would be discarded.
            report.digital.findings.append(Finding(
                severity="info",
                title="Adverse-media screening incomplete — verdict does NOT certify absence of adverse media",
                detail=_am_gap,
                source="dd_orchestrator._run_synthesis:R-F2779",
                confidence="ASSESSED",
            ))

    # ── 6c. SAR trigger — UK POCA / FATF typology ──
    # Triggers (original):
    #   - sanctions hit on subject OR director
    #   - ghost score >= 12 (RED) combined with layered secrecy chain
    #   - transaction value >= 100k with no declared activity
    # Extended triggers (FATF typology / POCA indicators):
    #   - ghost score >= 12 AND no directors (layered secrecy)
    #   - multiple jurisdictions with no apparent business reason
    #   - PEP + opaque ownership (PSC not disclosed)
    #   - entity registered < 12 months with large scope
    #   - director on multiple sanctioned boards
    #   - address cluster with 5+ co-located entities (mail-drop)
    sar_reasons: list[str] = []
    if any("sanctions" in str(f.title).lower() and "hit" in str(f.title).lower()
           for f in report.identity.findings):
        sar_reasons.append("sanctions hit on identity layer")
    if any("hit on sanctions" in str(f.title).lower()
           for f in report.network.findings):
        sar_reasons.append("sanctions hit in network layer (one-hop)")
    if report.synthesis.ghost_score_total >= 12:
        sar_reasons.append(f"ghost score {report.synthesis.ghost_score_total}/20 at RED threshold")

    # SAR-ext-1: ghost score >= 12 AND no directors (layered secrecy)
    _has_directors = bool(report.identity.directors)
    if report.synthesis.ghost_score_total >= 12 and not _has_directors:
        sar_reasons.append("ghost score >= 12 with no directors on file — layered secrecy indicator")

    # SAR-ext-2: multiple jurisdictions with no apparent business reason
    _jurisdictions_seen: set[str] = set()
    if report.identity.jurisdiction_iso2:
        _jurisdictions_seen.add(report.identity.jurisdiction_iso2)
    for _cl in report.network.cross_linked_entities:
        _j = _cl.get("jurisdiction") or _cl.get("jurisdiction_iso2") or ""
        if _j:
            _jurisdictions_seen.add(_j.upper()[:2])
    if len(_jurisdictions_seen) >= 3 and not report.identity.declared_activity:
        sar_reasons.append(
            f"entity spans {len(_jurisdictions_seen)} jurisdictions with no declared activity — complex structuring"
        )

    # SAR-ext-3: PEP connection combined with opaque ownership (no PSC / UBO)
    _has_pep = bool(report.network.pep_connections)
    _has_ubo = bool(report.identity.ubo_chain)
    _has_shareholders = bool(report.identity.shareholders)
    if _has_pep and not _has_ubo and not _has_shareholders:
        sar_reasons.append("PEP connection with no disclosed PSC/UBO — opaque ownership")

    # SAR-ext-4: entity registered < 12 months with large transaction scope
    _inc_date_str = report.identity.incorporation_date
    if _inc_date_str and not _is_person:
        try:
            from datetime import date as _date_type
            _inc_date = _date_type.fromisoformat(str(_inc_date_str)[:10])
            _age_days = (datetime.now(timezone.utc).date() - _inc_date).days
            if _age_days < 365 and report.identity.declared_activity:
                sar_reasons.append(
                    f"entity incorporated < 12 months ago ({_age_days} days) — newco with declared activity"
                )
        except (ValueError, TypeError):
            pass  # unparseable date — skip

    # SAR-ext-5: director appears on multiple sanctioned entities' boards
    _director_sanctions_hits = [
        f for f in report.identity.findings
        if getattr(f, "source", "") == "sanctions.director_screen"
        and getattr(f, "severity", "") in ("hard_stop", "red")
    ]
    if len(_director_sanctions_hits) >= 2:
        sar_reasons.append(
            f"{len(_director_sanctions_hits)} directors flagged on sanctions/debarment lists — cross-board exposure"
        )

    # SAR-ext-6: address cluster — entity shares address with 5+ others (mail-drop)
    _addr_cluster = report.network.address_cluster or {}
    _max_colocated = 0
    for _addr, _info in _addr_cluster.items() if isinstance(_addr_cluster, dict) else []:
        _n = len(_info) if isinstance(_info, list) else int(_info.get("count", 0)) if isinstance(_info, dict) else 0
        _max_colocated = max(_max_colocated, _n)
    if _max_colocated >= 5:
        sar_reasons.append(
            f"address shared with {_max_colocated}+ entities — mail-drop indicator"
        )

    if sar_reasons:
        report.synthesis.sar_trigger = True
        report.synthesis.sar_rationale = " · ".join(sar_reasons)

    # ── 6d. ACH matrix (structural) ──
    # Three hypotheses by default:
    #   H1: entity is a legitimate counterparty suitable for BD
    #   H2: entity is a higher-risk counterparty requiring enhanced DD
    #   H3: entity is a shell / concealment vehicle — refuse
    hypotheses = {
        "H1_legit": {"label": "Legitimate BD counterparty", "support": 0, "against": 0},
        "H2_enhanced": {"label": "Higher-risk, enhanced DD required", "support": 0, "against": 0},
        "H3_shell": {"label": "Shell / concealment vehicle — refuse", "support": 0, "against": 0},
    }
    ghost_total = report.synthesis.ghost_score_total
    if ghost_total <= 3:
        hypotheses["H1_legit"]["support"] += 3
        hypotheses["H3_shell"]["against"] += 3
    elif ghost_total <= 7:
        hypotheses["H2_enhanced"]["support"] += 2
        hypotheses["H1_legit"]["against"] += 1
    elif ghost_total <= 11:
        hypotheses["H2_enhanced"]["support"] += 3
        hypotheses["H3_shell"]["support"] += 1
    elif ghost_total <= 15:
        hypotheses["H3_shell"]["support"] += 3
        hypotheses["H1_legit"]["against"] += 3
    else:
        hypotheses["H3_shell"]["support"] += 5
        hypotheses["H1_legit"]["against"] += 5

    # Country risk contribution
    country_headline = (report.compliance.country_risk or {}).get("headline_risk")
    if country_headline in ("RED", "HARD_STOP"):
        hypotheses["H2_enhanced"]["support"] += 1
        hypotheses["H3_shell"]["support"] += 1
    elif country_headline == "AMBER":
        hypotheses["H2_enhanced"]["support"] += 1

    # Sanctions hit → H3 strongly favoured
    if report.synthesis.sar_trigger:
        hypotheses["H3_shell"]["support"] += 5
        hypotheses["H1_legit"]["against"] += 5

    # ── ACH-ext-1: Verification quality ──
    _grounded = report.verification.grounded_rate
    _conflicts = report.verification.conflicts
    if _grounded is not None and _grounded < 0.4:
        hypotheses["H2_enhanced"]["support"] += 2
        hypotheses["H1_legit"]["against"] += 1
    elif _grounded is not None and _grounded >= 0.8:
        hypotheses["H1_legit"]["support"] += 1
    if _conflicts:
        hypotheses["H2_enhanced"]["support"] += 1
        hypotheses["H3_shell"]["support"] += 1
        hypotheses["H1_legit"]["against"] += 1

    # ── ACH-ext-2: Digital footprint ──
    _has_press = bool(report.digital.press_coverage)
    _has_procurement = bool(report.digital.procurement_history)
    if not _has_press and not _has_procurement and not _is_person:
        hypotheses["H2_enhanced"]["support"] += 2
        hypotheses["H3_shell"]["support"] += 1
        hypotheses["H1_legit"]["against"] += 1
    elif _has_press and _has_procurement:
        hypotheses["H1_legit"]["support"] += 2

    # ── ACH-ext-3: Network red flags ──
    if report.network.pep_connections:
        hypotheses["H2_enhanced"]["support"] += 2
        hypotheses["H1_legit"]["against"] += 1
    if report.network.sanctions_network:
        hypotheses["H3_shell"]["support"] += 3
        hypotheses["H1_legit"]["against"] += 2

    # ── ACH-ext-4: Director screening ──
    _dir_sanctions = any(
        getattr(f, "source", "") == "sanctions.director_screen"
        and getattr(f, "severity", "") in ("hard_stop", "red")
        for f in report.identity.findings
    )
    if _dir_sanctions:
        hypotheses["H3_shell"]["support"] += 3
        hypotheses["H1_legit"]["against"] += 3

    # ── ACH-ext-5: Registration anomalies — empty company ──
    _no_directors = not report.identity.directors
    _no_inc_date = not report.identity.incorporation_date
    if _no_directors and _no_inc_date and not _is_person:
        hypotheses["H3_shell"]["support"] += 2
        hypotheses["H1_legit"]["against"] += 2

    # ── ACH-ext-6: Export control ──
    _ec = report.compliance.export_control or {}
    _ec_class = (_ec.get("classification") or _ec.get("rating") or "").upper()
    if _ec_class in ("RESTRICTED", "CONTROLLED", "ML", "MTCR", "WA-CAT1", "WA-CAT2"):
        hypotheses["H2_enhanced"]["support"] += 2
        hypotheses["H1_legit"]["against"] += 1

    # ── ACH-ext-7: Commercial coherence (Layer 5c, 2026-04-22) ──
    # A HIGH tier (score < 0.55) means the deal structure itself is
    # incoherent — strong signal for H2 enhanced-DD, and if combined with
    # other red signals pushes H3 (shell/fronting). ELEVATED is a soft
    # signal. GREEN is neutral.
    _cc_section = report.commercial_coherence
    _cc_tier = (_cc_section.tier or "GREEN").upper()
    if _cc_tier == "HIGH":
        hypotheses["H2_enhanced"]["support"] += 3
        hypotheses["H3_shell"]["support"] += 2
        hypotheses["H1_legit"]["against"] += 2
    elif _cc_tier == "ELEVATED":
        hypotheses["H2_enhanced"]["support"] += 1
        hypotheses["H1_legit"]["against"] += 1
    # Sector mismatch (non-defence SIC claiming defence deal) — classic
    # fronting pattern. Treat as a hard H3 signal on its own.
    if any(
        a.get("kind") == "sector_mismatch"
        for a in (_cc_section.anomalies or [])
    ):
        hypotheses["H3_shell"]["support"] += 3
        hypotheses["H1_legit"]["against"] += 3

    # ── Determine winner ──
    report.synthesis.ach_matrix = {
        "hypotheses": hypotheses,
        "method": "balance of support minus against",
        "winner": max(hypotheses.items(), key=lambda kv: kv[1]["support"] - kv[1]["against"])[0],
    }

    # ── 6d2. Competing narratives ──
    _winner = report.synthesis.ach_matrix["winner"]
    _h = hypotheses
    _narratives: list[str] = []
    if _winner == "H1_legit":
        _narratives.append(
            f"Most likely: {report.identity.entity_name or 'entity'} is a legitimate counterparty. "
            f"Supported by ghost score {ghost_total}/20, "
            f"grounded rate {_grounded if _grounded is not None else 'N/A'}, "
            f"and {'presence' if _has_press else 'absence'} in public record."
        )
        _narratives.append(
            "Alternative: entity may still present enhanced-DD risks if verification gaps "
            "remain or counterparty operates in a higher-risk jurisdiction."
        )
    elif _winner == "H2_enhanced":
        _narratives.append(
            f"Most likely: {report.identity.entity_name or 'entity'} is a higher-risk counterparty "
            f"requiring enhanced due diligence before engagement. "
            f"ACH balance: H2 support={_h['H2_enhanced']['support']}, "
            f"H1 net={_h['H1_legit']['support'] - _h['H1_legit']['against']}."
        )
        _narratives.append(
            "Alternative (benign): entity may be legitimate but operating in a complex "
            "regulatory environment or recently incorporated, explaining data sparsity."
        )
        _narratives.append(
            "Alternative (adverse): entity could be a concealment vehicle with "
            "enough surface legitimacy to pass basic checks — deeper investigation warranted."
        )
    else:  # H3_shell
        _narratives.append(
            f"Most likely: {report.identity.entity_name or 'entity'} is a shell or concealment vehicle. "
            f"ACH strongly favours H3 (support={_h['H3_shell']['support']}, "
            f"against={_h['H3_shell']['against']}). "
            f"Ghost score {ghost_total}/20."
        )
        _narratives.append(
            "Alternative: entity may be a dormant but legitimate holding company "
            "with minimal public footprint — verify with the counterparty directly."
        )
    report.synthesis.competing_narratives = _narratives

    # ── 6e. Key findings — pull the highest-severity items across sections ──
    all_findings: list[Finding] = []
    for section in (
        report.identity, report.network, report.verification,
        report.compliance, report.digital, report.commercial_coherence,
    ):
        for f in getattr(section, "findings", []) or []:
            all_findings.append(f)
    severity_order = {"hard_stop": 0, "red": 1, "amber": 2, "info": 3}
    all_findings.sort(key=lambda f: severity_order.get(getattr(f, "severity", "info"), 4))
    # R-F3571 — cap any ONE check's share of the summary. `all_findings[:10]` let
    # network_walker take 3 of 10 slots with the same observation about three
    # officers, pushing the sanctions screen and contract exposure out of view.
    report.synthesis.key_findings = _rollup_key_findings(all_findings)

    # ── 6f. Residual unknowns = all data_gaps combined (R-F2275: sanitised) ──
    def _sanitize_gap(g: str):
        # A genuine data-gap ("Directors unavailable for BR…") is decision-useful and kept.
        # A raw internal-error fragment ("'coroutine' object has no attribute as_dict",
        # "unexpected payload shape", stack text) must NEVER reach the user — map the known
        # overlay cases to a neutral line, drop the rest as noise.
        if not g:
            return None
        low = g.lower()
        if any(m in low for m in (
            "coroutine", "as_dict", "has no attribute", "traceback", "nonetype",
            "unexpected payload", "keyerror", "typeerror", "attributeerror", "object is not",
        )):
            if "country" in low or "risk" in low:
                return "Country-risk overlay was temporarily unavailable for this run."
            if "payload" in low or "indicator" in low or "world bank" in low or "wb " in low:
                return "Some macro-indicator overlays were temporarily unavailable."
            return None
        return g
    for section in (
        report.identity, report.network, report.verification,
        report.compliance, report.digital, report.commercial_coherence,
    ):
        for g in getattr(section, "data_gaps", []) or []:
            _sg = _sanitize_gap(g)
            if _sg and _sg not in report.synthesis.residual_unknowns:
                report.synthesis.residual_unknowns.append(_sg)

    report.synthesis.meta.duration_ms = int((time.time() - t0) * 1000)
    report.synthesis.meta.status = LayerStatus.OK.value


# =============================================================================
# BOTTOM-LINE + RECOMMENDATION (programmatic, pre-LLM)
# =============================================================================

def _mark_layer_errors_as_gaps(report) -> int:
    """R-F3029 — every errored/partial layer states its error in its OWN data_gaps.

    Pure and idempotent (re-running adds nothing): the marker prefix is checked
    before appending, because `_assemble_bluf` can run more than once per report.
    Returns how many gaps were added, for the caller's diagnostics."""
    _added = 0
    for _key in ("identity", "network", "verification", "compliance", "digital",
                 "synthesis", "sweep_data", "commercial_coherence"):
        layer = getattr(report, _key, None)
        meta = getattr(layer, "meta", None)
        if layer is None or meta is None:
            continue
        status = str(getattr(meta, "status", "") or "").lower()
        if status not in (LayerStatus.ERROR.value, LayerStatus.PARTIAL.value):
            continue
        err = str(getattr(meta, "error", "") or "").strip()
        gaps = getattr(layer, "data_gaps", None)
        if not isinstance(gaps, list):
            continue
        marker = f"[{_key} layer {status}]"
        if any(isinstance(g, str) and g.startswith(marker) for g in gaps):
            continue
        gaps.append(
            f"{marker} this layer did not complete"
            + (f" — {err}" if err else "")
            + ". Its results below are TRUNCATED, not exhaustive: treat an absence "
              "here as unchecked, not as clean."
        )
        _added += 1
    return _added


async def _assemble_bluf(report: ARKDDReport) -> None:
    """Populate report.bottom_line / recommendation / next_actions / confidence.

    Deterministic — no LLM call, just pattern matching over the sections
    so the orchestrator always returns a non-empty BLUF even when the
    cost cap prevented the LLM from running.
    """
    risk = report.risk_classification
    name = report.identity.entity_name or "subject"
    # R-F3029 — a layer that ERRORED must appear in that layer's DATA GAPS.
    # Live on dd_16db41eb5fa8 the digital layer carried
    # `meta.status=error, meta.error="timeout after 90s"`, yet `layers_skipped` was
    # empty, confidence read ASSESSED, and the timeout appeared in NO data-gaps
    # list — so a reader saw a thin digital section with no way to know it was cut
    # off rather than genuinely empty. The status field alone is not disclosure:
    # a truncated layer must say so where the reader looks for what is missing.
    _mark_layer_errors_as_gaps(report)
    # R-F2786 — the five customer questions are a clearance contract, not a
    # second risk model. Compute them before wording the BLUF so "no observed
    # red flags" can never become "standard contracting" while financials,
    # UBO, adverse media, sanctions/export controls, or registry identity are
    # unresolved.
    from .dd_schema import _dd_decision_readiness
    report.decision_readiness = _dd_decision_readiness(report.as_dict())

    # ── R-F2621: FAIL CLOSED when synthesis did not complete ──────────────
    # `risk_classification` defaults to GREEN (dd_schema.py:385/435) and is only
    # ASSIGNED at _run_synthesis:6380. Synthesis is wrapped in
    # `wait_for(..., timeout=_clamp_final(10))` (:9391); its except (:9392-9394)
    # marks the layer ERROR but leaves `risk_classification` at that GREEN
    # default. This function then read the default and emitted a confident
    # "GREEN — passes baseline due diligence" for a DD whose risk aggregation
    # NEVER RAN — skipping the sanctions-unverified override at :6389 with it.
    # Absence of computation must never read as "clean".
    #
    # Two fail-OPEN defaults make this reachable, so BOTH are checked:
    #   1. risk_classification defaults to GREEN  (dd_schema.py:385)
    #   2. SectionMeta.status defaults to "ok"    (dd_schema.py:75) — so a
    #      synthesis that never ran looks OK; `layers_run` (appended at :9387
    #      BEFORE the try) is the honest witness that it was attempted.
    # Verdict mirrors the proven R-F1628 hard-deadline pattern (:8283):
    # AMBER-LIGHT + an explicit reason, never GREEN, never empty.
    # `layers_run` is only EVIDENCE when the caller actually tracks it: the
    # orchestrator appends "synthesis" at :9387 BEFORE the try, so a populated
    # list that omits it means the layer was genuinely skipped. An EMPTY list
    # means "not tracked" (direct callers / focused tests), NOT "never ran" —
    # inferring a skip from it would fail closed on healthy reports.
    _synth_errored = report.synthesis.meta.status == LayerStatus.ERROR.value
    _synth_skipped = bool(report.layers_run) and "synthesis" not in report.layers_run
    if _synth_errored or _synth_skipped:
        _why = (
            (report.synthesis.meta.error or "synthesis layer error")
            if _synth_errored else "synthesis layer never ran"
        )
        report.risk_classification = RiskClassification.AMBER_LIGHT.value
        report.synthesis.risk_classification = RiskClassification.AMBER_LIGHT.value
        report.bottom_line = (
            f"🟠 INSUFFICIENT EVIDENCE — the risk analysis for {name} did not "
            f"complete ({_why}), so NO clean verdict can be issued. The evidence "
            f"layers that finished are included below, but the findings were never "
            f"aggregated into a risk classification — treat this as 'incomplete', "
            f"NOT as 'nothing found'. Re-run, or narrow scope (supply jurisdiction / "
            f"registration number / website) for a full result."
        )
        report.recommendation = (
            "Do NOT rely on this run to clear the subject. Re-run the DD; if it "
            "times out again, narrow the scope or raise ARIA_DD_TOTAL_BUDGET_S. "
            "Commission commercial DD before onboarding if the deadline is binding."
        )
        report.next_actions = [
            "Re-run the DD (the risk aggregation did not complete)",
            "Narrow scope — supply jurisdiction / registration number / website",
            "Do not issue a clean verdict on this run",
        ]
        # Surfaces the gate to the evidence-grade scorer (R-F2493) and lets
        # routes/aria.py:7651 auto-launch a full-depth background re-run.
        report.confidence_gate_triggered = True
        if not report.confidence_gate_reasons:
            report.confidence_gate_reasons = [f"synthesis incomplete — {_why}"]
        report.data_gaps_summary.append(
            f"R-F2621: synthesis did not complete ({_why}) — risk classification "
            f"was never computed; no clean verdict issued"
        )
        return

    if risk == RiskClassification.HARD_STOP.value:
        report.bottom_line = (
            f"🔴 HARD STOP — {name} triggers a mandatory refusal. "
            "Do NOT proceed with the transaction."
        )
        report.recommendation = (
            "Refuse the engagement. File SAR if reporting thresholds are met. "
            "Preserve all investigation evidence for compliance record."
        )
        report.next_actions = [
            "Do not contact the counterparty further until compliance sign-off",
            "Escalate to ECJU / OFSI / DBT compliance desk as appropriate",
            "Assess SAR filing obligation under POCA 2002 / national AML law",
            "Lock the case file — preserve all evidence",
        ]
    elif risk == RiskClassification.RED.value:
        report.bottom_line = (
            f"🔴 RED — {name} is very likely unsuitable for onboarding in current form. "
            "Independent commercial DD required before any further engagement."
        )
        report.recommendation = (
            "Commission a commercial-grade DD report from LSEG / Sayari / Dow Jones / Orbis. "
            "Do NOT proceed on open-source findings alone. Re-evaluate after commercial DD."
        )
        report.next_actions = [
            "Commission commercial DD (Sayari / LSEG / Dow Jones / Orbis)",
            "Halt any in-progress contracting until commercial DD returns clean",
            "Document the current AMBER-DARK / RED grounds in the case file",
        ]
    elif risk == RiskClassification.AMBER_DARK.value:
        report.bottom_line = (
            f"🟠 AMBER-DARK — {name} shows structural concerns. Enhanced DD is required; "
            "do not proceed without independent verification of beneficial ownership."
        )
        report.recommendation = (
            "Obtain commercial DD report on beneficial ownership. Require signed EUC "
            "from end-user government. Screen signatory identities. Escalate any new red flag to RED."
        )
        report.next_actions = [
            "Obtain commercial UBO verification",
            "Require signed EUC from end-user authority",
            "Identity-verify all signatories against independent sources",
            "Re-run orchestrator weekly via watchlist until risk tier improves",
        ]
    elif risk == RiskClassification.AMBER_LIGHT.value:
        # R-F298: when AMBER was reached purely via the confidence gate
        # (data too thin to issue GREEN, NOT because of a real risk
        # finding), the honest BLUF is "INSUFFICIENT EVIDENCE", not "can
        # proceed with enhanced DD". Otherwise we paper over data-empty
        # DDs as if they had been investigated.
        # R-F2361: the confidence gate that sets confidence_gate_triggered
        # only runs when the classification is GREEN (6192). An entity that
        # is AMBER for an UNRELATED reason (country risk, commercial
        # coherence) with NO registry substance — no directors, no
        # registration-status + incorporation-date — would otherwise skip
        # the gate and get the over-reassuring "can proceed" headline
        # despite never being registry-verified. Reframe those too:
        # honesty > reassurance, and this is most of the non-GB/US world.
        _has_reg_status = bool(report.identity.registration_status)
        _has_dirs = bool(report.identity.directors)
        _has_inc = bool(report.identity.incorporation_date)
        _data_starved = not (_has_dirs or (_has_reg_status and _has_inc))
        if getattr(report, "confidence_gate_triggered", False) or _data_starved:
            _gate_reasons = getattr(report, "confidence_gate_reasons", []) or []
            if not _gate_reasons and _data_starved:
                _missing_sub = []
                if not _has_reg_status:
                    _missing_sub.append("registration status")
                if not _has_dirs:
                    _missing_sub.append("directors")
                if not _has_inc:
                    _missing_sub.append("incorporation date")
                _gate_reasons = [
                    "no registry substance — " + ", ".join(_missing_sub) + " unverified"
                ]
            _reasons_str = "; ".join(_gate_reasons) if _gate_reasons else "insufficient verification"

            # R-F2493 — this branch EMITS the INSUFFICIENT-EVIDENCE / LIMITED-REGISTRY
            # verdict, entered via the GREEN confidence gate OR a data-starved AMBER.
            # Mark the flag on the report so it SERIALISES into the persisted dict and
            # the evidence-grade scorer (dd_schema _quality_metrics → R-F2493 hard cap)
            # reflects the honest gate. Before this, a data-starved INSUFFICIENT report
            # left confidence_gate_triggered=False and could still score C/60.
            report.confidence_gate_triggered = True
            if not getattr(report, "confidence_gate_reasons", None):
                report.confidence_gate_reasons = list(_gate_reasons)

            # R-F398 (2026-05-13): before emitting INSUFFICIENT EVIDENCE,
            # try a fallback web search on the entity name. ARIA self-
            # reported that "the dd_orchestrate has 9 layers but the
            # web-search layer appears to run only on real domains, not
            # on person names. Run brave_answer on each name + 'LinkedIn'
            # variation." A non-zero result count doesn't lift the gate
            # (the registry/director data is still missing — that's the
            # real failure) but it surfaces public hits so the operator
            # can see the public-intel surface that was unindexed.
            _fallback_hits: list[dict] = []
            try:
                _entity = (name or "").strip()
                if _entity and len(_entity) >= 3 and _entity.lower() != "subject":
                    from .researcher import _web_search as _ws
                    _variants = [_entity, f"{_entity} LinkedIn", f"{_entity} site:linkedin.com"]
                    for _v in _variants:
                        try:
                            _r = await asyncio.wait_for(_ws(_v), timeout=8.0)
                            if _r:
                                _fallback_hits.extend(list(_r)[:5])
                        except Exception:
                            continue
                    # Stitch into verification.data_gaps so the operator
                    # sees what public intel exists without it lifting
                    # the verdict (gate is still triggered legitimately).
                    if _fallback_hits:
                        report.verification.data_gaps.append(
                            f"R-F398 fallback web-search on '{_entity}' returned "
                            f"{len(_fallback_hits)} public hits (LinkedIn + general). "
                            f"Public-intel surface exists but the DD's registry / "
                            f"director / press layers did not pick it up — re-run "
                            f"with explicit hints (jurisdiction_iso2, website URL, "
                            f"or LinkedIn URL) to lift the confidence gate."
                        )
            except Exception:
                # Never break BLUF on fallback-search error.
                _fallback_hits = []

            _fallback_suffix = (
                f" R-F398 fallback search found {len(_fallback_hits)} public hit(s) — "
                f"see data_gaps."
                if _fallback_hits else ""
            )
            # R-F409 (2026-05-13): surface the auto-escalation status in the
            # BLUF so the operator sees "I tried deep too" — no more "why
            # did you only run shallow?". Operator-flagged 2026-05-13 08:18.
            _rf409_suffix = ""
            if getattr(report, "rf409_auto_escalated", False):
                _initial = getattr(report, "rf409_initial_mode", "standard")
                _rf409_suffix = (
                    f" R-F409: auto-escalated from {_initial}→deep, "
                    f"still insufficient. Operator action needed: supply "
                    f"jurisdiction_iso2 / website URL / known person name."
                )
            # R-F1592: when registry/identity is absent but OSINT WAS gathered
            # (press, digital findings, adverse media, fallback web hits), do
            # NOT bury it under a bare "INSUFFICIENT EVIDENCE" — lead with the
            # open-source briefing so the operator sees what WAS found, while
            # still honestly stating the registry gap. Operator 2026-06-15:
            # "she is not bringing any results" — the DD had 12 press items but
            # reported only "insufficient". The verdict/gate logic is unchanged;
            # only how the bottom line is framed when real OSINT exists.
            _press_n = len(getattr(report.digital, "press_coverage", []) or [])
            _dig_n = len(getattr(report.digital, "findings", []) or [])
            _am = getattr(report, "adverse_media", None) or {}
            _am_n = 0
            if isinstance(_am, dict):
                _am_n = int(_am.get("findings_count", 0) or 0) or len(_am.get("findings", []) or [])
            _osint_n = _press_n + _dig_n + _am_n + len(_fallback_hits)
            if _osint_n > 0:
                report.bottom_line = (
                    f"🟡 LIMITED REGISTRY DATA — {name}: corporate-registry identity "
                    f"could not be confirmed ({_reasons_str}), so this is an "
                    f"OPEN-SOURCE briefing, not a registry-verified DD — but OSINT "
                    f"WAS gathered: {_press_n} press item(s), {_dig_n} digital "
                    f"finding(s)"
                    + (f", {_am_n} adverse-media finding(s)" if _am_n else "")
                    + (f", {len(_fallback_hits)} public web hit(s)" if _fallback_hits else "")
                    + f". See the Digital/Press sections for the sources. Treat as "
                    f"'do-not-transact until registry-verified', NOT as 'nothing "
                    f"found'.{_fallback_suffix}{_rf409_suffix}"
                )
            else:
                report.bottom_line = (
                    f"🟡 INSUFFICIENT EVIDENCE — {name}: the DD did not gather "
                    f"enough data to issue a verdict. AMBER is a placeholder, "
                    f"not a substantive amber risk finding. "
                    f"Gate-triggered by: {_reasons_str}.{_fallback_suffix}{_rf409_suffix}"
                )
            report.recommendation = (
                "Re-run the DD in DEEP mode (or supply jurisdiction / "
                "registration number / website hints) before treating "
                "this as 'can proceed'. The current run did not exercise "
                "the layers that produce the registry / director / press "
                "evidence needed for a real classification."
            )
            report.next_actions = [
                "Re-run with mode=deep (or include the word 'deep' / "
                "'comprehensive' / 'full DD' in the request)",
                "Supply jurisdiction_iso2 if known",
                "Supply a website URL if not already provided — this "
                "unlocks the link-tree investigation path",
                "Resolve each data gap listed below; gate will lift once "
                "registry data + directors + incorporation date are present",
            ]
        else:
            report.bottom_line = (
                f"🟡 AMBER — {name} can proceed with enhanced due diligence. "
                "Resolve the gaps flagged below before contracting."
            )
            report.recommendation = (
                "Proceed with enhanced DD: require EUC, verify signatory identity, "
                "escalate any new red flag to RED. Close data gaps before contracting."
            )
            report.next_actions = [
                "Close the data gaps listed under residual unknowns",
                "Require EUC before any binding commitment",
                "Verify signatory identity via at least one independent source",
            ]
    else:
        # ── R-F3116 — ONE BLUF WRITER. This was the second of two forks. ──────
        # R-F3039/R-F3050 already noted "the second BLUF writer uses the same
        # helper" — the fork was known and only the coverage CLAUSE was shared. So
        # R-F3091 (entity scope) and R-F3092 (say each thing once) were applied to
        # the OTHER writer and never ran on a normal DD: a live end-to-end run
        # (Mitie, 2026-07-26) came back with `entity_scope: None` and next_actions
        # reading "Resolve decision-readiness blocker: registry status is
        # 'dissolved'" — verbatim restatements, the exact thing R-F3092 removed.
        # Both writers now render from `compose_decision_bluf`; there is no second
        # wording to drift.
        _ready = report.decision_readiness
        _bluf = compose_decision_bluf(_ready, name)
        report.bottom_line = _bluf["bottom_line"]
        report.recommendation = _bluf["recommendation"]
        report.next_actions = _bluf["next_actions"]

    # ── Layer 5c tag on the BLUF (2026-04-22) ──
    # When commercial coherence is ELEVATED or HIGH, surface it in the
    # headline so operators see the structural concern next to the
    # sanctions/ghost-score/risk verdict — not buried in the body.
    _cc_section = report.commercial_coherence
    _cc_tier = (_cc_section.tier or "GREEN").upper()
    if _cc_tier in ("ELEVATED", "HIGH") and _cc_section.meta.status not in (
        LayerStatus.SKIPPED.value, LayerStatus.ERROR.value,
    ):
        _icon = "🟠" if _cc_tier == "ELEVATED" else "🔴"
        _n_issues = (
            len(_cc_section.anomalies) + len(_cc_section.licence_chain_gaps)
            + len(_cc_section.jurisdiction_flags)
        )
        _tag = (
            f"\n\n{_icon} Commercial coherence {_cc_tier} "
            f"(score {_cc_section.coherence_score:.2f}) — {_n_issues} issue(s) "
            f"flagged in Layer 5c. See Commercial Coherence section."
        )
        if report.bottom_line and _tag not in report.bottom_line:
            report.bottom_line = report.bottom_line + _tag

    report.confidence_tag = report.verification.confidence_floor or "ASSESSED"
    # Aggregate all data_gaps into the top-level summary so consumers
    # can surface them without walking the whole report tree.
    for section in (
        report.identity, report.network, report.verification,
        report.compliance, report.digital, report.commercial_coherence,
    ):
        for g in getattr(section, "data_gaps", []) or []:
            if g not in report.data_gaps_summary:
                report.data_gaps_summary.append(g)

    # ── Auto-create compliance case from DD result (2026-04-13) ──────
    # Every entity screened gets tracked in the compliance workflow for
    # lifecycle management (re-screening, approval, audit trail).
    try:
        from . import compliance_workflow
        await compliance_workflow.auto_create_from_dd(
            entity_name=report.identity.entity_name,
            entity_type=report.identity.entity_type,
            jurisdiction=report.identity.jurisdiction_iso2 or "",
            registration_number=report.identity.registration_number or "",
            risk_level=report.risk_classification.lower().replace("-", "_").replace("amber_light", "amber").replace("amber_dark", "red"),
            risk_summary=report.bottom_line[:300],
            dd_run_id=report.run_id,
        )
    except Exception as _cw_err:
        logger.debug("Compliance workflow auto-create failed (non-fatal): %s", _cw_err)


# =============================================================================
# PERSISTENCE
# =============================================================================

# R-F1908 (G1 eradication) — vault-write helpers were CALLED at _persist_report
# but defined NOWHERE → NameError swallowed by the except, so DD cases silently
# never persisted. Defined here, defensive (getattr) so they cannot raise.
def _summarize_findings(report) -> str:
    return str(getattr(report, "bottom_line", "") or "")[:1000]


def _compute_risk_score(report) -> float:
    return {"GREEN": 0.0, "AMBER-LIGHT": 0.4, "AMBER-DARK": 0.6,
            "RED": 0.85, "HARD_STOP": 1.0}.get(
        str(getattr(report, "risk_classification", "") or "").upper(), 0.0)


def _extract_tags(report) -> list:
    rc = getattr(report, "risk_classification", "") or "unknown"
    et = getattr(getattr(report, "identity", None), "entity_type", "") or "company"
    return ["dd", str(rc).lower(), str(et)]


async def _persist_report(report: ARKDDReport) -> None:
    """Store the finished report in Redis + emit signals to brain_hook,
    intel_ledger, audit_log (RED/HARD_STOP only), mem0, and VLS (async,
    non-blocking).

    R-F573 (2026-05-16) — DD case file. Before persisting, compute the
    canonical_entity_id, resolve the version chain (looking up existing
    runs with the same canonical_id in the index), fetch the previous
    report if this is v2+, and attach a version_diff section. The three
    versioning fields (canonical_entity_id, version_number,
    previous_run_id) are added to the index entry so the
    /api/aria/dd/case/{canonical_entity_id} endpoint can fold N runs
    into a single case file.
    """
    try:
        from . import redis_store as rs
        from . import dd_versioning as _ver

        # R-F573: compute canonical entity ID + resolve version chain
        # before writing. Failure to compute the canonical_id is non-
        # fatal — we just persist as v1 / unkeyed (existing behaviour).
        canonical_id = None
        version_number = 1
        previous_run_id = None
        version_diff = None
        existing_index: list[dict] = []
        try:
            _lineage = report.target.get("_rerun_lineage") if isinstance(report.target, dict) else {}
            if isinstance(_lineage, dict):
                if not (report.identity.entity_name or "").strip() and _lineage.get("entity_name"):
                    report.identity.entity_name = _coerce_entity_text(_lineage.get("entity_name"))   # R-F3268
                if not report.identity.jurisdiction and _lineage.get("jurisdiction"):
                    report.identity.jurisdiction = _lineage.get("jurisdiction")
                if not report.identity.jurisdiction_iso2 and _lineage.get("jurisdiction_iso2"):
                    report.identity.jurisdiction_iso2 = _lineage.get("jurisdiction_iso2")
                if not report.identity.registration_number and _lineage.get("registration_number"):
                    report.identity.registration_number = _lineage.get("registration_number")
            else:
                _lineage = {}
            canonical_id = (report.target.get("canonical_entity_id") if isinstance(report.target, dict) else None) or _ver.canonical_entity_id_from_report(report)
            existing_index = await rs.get_json(REPORT_INDEX_KEY) or []
            if canonical_id:
                version_number, previous_run_id = _ver.resolve_version_chain(
                    canonical_id, existing_index,
                )
            _explicit_previous = (_lineage.get("previous_run_id") or (report.target.get("previous_run_id") if isinstance(report.target, dict) else None) or "").strip()
            if canonical_id and _explicit_previous and not previous_run_id:
                previous_run_id = _explicit_previous
                previous_body = await rs.get_json(REPORT_REDIS_KEY.format(run_id=previous_run_id)) or {}
                try:
                    version_number = max(int(previous_body.get("version_number") or 1) + 1, 2)
                except Exception:
                    version_number = 2
        except Exception as _ver_err:
            logger.debug("dd_orchestrator: version resolve failed: %s", _ver_err)
            existing_index = []

        # Persist the full serialised report plus a pre-rendered markdown
        # copy. training_export.dd_reports reads `rendered` for the
        # fine-tune capture payload — without it the collector always
        # short-circuits at the word-count guard. Keeping it at write
        # time avoids having to reconstruct DDReport from a plain dict
        # on the read side.
        _body = report.as_dict()
        try:
            # R-F1786: render_markdown is sync CPU-heavy (cx ~132, full report
            # build). Run it off the event loop so the persist hook never
            # starves the single-process loop (cf. GIL-wedge class R-F1621/1747).
            _body["rendered"] = await asyncio.to_thread(
                report.render_markdown, concise=False
            )
        except Exception as _rm_err:
            logger.debug("render_markdown failed during persist: %s", _rm_err)

        # R-F573 (initial) + R-F591 (2026-05-16): set the versioning
        # fields on BOTH the dataclass (so /dd/orchestrate's synchronous
        # response carries them — pre-R-F591 it only got Nones because
        # report.as_dict() ran on the dataclass before this hook) AND
        # the persisted body (so /dd/report/{run_id} reads them back
        # from Redis). The dataclass now has the fields as first-class
        # attributes per ARKDDReport.canonical_entity_id et al.
        report.canonical_entity_id = canonical_id
        report.version_number = version_number
        report.previous_run_id = previous_run_id
        _body["canonical_entity_id"] = canonical_id
        _body["version_number"] = version_number
        _body["previous_run_id"] = previous_run_id

        # R-F573: when this is a re-run (version_number > 1), load the
        # previous report and compute a finding-level diff. Best-effort
        # — if the previous report can't be fetched we still persist with
        # diff=None. (R-F877 removed the 7-day body TTL, so the previous
        # body no longer ages out — diffs work at any re-DD interval.)
        if version_number > 1 and previous_run_id:
            try:
                previous_body = await rs.get_json(
                    REPORT_REDIS_KEY.format(run_id=previous_run_id),
                )
                version_diff = _ver.compute_version_diff(
                    previous_report=previous_body,
                    current_report=_body,
                )
                # R-F591: write to dataclass AND body (same rationale as
                # canonical_entity_id et al above).
                report.version_diff = version_diff
                _body["version_diff"] = version_diff
            except Exception as _diff_err:
                logger.debug("dd_orchestrator: version diff failed: %s", _diff_err)
                report.version_diff = None
                _body["version_diff"] = None
        else:
            report.version_diff = None
            _body["version_diff"] = None

        await rs.set_json(
            REPORT_REDIS_KEY.format(run_id=report.run_id),
            _body,
            ex=REPORT_TTL_SECONDS,
        )
        try:
            new_entry = {
                "run_id": report.run_id,
                "generated_at": report.generated_at,
                # Mirror entity name + jurisdiction into the columns the
                # dashboard table expects so the library renders both.
                # R-F3268 — the dashboard renders this column directly, so a list
                # here would display as "['Acme Ltd']" in the library table.
                "entity_name": _coerce_entity_text(report.identity.entity_name),
                "jurisdiction": report.identity.jurisdiction,
                "jurisdiction_iso2": report.identity.jurisdiction_iso2,
                "registration_number": report.identity.registration_number,
                "website_url": (
                    report.target.get("website_url")
                    or report.target.get("website")
                    or report.target.get("url")
                    if isinstance(report.target, dict) else None
                ),
                "entity_type": report.identity.entity_type,
                # R-F130 (2026-05-10): write `severity` + `risk` +
                # `risk_classification` together so the library table
                # column populates regardless of which key the renderer
                # asks for.
                "severity": report.risk_classification,
                "risk": report.risk_classification,
                "risk_classification": report.risk_classification,
                # ── R-F3544 — CLEARANCE travels with the risk colour ──────────
                #
                # THE DEFECT, from the delivered Bidvest Noonan report
                # (dd_75d996233394): the list showed a GREEN badge while the report's
                # own assessment said "NOT CLEARED — ... this report cannot state
                # whether blocking risk exists", coverage 3/5. The colour and the text
                # answer DIFFERENT questions — risk aggregates adverse SIGNALS, clearance
                # asks whether there is enough evidence to clear — and the visually
                # dominant element carried the permissive one. A client who skims sees
                # green and proceeds on a report whose own words cannot clear them.
                #
                # R-F2786 separates those two BY DESIGN (its test asserts
                # `risk_classification == "GREEN"` under the comment "observed risk
                # remains separate"), and capping the colour would override a considered
                # design — I tried that as R-F3537 and reverted it. The right fix is to
                # SHIP BOTH FACTS so the surface can label them, which it could not do
                # before: the index row carried no clearance at all, so the badge had
                # nothing to render but the colour.
                "clearance_ready": (report.decision_readiness or {}).get("clearance_ready"),
                "clearance_status": (report.decision_readiness or {}).get("status"),
                "coverage_answered": (report.decision_readiness or {}).get("answered"),
                "coverage_required": (report.decision_readiness or {}).get("required"),
                "created_at": report.generated_at,
                # R-F573: case-file fields. Nullable so pre-R-F573
                # entries still load cleanly.
                "canonical_entity_id": canonical_id,
                "version_number": version_number,
                "previous_run_id": previous_run_id,
                # R-F607 (2026-05-16): per-user scoping fields. Nullable
                # for back-compat — pre-R-F607 entries persist with None
                # and are hidden from user-filtered list_reports calls.
                "user_id": getattr(report, "user_id", None),
                "user_email_lower": getattr(report, "user_email_lower", None),
                "user_email_domain": getattr(report, "user_email_domain", None),
                # R-F608 (2026-05-16): per-DD opt-out toggle. Default
                # True; list_reports treats missing as True so pre-R-F608
                # entries are shared to the company by default.
                "share_to_company": getattr(report, "share_to_company", True),
            }
            # R-F2341/R-F2343 — atomically REPLACE this run_id's entry (e.g. the
            # mark_dd_running 'running' placeholder) with the completed report. Reads the
            # CURRENT index inside the lock (NOT the minutes-old `existing_index` snapshot),
            # so a DD that started/finished during this run's layers is not clobbered.
            def _add_completed(index):
                index = [e for e in index if e.get("run_id") != report.run_id]
                index.insert(0, new_entry)
                return index
            await _mutate_report_index(_add_completed)
            # R-F575: mirror the index entry into the SQLite cold tier as a
            # redundant case-file chain store. Best-effort — failure is
            # non-fatal (the primary store now persists forever per R-F877).
            try:
                from . import dd_case_archive
                dd_case_archive.archive_entry(new_entry)
            except Exception as _arc_err:
                logger.debug("dd_orchestrator: cold-tier archive failed: %s", _arc_err)

            # R-F878 (2026-05-25) — auto-enroll the DD'd entity into the
            # watchlist. Pre-R-F878 orchestrate_dd NEVER called
            # add_to_watchlist, so the entities the team explicitly
            # scrutinises (a manual DD) were the ONLY ones that fell out of
            # re-screening — only autonomous-scan-discovered entities got
            # monitored. Closes that coherence hole: every completed DD
            # enrolls its canonical_entity_id so the daily re-screen tracks
            # it. Best-effort + guarded against thin/garbage names (same
            # entity guard rescreen uses to self-purge pollution).
            # Idempotent — add_to_watchlist dedups by name and only enriches.
            try:
                _wl_name = (report.identity.entity_name or "").strip()
                _enroll_ok = bool(_wl_name)
                try:
                    from . import sanctions as _sanc_enr
                    # R-F3239 - this name is the DD SUBJECT, registry-resolved
                    # moments ago. Gating it on the search-query shape heuristic
                    # meant R-F3228 could SCREEN "Marks & Spencer Group plc"
                    # while this refused to WATCH it: one name, two standards,
                    # on one page.
                    if hasattr(_sanc_enr, "_screenable"):
                        _enroll_ok = _enroll_ok and _sanc_enr._screenable(
                            _wl_name, trusted=True)
                    elif hasattr(_sanc_enr, "_looks_like_entity_name"):
                        _enroll_ok = _enroll_ok and _sanc_enr._looks_like_entity_name(_wl_name)
                except Exception:
                    pass
                # R-F3287 — this call no longer ENROLS. It deliberately does
                # not pass requested_by_user, so it can only enrich an entry
                # the user already added (back-filling canonical_entity_id,
                # last_dd_run_id, last_risk so the re-screen matches by
                # canonical id). If the entity is not on the list, the call
                # returns ok=False and nothing is created.
                #
                # This knowingly gives up R-F878's coherence property — that a
                # manually DD'd entity is automatically monitored. That was a
                # real gap when R-F878 closed it. The operator has weighed it
                # against unrequested spend: every enrolled entity is
                # re-screened on a recurring cycle at the user's cost, and
                # nobody asked for the subscription. Adding an entity is now
                # one click on the watchlist page.
                if _enroll_ok:
                    await add_to_watchlist({
                        "name": _wl_name,
                        "entity_type": report.identity.entity_type or None,
                        "jurisdiction": report.identity.jurisdiction or None,
                        "canonical_entity_id": canonical_id,
                        "source": "dd_auto_enroll",
                        "last_dd_run_id": report.run_id,
                        "last_risk": report.risk_classification,
                        "added_at": report.generated_at,
                        # R-F2355 — stamp the owner so the watchlist is per-user (mirrors
                        # the report index). Without this the watchlist is GLOBAL and one
                        # user's DD company leaks onto every other user's watchlist.
                        "user_id": getattr(report, "user_id", None),
                        "user_email_domain": getattr(report, "user_email_domain", None),
                        "share_to_company": getattr(report, "share_to_company", True),
                    })
            except Exception as _enr_err:
                logger.debug("dd_orchestrator: watchlist auto-enroll failed: %s", _enr_err)
        except Exception as e:
            logger.debug("dd_orchestrator: report index write failed: %s", e)
    except Exception as e:
        logger.warning("dd_orchestrator: Redis persist failed: %s", e)

    # ── Self-metrics: declared calibration (final confidence tag as a score)
    # + coverage (subsystems that produced findings). Real calibration arrives
    # later when corrections are logged against this run_id.
    try:
        from . import self_metrics
        _conf_score = {
            "CONFIRMED": 1.0, "PROBABLE": 0.75, "ASSESSED": 0.5, "UNCERTAIN": 0.25,
        }.get((report.confidence_tag or "ASSESSED").upper(), 0.5)
        _domain = (report.identity.jurisdiction or "unknown").upper() or "unknown"
        await self_metrics.emit(
            "calibration", _domain, "dd_declared_confidence",
            _conf_score,
            context={"run_id": report.run_id, "tag": report.confidence_tag,
                     "risk": report.risk_classification},
            source_module="dd_orchestrator",
        )
        # Coverage: fraction of the 6 DD subsystems that produced at least one
        # finding (identity, network, compliance, digital, verification,
        # commercial_coherence). Synthesis uses `key_findings` not
        # `findings` and is the aggregator of the other layers, so it's
        # not counted as a separate signal source. The comment previously
        # said "6 subsystems" but the list had 5 -- commercial_coherence
        # was missing, so coverage was always undercounted by 1/6.
        _subs = [report.identity, report.network, report.compliance,
                 report.digital, report.verification,
                 report.commercial_coherence]
        _produced = sum(1 for s in _subs
                        if s and (getattr(s, "findings", None) or getattr(s, "entity_name", None)))
        await self_metrics.emit(
            "coverage", _domain, "dd_subsystem_yield",
            _produced / max(1, len(_subs)),
            context={"run_id": report.run_id, "subsystems_produced": _produced},
            source_module="dd_orchestrator",
        )
    except Exception as _sm:
        logger.debug("dd_orchestrator self_metrics failed: %s", _sm)

    # ──     # ---- R-F1182: VLS cryptographic proof (fire-and-forget) ---------------------
    # After the report is fully persisted, seal it with a cryptographic
    # proof (hash + ECDSA signature + chain link). Never blocks the DD
    # pipeline -- errors are caught and wired to the brain.
    #
    # R-F2005: pass _body (the dict stored in Redis) instead of `report`
    # (the dataclass). The stored body includes `rendered` and
    # `version_diff` that report.as_dict() does NOT include, so the
    # proof hash never matched the stored body -- breaking the chain.
    try:
        from . import verifiable_ledger as _vls
        from . import engine_wiring as _ew
        _ew.wire_success(
            module="dd_orchestrator",
            summary=f"VLS proof requested for {report.run_id}",
            source_id=report.run_id,
        )
        # Fire-and-forget: schedule but don't await.
        # Pass _body (the stored dict) so the proof hash matches.
        _vls_body = dict(_body)
        _ew._dispatch_fire_and_forget(lambda: _vls.record_report(
            run_id=report.run_id,
            report_body=_vls_body,
            canonical_entity_id=canonical_id,
            version_number=version_number,
        ))
    except Exception as _vls_e:
        logger.debug("dd_orchestrator: VLS hook failed (non-fatal): %s", _vls_e)
    # R-F1184: intel_ledger signal (fire-and-forget)
    # Every completed DD report produces a permanent signal in the intel
    # ledger so query_ledger() can surface DD findings.
    try:
        from . import intel_ledger as _il
        await _il.add_signal({
            "summary": f"DD report: {report.identity.entity_name} ({report.identity.entity_type}, {report.identity.jurisdiction_iso2 or 'unknown'}) - risk={report.risk_classification}",
            "source": "dd_orchestrator",
            "type": "dd_report",
            "severity": "high" if report.risk_classification in ("RED", "HARD_STOP", "NO-GO") else "medium",
            "tags": ["dd", str(report.risk_classification).lower() if report.risk_classification else "unknown"],
            "timestamp": report.generated_at,
        })
    except Exception as _il_e:
        logger.debug("dd_orchestrator: intel_ledger hook failed (non-fatal): %s", _il_e)

    # R-F1184: audit_log record for RED/HARD_STOP verdicts
    _risk_upper = (report.risk_classification or "").upper()
    if _risk_upper in ("RED", "HARD_STOP", "NO-GO"):
        try:
            from . import audit_log as _al
            await _al.record(
                action="dd_verdict",
                actor="aria.dd_orchestrator",
                entity_name=report.identity.entity_name or "",
                deal_id="",
                inputs={"target": report.target},
                outputs={
                    "risk_classification": report.risk_classification,
                    "bottom_line": str(report.bottom_line)[:500],
                    "run_id": report.run_id,
                    "canonical_entity_id": report.canonical_entity_id,
                },
                decision=report.risk_classification,
                confidence=report.confidence_tag or "ASSESSED",
                notes=f"DD run {report.run_id} returned {report.risk_classification} on {report.identity.entity_name}",
                feed_brain=True,
            )
        except Exception as _al_e:
            logger.debug("dd_orchestrator: audit_log hook failed (non-fatal): %s", _al_e)

    # R-F1184: mem0 notebook entry (fire-and-forget)
    # A brief notebook entry per DD run helps ARIA recall past investigations.
    if (report.risk_classification or "") not in ("ERROR",):
        try:
            from . import mem0 as _mem0
            if _mem0.is_enabled():
                _summary = (
                    f"DD report on {report.identity.entity_name} "
                    f"({report.identity.entity_type}, {report.identity.jurisdiction_iso2 or 'unknown'}): "
                    f"risk={report.risk_classification}. "
                    f"{str(report.bottom_line)[:300]}"
                )
                await _mem0.summarise_and_store(
                    user_message=f"Run DD on {report.identity.entity_name}",
                    aria_response=_summary,
                    session_id=f"dd_{report.run_id}",
                    llm=None,
                    user_label="operator",
                )
        except Exception as _mem0_e:
            logger.debug("dd_orchestrator: mem0 hook failed (non-fatal): %s", _mem0_e)



    # R-F1658: record in the persistent DD vault (SQLite, survives restarts)
    try:
        from .dd_vault import get_vault as _get_dd_vault
        _vault = _get_dd_vault()
        # R-F2683 — snapshot the EVIDENCE GRADE alongside the risk score. Graded from
        # the same assessment the report renders (R-F2681), so vault and report agree.
        # A grading failure must NOT lose the case: fall through UNGRADED (the vault
        # then honestly reports "no grade") rather than inventing one or aborting the
        # whole record_case.
        _ev_grade, _ev_score, _ev_blockers = "", None, None
        try:
            from .dd_schema import _dd_quality_assessment as _dd_qa
            _qa = _dd_qa(report.as_dict())
            _ev_grade = _qa.get("grade") or ""
            _ev_score = _qa.get("score")
            _ev_blockers = _qa.get("blocking_reasons") or []
        except Exception as _qa_err:
            logger.debug("dd_vault: evidence grade unavailable (recorded ungraded): %s", _qa_err)
            # §21a — a console log is DARK. The case still persists (honestly ungraded),
            # so nothing else would ever surface a systematic grading breakage: it would
            # show only as a slow drift of evidence_grade='' rows with no self-heal
            # trigger. Wire the failure so the coder loop can see it.
            try:
                from .engine_wiring import wire_failure as _wf_grade
                _wf_grade(
                    module="dd_schema",
                    detail=(f"evidence grade failed for {getattr(report, 'run_id', '?')}"
                            f" — case recorded UNGRADED: {_qa_err}"),
                    gap_type="engine_failure",
                    source="dd_orchestrator:_persist_report:evidence_grade",
                )
            except Exception:
                pass
        _vault.record_case(
            canonical_entity_id=getattr(report, "canonical_entity_id", None)
                or _slugify_entity_name(getattr(report.identity, "entity_name", "unknown")),
            entity_name=getattr(report.identity, "entity_name", "unknown"),
            entity_type=getattr(report.identity, "entity_type", "company"),
            jurisdiction=getattr(report.identity, "jurisdiction", ""),
            registration_number=getattr(report.identity, "registration_number", ""),
            latest_report_id=report.run_id,
            findings_summary=_summarize_findings(report),
            risk_score=_compute_risk_score(report),
            risk_level=report.risk_classification or "unknown",
            tags=_extract_tags(report),
            evidence_grade=_ev_grade,
            evidence_score=_ev_score,
            grade_blockers=_ev_blockers,
        )
    except Exception as _vault_err:
        logger.debug("dd_vault: record failed (non-fatal): %s", _vault_err)
        # R-F2009b: wire vault failure to brain so it's not a silent drop
        try:
            from .engine_wiring import wire_failure as _wf_vault
            _wf_vault(
                module="dd_vault",
                detail=f"record_case failed for {getattr(report, 'run_id', '?')}: {_vault_err}",
                gap_type="persistence_failure",
                source="dd_orchestrator:_persist_report",
            )
        except Exception:
            pass

    # ── R-F2700 — POPULATE the relationship graph (DD Grade-A Phase 1, gap #2) ──
    # `add_cross_reference` existed with a full read side (get_cross_references /
    # get_related_cases → GET /dd/vault/case/{id} → the "Cross-References" + "Related
    # Cases" sections of dd-reports.html) but NO prod writer — called only from tests,
    # so the table was empty and both UI sections always rendered blank. This is the
    # writer. It runs AFTER R-F2697 gave the table a tenant-safe key: never wire this
    # before that ACL, or the graph fills with cross-tenant-readable rows.
    #
    # ANCHORING (the part that makes it real): network_walker emits cross-links as
    # FREE-TEXT names — {"name", "via_director", "jurisdiction", "registration_number"}
    # (network_walker.py:355-359) — while dd_cross_references keys on
    # canonical_entity_id and get_related_cases does get_case(id). Writing raw names
    # would produce edges that can never match a case: "Related Cases" would stay empty
    # forever and the UI would render un-anchored strings. So resolve each target through
    # the SAME canonicaliser a DD of that company would use (dd_versioning, R-F573) —
    # company:GB:<regnum> — and DROP anything too thin to canonicalise rather than invent
    # an id. An edge to a not-yet-DD'd company is still true and still renders; it simply
    # lights up "Related Cases" later, when that company gets its own case.
    try:
        _write_relationship_edges(report, _vault)
    except Exception as _xref_err:
        logger.debug("dd_vault: cross-reference write failed (non-fatal): %s", _xref_err)
        try:
            from .engine_wiring import wire_failure as _wf_xref
            _wf_xref(
                module="dd_vault",
                detail=(f"cross-reference write failed for "
                        f"{getattr(report, 'run_id', '?')}: {_xref_err}"),
                gap_type="persistence_failure",
                source="dd_orchestrator:_persist_report:cross_refs",
            )
        except Exception:
            pass

    # R-F2469 — persist per-RUN ownership in the WIPE-SURVIVING vault so an index
    # rebuild restores the REAL owner (never fabricated — the R-F2466 leak class).
    # Owner-less runs write nothing → stay owner-less (fail-closed).
    try:
        from .dd_vault import get_vault as _get_dd_vault2
        _get_dd_vault2().record_report_owner(
            getattr(report, "run_id", None),
            canonical_entity_id=getattr(report, "canonical_entity_id", None),
            user_id=getattr(report, "user_id", None),
            user_email_domain=getattr(report, "user_email_domain", None),
            share_to_company=getattr(report, "share_to_company", True),
        )
    except Exception as _own_err:
        logger.debug("dd_vault: record_report_owner failed (non-fatal): %s", _own_err)

