@fail_wire(module="dd_orchestrator", gap_type="engine_failure")
async def get_public_watchlist_alerts(since_hours: int = 168) -> list:
    """Read public-watchlist risk-change alerts (already tenant-free by construction)."""
    from datetime import timedelta as _td
    from . import redis_store as rs
    import json as _json
    raw = await rs.lrange(PUBLIC_WATCHLIST_ALERTS_KEY, 0, _PUBLIC_WATCHLIST_MAX - 1)
    cutoff = datetime.now(timezone.utc) - _td(hours=since_hours)
    out = []
    for r in raw:
        try:
            a = _json.loads(r) if isinstance(r, str) else r
            ts = a.get("timestamp")
            if ts:
                try:
                    if datetime.fromisoformat(str(ts).replace("Z", "+00:00")) < cutoff:
                        continue
                except Exception:
                    pass
            out.append(a)
        except Exception:
            continue
    return out


@fail_wire(module="dd_orchestrator", gap_type="engine_failure")
async def rescreen_public_watchlist() -> dict:
    """Re-screen the operator-curated PUBLIC watchlist and emit public-safe risk-change
    alerts (entity / change_type / status / detail only — NEVER a tenant field).
    Diffs against a dedicated public-state key (not customer DD reports)."""
    import asyncio as _aio
    import json as _json
    from . import redis_store as rs
    t0 = time.monotonic()
    # R-F3520 — not a clobber (nothing is written back), but the SAME false clean.
    # A swallowed StoreReadError read [] and returned "0 entities screened, no changes
    # detected, no errors" — a completed, clean public monitoring cycle that never ran.
    # An unperformed screen must report that it could not run, never a clean result.
    try:
        entities = await _read_watchlist_or_skip(PUBLIC_WATCHLIST_KEY)
    except _WatchlistUnavailable as exc:
        return {"entities_screened": 0, "changes_detected": [],
                "errors": [{"entity": "*", "error": f"public watchlist unreadable: {exc}"}],
                "screened": False,
                "note": ("The public watchlist could not be READ, so no screening was "
                         "performed. This is NOT a clean cycle."),
                "duration_ms": int((time.monotonic() - t0) * 1000)}
    if not entities:
        return {"entities_screened": 0, "changes_detected": [], "errors": [], "duration_ms": 0}
    try:
        from . import sanctions
        from ._sanctions_classify import classify_matches
    except Exception as e:
        return {"entities_screened": 0, "changes_detected": [], "errors": [{"entity": "*", "error": str(e)}], "duration_ms": 0}
    state = await rs.get_json(PUBLIC_WATCHLIST_STATE_KEY) or {}
    changes: list[dict] = []
    errors: list[dict] = []
    per_timeout = float(os.environ.get("ARIA_RESCREEN_PER_ENTITY_TIMEOUT_S", "60.0"))
    for entry in entities:
        name = (entry.get("name") or "").strip()
        if not name:
            continue
        try:
            async def _screen():
                if hasattr(sanctions, "screen_with_aliases"):
                    return await sanctions.screen_with_aliases(name)
                if hasattr(sanctions, "fuzzy_screen"):
                    return await sanctions.fuzzy_screen(name)
                return None
            screen = await (_aio.wait_for(_screen(), timeout=per_timeout) if per_timeout > 0 else _screen())
            if screen is None:
                errors.append({"entity": name, "error": "no sanctions entrypoint"})
                continue
            # --- R-F3690: the R-F2744 completeness gate, applied HERE too ---
            # R-F2744 added this gate to the OTHER re-screen loop (~:19681) and
            # this one never got it. The R-F2559 emit-only-increases rule below
            # stops a fabricated *alert*, but the comment "Removals/score moves
            # still update state below (for future diffs)" is the hole: on an
            # unavailable source, matches=[] derives CLEAN and the unconditional
            # `state[name.lower()] = {...}` at the bottom of this loop OVERWRITES
            # a genuine HIT baseline with CLEAN — permanently. The next real
            # screen then compares against a fabricated clean baseline, so the
            # entity's re-listing can never be detected as a change either.
            #
            # Fail closed: any error, any unavailable source, any explicit
            # screened=False ⇒ this entity is skipped entirely and its stored
            # baseline is left untouched.
            _screen_ok = (
                screen.get("error") is None
                and not screen.get("source_unavailable")
                and screen.get("screened", True) is not False
            )
            if not _screen_ok:
                errors.append({
                    "entity": name,
                    "error": screen.get("error") or "sanctions_source_unavailable",
                    "degraded": True,  # unperformed screen — NOT a clearance
                })
                continue
            matches = screen.get("matches") or []
            classified = classify_matches(matches, query_name=name)
            new_status = _derive_status(classified)
            new_score = _derive_score_from_matches(matches)
            _seen_before = name.lower() in state   # False on the first (baseline) screen
            prior = state.get(name.lower()) or {}
            old_status = prior.get("status", "CLEAN")
            old_score = float(prior.get("score", 0.0))
            change_type, detail = None, ""
            if old_status == "CLEAN" and new_status == "HIT":
                change_type = "new_hit"; detail = f"Previously clean, now sanctioned. {classified.get('summary','')[:200]}"
            elif old_status == "HIT" and new_status == "CLEAN":
                change_type = "removed"; detail = "Previously sanctioned, now clean across all lists."
            elif old_status != "PEP" and new_status == "PEP":
                change_type = "new_pep"; detail = f"New PEP / adverse-media match. {classified.get('summary','')[:200]}"
            elif abs(new_score - old_score) > 0.1:
                change_type = "score_change"; detail = f"Best match score changed {old_score:.2f} -> {new_score:.2f}."
            # never-false-clean (R-F2559 review #G): EMIT only risk-INCREASE events.
            # A dead/empty sanctions store returns no matches -> CLEAN, which could
            # fabricate a "removed"/"score_change"; new_hit/new_pep can NEVER be
            # produced by a dead store (it never yields HIT/PEP). Removals/score moves
            # still update state below (for future diffs) but are not promoted.
            # Honesty: the FIRST screen of a newly-curated entity sets the BASELINE — a
            # pre-existing sanction is not a "change", so only emit once we had a prior
            # observation (_seen_before).
            if change_type in ("new_hit", "new_pep") and _seen_before:
                alert = {
                    "entity": name,
                    "change_type": change_type,
                    "old_status": old_status,
                    "new_status": new_status,
                    "old_score": round(old_score, 3),
                    "new_score": round(new_score, 3),
                    "detail": detail,
                    "timestamp": datetime.now(timezone.utc).isoformat(),
                    "scope": "system_public",
                    # NO user_id / user_email_domain / share_to_company / run_id /
                    # impacted_deals — this store is public by construction.
                }
                changes.append(alert)
                await rs.lpush(PUBLIC_WATCHLIST_ALERTS_KEY, _json.dumps(alert, default=str))
                await rs.ltrim(PUBLIC_WATCHLIST_ALERTS_KEY, 0, _PUBLIC_WATCHLIST_MAX - 1)
            state[name.lower()] = {"status": new_status, "score": round(new_score, 3),
                                   "ts": datetime.now(timezone.utc).isoformat()}
        except _aio.TimeoutError:
            errors.append({"entity": name, "error": f"screen timeout >{per_timeout}s"})
        except Exception as e:
            errors.append({"entity": name, "error": str(e)[:200]})
    await rs.set_json(PUBLIC_WATCHLIST_STATE_KEY, state)
    return {"entities_screened": len(entities), "changes_detected": changes,
            "errors": errors, "duration_ms": int((time.monotonic() - t0) * 1000)}


@fail_wire(module="dd_orchestrator", gap_type="engine_failure")
async def remove_from_watchlist(name: str, user_id: str = "",
                                user_email_domain: str = "") -> dict:
    """R-F2401 — owner-scoped delete. Pre-fix this removed EVERY entry matching
    the name regardless of owner, so any authenticated user could delete another
    tenant's watchlist entry (IDOR write, violates R-F2097). Now a scoped caller
    (user_id set) removes ONLY entries they own or a same-company-shared entry;
    the configured legacy operator may also remove owner-less entries (single-
    operator deployment). user_id='' = admin / internal → unrestricted (keeps the
    autonomous re-screen self-purge working)."""
    from . import redis_store as rs
    try:
        current = await _read_watchlist_or_skip()
    except _WatchlistUnavailable as exc:
        # R-F3506 — the store could not be read, so the list must not be
        # rewritten. Report it as a FAILED removal (R-F3503: ok means "it will
        # no longer be re-screened"), never as a silent success over an entity
        # that is still being monitored.
        return {"ok": False, "removed": 0, "count": 0,
                "reason": f"watchlist store unavailable, nothing was changed: {exc}"}
    before = len(current)
    tgt = (name or "").strip().lower()
    _legacy_uid, _ = _dd_legacy_owner_fallback()
    _cdom = (user_email_domain or "").strip().lower()

    def _caller_may_remove(w: dict) -> bool:
        if not user_id:
            return True  # admin / internal — unrestricted
        w_owner = (w.get("user_id") or "").strip()
        if w_owner:
            if w_owner == user_id:
                return True
            w_dom = (w.get("user_email_domain") or "").strip().lower()
            # R-F2777 — no domain-share delete across a public webmail domain.
            return bool(_cdom and w_dom and _cdom == w_dom
                        and not _is_public_webmail_domain(_cdom)
                        and w.get("share_to_company", True) is not False)
        # owner-less entry: only the configured legacy operator may remove it
        return bool(_legacy_uid and user_id == _legacy_uid)

    kept = [
        w for w in current
        if not ((w.get("name") or "").strip().lower() == tgt and _caller_may_remove(w))
    ]
    await rs.set_json(WATCHLIST_KEY, kept)
    _removed = before - len(kept)
    # R-F3503 — `ok` must mean "the entity will no longer be re-screened",
    # because that is exactly what the UI tells the user on the strength of it
    # (public/watchlist.html: "will no longer be re-screened against sanctions &
    # PEP lists"). Returning ok=True for removed=0 turned a name mismatch — or a
    # legitimate owner-scope refusal (R-F2401, another tenant's entry) — into a
    # success message over an entity the monitor kept screening every 300s.
    # A workflow that ends in a label grants nothing; the store holding the
    # RESULT is what decides.
    _reason = ""
    if _removed == 0:
        _reason = (
            "no matching watchlist entry you are permitted to remove — it was "
            "not found, or it belongs to another owner"
        )
    return {"ok": _removed > 0, "removed": _removed, "count": len(kept),
            "reason": _reason}


@fail_wire(module="dd_orchestrator", gap_type="engine_failure")
async def get_watchlist(user_id: str | None = None,
                        user_email_domain: str | None = None) -> list[dict]:
    """R-F2355 — per-user scoping (mirrors list_reports R-F607/608). When ``user_id`` is
    set, return ONLY entries owned by that user OR shared by a same-email-domain colleague;
    entries with no owner (pre-R-F2355 / internal) are hidden from user-filtered views (fail
    CLOSED — R-F2097). ``user_id=None`` = admin / internal (the autonomous due-check) and
    sees the FULL list so monitoring still covers every watched entity."""
    from . import redis_store as rs
    items = await _read_watchlist_or_skip()  # R-F3506 strict; never rewrite from an empty read

    # R-F2401 — reclaim OWNER-LESS watchlist entries (mirrors the R-F2393 report
    # reclaim). A DD auto-enroll before R-F2355, or an entry whose owner was lost,
    # is owner-less and would stay hidden from the operator's scoped watchlist
    # forever (get_watchlist fails closed). Reclaim the true owner from the report
    # index by last_dd_run_id (the index carries owners post-R-F2393), else fall
    # back to the configured legacy operator; persist so it heals once.
    _ownerless_wl = [w for w in items
                     if isinstance(w, dict) and not (w.get("user_id") or "").strip()]
    if _ownerless_wl:
        _ff_uid, _ff_dom = _dd_legacy_owner_fallback()
        _idx_owner: dict[str, tuple] = {}
        try:
            _idx = await rs.get_json(REPORT_INDEX_KEY) or []
            for _e in _idx:
                if not isinstance(_e, dict):
                    continue
                _rid = (_e.get("run_id") or "").strip()
                _euid = (_e.get("user_id") or "").strip()
                if _rid and _euid:
                    _idx_owner[_rid] = (
                        _euid,
                        (_e.get("user_email_domain") or "").strip().lower() or None,
                        _e.get("share_to_company", True),
                    )
        except Exception:
            _idx_owner = {}
        _wl_changed = False
        for w in _ownerless_wl:
            _rid = (w.get("last_dd_run_id") or "").strip()
            _claim = _idx_owner.get(_rid)
            if _claim:
                w["user_id"] = _claim[0]
                if _claim[1] and not w.get("user_email_domain"):
                    w["user_email_domain"] = _claim[1]
                w.setdefault("share_to_company", _claim[2])
                w["_owner_reclaimed_by"] = "R-F2401_report_index"
                _wl_changed = True
            elif _ff_uid:
                w["user_id"] = _ff_uid
                if _ff_dom and not w.get("user_email_domain"):
                    w["user_email_domain"] = _ff_dom
                w.setdefault("share_to_company", True)
                w["_owner_reclaimed_by"] = "R-F2401_legacy_operator"
                _wl_changed = True
        if _wl_changed:
            try:
                await rs.set_json(WATCHLIST_KEY, items)
            except Exception:
                pass

    if not user_id:
        return items
    out: list[dict] = []
    for w in items:
        if not isinstance(w, dict):
            continue
        w_uid = w.get("user_id")
        if w_uid and w_uid == user_id:
            out.append(w)
        # R-F2777 — no domain-share across a public webmail domain (owner-exact only).
        elif (user_email_domain and w.get("user_email_domain") == user_email_domain
              and not _is_public_webmail_domain(user_email_domain)
              and w.get("share_to_company", True)):
            out.append(w)
    return out


@fail_wire(module="dd_orchestrator", gap_type="engine_failure")
async def reset_dd_memory(confirm: bool = False) -> dict:
    """R-F2337 — DANGER: wipe ALL DD state for a clean start (clears accumulated test
    data). Deletes every report body, the report index, all VLS proofs + chains, the
    watchlist + its alerts, and the DD vault (cases / cross-refs / financial profiles).
    Irreversible. Requires confirm=True. Runs IN-PROCESS on the single state_store
    connection (never spawn a second writer — R-F2277)."""
    if confirm is not True:
        return {"ok": False, "error": "confirm=True required (irreversible wipe)"}
    from . import redis_store as rs
    cleared: dict[str, Any] = {}
    # 1) report bodies (crucix:dd:report:{run_id}) — NOTE report_index uses '_' not ':'
    rep_keys = await rs.scan_keys("crucix:dd:report:*", count=5000)
    for k in rep_keys:
        await rs.delete(k)
    cleared["reports"] = len(rep_keys)
    # 2) report index
    await rs.delete(REPORT_INDEX_KEY)
    # 3) VLS proofs + chains (crucix:dd:vls:* covers both proofs and :chain:)
    vls_keys = await rs.scan_keys("crucix:dd:vls:*", count=10000)
    for k in vls_keys:
        await rs.delete(k)
    cleared["vls_proofs_and_chains"] = len(vls_keys)
    # 4) watchlist + alerts
    await rs.delete(WATCHLIST_KEY)
    await rs.delete(WATCHLIST_ALERTS_KEY)
    cleared["watchlist_and_alerts"] = 2
    # 5) DD vault (separate sqlite at /data/dd_vault.db, own connection)
    try:
        from .dd_vault import get_vault
        cleared["vault"] = get_vault().clear_all()
    except Exception as e:
        cleared["vault_error"] = str(e)
    try:
        from .engine_wiring import wire_success
        wire_success(module="dd_orchestrator",
                     summary=f"DD memory reset (clean slate): {cleared}",
                     source_id="dd_orchestrator:reset_dd_memory")
    except Exception:
        pass
    logger.warning("[dd_reset] R-F2337 DD memory WIPED for clean start: %s", cleared)
    return {"ok": True, "cleared": cleared}


